/// Typed scheduler-side errors that need HTTP-level discrimination.
///
/// Anyhow remains the default error type for internal Scheduler paths
/// (out-of-memory, prompt parsing, MLX failures, etc.). `SchedulerError`
/// only enumerates errors the HTTP server needs to map to non-400
/// responses. Wrap into anyhow via `anyhow::Error::new(SchedulerError::...)`
/// at the emit site; HTTP handlers downcast with
/// `err.downcast_ref::<SchedulerError>()`.
///
/// Replaces the pre-3e.3 string-match `err.to_string().contains("admission
/// queue full")` pattern (spec §9 R3 acknowledged-fragile).
#[derive(Error, Debug)]
pub enum SchedulerError {
    /// Admission queue rejected a request because the queue was already
    /// at `capacity`. Maps to HTTP 503 + Retry-After.
    #[error("admission queue full: capacity={capacity} reached")]
    QueueFull { capacity: usize },

    /// Request's `prompt_len + max_new_tokens` exceeds the server's
    /// effective cap_max (the smaller of `--max-cache-cap` CLI flag and
    /// the model's `max_position_embeddings`). Maps to HTTP 413
    /// Payload Too Large. B1-p2.3f.
    #[error(
        "request requires {required_total_tokens} total tokens: {input_tokens} input tokens + \
         {requested_max_output_tokens} maximum output tokens; the server maximum context capacity \
         is {server_max_context_tokens} tokens (Dashboard → MAX CONTEXT TOKENS). Reduce request \
         max_tokens to {max_allowed_output_tokens} or less, or increase MAX CONTEXT TOKENS in the \
         Dashboard."
    )]
    RequestTooLarge {
        required_total_tokens: usize,
        input_tokens: usize,
        requested_max_output_tokens: usize,
        server_max_context_tokens: usize,
        max_allowed_output_tokens: usize,
    },

    /// Admission gate: request's KV cache bytes plus active bytes would
    /// exceed the soft limit (85% of total budget). Maps to HTTP 503
    /// + Retry-After (T2). B1-p2.5.
    #[error(
        "memory budget exceeded: active {active_bytes} + requested {requested_bytes} > \
         soft limit {soft_limit_bytes}"
    )]
    MemoryBudgetExceeded {
        active_bytes: usize,
        requested_bytes: usize,
        soft_limit_bytes: usize,
    },

    #[error(
        "process memory pressure blocks admission: level={level:?} current={current_bytes} ceiling={ceiling_bytes}"
    )]
    MemoryPressure {
        level: crate::core::process_memory::PressureLevel,
        current_bytes: usize,
        ceiling_bytes: usize,
    },

    #[error(
        "prefill peak guard rejected request: requested_tokens={requested_tokens} selected_tokens={selected_tokens} target_bytes={target_bytes}"
    )]
    PrefillPeakUnsafe {
        requested_tokens: usize,
        selected_tokens: usize,
        target_bytes: usize,
    },

    #[error(
        "vision prefill peak guard rejected request: estimated_bytes={estimated_bytes} target_bytes={target_bytes}"
    )]
    VisionPrefillPeakUnsafe {
        estimated_bytes: usize,
        target_bytes: usize,
    },

    #[error(
        "cold mmap materialization guard rejected request: requested_bytes={requested_bytes} current_bytes={current_bytes} target_bytes={target_bytes}"
    )]
    ColdMaterializationUnsafe {
        requested_bytes: usize,
        current_bytes: usize,
        target_bytes: usize,
    },

    #[error(
        "prefix store backpressure blocks admission: pending_jobs={pending_jobs} pending_bytes={pending_bytes}"
    )]
    StoreBackpressure {
        pending_jobs: usize,
        pending_bytes: usize,
    },
}

