/// All per-request state the scheduler tracks. Pre-allocated at admit time
/// and held until eviction.
///
/// Fields are chosen to cover B1-p2.3b–3e needs without a later refactor.
/// VL fields (`pixel_values`, `image_grid_thw`, etc.) are intentionally
/// omitted from 3a — they get added in B1-p2.4 when VL B>1 lands.
#[derive(Debug, Clone)]
pub struct RequestState {
    /// Opaque token returned by [`Scheduler::admit`].
    pub id: RequestId,
    /// Position in the scheduler's slot vector (0..b_max). Fixed for the
    /// lifetime of this request — subsequent admits never relocate it.
    /// Used by 3b to index into the batched KV cache and per-row mask
    /// tensors.
    pub row_idx: usize,
    /// Original prompt token ids; copied from `GenerateRequest::prompt_ids`.
    pub prompt_ids: Vec<u32>,
    /// Decode-time tokens produced so far. Empty at admit. 3b pushes one
    /// token per `Scheduler::step()` per row.
    pub generated_tokens: Vec<u32>,
    /// Hard cap on tokens generated beyond the prompt.
    pub max_new_tokens: usize,
    /// Token ids that terminate the stream when produced; copied from
    /// `GenerateRequest::stop_token_ids`.
    pub stop_token_ids: Vec<u32>,
    /// Per-row sampler — cloned from the request's sampler at admit time so
    /// each row owns independent sampler state. Sampler is `Copy` post-3e.2;
    /// PRNG state lives in `Scheduler.prng_state` (centralized).
    pub sampler: Sampler,
    /// Immutable source plan retained for fresh prefill and rebase helpers.
    pub constraint_plan: Option<crate::core::constrained::ConstraintPlan>,
    /// Request-local token-level grammar state, advanced only by committed
    /// generated tokens.
    pub constraint: Option<crate::core::constrained::ConstraintSession>,
    /// Effective KV-cache length for this row: starts at `prompt_ids.len()`
    /// and is incremented by 1 per decode step (3b). Used by 3c to build
    /// the per-row decode mask.
    pub real_len: i32,
    /// `false` at admit; 3b sets `true` on EOS / `max_new_tokens` reached.
    pub finished: bool,
    /// `"stop"` or `"length"` when `finished` is `true`; otherwise `None`.
    pub finish_reason: Option<&'static str>,

    // ─── B1-p2.4: VL fields, carried from GenerateRequest at admit ───
    /// Vision inputs in image order. `None` for text-only rows. `Array`
    /// clone is mlx reference-counted — cheap. Lives until evict.
    pub pixel_values: Option<Vec<Array>>,
    /// Per-image `(temporal, height, width)` grid sizes; same len as image
    /// count for this row. `None` ⇔ `pixel_values.is_none()`.
    pub image_grid_thw: Option<Vec<(i32, i32, i32)>>,
    /// Spatial merge factor for image patches → embedding rows. Carried
    /// from `GenerateRequest::image_spatial_merge_size`. Unused if
    /// `pixel_values` is None.
    pub image_spatial_merge_size: i32,
    /// Tokenizer id of `<|image_pad|>`. Carried from
    /// `GenerateRequest::image_token_id`. Unused if `pixel_values` is None.
    pub image_token_id: i32,
    /// Per-request chunk size for chunked mid-batch prefill. Copied from
    /// `GenerateRequest::prefill_chunk_size` at admit time, clamped to i32.
    /// `0` is preserved as "disable chunking" and expanded to prompt length
    /// when `admit_mid_begin` initialises `AdmitMidHandle::chunk_size`.
    pub prefill_chunk_size: i32,
    /// Request-level rolling mid-admit chunk cap selected from the runtime
    /// scheduler profile.
    pub decode_cadence_mid_chunk_cap: usize,
    /// Optional TurboQuant K/V bit-widths for full-attention KV cache reads.
    pub kv_cache_turboquant_bits: Option<TurboQuantKVBits>,
    /// KV cache bytes charged to budget at admit time. Released on
    /// row completion / eviction. B1-p2.5.
    pub kv_bytes_admitted: usize,
}

fn completed_prompt_lookup_history(state: &RequestState) -> Option<Vec<u32>> {
    if !state.finished || !matches!(state.finish_reason, Some("stop") | Some("length")) {
        return None;
    }
    let mut history = Vec::with_capacity(state.prompt_ids.len() + state.generated_tokens.len());
    history.extend_from_slice(&state.prompt_ids);
    history.extend_from_slice(&state.generated_tokens);
    Some(history)
}

#[derive(Debug, Clone)]
pub struct ActiveKvParkedRequest {
    pub id: RequestId,
    pub payload: ActiveKvStoredPayload,
    state: RequestState,
    prng_key: [u32; 2],
    cache_cap: i32,
    cache_dtype: Dtype,
    prompt_lookup_row: Option<SchedulerPromptLookupRowState>,
    mtp_row: Option<ActiveKvParkedMtpRowState>,
}

/// Read pre-write per-row offsets from the first cache layer that tracks
/// per-row sequence positions (`Full` KV or `Mla` latent). Used by
/// [`Scheduler::step`] to construct the per-row decode mask before the forward.
///
/// All such layers advance their `offsets()` in lockstep across decode steps
/// (per-row offsets diverge across rows but NOT across layers for a given row).
/// Any such layer's offsets view is equivalent — picking the first is arbitrary
/// but consistent. `KVCache::offsets()` and `MlaLatentCache::offsets()` have
/// identical semantics. `Linear` (GatedDelta) caches do not expose per-row
/// offsets and are skipped.
fn first_full_layer_offsets(cache: &[LayerCache]) -> Result<&[i32]> {
    cache
        .iter()
        .find_map(|c| match c {
            LayerCache::Full(kv) => Some(kv.offsets()),
            LayerCache::Mla(mla) => Some(mla.offsets()),
            _ => None,
        })
        .ok_or_else(|| {
            anyhow!(
                "Scheduler::step: no offset-tracking (Full/Mla) layer in cache; per-row offsets unavailable"
            )
        })
}

fn cache_row_cached_len(cache: &[LayerCache], row: usize) -> Result<Option<i32>> {
    if cache.is_empty() {
        return Ok(None);
    }

    let mut cached_len = None;
    for (idx, layer) in cache.iter().enumerate() {
        let layer_offsets = match layer {
            LayerCache::Full(kv) => kv.offsets(),
            LayerCache::Linear(gd) => gd.offsets(),
            LayerCache::Mla(mla) => mla.offsets(),
        };
        let layer_cached_len = *layer_offsets.get(row).ok_or_else(|| {
            anyhow!(
                "cache_row_cached_len: row {} out of range for layer {}",
                row,
                idx
            )
        })?;
        if let Some(expected) = cached_len {
            if layer_cached_len != expected {
                anyhow::bail!(
                    "cache_row_cached_len: layer {idx} cached_len {layer_cached_len} != layer0 {expected}"
                );
            }
        } else {
            cached_len = Some(layer_cached_len);
        }
    }
    Ok(cached_len)
}

fn mtp_cache_row_cached_len(mtp_cache: &MtpCache, row: usize) -> Result<i32> {
    let mut cached_len = None;
    for idx in 0..mtp_cache.num_layers() {
        let layer = mtp_cache.layer(idx);
        let layer_cached_len = *layer.offsets().get(row).ok_or_else(|| {
            anyhow!(
                "mtp_cache_row_cached_len: row {} out of range for layer {}",
                row,
                idx
            )
        })?;
        if let Some(expected) = cached_len {
            if layer_cached_len != expected {
                anyhow::bail!(
                    "mtp_cache_row_cached_len: layer {idx} cached_len {layer_cached_len} != layer0 {expected}"
                );
            }
        } else {
            cached_len = Some(layer_cached_len);
        }
    }
    Ok(cached_len.unwrap_or(0))
}

fn cache_cap_and_dtype(cache: &[LayerCache]) -> Result<(i32, Dtype)> {
    let mut linear_cap = None;
    for layer in cache {
        match layer {
            LayerCache::Full(kv) => return Ok((kv.cap(), kv.dtype())),
            LayerCache::Mla(mla) => return Ok((mla.cap(), mla.dtype())),
            LayerCache::Linear(gd) => {
                linear_cap.get_or_insert(gd.cap());
            }
        };
    }
    linear_cap
        .map(|cap| (cap, Dtype::Bfloat16))
        .ok_or_else(|| anyhow!("cache_cap_and_dtype: cache has no layers"))
}

fn full_layer_cache_row_offset(cache: &[LayerCache], row: usize) -> Result<i32> {
    let mut expected = None;
    for (layer_idx, layer) in cache.iter().enumerate() {
        let LayerCache::Full(kv) = layer else {
            return Err(anyhow!(
                "full_layer_cache_row_offset: Gemma4 drafter requires Full KV at layer {layer_idx}"
            ));
        };
        let offset = *kv.offsets().get(row).ok_or_else(|| {
            anyhow!("full_layer_cache_row_offset: row {row} out of offsets for layer {layer_idx}")
        })?;
        if let Some(expected) = expected {
            if offset != expected {
                return Err(anyhow!(
                    "full_layer_cache_row_offset: row {row} offset {offset} at layer {layer_idx} != {expected}"
                ));
            }
        } else {
            expected = Some(offset);
        }
    }
    expected.ok_or_else(|| anyhow!("full_layer_cache_row_offset: cache has no layers"))
}

fn gemma4_verify_needs_batch_stable_qmm(
    kv_bits: Option<TurboQuantKVBits>,
    batch_width: usize,
    verify_len: usize,
) -> bool {
    kv_bits == Some(TurboQuantKVBits::K3V4) && batch_width > 1 && verify_len > 2
}

const GEMMA4_STABLE_ATTENTION_MIN_CONTEXT_TOKENS: usize = 1024;

fn gemma4_drafter_mid_admit_chunk_cap(
    kv_bits: Option<TurboQuantKVBits>,
    context_tokens: usize,
    prefill_chunk_size: i32,
    decode_cadence_mid_chunk_cap: usize,
) -> usize {
    if kv_bits == Some(TurboQuantKVBits::K3V4)
        && context_tokens > GEMMA4_STABLE_ATTENTION_MIN_CONTEXT_TOKENS
    {
        decode_cadence_mid_chunk_cap.max(prefill_chunk_size.max(1) as usize)
    } else {
        decode_cadence_mid_chunk_cap
    }
}

fn gemma4_long_verify_needs_stable_attention(
    _kv_bits: Option<TurboQuantKVBits>,
    context_tokens: usize,
    verify_len: usize,
    batch_width: usize,
) -> bool {
    context_tokens > GEMMA4_STABLE_ATTENTION_MIN_CONTEXT_TOKENS && verify_len > 1 && batch_width > 0
}

fn gemma4_verify_requires_sequential_q1(
    exact_batched_qualified: bool,
    kv_bits: Option<TurboQuantKVBits>,
    batch_width: usize,
    verify_lens: &[i32],
    verify_width: usize,
) -> bool {
    !exact_batched_qualified
        && kv_bits.is_some()
        && batch_width > 0
        && verify_width > 1
        && verify_lens.iter().all(|&len| len == verify_width as i32)
}

fn build_gemma4_drafter_batched_verify_input(
    active_rows: &[usize],
    contexts: &[Gemma4DrafterBatchedFillContext],
    cache_row_for_ctx: &[usize],
    max_len: usize,
) -> Result<(Array, Vec<i32>)> {
    let b = active_rows.len();
    if b == 0 || max_len == 0 {
        return Err(anyhow!(
            "build_gemma4_drafter_batched_verify_input: empty batch b={b} max_len={max_len}"
        ));
    }
    if contexts.len() != cache_row_for_ctx.len() {
        return Err(anyhow!(
            "build_gemma4_drafter_batched_verify_input: contexts.len()={} != cache_row_for_ctx.len()={}",
            contexts.len(),
            cache_row_for_ctx.len()
        ));
    }
    let mut flat = vec![0_u32; b * max_len];
    let mut lens = vec![0_i32; b];
    for (ctx, &compact_row) in contexts.iter().zip(cache_row_for_ctx.iter()) {
        if compact_row >= b {
            return Err(anyhow!(
                "build_gemma4_drafter_batched_verify_input: compact row {compact_row} >= batch {b}"
            ));
        }
        let input_len = ctx.verify_input.len();
        if input_len == 0 || input_len > max_len {
            return Err(anyhow!(
                "build_gemma4_drafter_batched_verify_input: row {} input_len={input_len} max_len={max_len}",
                ctx.row_idx
            ));
        }
        let start = compact_row * max_len;
        flat[start..start + input_len].copy_from_slice(&ctx.verify_input);
        lens[compact_row] = input_len as i32;
    }
    let arr: Array = (&flat[..], &[b as i32, max_len as i32][..]).try_into()?;
    Ok((arr, lens))
}

fn build_mtp_device_verify_input(
    contexts: &[MtpBatchedFillContext],
    cache_row_for_ctx: &[usize],
    batch: usize,
    max_len: usize,
    target: mlx::StreamOrDevice,
) -> Result<(Array, Vec<i32>)> {
    if batch == 0 || max_len == 0 {
        return Err(anyhow!(
            "build_mtp_device_verify_input: invalid batch={batch} max_len={max_len}"
        ));
    }
    if contexts.len() != cache_row_for_ctx.len() {
        return Err(anyhow!(
            "build_mtp_device_verify_input: contexts.len()={} != cache_row_for_ctx.len()={}",
            contexts.len(),
            cache_row_for_ctx.len()
        ));
    }

    let mut verify = Array::zeros_on(&[batch as i32, max_len as i32][..], Dtype::Uint32, target)?;
    let mut lens = vec![0_i32; batch];
    for (ctx, &compact_row) in contexts.iter().zip(cache_row_for_ctx.iter()) {
        if compact_row >= batch {
            return Err(anyhow!(
                "build_mtp_device_verify_input: compact row {compact_row} >= batch {batch}"
            ));
        }
        let input_len = ctx.draft_tokens.len() + 1;
        if input_len > max_len {
            return Err(anyhow!(
                "build_mtp_device_verify_input: row {} input_len={input_len} > max_len={max_len}",
                ctx.row_idx
            ));
        }
        let current: Array = (&[ctx.current_token][..], &[1_i32, 1_i32][..]).try_into()?;
        let mut token_steps = Vec::with_capacity(input_len);
        token_steps.push(&current);
        token_steps.extend(ctx.draft_tokens.iter());
        let row = mlx::ops::shape::concatenate_on(&token_steps, 1, target)?;
        verify = mlx::ops::indexing::slice_update_on(
            &verify,
            &row,
            &[compact_row as i32, 0_i32][..],
            &[compact_row as i32 + 1, input_len as i32][..],
            &[1_i32, 1_i32][..],
            target,
        )?;
        lens[compact_row] = input_len as i32;
    }
    Ok((verify, lens))
}

fn build_prompt_lookup_device_verify_input(
    contexts: &[PromptLookupBatchedFillContext],
    cache_row_for_ctx: &[usize],
    batch: usize,
    max_len: usize,
    canonical_device_drafts: Option<&[Vec<Array>]>,
    target: mlx::StreamOrDevice,
) -> Result<Array> {
    anyhow::ensure!(
        batch > 0 && max_len >= 2,
        "build_prompt_lookup_device_verify_input: invalid batch={batch} max_len={max_len}"
    );
    anyhow::ensure!(
        contexts.len() == cache_row_for_ctx.len(),
        "build_prompt_lookup_device_verify_input: contexts.len()={} != cache_row_for_ctx.len()={}",
        contexts.len(),
        cache_row_for_ctx.len()
    );

    let mut verify = Array::zeros_on(&[batch as i32, max_len as i32][..], Dtype::Uint32, target)?;
    if let Some(device_drafts) = canonical_device_drafts {
        anyhow::ensure!(
            device_drafts.len() == contexts.len(),
            "build_prompt_lookup_device_verify_input: device drafts {} != contexts {}",
            device_drafts.len(),
            contexts.len()
        );
    }
    for (ctx_idx, (ctx, &compact_row)) in contexts.iter().zip(cache_row_for_ctx.iter()).enumerate()
    {
        anyhow::ensure!(
            compact_row < batch,
            "build_prompt_lookup_device_verify_input: compact row {compact_row} >= batch {batch}"
        );
        let input_len = ctx.draft_tokens.len().saturating_add(1);
        anyhow::ensure!(
            input_len <= max_len,
            "build_prompt_lookup_device_verify_input: row {} input_len={input_len} > max_len={max_len}",
            ctx.row_idx
        );
        let current: Array = (&[ctx.current_token][..], &[1_i32, 1_i32][..]).try_into()?;
        let host_draft_steps;
        let draft_steps = if let Some(device_drafts) = canonical_device_drafts {
            anyhow::ensure!(
                device_drafts[ctx_idx].len() == ctx.draft_tokens.len(),
                "build_prompt_lookup_device_verify_input: row {} device drafts {} != host drafts {}",
                ctx.row_idx,
                device_drafts[ctx_idx].len(),
                ctx.draft_tokens.len()
            );
            &device_drafts[ctx_idx]
        } else {
            host_draft_steps = ctx
                .draft_tokens
                .iter()
                .map(|&token| {
                    Array::try_from((&[token][..], &[1_i32, 1_i32][..])).map_err(Into::into)
                })
                .collect::<Result<Vec<_>>>()?;
            &host_draft_steps
        };
        let mut token_steps = Vec::with_capacity(input_len);
        token_steps.push(&current);
        token_steps.extend(draft_steps.iter());
        let row = mlx::ops::shape::concatenate_on(&token_steps, 1, target)?;
        verify = mlx::ops::indexing::slice_update_on(
            &verify,
            &row,
            &[compact_row as i32, 0_i32][..],
            &[compact_row as i32 + 1, input_len as i32][..],
            &[1_i32, 1_i32][..],
            target,
        )?;
    }
    Ok(verify)
}

fn pack_greedy_acceptance_on(
    verify_input: &Array,
    verify_lens: &[i32],
    verified_ids: &Array,
    target: mlx::StreamOrDevice,
) -> Result<Array> {
    let shape = verify_input.shape();
    let dims = shape.as_slice();
    if dims.len() != 2 || dims[0] <= 0 || dims[1] < 1 {
        return Err(anyhow!(
            "pack_greedy_acceptance_on: expected verify input [B,S>=1], got {dims:?}"
        ));
    }
    if verified_ids.shape().as_slice() != dims {
        return Err(anyhow!(
            "pack_greedy_acceptance_on: verified shape {:?} != verify shape {dims:?}",
            verified_ids.shape().as_slice()
        ));
    }
    let batch = dims[0] as usize;
    let seq = dims[1] as usize;
    if verify_lens.len() != batch || verify_lens.iter().any(|&len| len < 0 || len as usize > seq) {
        return Err(anyhow!(
            "pack_greedy_acceptance_on: invalid verify lengths {verify_lens:?} for shape {dims:?}"
        ));
    }

    if seq == 1 {
        let accepted_len = Array::zeros_on((batch as i32, 1_i32), Dtype::Uint32, target)?;
        return mlx::ops::shape::concatenate_on(&[&accepted_len, verified_ids], 1, target)
            .map_err(Into::into);
    }

    let draft_width = seq - 1;
    let draft_tokens = mlx::ops::indexing::slice_strided_on(
        verify_input,
        &[0_i32, 1_i32][..],
        &[dims[0], dims[1]][..],
        &[1_i32, 1_i32][..],
        target,
    )?;
    let verified_draft_positions = mlx::ops::indexing::slice_strided_on(
        verified_ids,
        &[0_i32, 0_i32][..],
        &[dims[0], draft_width as i32][..],
        &[1_i32, 1_i32][..],
        target,
    )?;
    let draft_lens = verify_lens
        .iter()
        .map(|&len| len.saturating_sub(1) as u32)
        .collect::<Vec<_>>();
    let draft_lens_arr: Array = (&draft_lens[..], &[batch as i32, 1_i32][..]).try_into()?;
    let positions =
        mlx::ops::constructors::arange_on(0.0, draft_width as f64, 1.0, Dtype::Uint32, target)?
            .reshape_on(&[1_i32, draft_width as i32][..], target)?;
    let valid = positions.less_on(&draft_lens_arr, target)?;
    let matches = draft_tokens.equal_on(&verified_draft_positions, target)?;
    let all_valid_matches = mlx::ops::indexing::where_on(
        &valid,
        &matches,
        &mlx::ops::constructors::ones_on(
            &[batch as i32, draft_width as i32][..],
            Dtype::Bool,
            target,
        )?,
        target,
    )?;
    let accepted_prefix = all_valid_matches
        .astype_on(Dtype::Uint32, target)?
        .cumprod_on(1, false, true, target)?;
    let accepted_mask = mlx::ops::binary::multiply_on(
        &accepted_prefix,
        &valid.astype_on(Dtype::Uint32, target)?,
        target,
    )?;
    let accepted_len = accepted_mask.sum_on(1, true, target)?;
    let corrected = verified_ids.take_along_axis_on(&accepted_len, 1, target)?;
    mlx::ops::shape::concatenate_on(&[&accepted_len, &draft_tokens, &corrected], 1, target)
        .map_err(Into::into)
}

fn resolve_packed_greedy_acceptance(
    packed: &[u32],
    packed_stride: usize,
    compact_row: usize,
    draft_len: usize,
) -> Result<(Vec<u32>, SpeculativeResolution)> {
    let row_start = compact_row
        .checked_mul(packed_stride)
        .ok_or_else(|| anyhow!("resolve_packed_greedy_acceptance: row offset overflow"))?;
    let row = packed
        .get(row_start..row_start + packed_stride)
        .ok_or_else(|| {
            anyhow!(
                "resolve_packed_greedy_acceptance: row {compact_row} outside packed len {} stride {packed_stride}",
                packed.len()
            )
        })?;
    let accepted_draft_len = row[0] as usize;
    if accepted_draft_len > draft_len || draft_len + 2 > packed_stride {
        return Err(anyhow!(
            "resolve_packed_greedy_acceptance: accepted={accepted_draft_len} draft={draft_len} stride={packed_stride}"
        ));
    }
    let draft_tokens = row[1..1 + draft_len].to_vec();
    let corrected = row[packed_stride - 1];
    let mut tokens_to_append = draft_tokens[..accepted_draft_len].to_vec();
    tokens_to_append.push(corrected);
    Ok((
        draft_tokens,
        SpeculativeResolution {
            accepted_draft_len,
            tokens_to_append,
            accepted_verify_input_len: accepted_draft_len + 1,
            needs_rollback: accepted_draft_len < draft_len,
            exact_sampling: Default::default(),
        },
    ))
}

fn slice_hidden_row_position(
    hidden: &Array,
    row_idx: usize,
    pos: usize,
    target: mlx::StreamOrDevice,
) -> Result<Array> {
    let shape = hidden.shape();
    let dims = shape.as_slice();
    if dims.len() != 3 {
        return Err(anyhow!(
            "slice_hidden_row_position: expected hidden [B,S,H], got {dims:?}"
        ));
    }
    if row_idx as i32 >= dims[0] || pos as i32 >= dims[1] {
        return Err(anyhow!(
            "slice_hidden_row_position: row={row_idx} pos={pos} out of shape {dims:?}"
        ));
    }
    mlx::ops::indexing::slice_strided_on(
        hidden,
        &[row_idx as i32, pos as i32, 0_i32][..],
        &[row_idx as i32 + 1, pos as i32 + 1, dims[2]][..],
        &[1_i32, 1, 1][..],
        target,
    )
    .map_err(Into::into)
}

fn slice_logits_row_position(logits: &Array, row_idx: usize, pos: usize) -> Result<Array> {
    let shape = logits.shape();
    let dims = shape.as_slice();
    anyhow::ensure!(
        dims.len() == 3 && row_idx < dims[0] as usize && pos < dims[1] as usize,
        "slice_logits_row_position: row={row_idx} pos={pos} out of shape {dims:?}"
    );
    let sliced = mlx::ops::indexing::slice_strided(
        logits,
        &[row_idx as i32, pos as i32, 0_i32][..],
        &[row_idx as i32 + 1, pos as i32 + 1, dims[2]][..],
        &[1_i32, 1_i32, 1_i32][..],
    )?;
    sliced.reshape((dims[2],)).map_err(Into::into)
}

fn slice_hidden_row_prefix(
    hidden: &Array,
    row_idx: usize,
    len: usize,
    target: mlx::StreamOrDevice,
) -> Result<Array> {
    let shape = hidden.shape();
    let dims = shape.as_slice();
    if dims.len() != 3 {
        return Err(anyhow!(
            "slice_hidden_row_prefix: expected hidden [B,S,H], got {dims:?}"
        ));
    }
    if len == 0 || row_idx as i32 >= dims[0] || len as i32 > dims[1] {
        return Err(anyhow!(
            "slice_hidden_row_prefix: row={row_idx} len={len} out of shape {dims:?}"
        ));
    }
    mlx::ops::indexing::slice_strided_on(
        hidden,
        &[row_idx as i32, 0_i32, 0_i32][..],
        &[row_idx as i32 + 1, len as i32, dims[2]][..],
        &[1_i32, 1_i32, 1_i32][..],
        target,
    )
    .map_err(Into::into)
}

fn slice_position_ids_row_position(
    position_ids: &Array,
    row_idx: usize,
    pos: usize,
    target: mlx::StreamOrDevice,
) -> Result<Array> {
    let shape = position_ids.shape();
    let dims = shape.as_slice();
    match dims {
        [1, 1] => Ok(position_ids.clone()),
        [1, seq] => {
            if row_idx != 0 || pos as i32 >= *seq {
                return Err(anyhow!(
                    "slice_position_ids_row_position: row={row_idx} pos={pos} out of shape {dims:?}"
                ));
            }
            mlx::ops::indexing::slice_strided_on(
                position_ids,
                &[0_i32, pos as i32][..],
                &[1_i32, pos as i32 + 1][..],
                &[1_i32, 1_i32][..],
                target,
            )
            .map_err(Into::into)
        }
        [planes, batch, seq] => {
            if row_idx as i32 >= *batch || pos as i32 >= *seq {
                return Err(anyhow!(
                    "slice_position_ids_row_position: row={row_idx} pos={pos} out of shape {dims:?}"
                ));
            }
            mlx::ops::indexing::slice_strided_on(
                position_ids,
                &[0_i32, row_idx as i32, pos as i32][..],
                &[*planes, row_idx as i32 + 1, pos as i32 + 1][..],
                &[1_i32, 1_i32, 1_i32][..],
                target,
            )
            .map_err(Into::into)
        }
        _ => Err(anyhow!(
            "slice_position_ids_row_position: expected position_ids [1,1], [1,S], or [P,B,S], got {:?}",
            dims
        )),
    }
}

fn concatenate_position_id_steps(
    left: &Array,
    right: &Array,
    target: mlx::StreamOrDevice,
) -> Result<Array> {
    let left_shape = left.shape();
    let right_shape = right.shape();
    let left_dims = left_shape.as_slice();
    let right_dims = right_shape.as_slice();
    match (left_dims, right_dims) {
        ([1, 1], [1, 1]) => Ok(left.clone()),
        ([1, left_seq], [1, right_seq]) => {
            if *left_seq != 1 || *right_seq != 1 {
                return Err(anyhow!(
                    "concatenate_position_id_steps: expected single-step [1,1] ids, got {:?} and {:?}",
                    left_dims,
                    right_dims
                ));
            }
            mlx::ops::shape::concatenate_on(&[left, right], 1, target).map_err(Into::into)
        }
        ([planes, 1, left_seq], [right_planes, 1, right_seq]) => {
            if *planes != *right_planes || *left_seq != 1 || *right_seq != 1 {
                return Err(anyhow!(
                    "concatenate_position_id_steps: expected matching single-step [P,1,1] ids, got {:?} and {:?}",
                    left_dims,
                    right_dims
                ));
            }
            mlx::ops::shape::concatenate_on(&[left, right], 2, target).map_err(Into::into)
        }
        _ => Err(anyhow!(
            "concatenate_position_id_steps: expected [1,1] or [P,1,1] ids, got {:?} and {:?}",
            left_dims,
            right_dims
        )),
    }
}

fn build_mtp_batched_position_ids(starts: &[i32], lens: &[i32], max_len: i32) -> Result<Array> {
    if starts.len() != lens.len() {
        return Err(anyhow!(
            "build_mtp_batched_position_ids: starts len {} != lens len {}",
            starts.len(),
            lens.len()
        ));
    }
    if starts.is_empty() {
        return Err(anyhow!("build_mtp_batched_position_ids: batch is empty"));
    }
    if max_len <= 0 {
        return Err(anyhow!(
            "build_mtp_batched_position_ids: max_len must be > 0, got {max_len}"
        ));
    }
    let b = starts.len();
    let s = max_len as usize;
    let mut one_stream = vec![0_i32; b * s];
    for (row, (&start, &len)) in starts.iter().zip(lens.iter()).enumerate() {
        if start < 0 {
            return Err(anyhow!(
                "build_mtp_batched_position_ids: starts[{row}] = {start} must be >= 0"
            ));
        }
        if len < 0 || len > max_len {
            return Err(anyhow!(
                "build_mtp_batched_position_ids: lens[{row}] = {len} out of [0, {max_len}]"
            ));
        }
        for col in 0..len as usize {
            one_stream[row * s + col] = start + col as i32;
        }
    }
    let mut flat = Vec::with_capacity(3 * b * s);
    for _ in 0..3 {
        flat.extend_from_slice(&one_stream);
    }
    let arr: Array = (&flat[..], &[3_i32, b as i32, max_len][..]).try_into()?;
    Ok(arr)
}

fn row_tokens_from_flat(
    flat: &[u32],
    row_idx: usize,
    row_stride: usize,
    len: usize,
) -> Result<Vec<u32>> {
    let start = row_idx.checked_mul(row_stride).ok_or_else(|| {
        anyhow!("row_tokens_from_flat: row_idx={row_idx} row_stride={row_stride} overflow")
    })?;
    let end = start + len;
    if row_stride < len || end > flat.len() {
        return Err(anyhow!(
            "row_tokens_from_flat: row={row_idx} stride={row_stride} len={len} flat_len={}",
            flat.len()
        ));
    }
    Ok(flat[start..end].to_vec())
}

fn append_resolved_gemma4_tokens(
    row_state: &mut SchedulerGemma4DrafterRowState,
    ctx: &Gemma4DrafterBatchedFillContext,
    constraint: Option<&crate::core::constrained::ConstraintSession>,
    resolution: SpeculativeResolution,
) -> Result<usize> {
    let mut tokens_to_append = resolution.tokens_to_append;
    if let Some(stop_idx) = tokens_to_append
        .iter()
        .position(|token| ctx.stop_token_ids.contains(token))
    {
        tokens_to_append.truncate(stop_idx + 1);
    }
    tokens_to_append.truncate(ctx.remaining);
    if let Some(constraint) = constraint {
        constraint.truncate_invalid_speculative_bonus(&mut tokens_to_append)?;
    }
    let committed_tokens = tokens_to_append.len();
    row_state.pending_tokens.extend(tokens_to_append);
    Ok(committed_tokens)
}

fn active_kv_entry_supported(entry: &PagedPrefixEntry) -> bool {
    !entry.main_layers.is_empty()
        && (entry.mtp_layers.is_empty() == entry.mtp_last_hidden.is_none())
        && entry.gemma4_drafter_last_hidden.is_none()
        && ActiveKvEntryChunkReader::new(entry)
            .chunks()
            .all(|chunk| chunk.kind.is_supported_for_active_offload())
}

#[allow(clippy::manual_div_ceil)]
pub(crate) fn default_active_kv_hot_window_pages(block_size: i32) -> i32 {
    let block_size = block_size.max(1);
    ((1024 + block_size - 1) / block_size).max(2)
}

#[allow(clippy::manual_div_ceil)]
fn active_kv_budget_pages_for(
    block_size: i32,
    cache_cap: i32,
    batch: i32,
    soft_limit_bytes: usize,
    bytes_per_token: usize,
) -> i32 {
    let block_size = block_size.max(1);
    let cache_cap = cache_cap.max(1);
    let cache_cap_pages = ((cache_cap + block_size - 1) / block_size).max(1);

    let batch = usize::try_from(batch.max(1)).unwrap_or(1);
    let bytes_per_token = bytes_per_token.max(1);
    let budget_tokens_per_row = soft_limit_bytes / bytes_per_token / batch;
    let budget_tokens_per_row = i32::try_from(budget_tokens_per_row)
        .unwrap_or(i32::MAX)
        .max(1);

    ((budget_tokens_per_row + block_size - 1) / block_size).clamp(1, cache_cap_pages)
}

#[allow(clippy::manual_div_ceil)]
pub(crate) fn active_kv_hot_window_pages_for_budget(
    block_size: i32,
    cache_cap: i32,
    batch: i32,
    soft_limit_bytes: usize,
    bytes_per_token: usize,
) -> i32 {
    let block_size = block_size.max(1);
    let cache_cap = cache_cap.max(1);
    let cache_cap_pages = ((cache_cap + block_size - 1) / block_size).max(1);
    let floor_pages = default_active_kv_hot_window_pages(block_size).min(cache_cap_pages);
    let budget_pages = active_kv_budget_pages_for(
        block_size,
        cache_cap,
        batch,
        soft_limit_bytes,
        bytes_per_token,
    );

    budget_pages.clamp(floor_pages, cache_cap_pages)
}

#[cfg(test)]
#[allow(clippy::manual_div_ceil)]
fn default_active_kv_chunk_pages(block_size: i32) -> i32 {
    const TARGET_TOKENS: i32 = 2048;
    const MIN_CHUNK_PAGES: i32 = 4;
    const MAX_CHUNK_PAGES: i32 = 16;

    let block_size = block_size.max(1);
    ((TARGET_TOKENS + block_size - 1) / block_size).clamp(MIN_CHUNK_PAGES, MAX_CHUNK_PAGES)
}

#[allow(clippy::manual_div_ceil)]
pub(crate) fn active_kv_chunk_pages_for_budget(
    block_size: i32,
    cache_cap: i32,
    batch: i32,
    soft_limit_bytes: usize,
    bytes_per_token: usize,
    hot_window_pages: i32,
) -> i32 {
    let block_size = block_size.max(1);
    let cache_cap = cache_cap.max(1);
    let cache_cap_pages = ((cache_cap + block_size - 1) / block_size).max(1);
    let budget_pages = active_kv_budget_pages_for(
        block_size,
        cache_cap,
        batch,
        soft_limit_bytes,
        bytes_per_token,
    );
    let hot_window_pages = hot_window_pages.clamp(0, cache_cap_pages);
    let remaining_budget_pages = budget_pages.saturating_sub(hot_window_pages).max(1);
    let remaining_cache_pages = cache_cap_pages.saturating_sub(hot_window_pages).max(1);

    remaining_budget_pages.min(remaining_cache_pages)
}

fn cached_token_prefix_for_state(state: &RequestState, cached_len: i32) -> Result<Vec<u32>> {
    cached_token_prefix_for_state_and_pending(state, None, cached_len)
}

fn cached_token_prefix_for_state_and_pending(
    state: &RequestState,
    pending_tokens: Option<&VecDeque<u32>>,
    cached_len: i32,
) -> Result<Vec<u32>> {
    anyhow::ensure!(
        cached_len >= 0,
        "cached_token_prefix_for_state: cached_len {cached_len} is negative"
    );
    let cached_len = usize::try_from(cached_len)
        .map_err(|_| anyhow!("cached_token_prefix_for_state: cached_len overflow"))?;
    let mut tokens = Vec::with_capacity(state.prompt_ids.len() + state.generated_tokens.len());
    tokens.extend_from_slice(&state.prompt_ids);
    tokens.extend_from_slice(&state.generated_tokens);
    if let Some(pending_tokens) = pending_tokens {
        tokens.extend(pending_tokens.iter().copied());
    }
    anyhow::ensure!(
        cached_len <= tokens.len(),
        "cached_token_prefix_for_state: cached_len {cached_len} exceeds available tokens {}",
        tokens.len()
    );
    tokens.truncate(cached_len);
    Ok(tokens)
}

fn adopt_cache_row_layers(
    dst: &mut [LayerCache],
    src: &[LayerCache],
    dst_row: usize,
    src_row: usize,
    context: &str,
) -> Result<()> {
    if dst.len() != src.len() {
        return Err(anyhow!(
            "{context}: cache layer count mismatch ({} vs {})",
            dst.len(),
            src.len()
        ));
    }
    for (dst_layer, src_layer) in dst.iter_mut().zip(src.iter()) {
        match (dst_layer, src_layer) {
            (LayerCache::Full(dst_kv), LayerCache::Full(src_kv)) => {
                dst_kv.adopt_row_from(src_kv, dst_row, src_row)?;
            }
            (LayerCache::Linear(dst_gd), LayerCache::Linear(src_gd)) => {
                dst_gd.adopt_row_from(src_gd, dst_row, src_row)?;
            }
            (LayerCache::Mla(dst_mla), LayerCache::Mla(src_mla)) => {
                dst_mla.adopt_row_from(src_mla, dst_row, src_row)?;
            }
            _ => return Err(anyhow!("{context}: cache layer kind mismatch")),
        }
    }
    Ok(())
}

fn adopt_cache_row_layers_skipping_reused_paged(
    dst: &mut [LayerCache],
    src: &[LayerCache],
    dst_row: usize,
    src_row: usize,
    context: &str,
) -> Result<()> {
    if dst.len() != src.len() {
        return Err(anyhow!(
            "{context}: cache layer count mismatch ({} vs {})",
            dst.len(),
            src.len()
        ));
    }
    for (dst_layer, src_layer) in dst.iter_mut().zip(src.iter()) {
        match (dst_layer, src_layer) {
            (LayerCache::Full(dst_kv), LayerCache::Full(src_kv)) => {
                if dst_kv.paged().is_none() || src_kv.paged().is_none() {
                    dst_kv.adopt_row_from(src_kv, dst_row, src_row)?;
                }
            }
            (LayerCache::Linear(dst_gd), LayerCache::Linear(src_gd)) => {
                dst_gd.adopt_row_from(src_gd, dst_row, src_row)?;
            }
            (LayerCache::Mla(dst_mla), LayerCache::Mla(src_mla)) => {
                dst_mla.adopt_row_from(src_mla, dst_row, src_row)?;
            }
            _ => return Err(anyhow!("{context}: cache layer kind mismatch")),
        }
    }
    Ok(())
}

fn reuse_full_paged_storage(
    dst: &mut [LayerCache],
    src: &mut [LayerCache],
    owners: &[PagedKvBlockOwner],
    context: &str,
) -> Result<bool> {
    anyhow::ensure!(
        dst.len() == src.len(),
        "{context}: cache layer count mismatch ({} vs {})",
        dst.len(),
        src.len()
    );
    for (dst_layer, src_layer) in dst.iter().zip(src.iter()) {
        match (dst_layer, src_layer) {
            (LayerCache::Full(dst_kv), LayerCache::Full(src_kv)) => {
                dst_kv.validate_paged_storage_reuse_from(src_kv, owners)?;
            }
            (LayerCache::Linear(_), LayerCache::Linear(_))
            | (LayerCache::Mla(_), LayerCache::Mla(_)) => {}
            _ => return Err(anyhow!("{context}: cache layer kind mismatch")),
        }
    }
    let mut reused = false;
    for (dst_layer, src_layer) in dst.iter_mut().zip(src.iter_mut()) {
        match (dst_layer, src_layer) {
            (LayerCache::Full(dst_kv), LayerCache::Full(src_kv)) => {
                reused |= dst_kv.reuse_paged_storage_from(src_kv, owners)?;
            }
            (LayerCache::Linear(_), LayerCache::Linear(_))
            | (LayerCache::Mla(_), LayerCache::Mla(_)) => {}
            _ => return Err(anyhow!("{context}: cache layer kind mismatch")),
        }
    }
    Ok(reused)
}

fn bind_full_paged_cache_owners(
    cache: &mut [LayerCache],
    owners: &[PagedKvBlockOwner],
) -> Result<()> {
    for layer in cache {
        if let LayerCache::Full(kv) = layer {
            kv.bind_paged_execution_rows(owners)?;
        }
    }
    Ok(())
}

fn release_full_paged_cache_owner(
    cache: &mut [LayerCache],
    owner: PagedKvBlockOwner,
) -> Result<bool> {
    let mut released = false;
    for layer in cache {
        if let LayerCache::Full(kv) = layer {
            released |= kv.release_paged_owner(owner)?;
        }
    }
    Ok(released)
}

fn full_paged_owner_offset(cache: &[LayerCache], owner: PagedKvBlockOwner) -> Result<Option<i32>> {
    let mut owner_offset = None;
    for layer in cache {
        let LayerCache::Full(kv) = layer else {
            continue;
        };
        let Some(offset) = kv.paged_owner_offset(owner) else {
            continue;
        };
        if let Some(expected) = owner_offset {
            anyhow::ensure!(
                expected == offset,
                "FullPaged owner {owner:?} has inconsistent layer offsets {expected} and {offset}"
            );
        } else {
            owner_offset = Some(offset);
        }
    }
    Ok(owner_offset)
}

fn fork_full_paged_cache_owner(
    cache: &mut [LayerCache],
    source: PagedKvBlockOwner,
    destination: PagedKvBlockOwner,
) -> Result<bool> {
    let mut has_paged = false;
    for layer in cache.iter_mut() {
        if let LayerCache::Full(kv) = layer {
            has_paged |= kv.validate_paged_owner_fork(source, destination)?;
        }
    }
    if !has_paged {
        return Ok(false);
    }
    for layer in cache.iter_mut() {
        if let LayerCache::Full(kv) = layer {
            kv.fork_paged_owner_prevalidated(source, destination);
        }
    }
    validate_full_paged_owner_invariants(cache)?;
    Ok(true)
}

fn pin_full_paged_immutable_block(
    cache: &mut [LayerCache],
    source: PagedKvBlockOwner,
    block_index: i32,
    pin: PagedKvBlockOwner,
) -> Result<Option<ImmutablePrefixBlockBundle>> {
    let mut handles = Vec::new();
    for layer in cache.iter_mut() {
        if let LayerCache::Full(kv) = layer {
            if let Some(handle) = kv.validate_paged_immutable_block_pin(source, block_index, pin)? {
                handles.push(handle);
            }
        }
    }
    if handles.is_empty() {
        return Ok(None);
    }
    let mut handle_index = 0_usize;
    for layer in cache.iter_mut() {
        if let LayerCache::Full(kv) = layer {
            if kv.pin_paged_immutable_block_prevalidated(pin, handles[handle_index]) {
                handle_index += 1;
            }
        }
    }
    anyhow::ensure!(
        handle_index == handles.len(),
        "immutable block pin layer count changed after preflight"
    );
    validate_full_paged_owner_invariants(cache)?;
    Ok(Some(ImmutablePrefixBlockBundle { pin, handles }))
}

fn install_full_paged_immutable_prefix(
    cache: &mut [LayerCache],
    destination: PagedKvBlockOwner,
    bundles: &[ImmutablePrefixBlockBundle],
) -> Result<bool> {
    if bundles.is_empty() {
        return Ok(false);
    }
    let layer_count = bundles[0].handles.len();
    anyhow::ensure!(
        layer_count > 0
            && bundles
                .iter()
                .all(|bundle| bundle.handles.len() == layer_count),
        "immutable prefix bundle layer count mismatch"
    );
    let mut paged_layer = 0_usize;
    for layer in cache.iter_mut() {
        if let LayerCache::Full(kv) = layer {
            let handles = bundles
                .iter()
                .map(|bundle| bundle.handles[paged_layer])
                .collect::<Vec<_>>();
            if kv.validate_paged_immutable_prefix_install(destination, &handles)? {
                paged_layer += 1;
            }
        }
    }
    anyhow::ensure!(
        paged_layer == layer_count,
        "immutable prefix install expected {layer_count} paged layers, found {paged_layer}"
    );
    paged_layer = 0;
    for layer in cache.iter_mut() {
        if let LayerCache::Full(kv) = layer {
            let handles = bundles
                .iter()
                .map(|bundle| bundle.handles[paged_layer])
                .collect::<Vec<_>>();
            if kv.install_paged_immutable_prefix_prevalidated(destination, &handles) {
                paged_layer += 1;
            }
        }
    }
    validate_full_paged_owner_invariants(cache)?;
    Ok(true)
}

fn immutable_bundle_has_request_refs(
    cache: &[LayerCache],
    bundle: &ImmutablePrefixBlockBundle,
) -> Result<bool> {
    let mut paged_layer = 0_usize;
    let mut active = false;
    for layer in cache {
        if let LayerCache::Full(kv) = layer {
            let Some(has_request_refs) =
                kv.paged_immutable_handle_has_request_refs(bundle.handles[paged_layer])?
            else {
                continue;
            };
            active |= has_request_refs;
            paged_layer += 1;
        }
    }
    anyhow::ensure!(
        paged_layer == bundle.handles.len(),
        "immutable bundle expected {} paged layers, found {paged_layer}",
        bundle.handles.len()
    );
    Ok(active)
}

fn full_paged_page_bytes(cache: &[LayerCache]) -> usize {
    cache.iter().fold(0_usize, |total, layer| match layer {
        LayerCache::Full(kv) => total.saturating_add(kv.paged_page_bytes().unwrap_or(0)),
        LayerCache::Linear(_) | LayerCache::Mla(_) => total,
    })
}

fn cache_is_fullpaged_only(cache: &[LayerCache]) -> bool {
    !cache.is_empty()
        && cache.iter().all(|layer| match layer {
            LayerCache::Full(kv) => kv.paged().is_some(),
            LayerCache::Linear(_) | LayerCache::Mla(_) => false,
        })
}

fn full_paged_available_unique_pages(cache: &[LayerCache]) -> Option<usize> {
    let mut available = None;
    for layer in cache {
        match layer {
            LayerCache::Full(kv) => {
                let layer_available = kv.paged_available_unique_pages()?;
                available = Some(available.map_or(layer_available, |current: usize| {
                    current.min(layer_available)
                }));
            }
            LayerCache::Linear(_) | LayerCache::Mla(_) => return None,
        }
    }
    available
}

fn additional_full_paged_pages_for_targets(
    cache: &[LayerCache],
    block_size: usize,
    targets: &[(PagedKvBlockOwner, usize)],
) -> Result<usize> {
    targets.iter().try_fold(0_usize, |total, &(owner, target)| {
        let offset = usize::try_from(full_paged_owner_offset(cache, owner)?.unwrap_or(0))
            .map_err(|_| anyhow!("FullPaged owner {owner:?} has a negative offset"))?;
        let current_pages = offset.div_ceil(block_size);
        let target_pages = target.div_ceil(block_size);
        Ok(total.saturating_add(target_pages.saturating_sub(current_pages)))
    })
}

fn validate_full_paged_owner_invariants(cache: &[LayerCache]) -> Result<()> {
    for layer in cache {
        if let LayerCache::Full(kv) = layer {
            kv.validate_paged_owner_invariants()?;
        }
    }
    Ok(())
}

fn add_paged_physical_stats(total: &mut PagedKvPhysicalStats, layer: PagedKvPhysicalStats) {
    total.physical_pages_total = total
        .physical_pages_total
        .saturating_add(layer.physical_pages_total);
    total.physical_pages_free = total
        .physical_pages_free
        .saturating_add(layer.physical_pages_free);
    total.physical_pages_referenced = total
        .physical_pages_referenced
        .saturating_add(layer.physical_pages_referenced);
    total.shared_physical_pages = total
        .shared_physical_pages
        .saturating_add(layer.shared_physical_pages);
    total.shared_page_references = total
        .shared_page_references
        .saturating_add(layer.shared_page_references);
    total.max_page_refcount = total.max_page_refcount.max(layer.max_page_refcount);
    total.request_owned_tables = total
        .request_owned_tables
        .saturating_add(layer.request_owned_tables);
    total.transient_owned_tables = total
        .transient_owned_tables
        .saturating_add(layer.transient_owned_tables);
    total.immutable_pinned_tables = total
        .immutable_pinned_tables
        .saturating_add(layer.immutable_pinned_tables);
    total.immutable_pinned_pages = total
        .immutable_pinned_pages
        .saturating_add(layer.immutable_pinned_pages);
    total.orphan_pages = total.orphan_pages.saturating_add(layer.orphan_pages);
    total.cow_page_copies = total.cow_page_copies.saturating_add(layer.cow_page_copies);
    total.adopt_page_copies = total
        .adopt_page_copies
        .saturating_add(layer.adopt_page_copies);
    total.owner_forks = total.owner_forks.saturating_add(layer.owner_forks);
    total.forked_page_references = total
        .forked_page_references
        .saturating_add(layer.forked_page_references);
    total.owner_releases = total.owner_releases.saturating_add(layer.owner_releases);
}

fn paged_adopt_page_copies(cache: &[LayerCache]) -> u64 {
    cache
        .iter()
        .filter_map(|layer| match layer {
            LayerCache::Full(kv) => kv.paged_physical_stats(),
            LayerCache::Linear(_) | LayerCache::Mla(_) => None,
        })
        .fold(0_u64, |total, stats| {
            total.saturating_add(stats.adopt_page_copies)
        })
}

fn update_prefix_fingerprint_hash(hash: &mut u64, bytes: &[u8]) {
    const FNV_PRIME: u64 = 0x0000_0100_0000_01b3;
    for &byte in bytes {
        *hash ^= u64::from(byte);
        *hash = hash.wrapping_mul(FNV_PRIME);
    }
}

fn update_prefix_fingerprint_i32(hash: &mut u64, value: i32) {
    update_prefix_fingerprint_hash(hash, &value.to_le_bytes());
}

fn update_prefix_fingerprint_usize(hash: &mut u64, value: usize) {
    update_prefix_fingerprint_hash(hash, &value.to_le_bytes());
}

fn update_prefix_fingerprint_str(hash: &mut u64, value: &str) {
    update_prefix_fingerprint_usize(hash, value.len());
    update_prefix_fingerprint_hash(hash, value.as_bytes());
}

fn generate_request_from_state(state: &RequestState) -> Result<GenerateRequest> {
    Ok(GenerateRequest {
        prompt_ids: state.prompt_ids.clone(),
        max_new_tokens: state.max_new_tokens,
        sampler: state.sampler,
        stop_token_ids: state.stop_token_ids.clone(),
        prefill_chunk_size: usize::try_from(state.prefill_chunk_size)
            .map_err(|_| anyhow!("generate_request_from_state: negative prefill_chunk_size"))?,
        decode_cadence_mid_chunk_cap: state.decode_cadence_mid_chunk_cap,
        kv_cache_turboquant_bits: state.kv_cache_turboquant_bits,
        pixel_values: state.pixel_values.clone(),
        image_grid_thw: state.image_grid_thw.clone(),
        image_spatial_merge_size: state.image_spatial_merge_size,
        image_token_id: state.image_token_id,
        constraint: state.constraint_plan.clone(),
    })
}

fn generate_neural_rebase_request_from_state(state: &RequestState) -> Result<GenerateRequest> {
    anyhow::ensure!(
        !state.finished,
        "neural rebase requires an unfinished request"
    );
    let emitted = state.generated_tokens.len();
    anyhow::ensure!(
        emitted > 0,
        "neural rebase requires at least one committed generated token"
    );
    let mut prompt_ids = Vec::with_capacity(
        state
            .prompt_ids
            .len()
            .saturating_add(emitted)
            .saturating_sub(1),
    );
    prompt_ids.extend_from_slice(&state.prompt_ids);
    prompt_ids.extend_from_slice(&state.generated_tokens[..emitted - 1]);
    let max_new_tokens = state
        .max_new_tokens
        .saturating_sub(emitted)
        .saturating_add(1);
    anyhow::ensure!(
        max_new_tokens > 0,
        "neural rebase requires at least one remaining token"
    );
    Ok(GenerateRequest {
        prompt_ids,
        max_new_tokens,
        sampler: state.sampler,
        stop_token_ids: state.stop_token_ids.clone(),
        prefill_chunk_size: usize::try_from(state.prefill_chunk_size).map_err(|_| {
            anyhow!("generate_neural_rebase_request_from_state: negative prefill_chunk_size")
        })?,
        decode_cadence_mid_chunk_cap: state.decode_cadence_mid_chunk_cap,
        kv_cache_turboquant_bits: state.kv_cache_turboquant_bits,
        pixel_values: state.pixel_values.clone(),
        image_grid_thw: state.image_grid_thw.clone(),
        image_spatial_merge_size: state.image_spatial_merge_size,
        image_token_id: state.image_token_id,
        constraint: state.constraint_plan.clone(),
    })
}

fn add_mtp_stats(dst: &mut MtpSpeculativeStats, src: MtpSpeculativeStats) {
    dst.merge_from(src);
}

fn divided_mtp_stats_timing(stats: &MtpSpeculativeStats, divisor: u64) -> MtpSpeculativeStats {
    debug_assert!(divisor > 0);
    MtpSpeculativeStats {
        draft_forward_us: stats.draft_forward_us / divisor,
        verify_forward_us: stats.verify_forward_us / divisor,
        projection_us: stats.projection_us / divisor,
        sampling_us: stats.sampling_us / divisor,
        verify_accept_host_sync_us: stats.verify_accept_host_sync_us / divisor,
        main_rollback_us: stats.main_rollback_us / divisor,
        mtp_cache_commit_us: stats.mtp_cache_commit_us / divisor,
        mtp_prefill_cache_commit_us: stats.mtp_prefill_cache_commit_us / divisor,
        mtp_decode_cache_commit_us: stats.mtp_decode_cache_commit_us / divisor,
        mtp_cache_restore_us: stats.mtp_cache_restore_us / divisor,
        ..MtpSpeculativeStats::default()
    }
}

pub(crate) fn paged_prefix_fingerprint_for_request(
    pixel_values: Option<&[Array]>,
    image_grid_thw: Option<&[(i32, i32, i32)]>,
    image_token_id: i32,
    image_spatial_merge_size: i32,
) -> Result<Option<String>> {
    let Some(pixel_values) = pixel_values else {
        return Ok(None);
    };
    let grids = image_grid_thw.ok_or_else(|| {
        anyhow!("paged prefix cache VL fingerprint: pixel_values present but grid_thw is None")
    })?;

    let mut hash = 0xcbf2_9ce4_8422_2325_u64;
    update_prefix_fingerprint_str(&mut hash, "ironmlx-vl-prefix-v1");
    update_prefix_fingerprint_i32(&mut hash, image_token_id);
    update_prefix_fingerprint_i32(&mut hash, image_spatial_merge_size);
    update_prefix_fingerprint_usize(&mut hash, grids.len());
    for &(t, h, w) in grids {
        update_prefix_fingerprint_i32(&mut hash, t);
        update_prefix_fingerprint_i32(&mut hash, h);
        update_prefix_fingerprint_i32(&mut hash, w);
    }

    update_prefix_fingerprint_usize(&mut hash, pixel_values.len());
    for pixel_array in pixel_values {
        update_prefix_fingerprint_str(&mut hash, &pixel_array.dtype().to_string());
        let shape = pixel_array.shape();
        update_prefix_fingerprint_usize(&mut hash, shape.as_slice().len());
        for &dim in shape.as_slice() {
            update_prefix_fingerprint_i32(&mut hash, dim);
        }
        let values = mlx::ops::astype(pixel_array, Dtype::Float32)?.to_vec::<f32>()?;
        update_prefix_fingerprint_usize(&mut hash, values.len());
        for value in values {
            update_prefix_fingerprint_hash(&mut hash, &value.to_bits().to_le_bytes());
        }
    }

    Ok(Some(format!("vl:{hash:016x}")))
}

fn immutable_prefix_chain_hash(model_id: &str, parent_hash: Option<u64>, tokens: &[u32]) -> u64 {
    let mut hash = 0xcbf2_9ce4_8422_2325_u64;
    update_prefix_fingerprint_str(&mut hash, "ironmlx-fullpaged-block-v1");
    update_prefix_fingerprint_str(&mut hash, model_id);
    update_prefix_fingerprint_hash(&mut hash, &parent_hash.unwrap_or(0).to_le_bytes());
    update_prefix_fingerprint_usize(&mut hash, tokens.len());
    for &token in tokens {
        update_prefix_fingerprint_hash(&mut hash, &token.to_le_bytes());
    }
    hash
}

fn evict_one_idle_immutable_leaf(
    pool: &mut ImmutablePrefixBlockPool,
    cache: &mut [LayerCache],
    protected: &HashSet<u64>,
    pressure_reclaim: bool,
) -> Result<bool> {
    let mut candidates = pool
        .entries
        .values()
        .filter(|entry| entry.child_count == 0 && !protected.contains(&entry.id))
        .map(|entry| (entry.last_access, entry.id))
        .collect::<Vec<_>>();
    candidates.sort_unstable();
    for (_, id) in candidates {
        let entry = pool
            .entries
            .get(&id)
            .expect("immutable eviction candidate remained present");
        if immutable_bundle_has_request_refs(cache, &entry.bundle)? {
            pool.stats.blocked_evictions = pool.stats.blocked_evictions.saturating_add(1);
            continue;
        }
        let entry = pool
            .entries
            .remove(&id)
            .expect("immutable eviction candidate remained present");
        pool.pending_store_blocks.remove(&id);
        pool.lookup.remove(&entry.key);
        if let Some(parent) = entry.key.parent {
            let parent = pool
                .entries
                .get_mut(&parent)
                .ok_or_else(|| anyhow!("immutable block {id} parent {parent} is absent"))?;
            parent.child_count = parent
                .child_count
                .checked_sub(1)
                .ok_or_else(|| anyhow!("immutable block {id} parent child count underflow"))?;
        }
        release_full_paged_cache_owner(cache, entry.bundle.pin)?;
        pool.stats.evicted_blocks = pool.stats.evicted_blocks.saturating_add(1);
        if pressure_reclaim {
            pool.stats.pressure_evicted_blocks =
                pool.stats.pressure_evicted_blocks.saturating_add(1);
        }
        return Ok(true);
    }
    pool.stats.blocked_evictions = pool.stats.blocked_evictions.saturating_add(1);
    Ok(false)
}

fn reclaim_idle_immutable_blocks_for_targets(
    pool: &mut ImmutablePrefixBlockPool,
    cache: &mut [LayerCache],
    targets: &[(PagedKvBlockOwner, usize)],
) -> Result<()> {
    if !cache_is_fullpaged_only(cache) {
        anyhow::ensure!(
            pool.is_empty(),
            "non-empty immutable prefix pool cannot be attached to a mixed cache layout"
        );
        return Ok(());
    }
    let required = additional_full_paged_pages_for_targets(cache, pool.block_size, targets)?;
    while full_paged_available_unique_pages(cache).unwrap_or(0) < required {
        anyhow::ensure!(
            evict_one_idle_immutable_leaf(pool, cache, &HashSet::new(), false)?,
            "FullPaged immutable prefix pool cannot reclaim enough idle blocks for {required} new pages"
        );
    }
    Ok(())
}

fn reclaim_idle_immutable_blocks_to(
    pool: &mut ImmutablePrefixBlockPool,
    cache: &mut [LayerCache],
    target_blocks: usize,
) -> Result<usize> {
    let mut evicted = 0_usize;
    while pool.entries.len() > target_blocks {
        if !evict_one_idle_immutable_leaf(pool, cache, &HashSet::new(), true)? {
            break;
        }
        evicted = evicted.saturating_add(1);
    }
    Ok(evicted)
}

fn validate_immutable_prefix_pool_invariants(
    pool: &ImmutablePrefixBlockPool,
    cache: &[LayerCache],
) -> Result<()> {
    anyhow::ensure!(
        cache_is_fullpaged_only(cache),
        "non-empty immutable prefix pool requires a FullPaged-only cache"
    );
    anyhow::ensure!(
        pool.entries.len() <= pool.max_blocks,
        "immutable prefix pool has {} entries above max {}",
        pool.entries.len(),
        pool.max_blocks
    );
    anyhow::ensure!(
        pool.lookup.len() == pool.entries.len(),
        "immutable prefix lookup has {} keys for {} entries",
        pool.lookup.len(),
        pool.entries.len()
    );
    anyhow::ensure!(
        pool.pending_store_blocks
            .iter()
            .all(|id| pool.entries.contains_key(id)),
        "immutable prefix SSD pending set contains an absent block"
    );
    let paged_layers = cache
        .iter()
        .filter(|layer| matches!(layer, LayerCache::Full(_)))
        .count();
    let mut expected_children = HashMap::<u64, usize>::new();
    for (&id, entry) in &pool.entries {
        anyhow::ensure!(entry.id == id, "immutable prefix entry id mismatch");
        anyhow::ensure!(
            pool.lookup.get(&entry.key) == Some(&id),
            "immutable prefix entry {id} is absent from exact lookup"
        );
        anyhow::ensure!(
            entry.bundle.pin == PagedKvBlockOwner::Immutable(id),
            "immutable prefix entry {id} has mismatched pin {:?}",
            entry.bundle.pin
        );
        anyhow::ensure!(
            entry.bundle.handles.len() == paged_layers,
            "immutable prefix entry {id} has {} handles for {paged_layers} layers",
            entry.bundle.handles.len()
        );
        let parent_hash = match entry.key.parent {
            Some(parent) => {
                let parent_entry = pool.entries.get(&parent).ok_or_else(|| {
                    anyhow!("immutable prefix entry {id} parent {parent} is absent")
                })?;
                *expected_children.entry(parent).or_default() += 1;
                Some(parent_entry.chain_hash)
            }
            None => None,
        };
        anyhow::ensure!(
            entry.chain_hash
                == immutable_prefix_chain_hash(&pool.model_id, parent_hash, &entry.key.tokens),
            "immutable prefix entry {id} chain hash mismatch"
        );
        let mut handle_index = 0_usize;
        for layer in cache {
            if let LayerCache::Full(kv) = layer {
                anyhow::ensure!(
                    kv.validate_paged_immutable_pin_handle(
                        entry.bundle.pin,
                        entry.bundle.handles[handle_index],
                    )?,
                    "immutable prefix entry {id} layer {handle_index} is not FullPaged"
                );
                handle_index += 1;
            }
        }
    }
    for (&id, entry) in &pool.entries {
        anyhow::ensure!(
            entry.child_count == expected_children.get(&id).copied().unwrap_or(0),
            "immutable prefix entry {id} child count {} is incorrect",
            entry.child_count
        );
    }
    Ok(())
}

fn immutable_block_store_spec(
    config: &PagedPrefixCacheConfig,
    cache: &[LayerCache],
    tokens: &[u32],
    parent_hash: Option<u64>,
) -> Result<PagedPrefixKeySpec> {
    anyhow::ensure!(
        tokens.len() == usize::try_from(config.block_size).unwrap_or(0),
        "immutable block store requires exactly one configured block"
    );
    let mut spec = paged_prefix_key_spec_for_full_caches(&config.model_id, tokens, cache)?
        .ok_or_else(|| anyhow!("immutable block store requires a FullPaged-only cache"))?;
    spec.entry_kind = PrefixEntryKind::ImmutableBlock;
    spec.fingerprint = Some(match parent_hash {
        Some(hash) => format!("immutable-parent:{hash:016x}"),
        None => "immutable-root".to_owned(),
    });
    Ok(spec)
}

fn immutable_bundle_entry(
    cache: &[LayerCache],
    bundle: &ImmutablePrefixBlockBundle,
) -> Result<PagedPrefixEntry> {
    let mut main_layers = Vec::with_capacity(bundle.handles.len());
    let mut handle_index = 0_usize;
    for layer in cache {
        let LayerCache::Full(kv) = layer else {
            anyhow::bail!("immutable block export requires a FullPaged-only cache");
        };
        let handle = *bundle
            .handles
            .get(handle_index)
            .ok_or_else(|| anyhow!("immutable block export handle count mismatch"))?;
        let payload = kv
            .paged_immutable_block_prefix_on(bundle.pin, handle, ())?
            .ok_or_else(|| anyhow!("immutable block export layer is not FullPaged"))?;
        main_layers.push(PrefixLayerPayload::FullPaged {
            k_pages: payload.k_pages,
            v_pages: payload.v_pages,
        });
        handle_index += 1;
    }
    anyhow::ensure!(
        handle_index == bundle.handles.len(),
        "immutable block export found {handle_index} layers for {} handles",
        bundle.handles.len()
    );
    Ok(PagedPrefixEntry {
        main_layers,
        ..PagedPrefixEntry::default()
    })
}

fn install_full_paged_immutable_block_from_entry(
    cache: &mut [LayerCache],
    pin: PagedKvBlockOwner,
    block_index: usize,
    entry: PagedPrefixEntry,
) -> Result<ImmutablePrefixBlockBundle> {
    anyhow::ensure!(
        entry.mtp_layers.is_empty()
            && entry.mtp_last_hidden.is_none()
            && entry.gemma4_drafter_last_hidden.is_none(),
        "immutable block SSD entry contains unsupported side state"
    );
    let expected_layers = cache
        .iter()
        .filter(|layer| matches!(layer, LayerCache::Full(_)))
        .count();
    anyhow::ensure!(
        cache_is_fullpaged_only(cache) && entry.main_layers.len() == expected_layers,
        "immutable block SSD entry layer count/layout mismatch"
    );
    let block_index = i32::try_from(block_index).map_err(|_| anyhow!("block index overflow"))?;
    let mut payloads = entry.main_layers.into_iter();
    let install_result = (|| -> Result<Vec<PagedKvImmutableBlockHandle>> {
        let mut handles = Vec::with_capacity(expected_layers);
        for layer in cache.iter_mut() {
            let LayerCache::Full(kv) = layer else {
                anyhow::bail!("immutable block SSD install requires FullPaged-only cache");
            };
            let payload = payloads
                .next()
                .ok_or_else(|| anyhow!("immutable block SSD payload ended early"))?;
            let PrefixLayerPayload::FullPaged { k_pages, v_pages } = payload else {
                anyhow::bail!("immutable block SSD payload is not FullPaged");
            };
            let prefix = PagedPrefixLayer { k_pages, v_pages };
            let handle = kv
                .install_paged_immutable_block_from_prefix_on(pin, block_index, &prefix, ())?
                .ok_or_else(|| anyhow!("immutable block SSD destination is not FullPaged"))?;
            handles.push(handle);
        }
        anyhow::ensure!(
            payloads.next().is_none(),
            "immutable block SSD payload has extra layers"
        );
        Ok(handles)
    })();
    let handles = match install_result {
        Ok(handles) => handles,
        Err(error) => {
            release_full_paged_cache_owner(cache, pin)?;
            return Err(error);
        }
    };
    if let Err(error) = validate_full_paged_owner_invariants(cache) {
        release_full_paged_cache_owner(cache, pin)?;
        return Err(error);
    }
    Ok(ImmutablePrefixBlockBundle { pin, handles })
}

fn queue_immutable_block_store(
    pool: &mut ImmutablePrefixBlockPool,
    cache: &[LayerCache],
    config: Option<&PagedPrefixCacheConfig>,
    entry_id: u64,
) -> Result<ImmutableBlockStoreAttempt> {
    let Some(config) = config else {
        return Ok(ImmutableBlockStoreAttempt::Persisted);
    };
    let entry = pool
        .entries
        .get(&entry_id)
        .ok_or_else(|| anyhow!("immutable block {entry_id} is absent before SSD queue"))?;
    let parent_hash = entry
        .key
        .parent
        .and_then(|parent| pool.entries.get(&parent).map(|entry| entry.chain_hash));
    let spec = immutable_block_store_spec(config, cache, &entry.key.tokens, parent_hash)?;
    let store = config.store();
    if store.contains_persisted(&spec)? {
        return Ok(ImmutableBlockStoreAttempt::Persisted);
    }
    let permit = match crate::core::cache::process_async_prefix_store_queue().try_admit(
        store,
        spec,
        AsyncPrefixStoreCancellation::default(),
    ) {
        AsyncPrefixStoreAdmission::Admitted(permit) => *permit,
        AsyncPrefixStoreAdmission::Coalesced => {
            return Ok(ImmutableBlockStoreAttempt::Pending);
        }
        AsyncPrefixStoreAdmission::Backpressured => {
            pool.stats.ssd_store_backpressure = pool.stats.ssd_store_backpressure.saturating_add(1);
            return Ok(ImmutableBlockStoreAttempt::Backpressured);
        }
        AsyncPrefixStoreAdmission::Closed => {
            return Err(anyhow!("immutable block SSD async store is closed"));
        }
    };
    let payload = immutable_bundle_entry(cache, &entry.bundle)?;
    let attempt = match permit.submit(payload) {
        AsyncPrefixStoreSubmit::Queued => {
            pool.stats.ssd_blocks_queued = pool.stats.ssd_blocks_queued.saturating_add(1);
            ImmutableBlockStoreAttempt::Pending
        }
        AsyncPrefixStoreSubmit::Coalesced => ImmutableBlockStoreAttempt::Pending,
        AsyncPrefixStoreSubmit::Backpressured => {
            pool.stats.ssd_store_backpressure = pool.stats.ssd_store_backpressure.saturating_add(1);
            ImmutableBlockStoreAttempt::Backpressured
        }
        AsyncPrefixStoreSubmit::Cancelled => ImmutableBlockStoreAttempt::Pending,
        AsyncPrefixStoreSubmit::Closed => {
            return Err(anyhow!("immutable block SSD async store is closed"));
        }
    };
    Ok(attempt)
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ImmutableBlockStoreAttempt {
    Persisted,
    Pending,
    Backpressured,
}

fn retry_pending_immutable_block_stores(
    pool: &mut ImmutablePrefixBlockPool,
    cache: &[LayerCache],
    config: Option<&PagedPrefixCacheConfig>,
    limit: usize,
) -> Result<usize> {
    let mut ids = pool
        .pending_store_blocks
        .iter()
        .copied()
        .collect::<Vec<_>>();
    ids.sort_unstable();
    let mut persisted = 0_usize;
    for id in ids.into_iter().take(limit) {
        if !pool.entries.contains_key(&id) {
            pool.pending_store_blocks.remove(&id);
            continue;
        }
        match queue_immutable_block_store(pool, cache, config, id)? {
            ImmutableBlockStoreAttempt::Persisted => {
                pool.pending_store_blocks.remove(&id);
                persisted = persisted.saturating_add(1);
            }
            ImmutableBlockStoreAttempt::Pending => {}
            ImmutableBlockStoreAttempt::Backpressured => break,
        }
    }
    Ok(persisted)
}

#[allow(clippy::too_many_arguments)]
fn try_load_immutable_block_from_store(
    pool: &mut ImmutablePrefixBlockPool,
    cache: &mut [LayerCache],
    config: Option<&PagedPrefixCacheConfig>,
    governor: Option<&crate::core::process_memory::SharedProcessMemoryGovernor>,
    parent: Option<u64>,
    parent_hash: Option<u64>,
    tokens: &[u32],
    block_index: usize,
) -> Result<Option<u64>> {
    let Some(config) = config else {
        return Ok(None);
    };
    let spec = immutable_block_store_spec(config, cache, tokens, parent_hash)?;
    let reservation = if let Some(governor) = governor {
        governor.sample_process();
        match governor.try_reserve(spec.payload_bytes(), "immutable_block_ssd_load") {
            Ok(reservation) => Some(reservation),
            Err(error) => {
                pool.stats.ssd_load_pressure_skips =
                    pool.stats.ssd_load_pressure_skips.saturating_add(1);
                tracing::debug!(%error, "immutable block SSD load skipped by memory governor");
                return Ok(None);
            }
        }
    } else {
        None
    };
    let observed = config.store().load_observed(&spec)?;
    if observed.status != PagedPrefixLoadStatus::Hit {
        return Ok(None);
    }
    let payload = observed
        .entry
        .ok_or_else(|| anyhow!("immutable block SSD hit has no payload"))?;

    let protected = parent.into_iter().collect::<HashSet<_>>();
    while pool.entries.len() >= pool.max_blocks {
        if !evict_one_idle_immutable_leaf(pool, cache, &protected, false)? {
            return Ok(None);
        }
    }
    while full_paged_available_unique_pages(cache).unwrap_or(0) < 1 {
        if !evict_one_idle_immutable_leaf(pool, cache, &protected, false)? {
            return Ok(None);
        }
    }
    if let Some(parent_id) = parent {
        anyhow::ensure!(
            pool.entries.contains_key(&parent_id),
            "immutable SSD block parent {parent_id} disappeared before install"
        );
    }
    let key = ImmutablePrefixBlockLookupKey {
        parent,
        tokens: tokens.into(),
    };
    let id = pool.next_id;
    anyhow::ensure!(
        !pool.lookup.contains_key(&key) && !pool.entries.contains_key(&id),
        "immutable SSD block identity collided during actor-owned install"
    );
    let pin = PagedKvBlockOwner::Immutable(id);
    let bundle = install_full_paged_immutable_block_from_entry(cache, pin, block_index, payload)?;
    pool.next_id = pool.next_id.saturating_add(1);
    let chain_hash = immutable_prefix_chain_hash(&pool.model_id, parent_hash, tokens);
    pool.access_clock = pool.access_clock.saturating_add(1);
    if let Some(parent_id) = parent {
        let parent_entry = pool
            .entries
            .get_mut(&parent_id)
            .expect("immutable SSD parent validated above");
        parent_entry.child_count = parent_entry.child_count.saturating_add(1);
    }
    pool.lookup.insert(key.clone(), id);
    pool.entries.insert(
        id,
        ImmutablePrefixBlockEntry {
            id,
            chain_hash,
            key,
            bundle,
            child_count: 0,
            last_access: pool.access_clock,
        },
    );
    pool.stats.ssd_block_hits = pool.stats.ssd_block_hits.saturating_add(1);
    pool.stats.ssd_blocks_loaded = pool.stats.ssd_blocks_loaded.saturating_add(1);
    if let Some(reservation) = reservation {
        reservation.commit();
    }
    Ok(Some(id))
}

fn restore_immutable_prefix_blocks(
    pool: &mut ImmutablePrefixBlockPool,
    cache: &mut [LayerCache],
    config: Option<&PagedPrefixCacheConfig>,
    governor: Option<&crate::core::process_memory::SharedProcessMemoryGovernor>,
    destination: PagedKvBlockOwner,
    prompt_ids: &[u32],
) -> Result<Option<i32>> {
    if pool.max_blocks == 0 || prompt_ids.len() <= 1 {
        return Ok(None);
    }
    let max_blocks = (prompt_ids.len() - 1) / pool.block_size;
    if max_blocks == 0 {
        return Ok(None);
    }
    let mut parent = None;
    let mut bundles = Vec::with_capacity(max_blocks);
    let mut hit_ids = Vec::with_capacity(max_blocks);
    let mut active_hits = 0_u64;
    let mut idle_hits = 0_u64;
    for block_index in 0..max_blocks {
        let start = block_index * pool.block_size;
        let end = start + pool.block_size;
        let key = ImmutablePrefixBlockLookupKey {
            parent,
            tokens: prompt_ids[start..end].into(),
        };
        let id = if let Some(&id) = pool.lookup.get(&key) {
            id
        } else {
            let parent_hash =
                parent.and_then(|parent| pool.entries.get(&parent).map(|entry| entry.chain_hash));
            let Some(id) = try_load_immutable_block_from_store(
                pool,
                cache,
                config,
                governor,
                parent,
                parent_hash,
                &prompt_ids[start..end],
                block_index,
            )?
            else {
                pool.stats.lookup_misses = pool.stats.lookup_misses.saturating_add(1);
                break;
            };
            id
        };
        let entry = pool
            .entries
            .get(&id)
            .ok_or_else(|| anyhow!("immutable prefix lookup points to absent block {id}"))?;
        let parent_hash = entry
            .key
            .parent
            .and_then(|parent| pool.entries.get(&parent).map(|entry| entry.chain_hash));
        let expected_hash =
            immutable_prefix_chain_hash(&pool.model_id, parent_hash, &entry.key.tokens);
        anyhow::ensure!(
            entry.chain_hash == expected_hash && entry.key == key,
            "immutable prefix block {id} identity mismatch"
        );
        if immutable_bundle_has_request_refs(cache, &entry.bundle)? {
            active_hits = active_hits.saturating_add(1);
        } else {
            idle_hits = idle_hits.saturating_add(1);
        }
        bundles.push(entry.bundle.clone());
        hit_ids.push(id);
        parent = Some(id);
    }
    if bundles.is_empty() {
        return Ok(None);
    }
    anyhow::ensure!(
        install_full_paged_immutable_prefix(cache, destination, &bundles)?,
        "immutable prefix matched but FullPaged install was unavailable"
    );
    for id in hit_ids {
        pool.touch(id);
    }
    let restored_blocks = bundles.len() as u64;
    pool.stats.restored_blocks = pool.stats.restored_blocks.saturating_add(restored_blocks);
    pool.stats.active_block_hits = pool.stats.active_block_hits.saturating_add(active_hits);
    pool.stats.idle_block_hits = pool.stats.idle_block_hits.saturating_add(idle_hits);
    pool.stats.dedup_saved_bytes = pool
        .stats
        .dedup_saved_bytes
        .saturating_add((full_paged_page_bytes(cache) as u64).saturating_mul(restored_blocks));
    Ok(Some(
        i32::try_from(bundles.len().saturating_mul(pool.block_size))
            .map_err(|_| anyhow!("immutable prefix restored length overflow"))?,
    ))
}

fn publish_immutable_prefix_blocks(
    pool: &mut ImmutablePrefixBlockPool,
    cache: &mut [LayerCache],
    config: Option<&PagedPrefixCacheConfig>,
    source: PagedKvBlockOwner,
    token_ids: &[u32],
) -> Result<usize> {
    if pool.max_blocks == 0 || token_ids.len() < pool.block_size {
        return Ok(0);
    }
    let source_offset = full_paged_owner_offset(cache, source)?.unwrap_or(0);
    let source_blocks = usize::try_from(source_offset.max(0)).unwrap_or(0) / pool.block_size;
    let block_count = (token_ids.len() / pool.block_size).min(source_blocks);
    let mut parent = None;
    let mut parent_hash = None;
    let mut published = 0_usize;
    let mut store_backpressured = false;
    for block_index in 0..block_count {
        let start = block_index * pool.block_size;
        let end = start + pool.block_size;
        let key = ImmutablePrefixBlockLookupKey {
            parent,
            tokens: token_ids[start..end].into(),
        };
        if let Some(&id) = pool.lookup.get(&key) {
            let entry = pool
                .entries
                .get(&id)
                .ok_or_else(|| anyhow!("immutable prefix lookup points to absent block {id}"))?;
            parent_hash = Some(entry.chain_hash);
            parent = Some(id);
            pool.touch(id);
            if config.is_some() {
                pool.pending_store_blocks.insert(id);
                if !store_backpressured {
                    match queue_immutable_block_store(pool, cache, config, id)? {
                        ImmutableBlockStoreAttempt::Persisted => {
                            pool.pending_store_blocks.remove(&id);
                        }
                        ImmutableBlockStoreAttempt::Pending => {}
                        ImmutableBlockStoreAttempt::Backpressured => {
                            store_backpressured = true;
                        }
                    }
                }
            }
            continue;
        }
        while pool.entries.len() >= pool.max_blocks {
            let protected = parent.into_iter().collect::<HashSet<_>>();
            if !evict_one_idle_immutable_leaf(pool, cache, &protected, false)? {
                return Ok(published);
            }
        }
        let id = pool.next_id;
        pool.next_id = pool.next_id.saturating_add(1);
        let pin = PagedKvBlockOwner::Immutable(id);
        let Some(bundle) = pin_full_paged_immutable_block(
            cache,
            source,
            i32::try_from(block_index).map_err(|_| anyhow!("block index overflow"))?,
            pin,
        )?
        else {
            return Ok(published);
        };
        let chain_hash = immutable_prefix_chain_hash(&pool.model_id, parent_hash, &key.tokens);
        pool.access_clock = pool.access_clock.saturating_add(1);
        if let Some(parent_id) = parent {
            let parent_entry = pool
                .entries
                .get_mut(&parent_id)
                .ok_or_else(|| anyhow!("immutable parent {parent_id} is absent"))?;
            parent_entry.child_count = parent_entry.child_count.saturating_add(1);
        }
        pool.lookup.insert(key.clone(), id);
        pool.entries.insert(
            id,
            ImmutablePrefixBlockEntry {
                id,
                chain_hash,
                key,
                bundle,
                child_count: 0,
                last_access: pool.access_clock,
            },
        );
        pool.stats.published_blocks = pool.stats.published_blocks.saturating_add(1);
        published += 1;
        if config.is_some() {
            pool.pending_store_blocks.insert(id);
            if !store_backpressured {
                match queue_immutable_block_store(pool, cache, config, id)? {
                    ImmutableBlockStoreAttempt::Persisted => {
                        pool.pending_store_blocks.remove(&id);
                    }
                    ImmutableBlockStoreAttempt::Pending => {}
                    ImmutableBlockStoreAttempt::Backpressured => {
                        store_backpressured = true;
                    }
                }
            }
        }
        parent_hash = Some(chain_hash);
        parent = Some(id);
    }
    Ok(published)
}

fn try_restore_paged_prefix_for_prompt(
    config: Option<&PagedPrefixCacheConfig>,
    prefix_lru_cache: Option<&PrefixLruCacheHandle>,
    cache: &mut [LayerCache],
    prompt_ids: &[u32],
    fingerprint: Option<&str>,
) -> Result<Option<i32>> {
    try_restore_paged_prefix_for_prompt_row(
        config,
        prefix_lru_cache,
        cache,
        0,
        prompt_ids,
        fingerprint,
    )
}

fn paged_prefix_restore_candidates(
    store: &PagedPrefixStore,
    prefix_lru_cache: Option<&PrefixLruCacheHandle>,
    prompt_len: usize,
) -> Result<Vec<(usize, i32)>> {
    if prompt_len <= 1 {
        return Ok(Vec::new());
    }
    let max_cached_len = i32::try_from(prompt_len - 1)
        .map_err(|_| anyhow!("paged prefix restore length exceeds i32"))?;
    // The writer always stores the maximal reusable prefix (prompt_len - 1).
    // Probe it directly so an in-flight async store entry is visible before
    // its temporary directory has been atomically renamed into place.
    let mut cached_lengths = vec![max_cached_len];
    if let Some(prefix_lru_cache) = prefix_lru_cache {
        cached_lengths.extend(
            lock_prefix_lru_cache(prefix_lru_cache)?
                .cached_lengths_descending(max_cached_len as usize),
        );
    }
    cached_lengths.extend(store.cached_lengths_descending(max_cached_len)?);
    cached_lengths.sort_unstable_by(|a, b| b.cmp(a));
    cached_lengths.dedup();
    let mut candidates = Vec::with_capacity(cached_lengths.len());
    for cached_len in cached_lengths {
        let restore_len = usize::try_from(cached_len)
            .map_err(|_| anyhow!("paged prefix cached length must be positive"))?;
        candidates.push((restore_len, cached_len));
    }
    Ok(candidates)
}

fn lock_prefix_lru_cache(
    prefix_lru_cache: &PrefixLruCacheHandle,
) -> Result<MutexGuard<'_, PrefixLruCache>> {
    prefix_lru_cache
        .lock()
        .map_err(|_| anyhow!("prefix LRU cache lock poisoned"))
}

fn try_load_prefix_lru_entry(
    prefix_lru_cache: Option<&PrefixLruCacheHandle>,
    spec: &crate::core::cache::PagedPrefixKeySpec,
) -> Result<Option<(String, PagedPrefixEntry, PagedPrefixEntryStats, u128)>> {
    let Some(prefix_lru_cache) = prefix_lru_cache else {
        return Ok(None);
    };
    let load_start = Instant::now();
    let observed = lock_prefix_lru_cache(prefix_lru_cache)?.load_observed(spec)?;
    let load_us = load_start.elapsed().as_micros();
    if observed.status != PagedPrefixLoadStatus::Hit {
        tracing::trace!(
            "prefix LRU cache miss: key={} status={:?} load_us={}",
            observed.key,
            observed.status,
            load_us
        );
        return Ok(None);
    }
    let key = observed.key;
    let stats = observed
        .stats
        .unwrap_or_else(|| empty_prefix_stats(spec.cached_len));
    let entry = observed
        .entry
        .ok_or_else(|| anyhow!("prefix LRU observed hit without entry"))?;
    Ok(Some((key, entry, stats, load_us)))
}

fn try_insert_prefix_lru_entry(
    prefix_lru_cache: Option<&PrefixLruCacheHandle>,
    spec: crate::core::cache::PagedPrefixKeySpec,
    entry: PagedPrefixEntry,
    main_row: usize,
    mtp_row: Option<usize>,
) -> Result<Option<String>> {
    let Some(prefix_lru_cache) = prefix_lru_cache else {
        return Ok(None);
    };
    let save_start = Instant::now();
    let result = lock_prefix_lru_cache(prefix_lru_cache)?.insert(spec, entry)?;
    let save_us = save_start.elapsed().as_micros();
    match result.status {
        PrefixLruInsertStatus::Stored | PrefixLruInsertStatus::Replaced => {
            log_prefix_lru_save(
                match result.status {
                    PrefixLruInsertStatus::Stored => "saved",
                    PrefixLruInsertStatus::Replaced => "updated",
                    PrefixLruInsertStatus::SkippedOversized => unreachable!(),
                },
                &result.key,
                main_row,
                mtp_row,
                result.stats,
                save_us,
            );
            Ok(Some(result.key))
        }
        PrefixLruInsertStatus::SkippedOversized => {
            tracing::trace!(
                "prefix LRU cache save skipped: row={} key={} status=oversized payload_bytes={} max_bytes={}",
                main_row,
                result.key,
                result.stats.payload_bytes,
                lock_prefix_lru_cache(prefix_lru_cache)?.max_bytes()
            );
            Ok(None)
        }
    }
}

fn try_admit_prefix_store_entry(
    store: PagedPrefixStore,
    spec: &PagedPrefixKeySpec,
    main_row: usize,
    mtp_row: Option<usize>,
) -> Result<Option<(String, Option<AsyncPrefixStorePermit>)>> {
    let key = PagedPrefixStore::key_for(spec);
    match crate::core::cache::process_async_prefix_store_queue().try_admit(
        store,
        spec.clone(),
        AsyncPrefixStoreCancellation::default(),
    ) {
        AsyncPrefixStoreAdmission::Admitted(permit) => Ok(Some((key, Some(*permit)))),
        AsyncPrefixStoreAdmission::Coalesced => Ok(Some((key, None))),
        AsyncPrefixStoreAdmission::Backpressured => {
            tracing::warn!(
                main_row,
                ?mtp_row,
                key,
                "paged SSD prefix cache extraction skipped by async-store backpressure"
            );
            Ok(None)
        }
        AsyncPrefixStoreAdmission::Closed => {
            Err(anyhow!("paged SSD prefix cache async store is closed"))
        }
    }
}

fn submit_prefix_store_entry(
    permit: AsyncPrefixStorePermit,
    key: String,
    entry: PagedPrefixEntry,
    cached_len: i32,
    main_row: usize,
    mtp_row: Option<usize>,
) -> Result<Option<String>> {
    let stats = entry.observability_stats(cached_len);
    match permit.submit(entry) {
        AsyncPrefixStoreSubmit::Queued => {
            log_paged_prefix_save("queued", &key, main_row, mtp_row, stats, 0);
            Ok(Some(key))
        }
        AsyncPrefixStoreSubmit::Coalesced => Ok(Some(key)),
        AsyncPrefixStoreSubmit::Cancelled => Ok(None),
        AsyncPrefixStoreSubmit::Backpressured => {
            tracing::warn!(
                main_row,
                ?mtp_row,
                key,
                "paged SSD prefix cache write skipped by async-store backpressure"
            );
            Ok(None)
        }
        AsyncPrefixStoreSubmit::Closed => {
            Err(anyhow!("paged SSD prefix cache async store is closed"))
        }
    }
}

fn try_restore_paged_prefix_for_prompt_row(
    config: Option<&PagedPrefixCacheConfig>,
    prefix_lru_cache: Option<&PrefixLruCacheHandle>,
    cache: &mut [LayerCache],
    cache_row: usize,
    prompt_ids: &[u32],
    fingerprint: Option<&str>,
) -> Result<Option<i32>> {
    let Some(config) = config else {
        return Ok(None);
    };
    if prompt_ids.len() <= 1 {
        return Ok(None);
    }
    if fingerprint.is_none() && cache_is_fullpaged_only(cache) {
        return Ok(None);
    }
    let store = config.store();
    for (restore_len, cached_len) in
        paged_prefix_restore_candidates(&store, prefix_lru_cache, prompt_ids.len())?
    {
        let Some(spec) = prefix_key_spec_for_caches(
            &config.model_id,
            &prompt_ids[..restore_len],
            cached_len,
            fingerprint,
            config.block_size,
            cache,
        )?
        else {
            return Ok(None);
        };
        if let Some((key, entry, stats, load_us)) =
            try_load_prefix_lru_entry(prefix_lru_cache, &spec)?
        {
            restore_prefix_entry_for_row(cache, &entry, cache_row, cached_len)?;
            log_prefix_lru_hit("hit", &key, cache_row, None, restore_len, stats, load_us);
            return Ok(Some(cached_len));
        }
        let load_start = Instant::now();
        let observed = store.load_observed(&spec)?;
        let load_us = load_start.elapsed().as_micros();
        if observed.status != PagedPrefixLoadStatus::Hit {
            tracing::trace!(
                "paged SSD prefix cache miss: row={} tokens={} key={} status={:?} load_us={}",
                cache_row,
                restore_len,
                observed.key,
                observed.status,
                load_us
            );
            continue;
        };
        let key = observed.key;
        let stats = observed
            .stats
            .unwrap_or_else(|| empty_prefix_stats(cached_len));
        let entry = observed
            .entry
            .ok_or_else(|| anyhow!("paged prefix observed hit without entry"))?;
        try_insert_prefix_lru_entry(prefix_lru_cache, spec, entry.clone(), cache_row, None)?;
        restore_prefix_entry_for_row(cache, &entry, cache_row, cached_len)?;
        log_paged_prefix_hit("hit", &key, cache_row, None, restore_len, stats, load_us);
        return Ok(Some(cached_len));
    }
    Ok(None)
}

fn try_restore_paged_prefix_for_prompt_rows(
    config: Option<&PagedPrefixCacheConfig>,
    prefix_lru_cache: Option<&PrefixLruCacheHandle>,
    cache: &mut [LayerCache],
    cache_rows: &[usize],
    prompt_ids: &[u32],
    fingerprint: Option<&str>,
) -> Result<Option<i32>> {
    if cache_rows.is_empty() {
        return Ok(None);
    }
    if fingerprint.is_none() && cache_is_fullpaged_only(cache) {
        return Ok(None);
    }
    if cache_rows.len() == 1 {
        return try_restore_paged_prefix_for_prompt_row(
            config,
            prefix_lru_cache,
            cache,
            cache_rows[0],
            prompt_ids,
            fingerprint,
        );
    }
    let Some(config) = config else {
        return Ok(None);
    };
    if prompt_ids.len() <= 1 {
        return Ok(None);
    }
    let store = config.store();
    for (restore_len, cached_len) in
        paged_prefix_restore_candidates(&store, prefix_lru_cache, prompt_ids.len())?
    {
        let Some(spec) = prefix_key_spec_for_caches(
            &config.model_id,
            &prompt_ids[..restore_len],
            cached_len,
            fingerprint,
            config.block_size,
            cache,
        )?
        else {
            return Ok(None);
        };
        if let Some((key, entry, stats, load_us)) =
            try_load_prefix_lru_entry(prefix_lru_cache, &spec)?
        {
            restore_prefix_entry_for_rows(cache, &entry, cache_rows, cached_len)?;
            for (idx, &cache_row) in cache_rows.iter().enumerate() {
                let row_load_us = if idx == 0 { load_us } else { 0 };
                log_prefix_lru_hit(
                    "hit",
                    &key,
                    cache_row,
                    None,
                    restore_len,
                    stats,
                    row_load_us,
                );
            }
            return Ok(Some(cached_len));
        }
        let load_start = Instant::now();
        let observed = store.load_observed(&spec)?;
        let load_us = load_start.elapsed().as_micros();
        if observed.status != PagedPrefixLoadStatus::Hit {
            tracing::trace!(
                "paged SSD prefix cache miss: rows={:?} tokens={} key={} status={:?} load_us={}",
                cache_rows,
                restore_len,
                observed.key,
                observed.status,
                load_us
            );
            continue;
        };
        let key = observed.key;
        let stats = observed
            .stats
            .unwrap_or_else(|| empty_prefix_stats(cached_len));
        let entry = observed
            .entry
            .ok_or_else(|| anyhow!("paged prefix observed hit without entry"))?;
        try_insert_prefix_lru_entry(prefix_lru_cache, spec, entry.clone(), cache_rows[0], None)?;
        restore_prefix_entry_for_rows(cache, &entry, cache_rows, cached_len)?;
        for (idx, &cache_row) in cache_rows.iter().enumerate() {
            let row_load_us = if idx == 0 { load_us } else { 0 };
            log_paged_prefix_hit(
                "hit",
                &key,
                cache_row,
                None,
                restore_len,
                stats,
                row_load_us,
            );
        }
        return Ok(Some(cached_len));
    }
    Ok(None)
}

fn try_save_paged_prefix_for_prompt(
    config: Option<&PagedPrefixCacheConfig>,
    prefix_lru_cache: Option<&PrefixLruCacheHandle>,
    cache: &[LayerCache],
    prompt_ids: &[u32],
    fingerprint: Option<&str>,
) -> Result<Option<String>> {
    try_save_paged_prefix_for_prompt_row(
        config,
        prefix_lru_cache,
        cache,
        0,
        prompt_ids,
        fingerprint,
    )
}

fn try_save_paged_prefix_for_prompt_row(
    config: Option<&PagedPrefixCacheConfig>,
    prefix_lru_cache: Option<&PrefixLruCacheHandle>,
    cache: &[LayerCache],
    cache_row: usize,
    prompt_ids: &[u32],
    fingerprint: Option<&str>,
) -> Result<Option<String>> {
    let Some(config) = config else {
        return Ok(None);
    };
    if prompt_ids.is_empty() {
        return Ok(None);
    }
    if fingerprint.is_none() && cache_is_fullpaged_only(cache) {
        return Ok(None);
    }
    let Some(cached_len) = cache_row_cached_len(cache, cache_row)? else {
        return Ok(None);
    };
    if cached_len == 0 {
        return Ok(None);
    }
    if cached_len != prompt_ids.len() as i32 {
        anyhow::bail!(
            "try_save_paged_prefix_for_prompt: cache cached_len {cached_len} != token length {}",
            prompt_ids.len()
        );
    }
    let Some(spec) = prefix_key_spec_for_caches(
        &config.model_id,
        prompt_ids,
        cached_len,
        fingerprint,
        config.block_size,
        cache,
    )?
    else {
        return Ok(None);
    };
    let store = config.store();
    let Some((key, permit)) = try_admit_prefix_store_entry(store, &spec, cache_row, None)? else {
        return Ok(None);
    };
    let Some(permit) = permit else {
        return Ok(Some(key));
    };
    let Some((entry, cached_len)) = prefix_entry_for_row(cache, cache_row)? else {
        return Ok(None);
    };
    if cached_len == 0 {
        return Ok(None);
    }
    if cached_len != prompt_ids.len() as i32 {
        anyhow::bail!(
            "try_save_paged_prefix_for_prompt: cache cached_len {cached_len} != token length {}",
            prompt_ids.len()
        );
    }
    try_insert_prefix_lru_entry(
        prefix_lru_cache,
        spec.clone(),
        entry.clone(),
        cache_row,
        None,
    )?;
    submit_prefix_store_entry(permit, key, entry, cached_len, cache_row, None)
}

fn mtp_layer_specs_for_cache(mtp_cache: &MtpCache, cached_len: i32) -> Vec<PrefixMtpLayerSpec> {
    (0..mtp_cache.num_layers())
        .map(|idx| {
            let layer = mtp_cache.layer(idx);
            PrefixMtpLayerSpec {
                k: PrefixTensorSpec {
                    dtype: layer.dtype(),
                    shape: vec![1_i32, layer.n_kv_heads(), cached_len, layer.head_dim()],
                },
                v: PrefixTensorSpec {
                    dtype: layer.dtype(),
                    shape: vec![1_i32, layer.n_kv_heads(), cached_len, layer.v_head_dim()],
                },
            }
        })
        .collect()
}

fn mtp_last_hidden_spec(dtype: Dtype, hidden_size: i32) -> PrefixTensorSpec {
    PrefixTensorSpec {
        dtype,
        shape: vec![1_i32, 1_i32, hidden_size],
    }
}

#[allow(clippy::too_many_arguments)]
fn try_restore_paged_prefix_for_prompt_with_mtp(
    config: Option<&PagedPrefixCacheConfig>,
    prefix_lru_cache: Option<&PrefixLruCacheHandle>,
    main_cache: &mut [LayerCache],
    mtp_cache: &mut MtpCache,
    prompt_ids: &[u32],
    hidden_size: i32,
    hidden_dtype: Dtype,
    fingerprint: Option<&str>,
) -> Result<Option<(i32, Array)>> {
    try_restore_paged_prefix_for_prompt_with_mtp_row(
        config,
        prefix_lru_cache,
        main_cache,
        0,
        mtp_cache,
        0,
        prompt_ids,
        hidden_size,
        hidden_dtype,
        fingerprint,
    )
}

#[allow(clippy::too_many_arguments)]
fn try_restore_paged_prefix_for_prompt_with_mtp_row(
    config: Option<&PagedPrefixCacheConfig>,
    prefix_lru_cache: Option<&PrefixLruCacheHandle>,
    main_cache: &mut [LayerCache],
    main_cache_row: usize,
    mtp_cache: &mut MtpCache,
    mtp_cache_row: usize,
    prompt_ids: &[u32],
    hidden_size: i32,
    hidden_dtype: Dtype,
    fingerprint: Option<&str>,
) -> Result<Option<(i32, Array)>> {
    let Some(config) = config else {
        return Ok(None);
    };
    if prompt_ids.len() <= 1 {
        return Ok(None);
    }
    let store = config.store();
    for (restore_len, cached_len) in
        paged_prefix_restore_candidates(&store, prefix_lru_cache, prompt_ids.len())?
    {
        let Some(mut spec) = prefix_key_spec_for_caches(
            &config.model_id,
            &prompt_ids[..restore_len],
            cached_len,
            fingerprint,
            config.block_size,
            main_cache,
        )?
        else {
            return Ok(None);
        };
        spec.mtp_layers = mtp_layer_specs_for_cache(mtp_cache, cached_len);
        spec.mtp_last_hidden = Some(mtp_last_hidden_spec(hidden_dtype, hidden_size));
        if let Some((key, entry, stats, load_us)) =
            try_load_prefix_lru_entry(prefix_lru_cache, &spec)?
        {
            restore_prefix_entry_for_row(main_cache, &entry, main_cache_row, cached_len)?;
            mtp_cache.restore_prefix_layers_for_row_on(
                &entry.mtp_layers,
                mtp_cache_row,
                cached_len,
                (),
            )?;
            let last_hidden = entry
                .mtp_last_hidden
                .ok_or_else(|| anyhow!("prefix LRU MTP hit missing last_hidden"))?;
            log_prefix_lru_hit(
                "MTP hit",
                &key,
                main_cache_row,
                Some(mtp_cache_row),
                restore_len,
                stats,
                load_us,
            );
            return Ok(Some((cached_len, last_hidden)));
        }
        let load_start = Instant::now();
        let observed = store.load_observed(&spec)?;
        let load_us = load_start.elapsed().as_micros();
        if observed.status != PagedPrefixLoadStatus::Hit {
            tracing::trace!(
                "paged SSD prefix cache MTP miss: main_row={} mtp_row={} tokens={} key={} status={:?} load_us={}",
                main_cache_row,
                mtp_cache_row,
                restore_len,
                observed.key,
                observed.status,
                load_us
            );
            continue;
        };
        let key = observed.key;
        let stats = observed
            .stats
            .unwrap_or_else(|| empty_prefix_stats(cached_len));
        let entry = observed
            .entry
            .ok_or_else(|| anyhow!("paged prefix observed MTP hit without entry"))?;
        try_insert_prefix_lru_entry(
            prefix_lru_cache,
            spec,
            entry.clone(),
            main_cache_row,
            Some(mtp_cache_row),
        )?;
        restore_prefix_entry_for_row(main_cache, &entry, main_cache_row, cached_len)?;
        mtp_cache.restore_prefix_layers_for_row_on(
            &entry.mtp_layers,
            mtp_cache_row,
            cached_len,
            (),
        )?;
        let last_hidden = entry
            .mtp_last_hidden
            .ok_or_else(|| anyhow!("paged prefix MTP hit missing last_hidden"))?;
        log_paged_prefix_hit(
            "MTP hit",
            &key,
            main_cache_row,
            Some(mtp_cache_row),
            restore_len,
            stats,
            load_us,
        );
        return Ok(Some((cached_len, last_hidden)));
    }
    Ok(None)
}

fn try_save_paged_prefix_for_prompt_with_mtp(
    config: Option<&PagedPrefixCacheConfig>,
    prefix_lru_cache: Option<&PrefixLruCacheHandle>,
    main_cache: &[LayerCache],
    mtp_cache: &MtpCache,
    last_hidden: &Array,
    prompt_ids: &[u32],
    fingerprint: Option<&str>,
) -> Result<Option<String>> {
    try_save_paged_prefix_for_prompt_with_mtp_row(
        config,
        prefix_lru_cache,
        main_cache,
        0,
        mtp_cache,
        0,
        last_hidden,
        prompt_ids,
        fingerprint,
    )
}

#[allow(clippy::too_many_arguments)]
fn try_save_paged_prefix_for_prompt_with_mtp_row(
    config: Option<&PagedPrefixCacheConfig>,
    prefix_lru_cache: Option<&PrefixLruCacheHandle>,
    main_cache: &[LayerCache],
    main_cache_row: usize,
    mtp_cache: &MtpCache,
    mtp_cache_row: usize,
    last_hidden: &Array,
    prompt_ids: &[u32],
    fingerprint: Option<&str>,
) -> Result<Option<String>> {
    let Some(config) = config else {
        return Ok(None);
    };
    if prompt_ids.is_empty() {
        return Ok(None);
    }
    let Some(cached_len) = cache_row_cached_len(main_cache, main_cache_row)? else {
        return Ok(None);
    };
    if cached_len == 0 {
        return Ok(None);
    }
    if cached_len != prompt_ids.len() as i32 {
        anyhow::bail!(
            "try_save_paged_prefix_for_prompt_with_mtp: main row {main_cache_row} cached_len {cached_len} != token length {}",
            prompt_ids.len()
        );
    }
    let mtp_cached_len = mtp_cache_row_cached_len(mtp_cache, mtp_cache_row)?;
    if mtp_cached_len != cached_len {
        anyhow::bail!(
            "try_save_paged_prefix_for_prompt_with_mtp: MTP row {mtp_cache_row} cached_len {mtp_cached_len} != main {cached_len}"
        );
    }
    let Some(mut spec) = prefix_key_spec_for_caches(
        &config.model_id,
        prompt_ids,
        cached_len,
        fingerprint,
        config.block_size,
        main_cache,
    )?
    else {
        return Ok(None);
    };
    spec.mtp_layers = mtp_layer_specs_for_cache(mtp_cache, cached_len);
    spec.mtp_last_hidden = Some(PrefixTensorSpec::from_array(last_hidden));
    let store = config.store();
    let Some((key, permit)) =
        try_admit_prefix_store_entry(store, &spec, main_cache_row, Some(mtp_cache_row))?
    else {
        return Ok(None);
    };
    let Some(permit) = permit else {
        return Ok(Some(key));
    };
    let Some((mut entry, cached_len)) = prefix_entry_for_row(main_cache, main_cache_row)? else {
        return Ok(None);
    };
    if cached_len == 0 {
        return Ok(None);
    }
    if cached_len != prompt_ids.len() as i32 {
        anyhow::bail!(
            "try_save_paged_prefix_for_prompt_with_mtp: main row {main_cache_row} cached_len {cached_len} != token length {}",
            prompt_ids.len()
        );
    }
    let (mtp_layers, mtp_cached_len) = mtp_cache.prefix_layers_for_row_on(mtp_cache_row, ())?;
    if mtp_cached_len != cached_len {
        anyhow::bail!(
            "try_save_paged_prefix_for_prompt_with_mtp: MTP row {mtp_cache_row} cached_len {mtp_cached_len} != main {cached_len}"
        );
    }
    entry.mtp_layers = mtp_layers;
    entry.mtp_last_hidden = Some(last_hidden.clone());

    spec.mtp_layers = entry.mtp_layer_specs();
    spec.mtp_last_hidden = entry.mtp_last_hidden_spec();
    try_insert_prefix_lru_entry(
        prefix_lru_cache,
        spec.clone(),
        entry.clone(),
        main_cache_row,
        Some(mtp_cache_row),
    )?;
    submit_prefix_store_entry(
        permit,
        key,
        entry,
        cached_len,
        main_cache_row,
        Some(mtp_cache_row),
    )
}

fn empty_prefix_stats(cached_len: i32) -> PagedPrefixEntryStats {
    PagedPrefixEntryStats {
        cached_len,
        ..PagedPrefixEntryStats::default()
    }
}

