fn forward_single_text_suffix<M: Model>(
    model: &M,
    cache: &mut [LayerCache],
    prompt_ids: &[u32],
    start_pos: i32,
    end_pos: i32,
    dummy_position_ids: Option<&Array>,
) -> Result<Array> {
    if start_pos < 0 || start_pos >= end_pos {
        anyhow::bail!("forward_single_text_suffix: invalid range [{start_pos}, {end_pos})");
    }
    let last_pos = end_pos - 1;
    if start_pos < last_pos {
        let prefix_ids = &prompt_ids[start_pos as usize..last_pos as usize];
        let prefix_len = last_pos - start_pos;
        let prefix_arr: Array = (prefix_ids, &[1_i32, prefix_len][..]).try_into()?;
        let prefix_position_ids = if let Some(dummy) = dummy_position_ids {
            dummy.clone()
        } else {
            build_position_ids(start_pos, prefix_len)?
        };
        let prefix_hidden = model.forward_text_hidden(
            &prefix_arr,
            &prefix_position_ids,
            None,
            None,
            Some(&mut *cache),
            mlx::StreamOrDevice::default(),
        )?;
        mlx::transforms::eval(&[&prefix_hidden])?;
    }

    let last_ids = &prompt_ids[last_pos as usize..end_pos as usize];
    let last_arr: Array = (last_ids, &[1_i32, 1_i32][..]).try_into()?;
    let last_position_ids = if let Some(dummy) = dummy_position_ids {
        dummy.clone()
    } else {
        build_position_ids(last_pos, 1)?
    };
    model.forward_on(
        &last_arr,
        &last_position_ids,
        None,
        None,
        Some(cache),
        mlx::StreamOrDevice::default(),
    )
}

fn maybe_build_sparse_decode_mask(
    cache: &[LayerCache],
    per_row_lens: &[i32],
) -> Result<Option<Array>> {
    for row in 0..per_row_lens.len() {
        cache_row_cached_len(cache, row)?;
    }
    let Some(pre_offsets) = cache.iter().find_map(|c| match c {
        LayerCache::Full(kv) => Some(kv.offsets()),
        LayerCache::Mla(mla) => Some(mla.offsets()),
        _ => None,
    }) else {
        return Ok(None);
    };
    anyhow::ensure!(
        pre_offsets.len() == per_row_lens.len(),
        "maybe_build_sparse_decode_mask: offset rows {} != per_row_lens {}",
        pre_offsets.len(),
        per_row_lens.len()
    );
    let max_new_len = per_row_lens
        .iter()
        .copied()
        .max()
        .expect("per_row_lens is non-empty");
    if max_new_len > 1 {
        return build_batched_append_attention_mask(
            pre_offsets,
            per_row_lens,
            max_new_len,
            Dtype::Bfloat16,
        )
        .map(Some);
    }
    let mask_row_lens: Vec<i32> = pre_offsets
        .iter()
        .zip(per_row_lens.iter())
        .map(|(&offset, &new_len)| {
            if offset == 0 && new_len == 0 {
                1
            } else {
                offset + new_len
            }
        })
        .collect();
    let max_real_len = mask_row_lens
        .iter()
        .copied()
        .max()
        .expect("per_row_lens is non-empty");
    maybe_build_decode_mask(&mask_row_lens, max_real_len)
}

fn concat_logits_rows(logit_rows: Vec<Array>) -> Result<Array> {
    let mut rows = Vec::with_capacity(logit_rows.len());
    for row in logit_rows {
        let shape = row.shape();
        let shape = shape.as_slice();
        anyhow::ensure!(
            shape.len() == 1,
            "concat_logits_rows: expected rank-1 row logits, got rank {}",
            shape.len()
        );
        rows.push(row.reshape(&[1_i32, 1_i32, shape[0]][..])?);
    }
    let refs: Vec<&Array> = rows.iter().collect();
    mlx::ops::shape::concatenate(&refs, 0).map_err(anyhow::Error::from)
}

fn prefix_restore_groups(
    prompt_ids: &[Vec<u32>],
    fingerprints: Option<&[Option<String>]>,
) -> Result<Vec<Vec<usize>>> {
    if let Some(fingerprints) = fingerprints {
        anyhow::ensure!(
            fingerprints.len() == prompt_ids.len(),
            "prefix_restore_groups: fingerprints rows {} != prompt rows {}",
            fingerprints.len(),
            prompt_ids.len()
        );
    }

    let mut groups = Vec::new();
    let mut grouped = vec![false; prompt_ids.len()];
    for row in 0..prompt_ids.len() {
        if grouped[row] {
            continue;
        }
        let row_fingerprint = fingerprints.and_then(|values| values[row].as_deref());
        let mut group = vec![row];
        grouped[row] = true;
        for other in row + 1..prompt_ids.len() {
            if grouped[other] || prompt_ids[other] != prompt_ids[row] {
                continue;
            }
            let other_fingerprint = fingerprints.and_then(|values| values[other].as_deref());
            if other_fingerprint != row_fingerprint {
                continue;
            }
            grouped[other] = true;
            group.push(other);
        }
        groups.push(group);
    }
    Ok(groups)
}

struct BatchedTextPrefixReplay<'a> {
    prompt_ids: &'a [Vec<u32>],
    initial_replay_from: &'a [usize],
    prefix_restore_attempted: &'a [bool],
    dummy_position_ids: Option<&'a Array>,
    prefix_cache_config: Option<&'a PagedPrefixCacheConfig>,
    prefix_lru_cache: Option<&'a PrefixLruCacheHandle>,
    runtime_usage: &'a crate::core::runtime_usage::ModelRuntimeUsageCounters,
}

fn batched_text_input_ids(
    prompt_ids: &[Vec<u32>],
    per_row_lens: &[i32],
    max_len: usize,
) -> Result<Array> {
    anyhow::ensure!(
        prompt_ids.len() == per_row_lens.len(),
        "batched_text_input_ids: prompt rows {} != lens {}",
        prompt_ids.len(),
        per_row_lens.len()
    );
    let b = prompt_ids.len();
    let mut flat = vec![0_i32; b * max_len];
    for (row, ids) in prompt_ids.iter().enumerate() {
        let len = usize::try_from(per_row_lens[row])
            .map_err(|_| anyhow!("batched_text_input_ids: negative row length"))?;
        anyhow::ensure!(
            len <= ids.len(),
            "batched_text_input_ids: row {row} len {len} exceeds prompt len {}",
            ids.len()
        );
        anyhow::ensure!(
            len <= max_len,
            "batched_text_input_ids: row {row} len {len} exceeds max_len {max_len}"
        );
        for col in 0..len {
            flat[row * max_len + col] = ids[col] as i32;
        }
    }
    (&flat[..], &[b as i32, max_len as i32][..])
        .try_into()
        .map_err(anyhow::Error::from)
}

#[allow(clippy::too_many_arguments)]
fn forward_batched_text_prefill<M: Model>(
    model: &M,
    input_ids: &Array,
    position_ids: &Array,
    per_row_lens: &[i32],
    max_len: i32,
    cache: Option<&mut [LayerCache]>,
    target: mlx::StreamOrDevice,
) -> Result<Array> {
    if per_row_lens.iter().all(|&len| len == max_len) {
        return model.batched_prefill_causal(input_ids, position_ids, per_row_lens, cache, target);
    }

    let attention_mask = build_batch_attention_mask(per_row_lens, max_len, Dtype::Bfloat16)?;
    let linear_attention_mask = build_batch_linear_mask(per_row_lens, max_len)?;
    model.batched_prefill(
        input_ids,
        position_ids,
        &attention_mask,
        &linear_attention_mask,
        per_row_lens,
        cache,
        target,
    )
}

fn try_save_batched_text_prefix_row(
    prefix_cache_config: Option<&PagedPrefixCacheConfig>,
    prefix_lru_cache: Option<&PrefixLruCacheHandle>,
    cache: &[LayerCache],
    row: usize,
    prompt_ids: &[u32],
    label: &str,
) {
    match try_save_paged_prefix_for_prompt_row(
        prefix_cache_config,
        prefix_lru_cache,
        cache,
        row,
        prompt_ids,
        None,
    ) {
        Ok(Some(key)) => {
            tracing::debug!(
                "paged SSD prefix cache saved batched text {label}: row={row} key={key}"
            );
        }
        Ok(None) => {}
        Err(err) => {
            tracing::warn!(
                "paged SSD prefix cache batched text {label} save skipped: row={row} {err:#}"
            );
        }
    }
}

fn forward_batched_text_cold_miss_with_paged_prefix<M: Model>(
    model: &M,
    cache: &mut [LayerCache],
    prompt_ids: &[Vec<u32>],
    prefix_cache_config: Option<&PagedPrefixCacheConfig>,
    prefix_lru_cache: Option<&PrefixLruCacheHandle>,
) -> Result<Array> {
    let b = prompt_ids.len();
    anyhow::ensure!(
        b > 0,
        "forward_batched_text_cold_miss_with_paged_prefix: empty batch"
    );
    anyhow::ensure!(
        prompt_ids.iter().all(|ids| ids.len() > 1),
        "forward_batched_text_cold_miss_with_paged_prefix: prompt length must be > 1"
    );

    let mut prefix_lens = Vec::with_capacity(b);
    for ids in prompt_ids {
        prefix_lens.push(
            i32::try_from(ids.len() - 1)
                .map_err(|_| anyhow!("batched text prefix length exceeds i32"))?,
        );
    }
    let max_prefix_len = prefix_lens
        .iter()
        .copied()
        .max()
        .expect("batch is non-empty");
    let prefix_input_ids =
        batched_text_input_ids(prompt_ids, &prefix_lens, max_prefix_len as usize)?;
    let position_ids = build_position_ids_batched(&prefix_lens, max_prefix_len)?;
    let prefix_logits = forward_batched_text_prefill(
        model,
        &prefix_input_ids,
        &position_ids,
        &prefix_lens,
        max_prefix_len,
        Some(&mut *cache),
        mlx::StreamOrDevice::default(),
    )?;
    mlx::transforms::eval(&[&prefix_logits])?;

    for (row, ids) in prompt_ids.iter().enumerate() {
        try_save_batched_text_prefix_row(
            prefix_cache_config,
            prefix_lru_cache,
            cache,
            row,
            &ids[..ids.len() - 1],
            "prefix",
        );
    }

    let last_tokens: Vec<i32> = prompt_ids
        .iter()
        .map(|ids| ids.last().copied().expect("prompt len > 1") as i32)
        .collect();
    let last_input_ids: Array = (&last_tokens[..], &[b as i32, 1_i32][..]).try_into()?;
    let per_row_lens = vec![1_i32; b];
    let position_ids = build_decode_position_ids(&prefix_lens)?;
    let decode_mask = maybe_build_sparse_decode_mask(cache, &per_row_lens)?;
    let logits = model.forward_on(
        &last_input_ids,
        &position_ids,
        Some(&per_row_lens),
        decode_mask.as_ref(),
        Some(&mut *cache),
        mlx::StreamOrDevice::default(),
    )?;
    mlx::transforms::eval(&[&logits])?;

    for (row, ids) in prompt_ids.iter().enumerate() {
        try_save_batched_text_prefix_row(
            prefix_cache_config,
            prefix_lru_cache,
            cache,
            row,
            ids,
            "prompt",
        );
    }

    Ok(logits)
}

fn forward_batched_text_with_paged_prefix<M: Model>(
    model: &M,
    cache: &mut [LayerCache],
    input: BatchedTextPrefixReplay<'_>,
) -> Result<Array> {
    let BatchedTextPrefixReplay {
        prompt_ids,
        initial_replay_from,
        prefix_restore_attempted,
        dummy_position_ids,
        prefix_cache_config,
        prefix_lru_cache,
        runtime_usage,
    } = input;
    anyhow::ensure!(
        !prompt_ids.is_empty(),
        "forward_batched_text_with_paged_prefix: empty batch"
    );
    let b = prompt_ids.len();
    anyhow::ensure!(
        initial_replay_from.len() == b,
        "forward_batched_text_with_paged_prefix: initial replay rows {} != batch {b}",
        initial_replay_from.len()
    );
    anyhow::ensure!(
        prefix_restore_attempted.len() == b,
        "forward_batched_text_with_paged_prefix: attempted rows {} != batch {b}",
        prefix_restore_attempted.len()
    );
    let mut replay_from = initial_replay_from.to_vec();
    for group in prefix_restore_groups(prompt_ids, None)? {
        let first_row = group[0];
        if prefix_restore_attempted[first_row] {
            anyhow::ensure!(
                group.iter().all(|&row| prefix_restore_attempted[row]
                    && replay_from[row] == replay_from[first_row]),
                "prefix restore state diverged inside an identical-prompt group"
            );
            continue;
        }
        let restored = try_restore_paged_prefix_for_prompt_rows(
            prefix_cache_config,
            prefix_lru_cache,
            cache,
            &group,
            &prompt_ids[first_row],
            None,
        )?
        .unwrap_or(0) as usize;
        runtime_usage
            .record_prefix_cache_hit_tokens((restored as u64).saturating_mul(group.len() as u64));
        for row in group {
            replay_from[row] = restored;
        }
    }

    if dummy_position_ids.is_none()
        && replay_from.iter().all(|&pos| pos == 0)
        && prompt_ids.iter().all(|ids| ids.len() > 1)
    {
        return forward_batched_text_cold_miss_with_paged_prefix(
            model,
            cache,
            prompt_ids,
            prefix_cache_config,
            prefix_lru_cache,
        );
    }

    let max_len = prompt_ids.iter().map(Vec::len).max().unwrap_or(0);
    let mut final_logits: Vec<Option<Array>> = (0..b).map(|_| None).collect();

    for pos in 0..max_len {
        let mut token_flat = vec![0_i32; b];
        let mut per_row_lens = vec![0_i32; b];
        let mut per_row_pos = vec![0_i32; b];
        let mut has_active = false;

        for (row, ids) in prompt_ids.iter().enumerate() {
            if pos < replay_from[row] || pos >= ids.len() {
                continue;
            }
            token_flat[row] = ids[pos] as i32;
            per_row_lens[row] = 1;
            per_row_pos[row] = pos as i32;
            has_active = true;
        }
        if !has_active {
            continue;
        }

        let input_ids: Array = (&token_flat[..], &[b as i32, 1_i32][..]).try_into()?;
        let position_ids = if let Some(dummy) = dummy_position_ids {
            dummy.clone()
        } else {
            build_decode_position_ids(&per_row_pos)?
        };
        let decode_mask = maybe_build_sparse_decode_mask(cache, &per_row_lens)?;
        let logits = model.forward_on(
            &input_ids,
            &position_ids,
            Some(&per_row_lens),
            decode_mask.as_ref(),
            Some(&mut *cache),
            mlx::StreamOrDevice::default(),
        )?;
        mlx::transforms::eval(&[&logits])?;

        for (row, ids) in prompt_ids.iter().enumerate() {
            if per_row_lens[row] == 0 {
                continue;
            }
            if ids.len() > 1 && pos + 2 == ids.len() {
                match try_save_paged_prefix_for_prompt_row(
                    prefix_cache_config,
                    prefix_lru_cache,
                    cache,
                    row,
                    &ids[..ids.len() - 1],
                    None,
                ) {
                    Ok(Some(key)) => {
                        tracing::debug!(
                            "paged SSD prefix cache saved batched text prefix: row={row} key={key}"
                        );
                    }
                    Ok(None) => {}
                    Err(err) => {
                        tracing::warn!(
                            "paged SSD prefix cache batched text prefix save skipped: row={row} {err:#}"
                        );
                    }
                }
            }
            if pos + 1 == ids.len() {
                match try_save_paged_prefix_for_prompt_row(
                    prefix_cache_config,
                    prefix_lru_cache,
                    cache,
                    row,
                    ids,
                    None,
                ) {
                    Ok(Some(key)) => {
                        tracing::debug!(
                            "paged SSD prefix cache saved batched text prompt: row={row} key={key}"
                        );
                    }
                    Ok(None) => {}
                    Err(err) => {
                        tracing::warn!(
                            "paged SSD prefix cache batched text prompt save skipped: row={row} {err:#}"
                        );
                    }
                }
                final_logits[row] = Some(slice_logits_row(&logits, row)?);
            }
        }
    }

    let mut rows = Vec::with_capacity(b);
    for (row, logits) in final_logits.into_iter().enumerate() {
        rows.push(logits.ok_or_else(|| {
            anyhow!("forward_batched_text_with_paged_prefix: missing final logits for row {row}")
        })?);
    }
    concat_logits_rows(rows)
}

fn build_vl_position_stream(
    prompt_ids: &[i32],
    grid_thw: GridThwSlice<'_>,
    image_token_id: i32,
    image_spatial_merge_size: i32,
) -> Result<Vec<i32>> {
    let len = prompt_ids.len();
    anyhow::ensure!(!prompt_ids.is_empty(), "VL prefix replay: empty prompt row");
    match grid_thw {
        Some(grids) if !grids.is_empty() => {
            let position_ids =
                build_position_ids_vl(prompt_ids, grids, image_token_id, image_spatial_merge_size)?;
            position_ids
                .to_vec::<i32>()
                .map_err(|e| anyhow!("VL prefix replay position_ids to_vec failed: {e}"))
        }
        _ => {
            let mut flat = vec![0_i32; 3 * len];
            for col in 0..len {
                flat[col] = col as i32;
                flat[len + col] = col as i32;
                flat[2 * len + col] = col as i32;
            }
            Ok(flat)
        }
    }
}

struct BatchedVlPrefixReplay<'a> {
    prompt_ids: &'a [Vec<i32>],
    pixel_values: &'a [PixelValuesSlice<'a>],
    grid_thw: &'a [GridThwSlice<'a>],
    image_token_id: i32,
    image_spatial_merge_size: i32,
    dummy_position_ids: Option<&'a Array>,
    prefix_cache_config: Option<&'a PagedPrefixCacheConfig>,
    prefix_lru_cache: Option<&'a PrefixLruCacheHandle>,
    runtime_usage: &'a crate::core::runtime_usage::ModelRuntimeUsageCounters,
}

fn batched_vl_input_ids(
    prompt_ids: &[Vec<i32>],
    per_row_lens: &[i32],
    max_len: usize,
) -> Result<Array> {
    anyhow::ensure!(
        prompt_ids.len() == per_row_lens.len(),
        "batched_vl_input_ids: prompt rows {} != lens {}",
        prompt_ids.len(),
        per_row_lens.len()
    );
    let b = prompt_ids.len();
    let mut flat = vec![0_i32; b * max_len];
    for (row, ids) in prompt_ids.iter().enumerate() {
        let len = usize::try_from(per_row_lens[row])
            .map_err(|_| anyhow!("batched_vl_input_ids: negative row length"))?;
        anyhow::ensure!(
            len <= ids.len(),
            "batched_vl_input_ids: row {row} len {len} exceeds prompt len {}",
            ids.len()
        );
        anyhow::ensure!(
            len <= max_len,
            "batched_vl_input_ids: row {row} len {len} exceeds max_len {max_len}"
        );
        for col in 0..len {
            flat[row * max_len + col] = ids[col];
        }
    }
    (&flat[..], &[b as i32, max_len as i32][..])
        .try_into()
        .map_err(anyhow::Error::from)
}

fn batched_vl_last_position_ids(
    prompt_ids: &[Vec<i32>],
    grid_thw: &[GridThwSlice<'_>],
    image_token_id: i32,
    image_spatial_merge_size: i32,
) -> Result<Array> {
    let b = prompt_ids.len();
    anyhow::ensure!(
        grid_thw.len() == b,
        "batched_vl_last_position_ids: grid rows {} != batch {b}",
        grid_thw.len()
    );
    let mut flat = vec![0_i32; 3 * b];
    for row in 0..b {
        let ids = &prompt_ids[row];
        anyhow::ensure!(
            !ids.is_empty(),
            "batched_vl_last_position_ids: row {row} has empty prompt"
        );
        let row_stream =
            build_vl_position_stream(ids, grid_thw[row], image_token_id, image_spatial_merge_size)?;
        let pos = ids.len() - 1;
        for stream in 0..3 {
            flat[stream * b + row] = row_stream[stream * ids.len() + pos];
        }
    }
    (&flat[..], &[3_i32, b as i32, 1_i32][..])
        .try_into()
        .map_err(anyhow::Error::from)
}

fn try_save_batched_vl_prefix_row(
    prefix_cache_config: Option<&PagedPrefixCacheConfig>,
    prefix_lru_cache: Option<&PrefixLruCacheHandle>,
    cache: &[LayerCache],
    row: usize,
    prompt_ids: &[u32],
    fingerprint: Option<&str>,
    label: &str,
) {
    match try_save_paged_prefix_for_prompt_row(
        prefix_cache_config,
        prefix_lru_cache,
        cache,
        row,
        prompt_ids,
        fingerprint,
    ) {
        Ok(Some(key)) => {
            tracing::debug!("paged SSD prefix cache saved batched VL {label}: row={row} key={key}");
        }
        Ok(None) => {}
        Err(err) => {
            tracing::warn!(
                "paged SSD prefix cache batched VL {label} save skipped: row={row} {err:#}"
            );
        }
    }
}

#[allow(clippy::too_many_arguments)]
fn forward_batched_vl_cold_miss_with_paged_prefix<M: Model + DenseVlMethods>(
    model: &M,
    cache: &mut [LayerCache],
    prompt_ids: &[Vec<i32>],
    prompt_ids_u32: &[Vec<u32>],
    pixel_values: &[PixelValuesSlice<'_>],
    grid_thw: &[GridThwSlice<'_>],
    image_token_id: i32,
    image_spatial_merge_size: i32,
    dummy_position_ids: Option<&Array>,
    prefix_cache_config: Option<&PagedPrefixCacheConfig>,
    prefix_lru_cache: Option<&PrefixLruCacheHandle>,
    fingerprints: &[Option<String>],
) -> Result<Array> {
    let b = prompt_ids.len();
    anyhow::ensure!(
        b > 0,
        "forward_batched_vl_cold_miss_with_paged_prefix: empty batch"
    );
    anyhow::ensure!(
        prompt_ids.iter().all(|ids| ids.len() > 1),
        "forward_batched_vl_cold_miss_with_paged_prefix: prompt length must be > 1"
    );
    anyhow::ensure!(
        prompt_ids_u32.len() == b
            && pixel_values.len() == b
            && grid_thw.len() == b
            && fingerprints.len() == b,
        "forward_batched_vl_cold_miss_with_paged_prefix: per-row inputs must match batch"
    );

    let mut prefix_lens = Vec::with_capacity(b);
    for ids in prompt_ids {
        prefix_lens.push(
            i32::try_from(ids.len() - 1)
                .map_err(|_| anyhow!("batched VL prefix length exceeds i32"))?,
        );
    }
    let max_prefix_len = prefix_lens
        .iter()
        .copied()
        .max()
        .expect("batch is non-empty");
    let max_prefix_len_usize = usize::try_from(max_prefix_len)
        .map_err(|_| anyhow!("batched VL max prefix length is negative"))?;
    let prefix_input_ids = batched_vl_input_ids(prompt_ids, &prefix_lens, max_prefix_len_usize)?;
    let prefix_prompt_refs: Vec<&[i32]> = prompt_ids
        .iter()
        .zip(prefix_lens.iter())
        .map(|(ids, &len)| &ids[..len as usize])
        .collect();
    let prefix_position_ids = if let Some(dummy) = dummy_position_ids {
        dummy.clone()
    } else {
        build_position_ids_vl_batched(
            &prefix_prompt_refs,
            grid_thw,
            image_token_id,
            image_spatial_merge_size,
            max_prefix_len,
        )?
    };
    let attention_mask = build_batch_attention_mask(&prefix_lens, max_prefix_len, Dtype::Bfloat16)?;
    let linear_attention_mask = build_batch_linear_mask(&prefix_lens, max_prefix_len)?;
    let prefix_logits = model.batched_prefill_vl(
        &prefix_input_ids,
        &prefix_position_ids,
        &attention_mask,
        &linear_attention_mask,
        &prefix_lens,
        pixel_values,
        grid_thw,
        image_token_id,
        Some(&mut *cache),
        mlx::StreamOrDevice::default(),
    )?;
    mlx::transforms::eval(&[&prefix_logits])?;

    for row in 0..b {
        try_save_batched_vl_prefix_row(
            prefix_cache_config,
            prefix_lru_cache,
            cache,
            row,
            &prompt_ids_u32[row][..prompt_ids_u32[row].len() - 1],
            fingerprints[row].as_deref(),
            "prefix",
        );
    }

    let last_tokens: Vec<i32> = prompt_ids
        .iter()
        .map(|ids| ids.last().copied().expect("prompt len > 1"))
        .collect();
    let last_input_ids: Array = (&last_tokens[..], &[b as i32, 1_i32][..]).try_into()?;
    let per_row_lens = vec![1_i32; b];
    let position_ids = if let Some(dummy) = dummy_position_ids {
        dummy.clone()
    } else {
        batched_vl_last_position_ids(
            prompt_ids,
            grid_thw,
            image_token_id,
            image_spatial_merge_size,
        )?
    };
    let decode_mask = maybe_build_sparse_decode_mask(cache, &per_row_lens)?;
    let logits = model.forward_vl_chunk(
        &last_input_ids,
        &position_ids,
        Some(&per_row_lens),
        decode_mask.as_ref(),
        Some(&mut *cache),
        None,
        image_token_id,
        mlx::StreamOrDevice::default(),
    )?;
    mlx::transforms::eval(&[&logits])?;

    for row in 0..b {
        try_save_batched_vl_prefix_row(
            prefix_cache_config,
            prefix_lru_cache,
            cache,
            row,
            &prompt_ids_u32[row],
            fingerprints[row].as_deref(),
            "prompt",
        );
    }

    Ok(logits)
}

fn forward_batched_vl_with_paged_prefix<M: Model + DenseVlMethods>(
    model: &M,
    cache: &mut [LayerCache],
    input: BatchedVlPrefixReplay<'_>,
) -> Result<Array> {
    let BatchedVlPrefixReplay {
        prompt_ids,
        pixel_values,
        grid_thw,
        image_token_id,
        image_spatial_merge_size,
        dummy_position_ids,
        prefix_cache_config,
        prefix_lru_cache,
        runtime_usage,
    } = input;
    let b = prompt_ids.len();
    anyhow::ensure!(b > 0, "forward_batched_vl_with_paged_prefix: empty batch");
    anyhow::ensure!(
        pixel_values.len() == b,
        "forward_batched_vl_with_paged_prefix: pixel_values rows {} != batch {b}",
        pixel_values.len()
    );
    anyhow::ensure!(
        grid_thw.len() == b,
        "forward_batched_vl_with_paged_prefix: grid_thw rows {} != batch {b}",
        grid_thw.len()
    );

    let prompt_ids_u32: Vec<Vec<u32>> = prompt_ids
        .iter()
        .map(|ids| ids.iter().map(|&tok| tok as u32).collect())
        .collect();
    let mut fingerprints = Vec::with_capacity(b);
    for row in 0..b {
        let fingerprint = if prefix_cache_config.is_some() {
            paged_prefix_fingerprint_for_request(
                pixel_values[row],
                grid_thw[row],
                image_token_id,
                image_spatial_merge_size,
            )?
        } else {
            None
        };
        fingerprints.push(fingerprint);
    }

    let mut replay_from = vec![0_usize; b];
    for group in prefix_restore_groups(&prompt_ids_u32, Some(&fingerprints))? {
        let first_row = group[0];
        let restored = try_restore_paged_prefix_for_prompt_rows(
            prefix_cache_config,
            prefix_lru_cache,
            cache,
            &group,
            &prompt_ids_u32[first_row],
            fingerprints[first_row].as_deref(),
        )?
        .unwrap_or(0) as usize;
        runtime_usage
            .record_prefix_cache_hit_tokens((restored as u64).saturating_mul(group.len() as u64));
        for row in group {
            replay_from[row] = restored;
        }
    }

    if replay_from.iter().all(|&pos| pos == 0)
        && prompt_ids.iter().all(|ids| ids.len() > 1)
        && prompt_ids
            .iter()
            .all(|ids| ids.last().copied() != Some(image_token_id))
    {
        return forward_batched_vl_cold_miss_with_paged_prefix(
            model,
            cache,
            prompt_ids,
            &prompt_ids_u32,
            pixel_values,
            grid_thw,
            image_token_id,
            image_spatial_merge_size,
            dummy_position_ids,
            prefix_cache_config,
            prefix_lru_cache,
            &fingerprints,
        );
    }

    let position_streams = if dummy_position_ids.is_some() {
        Vec::new()
    } else {
        let mut streams = Vec::with_capacity(b);
        for row in 0..b {
            streams.push(build_vl_position_stream(
                &prompt_ids[row],
                grid_thw[row],
                image_token_id,
                image_spatial_merge_size,
            )?);
        }
        streams
    };

    let mut vision_embeds_full = Vec::with_capacity(b);
    for row in 0..b {
        let embeds = match (pixel_values[row], grid_thw[row]) {
            (Some(pv), Some(grids)) if !grids.is_empty() => {
                Some(model.compute_vision_embeds(pv, grids, mlx::StreamOrDevice::default())?)
            }
            (Some(_), None) => {
                anyhow::bail!(
                    "forward_batched_vl_with_paged_prefix: row {row} has pixel_values but grid_thw is None"
                );
            }
            _ => None,
        };
        vision_embeds_full.push(embeds);
    }

    let max_len = prompt_ids.iter().map(Vec::len).max().unwrap_or(0);
    let mut final_logits: Vec<Option<Array>> = (0..b).map(|_| None).collect();

    for pos in 0..max_len {
        let mut token_flat = vec![0_i32; b];
        let mut per_row_lens = vec![0_i32; b];
        let mut has_active = false;

        for row in 0..b {
            let ids = &prompt_ids[row];
            if pos < replay_from[row] || pos >= ids.len() {
                continue;
            }
            token_flat[row] = ids[pos];
            per_row_lens[row] = 1;
            has_active = true;
        }
        if !has_active {
            continue;
        }

        let input_ids: Array = (&token_flat[..], &[b as i32, 1_i32][..]).try_into()?;
        let position_ids = if let Some(dummy) = dummy_position_ids {
            dummy.clone()
        } else {
            let mut flat = vec![0_i32; 3 * b];
            for row in 0..b {
                if per_row_lens[row] == 0 {
                    continue;
                }
                let row_len = prompt_ids[row].len();
                let row_stream = &position_streams[row];
                for stream in 0..3 {
                    flat[stream * b + row] = row_stream[stream * row_len + pos];
                }
            }
            (&flat[..], &[3_i32, b as i32, 1_i32][..]).try_into()?
        };

        let mut vision_slices = Vec::new();
        for row in 0..b {
            if per_row_lens[row] == 0 || token_flat[row] != image_token_id {
                continue;
            }
            let embeds = vision_embeds_full[row].as_ref().ok_or_else(|| {
                anyhow!(
                    "forward_batched_vl_with_paged_prefix: row {row} image token without vision embeds"
                )
            })?;
            let image_row = prompt_ids[row][..pos]
                .iter()
                .filter(|&&tok| tok == image_token_id)
                .count();
            vision_slices.push(slice_vision_embeds_rows(embeds, image_row, image_row + 1)?);
        }
        let vision_embeds_slice = match vision_slices.len() {
            0 => None,
            1 => vision_slices.pop(),
            _ => {
                let refs: Vec<&Array> = vision_slices.iter().collect();
                Some(
                    mlx::ops::shape::concatenate(&refs, 0)
                        .map_err(|e| anyhow!("VL prefix replay vision concatenate failed: {e}"))?,
                )
            }
        };

        let decode_mask = maybe_build_sparse_decode_mask(cache, &per_row_lens)?;
        let logits = model.forward_vl_chunk(
            &input_ids,
            &position_ids,
            Some(&per_row_lens),
            decode_mask.as_ref(),
            Some(&mut *cache),
            vision_embeds_slice.as_ref(),
            image_token_id,
            mlx::StreamOrDevice::default(),
        )?;
        mlx::transforms::eval(&[&logits])?;

        for row in 0..b {
            if per_row_lens[row] == 0 {
                continue;
            }
            let ids = &prompt_ids[row];
            let ids_u32 = &prompt_ids_u32[row];
            let fingerprint = fingerprints[row].as_deref();
            if ids.len() > 1 && pos + 2 == ids.len() {
                match try_save_paged_prefix_for_prompt_row(
                    prefix_cache_config,
                    prefix_lru_cache,
                    cache,
                    row,
                    &ids_u32[..ids_u32.len() - 1],
                    fingerprint,
                ) {
                    Ok(Some(key)) => {
                        tracing::debug!(
                            "paged SSD prefix cache saved batched VL prefix: row={row} key={key}"
                        );
                    }
                    Ok(None) => {}
                    Err(err) => {
                        tracing::warn!(
                            "paged SSD prefix cache batched VL prefix save skipped: row={row} {err:#}"
                        );
                    }
                }
            }
            if pos + 1 == ids.len() {
                match try_save_paged_prefix_for_prompt_row(
                    prefix_cache_config,
                    prefix_lru_cache,
                    cache,
                    row,
                    ids_u32,
                    fingerprint,
                ) {
                    Ok(Some(key)) => {
                        tracing::debug!(
                            "paged SSD prefix cache saved batched VL prompt: row={row} key={key}"
                        );
                    }
                    Ok(None) => {}
                    Err(err) => {
                        tracing::warn!(
                            "paged SSD prefix cache batched VL prompt save skipped: row={row} {err:#}"
                        );
                    }
                }
                final_logits[row] = Some(slice_logits_row(&logits, row)?);
            }
        }
    }

    let mut rows = Vec::with_capacity(b);
    for (row, logits) in final_logits.into_iter().enumerate() {
        rows.push(logits.ok_or_else(|| {
            anyhow!("forward_batched_vl_with_paged_prefix: missing final logits for row {row}")
        })?);
    }
    concat_logits_rows(rows)
}

fn count_image_pad_i32(tokens: &[i32], image_token_id: i32) -> usize {
    tokens.iter().filter(|&&tok| tok == image_token_id).count()
}

fn slice_vision_embeds_for_image_pads(
    vision_embeds_full: Option<&Array>,
    start: usize,
    count: usize,
) -> Result<Option<Array>> {
    if count == 0 {
        return Ok(None);
    }
    let ve_full = vision_embeds_full
        .ok_or_else(|| anyhow!("slice_vision_embeds_for_image_pads: image pads without embeds"))?;
    Ok(Some(slice_vision_embeds_rows(
        ve_full,
        start,
        start + count,
    )?))
}

struct SingleVlSuffixInput<'a> {
    prompt_ids: &'a [i32],
    start_pos: i32,
    end_pos: i32,
    position_ids_full: &'a Array,
    position_ids_is_dummy: bool,
    vision_embeds_full: Option<&'a Array>,
    image_token_id: i32,
}

fn forward_single_vl_suffix<M: Model + DenseVlMethods>(
    model: &M,
    cache: &mut [LayerCache],
    input: SingleVlSuffixInput<'_>,
) -> Result<Array> {
    let SingleVlSuffixInput {
        prompt_ids,
        start_pos,
        end_pos,
        position_ids_full,
        position_ids_is_dummy,
        vision_embeds_full,
        image_token_id,
    } = input;
    if start_pos < 0 || start_pos >= end_pos {
        anyhow::bail!("forward_single_vl_suffix: invalid range [{start_pos}, {end_pos})");
    }
    let last_pos = end_pos - 1;
    let image_pads_before = count_image_pad_i32(&prompt_ids[..start_pos as usize], image_token_id);
    let mut image_pad_cursor = image_pads_before;

    if start_pos < last_pos {
        let prefix_ids = &prompt_ids[start_pos as usize..last_pos as usize];
        let prefix_len = last_pos - start_pos;
        let prefix_arr: Array = (prefix_ids, &[1_i32, prefix_len][..]).try_into()?;
        let prefix_position_ids = if position_ids_is_dummy {
            position_ids_full.clone()
        } else {
            slice_pos_ids_axis2(position_ids_full, start_pos, last_pos)?
        };
        let prefix_image_pads = count_image_pad_i32(prefix_ids, image_token_id);
        let prefix_vision_embeds = slice_vision_embeds_for_image_pads(
            vision_embeds_full,
            image_pad_cursor,
            prefix_image_pads,
        )?;
        image_pad_cursor += prefix_image_pads;
        let prefix_hidden = model.forward_vl_hidden(
            &prefix_arr,
            &prefix_position_ids,
            None,
            None,
            Some(&mut *cache),
            prefix_vision_embeds.as_ref(),
            image_token_id,
            mlx::StreamOrDevice::default(),
        )?;
        mlx::transforms::eval(&[&prefix_hidden])?;
    }

    let last_ids = &prompt_ids[last_pos as usize..end_pos as usize];
    let last_arr: Array = (last_ids, &[1_i32, 1_i32][..]).try_into()?;
    let last_position_ids = if position_ids_is_dummy {
        position_ids_full.clone()
    } else {
        slice_pos_ids_axis2(position_ids_full, last_pos, end_pos)?
    };
    let last_image_pads = count_image_pad_i32(last_ids, image_token_id);
    let last_vision_embeds =
        slice_vision_embeds_for_image_pads(vision_embeds_full, image_pad_cursor, last_image_pads)?;

    model.forward_vl_chunk(
        &last_arr,
        &last_position_ids,
        None,
        None,
        Some(cache),
        last_vision_embeds.as_ref(),
        image_token_id,
        mlx::StreamOrDevice::default(),
    )
}

/// Fixed-capacity scheduler holding up to `b_max` in-flight requests.
///
/// 3a is single-threaded only — no `Send + Sync` impls. A later sub-phase
/// will decide whether to run the scheduler on the main runtime thread or
/// in `tokio::spawn_blocking`.
pub struct Scheduler<M: Model> {
    b_max: usize,
    slots: Vec<Option<RequestState>>,
    next_id: u64,
    phase: Phase,
    cache: Option<Vec<LayerCache>>,
    /// Scheduler slot rows represented by `cache` batch rows. The cache is
    /// compact: `cache_rows[i]` is the scheduler slot stored at model batch
    /// row `i`.
    cache_rows: Vec<usize>,
    request_block_tables: HashMap<RequestId, RequestBlockTable>,
    request_owned_kv_forks: u64,
    request_owned_kv_layout_rebuilds: u64,
    request_owned_kv_layout_rebuild_page_copies: u64,
    immutable_prefix_blocks: Option<ImmutablePrefixBlockPool>,
    /// Reusable placeholder for models that derive positions internally and
    /// do not consume caller-built MRoPE position ids.
    dummy_position_ids: Option<Array>,
    /// Optional row-scoped MTP runtime state for active speculative rows.
    mtp_state: Option<SchedulerMtpState>,
    /// Optional row-scoped Gemma4 assistant-drafter runtime state.
    gemma4_drafter_state: Option<SchedulerGemma4DrafterState>,
    /// Optional request-local CPU PromptLookup state.
    prompt_lookup_state: Option<SchedulerPromptLookupState>,
    /// Immutable histories shared only within this model-engine trust domain.
    shared_prompt_lookup_pool: Option<SharedPromptLookupPool>,
    poisoned: bool,
    /// Upper bound on `prompt_len + max_new_tokens` per request, computed
    /// at boot as `min(cli_max_cache_cap, model.config.max_position_embeddings)`.
    /// `admit` and `admit_mid` reject requests exceeding this with
    /// [`SchedulerError::RequestTooLarge`]. B1-p2.3f.
    effective_cap_max: usize,
    /// Centralized per-row PRNG state, shape `[b_max, 2]` u32.
    /// Row `i` holds the PRNG key for slot `i`. Initialized to zeros;
    /// `init_row_prng` seeds a row on every new admission. (B1-p2.3e.2)
    pub(crate) prng_state: Array,
    /// Runtime memory budget tracker. Charged at admit; released on slot
    /// clear. Also holds the soft_limit for admission gating. (B1-p2.5)
    pub(crate) budget_state: crate::core::memory_budget::BudgetState,
    /// Snapshot of the model's memory-budget metadata, used to compute
    /// per-request KV byte cost in admit. (B1-p2.5)
    pub(crate) meta: crate::core::memory_budget::ModelMeta,
    /// Count of admits rejected by the memory budget gate. Used by T3
    /// /healthz. (B1-p2.5)
    pub(crate) memory_budget_exceeded_count: std::sync::Arc<std::sync::atomic::AtomicU64>,
    /// Optional paged SSD prefix cache. When set, full-attention KV caches use
    /// paged storage; text-only single-row prefill can restore/save prompt
    /// prefixes through the on-disk store.
    paged_prefix_cache: Option<PagedPrefixCacheConfig>,
    /// Optional process-local hot prefix cache layered above the SSD store.
    prefix_lru_cache: Option<PrefixLruCacheHandle>,
    /// Optional request-level Active KV offload store. Disabled by default.
    active_kv_store: Option<ActiveKvOffloadStore>,
    /// Active KV runtime config. Also drives transparent paged hot/cold tiering
    /// when paged full-attention KV storage is active.
    active_kv_config: ActiveKvOffloadConfig,
    /// Shared Active KV metrics used by `/healthz` and Dashboard status.
    active_kv_stats: Option<ActiveKvOffloadSharedStats>,
    process_memory_governor: Option<crate::core::process_memory::SharedProcessMemoryGovernor>,
    cold_materialization_tracker:
        Arc<OnceLock<Arc<crate::core::process_memory::ColdMaterializationTracker>>>,
    runtime_usage: Arc<crate::core::runtime_usage::ModelRuntimeUsageCounters>,
    governor_admission_reservations:
        HashMap<RequestId, crate::core::process_memory::MemoryReservation>,
    _marker: PhantomData<fn(&M) -> ()>,
}

impl<M: Model> std::fmt::Debug for Scheduler<M> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("Scheduler")
            .field("b_max", &self.b_max)
            .field("slots", &self.slots)
            .field("next_id", &self.next_id)
            .field("phase", &self.phase)
            .field("cache_layers", &self.cache.as_ref().map(|c| c.len()))
            .field("cache_rows", &self.cache_rows)
            .field("has_dummy_position_ids", &self.dummy_position_ids.is_some())
            .field("has_mtp_state", &self.mtp_state.is_some())
            .field(
                "has_gemma4_drafter_state",
                &self.gemma4_drafter_state.is_some(),
            )
            .field("has_prefix_lru_cache", &self.prefix_lru_cache.is_some())
            .field("has_active_kv_store", &self.active_kv_store.is_some())
            .field("poisoned", &self.poisoned)
            .finish()
    }
}

impl<M: Model> Scheduler<M> {
    /// Construct a scheduler with `b_max` pre-allocated slots, all `None`.
    /// `effective_cap_max` is the hard upper bound on per-request
    /// `prompt_len + max_new_tokens` — admit gates reject requests beyond
    /// this with [`SchedulerError::RequestTooLarge`] (HTTP 413 downstream).
    ///
    /// Validates startup memory budget via `validate_startup_budget`; returns
    /// `Err(MemoryBudgetError)` if `b_max × effective_cap_max × per_token_bytes`
    /// exceeds available system RAM. (B1-p2.5)
    ///
    /// **Thread affinity**: `Array::zeros` for `prng_state` is allocated on
    /// the current thread's Metal Stream. Call this on the thread that will
    /// own the Scheduler. For actor spawning, prefer [`Scheduler::new_with_state`]
    /// so budget validation can happen on the calling thread while Array
    /// allocation happens on the worker thread.
    pub fn new(
        b_max: usize,
        effective_cap_max: usize,
        meta: crate::core::memory_budget::ModelMeta,
    ) -> Result<Self, crate::core::memory_budget::MemoryBudgetError> {
        let budget_state =
            crate::core::memory_budget::validate_startup_budget(b_max, effective_cap_max, &meta)?;
        let memory_budget_exceeded_count =
            std::sync::Arc::new(std::sync::atomic::AtomicU64::new(0));
        Self::new_with_state(
            b_max,
            effective_cap_max,
            budget_state,
            memory_budget_exceeded_count,
            meta,
        )
    }

    /// Variant that accepts pre-created [`BudgetState`] and
    /// `memory_budget_exceeded_count` Arc. Used by [`spawn_scheduler_actor`]
    /// for thread-affinity-correct construction: budget validation happens on
    /// the calling thread; Array allocation (prng_state) happens inside
    /// `spawn_blocking` on the worker thread that will own the Scheduler.
    ///
    /// Callers are responsible for ensuring `budget_state` was produced by
    /// [`validate_startup_budget`] with consistent `b_max` / `effective_cap_max`.
    pub fn new_with_state(
        b_max: usize,
        effective_cap_max: usize,
        budget_state: crate::core::memory_budget::BudgetState,
        memory_budget_exceeded_count: std::sync::Arc<std::sync::atomic::AtomicU64>,
        meta: crate::core::memory_budget::ModelMeta,
    ) -> Result<Self, crate::core::memory_budget::MemoryBudgetError> {
        let mut slots = Vec::with_capacity(b_max);
        for _ in 0..b_max {
            slots.push(None);
        }
        // Initialize prng_state to zeros [b_max, 2] u32. Each slot's row is
        // seeded via init_row_prng on admission.
        // IMPORTANT: Array::zeros binds to the current thread's Metal Stream.
        // This method must be called on the thread that will drive the Scheduler.
        let prng_state =
            Array::zeros(&[b_max as i32, 2_i32][..], Dtype::Uint32).expect("prng_state zeros");
        Ok(Self {
            b_max,
            slots,
            next_id: 0,
            phase: Phase::Idle,
            cache: None,
            cache_rows: Vec::new(),
            request_block_tables: HashMap::new(),
            request_owned_kv_forks: 0,
            request_owned_kv_layout_rebuilds: 0,
            request_owned_kv_layout_rebuild_page_copies: 0,
            immutable_prefix_blocks: None,
            dummy_position_ids: None,
            mtp_state: None,
            gemma4_drafter_state: None,
            prompt_lookup_state: None,
            shared_prompt_lookup_pool: None,
            poisoned: false,
            effective_cap_max,
            prng_state,
            budget_state,
            meta,
            memory_budget_exceeded_count,
            paged_prefix_cache: None,
            prefix_lru_cache: None,
            active_kv_store: None,
            active_kv_config: ActiveKvOffloadConfig::disabled(),
            active_kv_stats: None,
            process_memory_governor: None,
            cold_materialization_tracker: Arc::new(OnceLock::new()),
            runtime_usage: Arc::new(
                crate::core::runtime_usage::ModelRuntimeUsageCounters::default(),
            ),
            governor_admission_reservations: HashMap::new(),
            _marker: PhantomData,
        })
    }

    pub fn enable_paged_prefix_cache(&mut self, config: PagedPrefixCacheConfig) -> Result<()> {
        config.validate()?;
        self.immutable_prefix_blocks = Some(ImmutablePrefixBlockPool::new(
            config.model_id.clone(),
            config.block_size,
            config.max_pages,
            self.b_max,
        ));
        self.paged_prefix_cache = Some(config);
        Ok(())
    }

    pub fn enable_prefix_lru_cache(&mut self, config: PrefixLruCacheConfig) -> Result<()> {
        if self.paged_prefix_cache.is_none() {
            anyhow::bail!("prefix LRU cache requires paged prefix cache");
        }
        self.prefix_lru_cache = Some(Arc::new(Mutex::new(PrefixLruCache::new(config)?)));
        Ok(())
    }

    pub fn enable_shared_prefix_lru_cache(&mut self, cache: SharedPrefixLruCache) -> Result<()> {
        if self.paged_prefix_cache.is_none() {
            anyhow::bail!("prefix LRU cache requires paged prefix cache");
        }
        self.prefix_lru_cache = Some(cache);
        Ok(())
    }

    pub fn enable_active_kv_offload(
        &mut self,
        config: ActiveKvOffloadConfig,
        stats: ActiveKvOffloadSharedStats,
    ) -> Result<()> {
        if !config.enabled {
            self.active_kv_store = None;
            self.active_kv_config = config;
            self.active_kv_stats = Some(stats);
            return Ok(());
        }
        self.active_kv_store = Some(ActiveKvOffloadStore::new(config.clone())?);
        self.active_kv_config = config;
        self.active_kv_stats = Some(stats);
        Ok(())
    }

    pub fn active_kv_offload_enabled(&self) -> bool {
        self.active_kv_store.is_some()
    }

    pub fn enable_process_memory_governor(
        &mut self,
        governor: crate::core::process_memory::SharedProcessMemoryGovernor,
    ) {
        governor.sample_process();
        self.process_memory_governor = Some(governor);
    }

    pub(crate) fn share_cold_materialization_tracker(
        &mut self,
        tracker: Arc<OnceLock<Arc<crate::core::process_memory::ColdMaterializationTracker>>>,
    ) {
        self.cold_materialization_tracker = tracker;
    }

    pub(crate) fn share_runtime_usage(
        &mut self,
        runtime_usage: Arc<crate::core::runtime_usage::ModelRuntimeUsageCounters>,
    ) {
        self.runtime_usage = runtime_usage;
    }

    fn begin_cold_materialization(
        &self,
        components: crate::core::process_memory::MaterializationComponents,
    ) -> Result<Option<crate::core::process_memory::ColdMaterializationGuard>> {
        let (Some(tracker), Some(governor)) = (
            self.cold_materialization_tracker.get(),
            self.process_memory_governor.as_ref(),
        ) else {
            return Ok(None);
        };
        tracker.begin(components, governor).map(Some).map_err(|_| {
            let snapshot = governor.snapshot();
            anyhow::Error::new(SchedulerError::ColdMaterializationUnsafe {
                requested_bytes: components.requested_bytes(tracker.estimate()),
                current_bytes: snapshot.current_usage_bytes,
                target_bytes: snapshot.hard_watermark_bytes,
            })
        })
    }

    fn active_materialization_components(
        &self,
        speculative: bool,
    ) -> crate::core::process_memory::MaterializationComponents {
        crate::core::process_memory::MaterializationComponents::for_request(
            self.slots
                .iter()
                .flatten()
                .any(|state| state.pixel_values.is_some()),
            speculative,
        )
    }

    pub fn memory_governor_snapshot(
        &self,
    ) -> Option<crate::core::process_memory::MemoryGovernorSnapshot> {
        self.process_memory_governor
            .as_ref()
            .map(|governor| governor.snapshot())
    }

    pub fn apply_process_memory_pressure(&mut self) -> Result<MemoryPressureReclaim> {
        let Some(governor) = self.process_memory_governor.clone() else {
            return Ok(MemoryPressureReclaim {
                level: crate::core::process_memory::PressureLevel::Normal,
                immutable_blocks_evicted: 0,
                prompt_lookup_entries_evicted: 0,
                demoted_pages: 0,
                should_park_request: false,
            });
        };
        let snapshot = governor.sample_process();
        if snapshot.pressure_level == crate::core::process_memory::PressureLevel::Normal {
            if let Some(cache) = self.cache.as_mut() {
                let restored = cache
                    .iter_mut()
                    .map(|layer| usize::from(layer.restore_configured_paged_hot_window()))
                    .sum::<usize>();
                if restored > 0 {
                    tracing::info!(
                        restored_layers = restored,
                        "memory governor restored active KV hot-window policy"
                    );
                }
            }
        } else {
            mlx::transforms::clear_cache();
        }

        let mut immutable_blocks_evicted = 0_usize;
        let mut prompt_lookup_entries_evicted = 0_usize;
        if snapshot.pressure_level != crate::core::process_memory::PressureLevel::Normal {
            let retain_ratio = match snapshot.pressure_level {
                crate::core::process_memory::PressureLevel::Normal => unreachable!(),
                crate::core::process_memory::PressureLevel::Soft => (3_usize, 4_usize),
                crate::core::process_memory::PressureLevel::Hard => (1, 4),
                crate::core::process_memory::PressureLevel::Emergency => (0, 1),
            };
            if let (Some(pool), Some(cache)) =
                (self.immutable_prefix_blocks.as_mut(), self.cache.as_mut())
            {
                let target = pool
                    .entries
                    .len()
                    .saturating_mul(retain_ratio.0)
                    .div_ceil(retain_ratio.1);
                immutable_blocks_evicted = reclaim_idle_immutable_blocks_to(pool, cache, target)?;
            }
            if let Some(pool) = self.shared_prompt_lookup_pool.as_mut() {
                prompt_lookup_entries_evicted =
                    pool.reclaim_fraction(retain_ratio.0, retain_ratio.1);
                if let Some(state) = self.prompt_lookup_state.as_mut() {
                    state.stats.shared_evictions = state
                        .stats
                        .shared_evictions
                        .saturating_add(prompt_lookup_entries_evicted as u64);
                    state.stats.shared_pressure_evictions = state
                        .stats
                        .shared_pressure_evictions
                        .saturating_add(prompt_lookup_entries_evicted as u64);
                    state.stats.shared_entries_current = pool.len() as u64;
                    state.stats.shared_estimated_bytes_current = pool.estimated_bytes() as u64;
                    state.stats.shared_estimated_bytes_peak = state
                        .stats
                        .shared_estimated_bytes_peak
                        .max(pool.estimated_bytes_peak() as u64);
                }
            }
        }

        let mut demoted_pages = 0usize;
        if snapshot.pressure_level.rank() >= crate::core::process_memory::PressureLevel::Hard.rank()
        {
            if let Some(cache) = self.cache.as_mut() {
                for layer in cache {
                    demoted_pages = demoted_pages.saturating_add(layer.shrink_paged_hot_window(1)?);
                }
            }
            if demoted_pages > 0 {
                tracing::info!(
                    demoted_pages,
                    ?snapshot.pressure_level,
                    "memory governor demoted active KV hot pages"
                );
                self.refresh_active_kv_residency_stats();
            }
        }
        if immutable_blocks_evicted > 0 {
            tracing::info!(
                immutable_blocks_evicted,
                ?snapshot.pressure_level,
                "memory governor evicted idle immutable FullPaged blocks"
            );
        }
        let refreshed = if immutable_blocks_evicted > 0
            || prompt_lookup_entries_evicted > 0
            || demoted_pages > 0
        {
            governor.refresh_process()
        } else {
            snapshot
        };
        if refreshed.pressure_level == crate::core::process_memory::PressureLevel::Emergency
            && self.active_count() == 0
            && self
                .immutable_prefix_blocks
                .as_ref()
                .is_none_or(ImmutablePrefixBlockPool::is_empty)
        {
            self.discard_retained_immutable_prefix_cache();
        }
        Ok(MemoryPressureReclaim {
            level: refreshed.pressure_level,
            immutable_blocks_evicted,
            prompt_lookup_entries_evicted,
            demoted_pages,
            should_park_request: refreshed.pressure_level.rank()
                >= crate::core::process_memory::PressureLevel::Hard.rank()
                && self.active_count() > 0,
        })
    }

    pub fn retry_pending_immutable_prefix_stores(&mut self, limit: usize) -> Result<usize> {
        let (Some(pool), Some(cache)) =
            (self.immutable_prefix_blocks.as_mut(), self.cache.as_ref())
        else {
            return Ok(0);
        };
        retry_pending_immutable_block_stores(pool, cache, self.paged_prefix_cache.as_ref(), limit)
    }

    fn plan_prefill_chunk(
        &self,
        requested_tokens: usize,
        kv_len: usize,
        batch_size: usize,
    ) -> Result<Option<crate::core::process_memory::PrefillChunkPlan>> {
        let Some(governor) = self.process_memory_governor.as_ref() else {
            return Ok(None);
        };
        governor.sample_process();
        match governor.plan_prefill_chunk(requested_tokens, kv_len, batch_size, &self.meta) {
            Ok(plan) => Ok(Some(plan)),
            Err(first_error) => {
                // One idempotent reclaim-and-retry is part of the prefill
                // contract. `clear_cache` only releases MLX's reusable buffer
                // cache; it does not mutate model weights or request KV.
                mlx::transforms::clear_cache();
                governor.refresh_process();
                governor
                    .plan_prefill_chunk(requested_tokens, kv_len, batch_size, &self.meta)
                    .map(Some)
                    .map_err(|retry_error| {
                        tracing::warn!(
                            first_error = %first_error,
                            retry_error = %retry_error,
                            requested_tokens,
                            kv_len,
                            batch_size,
                            "prefill peak guard rejected after one reclaim retry"
                        );
                        let snapshot = governor.snapshot();
                        anyhow::Error::new(SchedulerError::PrefillPeakUnsafe {
                            requested_tokens,
                            selected_tokens: 0,
                            target_bytes: snapshot.effective_ceiling_bytes,
                        })
                    })
            }
        }
    }

    fn commit_governor_admission(&mut self, id: RequestId) {
        if let Some(reservation) = self.governor_admission_reservations.remove(&id) {
            reservation.commit();
        }
    }

    fn commit_governor_admission_after_materialization(&mut self, id: RequestId) {
        let Some(reservation) = self.governor_admission_reservations.remove(&id) else {
            return;
        };
        reservation.commit();
        if let Some(governor) = self.process_memory_governor.as_ref() {
            // Admission reserves the full KV cap before the first model step.
            // Once that step has been evaluated, one-shot KV buffers are part
            // of the authoritative footprint; retaining the reservation would
            // count the same bytes again when planning the next prefill chunk.
            governor.refresh_process();
        }
    }

    fn commit_all_governor_admissions(&mut self) {
        for (_, reservation) in self.governor_admission_reservations.drain() {
            reservation.commit();
        }
    }

    fn rollback_all_governor_admissions(&mut self) {
        self.governor_admission_reservations.clear();
    }

    fn temp_scheduler_with_parent_budget<T>(&self) -> Result<Scheduler<T>>
    where
        T: Model,
    {
        let budget_state = crate::core::memory_budget::BudgetState::with_soft_limit(
            self.budget_state.soft_limit(),
            self.budget_state.logical_cap(),
            self.budget_state.resident_cap(),
            self.budget_state.policy(),
        );
        let mut scheduler = Scheduler::<T>::new_with_state(
            1,
            self.effective_cap_max,
            budget_state,
            self.memory_budget_exceeded_count.clone(),
            self.meta,
        )
        .map_err(anyhow::Error::from)?;
        if let Some(governor) = self.process_memory_governor.as_ref() {
            scheduler.enable_process_memory_governor(Arc::clone(governor));
        }
        Ok(scheduler)
    }

    pub fn refresh_active_kv_residency_stats(&self) {
        let Some(stats) = self.active_kv_stats.as_ref() else {
            return;
        };
        let mut summary = ActiveKvResidencySummary::default();
        if let Some(cache) = &self.cache {
            for layer in cache {
                let LayerCache::Full(kv) = layer else {
                    continue;
                };
                let Some(layer_summary) = kv.paged_hot_cold_summary() else {
                    continue;
                };
                summary.resident_pages += layer_summary.resident_pages;
                summary.offloaded_pages += layer_summary.offloaded_pages;
                summary.loading_pages += layer_summary.loading_pages;
                summary.dirty_pages += layer_summary.dirty_pages;
                summary.offloaded_bytes = summary
                    .offloaded_bytes
                    .saturating_add(layer_summary.offloaded_bytes);
                summary.swap_out_count = summary
                    .swap_out_count
                    .saturating_add(layer_summary.swap_out_count);
                summary.swap_in_count = summary
                    .swap_in_count
                    .saturating_add(layer_summary.swap_in_count);
                summary.stream_read_count = summary
                    .stream_read_count
                    .saturating_add(layer_summary.stream_read_count);
            }
        }
        stats.set_residency_summary(summary);
    }

    pub fn discard_active_kv_request(&self, parked: &ActiveKvParkedRequest) -> Result<()> {
        let Some(store) = self.active_kv_store.as_ref() else {
            return Ok(());
        };
        store.remove(&parked.payload)
    }

    fn share_prefix_lru_cache(&mut self, prefix_lru_cache: PrefixLruCacheHandle) {
        self.prefix_lru_cache = Some(prefix_lru_cache);
    }

    pub fn park_active_kv_request(
        &mut self,
        id: RequestId,
        model: &M,
    ) -> Result<Option<ActiveKvParkedRequest>> {
        self.ensure_not_poisoned()?;
        let Some(store) = self.active_kv_store.clone() else {
            return Ok(None);
        };
        let stats = self.active_kv_stats.clone();
        let row_idx = self
            .slots
            .iter()
            .position(|slot| matches!(slot, Some(state) if state.id == id))
            .ok_or_else(|| anyhow!("request id {} not found", id.0))?;
        if self
            .gemma4_drafter_state
            .as_ref()
            .is_some_and(|state| state.rows.contains_key(&row_idx))
        {
            return Ok(None);
        }
        if self
            .prompt_lookup_state
            .as_ref()
            .and_then(|state| state.rows.get(&row_idx))
            .is_some_and(|row| !row.pending_tokens.is_empty())
        {
            return Ok(None);
        }
        let state = self.slots[row_idx]
            .as_ref()
            .expect("row_idx found an occupied slot");
        if state.finished || state.generated_tokens.is_empty() {
            return Ok(None);
        }
        let Some(cache) = self.cache.as_ref() else {
            return Ok(None);
        };
        let Some(cache_row) = self.cache_rows.iter().position(|&row| row == row_idx) else {
            return Ok(None);
        };
        let (cache_cap, cache_dtype) = cache_cap_and_dtype(cache)?;
        let Some((mut entry, cached_len)) = prefix_entry_for_row(cache, cache_row)? else {
            return Ok(None);
        };
        let parked_mtp_row = self
            .mtp_state
            .as_ref()
            .and_then(|mtp_state| {
                mtp_state
                    .rows
                    .get(&row_idx)
                    .map(|row| (mtp_state.cfg, mtp_state.stats.clone(), row))
            })
            .map(|(cfg, stats, row)| -> Result<ActiveKvParkedMtpRowState> {
                let (mtp_layers, mtp_cached_len) = row.mtp_cache.prefix_layers_for_row_on(0, ())?;
                let mtp_cache_cap = row.mtp_cache.layer(0).cap();
                entry.mtp_layers = mtp_layers;
                entry.mtp_last_hidden = Some(row.last_hidden.clone());
                Ok(ActiveKvParkedMtpRowState {
                    cfg,
                    stats,
                    pending_tokens: row.pending_tokens.clone(),
                    deferred_tail_commit: row.deferred_tail_commit.clone(),
                    adaptive_draft_tokens: row.adaptive_draft_tokens,
                    draft_policy: row.draft_policy.clone(),
                    cached_len: mtp_cached_len,
                    cache_cap: mtp_cache_cap,
                })
            })
            .transpose()?;
        if cached_len <= 0 || !active_kv_entry_supported(&entry) {
            return Ok(None);
        }
        let cached_token_ids = cached_token_prefix_for_state_and_pending(
            state,
            parked_mtp_row.as_ref().map(|row| &row.pending_tokens),
            cached_len,
        )?;
        let prng_key = self.prng_key_for_row(row_idx)?;

        let (payload, elapsed_us) =
            timed(|| store.save(id.0, &cached_token_ids, cached_len, &entry))?;
        let active_rows: Vec<usize> = self
            .slots
            .iter()
            .enumerate()
            .filter_map(|(row, slot)| {
                (row != row_idx
                    && matches!(
                        slot,
                        Some(state) if !state.finished && !state.generated_tokens.is_empty()
                    ))
                .then_some(row)
            })
            .collect();
        if let Err(err) = self.rebuild_cache_layout(model, &active_rows) {
            let _ = store.remove(&payload);
            if let Some(stats) = &stats {
                stats.record_error();
            }
            return Err(err);
        }
        if let Some(table) = self.request_block_tables.remove(&id) {
            if let Some(cache) = self.cache.as_mut() {
                release_full_paged_cache_owner(cache, table.owner)?;
            }
        }

        let prompt_lookup_row = self
            .prompt_lookup_state
            .as_mut()
            .and_then(|state| state.rows.remove(&row_idx));
        if let Some(state) = self.prompt_lookup_state.as_mut() {
            Self::refresh_prompt_lookup_index_stats(state);
        }
        if parked_mtp_row.is_some() {
            self.mtp_state
                .as_mut()
                .expect("parked MTP row was read from MTP state")
                .rows
                .remove(&row_idx)
                .expect("parked MTP row still exists after main cache rebuild");
        }
        let state = self.slots[row_idx]
            .take()
            .expect("row_idx still occupied after cache layout rebuild");
        self.budget_state.release(state.kv_bytes_admitted);
        if let Some(stats) = &stats {
            stats.record_swap_out(payload.stats, elapsed_us);
        }
        Ok(Some(ActiveKvParkedRequest {
            id,
            payload,
            state,
            prng_key,
            cache_cap,
            cache_dtype,
            prompt_lookup_row,
            mtp_row: parked_mtp_row,
        }))
    }

    pub fn restore_active_kv_request(
        &mut self,
        parked: &ActiveKvParkedRequest,
        model: &M,
    ) -> Result<RequestId> {
        self.ensure_not_poisoned()?;
        if let Some(prompt_lookup_row) = parked.prompt_lookup_row.as_ref() {
            let cfg = prompt_lookup_row.cfg;
            anyhow::ensure!(
                self.prompt_lookup_state
                    .as_ref()
                    .is_none_or(|state| state.cfg == cfg),
                "active KV restore prompt lookup config mismatch"
            );
        }
        anyhow::ensure!(
            self.slots
                .iter()
                .all(|slot| !matches!(slot, Some(state) if state.id == parked.id)),
            "request id {} is already active",
            parked.id.0
        );
        let Some(store) = self.active_kv_store.clone() else {
            anyhow::bail!("active KV offload is not enabled");
        };
        let stats = self.active_kv_stats.clone();
        let row_idx = self
            .slots
            .iter()
            .position(|slot| slot.is_none())
            .ok_or_else(|| anyhow!("active KV restore: scheduler full"))?;
        if let Err((active, requested, soft_limit)) =
            self.budget_state.try_admit(parked.state.kv_bytes_admitted)
        {
            if let Some(stats) = &stats {
                stats.record_error();
            }
            return Err(anyhow::Error::new(SchedulerError::MemoryBudgetExceeded {
                active_bytes: active,
                requested_bytes: requested,
                soft_limit_bytes: soft_limit,
            }));
        }
        let prepared = (|| -> Result<(PagedPrefixEntry, u64, Option<SchedulerMtpRowState>)> {
            let (entry, elapsed_us) = timed(|| store.load(&parked.payload))?;
            let restored_mtp_row = match parked.mtp_row.as_ref() {
                Some(parked_mtp) => {
                    if let Some(mtp_state) = self.mtp_state.as_ref() {
                        anyhow::ensure!(
                            mtp_state.cfg == parked_mtp.cfg,
                            "active KV restore: MTP config changed while request was parked"
                        );
                        anyhow::ensure!(
                            !mtp_state.rows.contains_key(&row_idx),
                            "active KV restore: destination row {row_idx} already has MTP state"
                        );
                    }
                    let last_hidden = entry.mtp_last_hidden.clone().ok_or_else(|| {
                        anyhow!("active KV restore: MTP payload is missing last_hidden")
                    })?;
                    let (mtp_cache, restored_cached_len) =
                        MtpCache::from_prefix_layers_for_single_row(
                            &entry.mtp_layers,
                            parked_mtp.cache_cap,
                            (),
                        )?;
                    anyhow::ensure!(
                        restored_cached_len == parked_mtp.cached_len,
                        "active KV restore: MTP cached length {restored_cached_len} != parked {}",
                        parked_mtp.cached_len
                    );
                    Some(SchedulerMtpRowState {
                        mtp_cache,
                        pending_tokens: parked_mtp.pending_tokens.clone(),
                        last_hidden,
                        deferred_tail_commit: parked_mtp.deferred_tail_commit.clone(),
                        adaptive_draft_tokens: parked_mtp.adaptive_draft_tokens,
                        draft_policy: parked_mtp.draft_policy.clone(),
                    })
                }
                None => {
                    anyhow::ensure!(
                        entry.mtp_layers.is_empty() && entry.mtp_last_hidden.is_none(),
                        "active KV restore: unexpected MTP payload without parked MTP state"
                    );
                    None
                }
            };
            Ok((entry, elapsed_us, restored_mtp_row))
        })();
        let (entry, elapsed_us, restored_mtp_row) = match prepared {
            Ok(prepared) => prepared,
            Err(err) => {
                self.budget_state.release(parked.state.kv_bytes_admitted);
                if let Some(stats) = &stats {
                    stats.record_error();
                }
                return Err(err);
            }
        };
        let mut state = parked.state.clone();
        state.row_idx = row_idx;
        self.slots[row_idx] = Some(state);
        self.request_block_tables
            .insert(parked.id, RequestBlockTable::new(parked.id));
        let install_result = self
            .install_active_kv_payload(
                row_idx,
                &entry,
                parked.payload.cached_len,
                parked.cache_cap,
                parked.cache_dtype,
                model,
            )
            .and_then(|_| self.write_row_prng_host(row_idx, parked.prng_key));
        if let Err(err) = install_result {
            if let Some(table) = self.request_block_tables.remove(&parked.id) {
                if let Some(cache) = self.cache.as_mut() {
                    let _ = release_full_paged_cache_owner(cache, table.owner);
                }
            }
            if let Some(state) = self.slots[row_idx].take() {
                self.budget_state.release(state.kv_bytes_admitted);
            }
            if let Some(stats) = &stats {
                stats.record_error();
            }
            return Err(err);
        }
        if let Some(prompt_lookup_row) = parked.prompt_lookup_row.clone() {
            let cfg = prompt_lookup_row.cfg;
            let state =
                self.prompt_lookup_state
                    .get_or_insert_with(|| SchedulerPromptLookupState {
                        cfg,
                        rows: HashMap::new(),
                        stats: PromptLookupStats::default(),
                    });
            state.rows.insert(row_idx, prompt_lookup_row);
            Self::refresh_prompt_lookup_index_stats(state);
        }
        if let Some(mtp_row) = restored_mtp_row {
            let parked_mtp = parked
                .mtp_row
                .as_ref()
                .expect("restored MTP row has parked metadata");
            self.mtp_state
                .get_or_insert_with(|| SchedulerMtpState {
                    cfg: parked_mtp.cfg,
                    rows: HashMap::new(),
                    stats: parked_mtp.stats.clone(),
                })
                .rows
                .insert(row_idx, mtp_row);
        }
        if matches!(self.phase, Phase::Idle | Phase::Finished) {
            self.phase = Phase::Decoding;
        }
        if let Err(err) = store.remove(&parked.payload) {
            tracing::warn!("active KV restored but payload cleanup failed: {err:#}");
        }
        if let Some(stats) = &stats {
            stats.record_swap_in(parked.payload.stats, elapsed_us);
        }
        Ok(parked.id)
    }

    /// Seed the PRNG state for `row_idx` from `seed`.
    ///
    /// Uses the to_vec + host-replace + try_from pattern to avoid
    /// `slice_update` (T0 measured at 274 ms/call in hot path).
    /// Called only on admission (not in hot path) so ~80 µs to_vec cost is OK.
    fn init_row_prng(&mut self, row_idx: usize, seed: u64) -> Result<()> {
        let b_max = self.prng_state.shape().as_slice()[0] as usize;
        anyhow::ensure!(
            row_idx < b_max,
            "init_row_prng: row_idx={row_idx} >= b_max={b_max}"
        );
        let key = mlx::random::key(seed)?;
        let key_host: Vec<u32> = key.to_vec()?;
        let mut new_host: Vec<u32> = self.prng_state.to_vec()?;
        new_host[row_idx * 2] = key_host[0];
        new_host[row_idx * 2 + 1] = key_host[1];
        self.prng_state = (new_host.as_slice(), &[b_max as i32, 2_i32][..]).try_into()?;
        Ok(())
    }

    /// Write an updated row key back into `prng_state` after sampling.
    ///
    /// Same to_vec + host-replace + try_from pattern as `init_row_prng`.
    fn write_row_prng(&mut self, row_idx: usize, row_key: &Array) -> Result<()> {
        let b_max = self.prng_state.shape().as_slice()[0] as usize;
        anyhow::ensure!(
            row_idx < b_max,
            "write_row_prng: row_idx={row_idx} >= b_max={b_max}"
        );
        let key_host: Vec<u32> = row_key.to_vec()?;
        let mut host: Vec<u32> = self.prng_state.to_vec()?;
        host[row_idx * 2] = key_host[0];
        host[row_idx * 2 + 1] = key_host[1];
        self.prng_state = (host.as_slice(), &[b_max as i32, 2_i32][..]).try_into()?;
        Ok(())
    }

    fn prng_key_for_row(&self, row_idx: usize) -> Result<[u32; 2]> {
        let b_max = self.prng_state.shape().as_slice()[0] as usize;
        anyhow::ensure!(
            row_idx < b_max,
            "prng_key_for_row: row_idx={row_idx} >= b_max={b_max}"
        );
        let host: Vec<u32> = self.prng_state.to_vec()?;
        Ok([host[row_idx * 2], host[row_idx * 2 + 1]])
    }

    fn write_row_prng_host(&mut self, row_idx: usize, row_key: [u32; 2]) -> Result<()> {
        let b_max = self.prng_state.shape().as_slice()[0] as usize;
        anyhow::ensure!(
            row_idx < b_max,
            "write_row_prng_host: row_idx={row_idx} >= b_max={b_max}"
        );
        let mut host: Vec<u32> = self.prng_state.to_vec()?;
        host[row_idx * 2] = row_key[0];
        host[row_idx * 2 + 1] = row_key[1];
        self.prng_state = (host.as_slice(), &[b_max as i32, 2_i32][..]).try_into()?;
        Ok(())
    }

    /// Maximum concurrent in-flight requests this scheduler can hold.
    pub fn b_max(&self) -> usize {
        self.b_max
    }

    fn reusable_dummy_position_ids(&mut self) -> Result<Array> {
        if let Some(position_ids) = self.dummy_position_ids.as_ref() {
            return Ok(position_ids.clone());
        }
        let position_ids = build_position_ids(0, 1)?;
        self.dummy_position_ids = Some(position_ids.clone());
        Ok(position_ids)
    }

    fn kv_cache_turboquant_bits_for_rows(
        &self,
        rows: &[usize],
    ) -> Result<Option<TurboQuantKVBits>> {
        let mut bits = None;
        for &row in rows {
            let Some(state) = self.slots.get(row).and_then(Option::as_ref) else {
                continue;
            };
            if let Some(row_bits) = state.kv_cache_turboquant_bits {
                if let Some(existing) = bits {
                    anyhow::ensure!(
                        existing == row_bits,
                        "scheduler batch mixes TurboQuant KV configs: {existing} and {row_bits}"
                    );
                } else {
                    bits = Some(row_bits);
                }
            }
        }
        Ok(bits)
    }

    fn block_owners_for_rows(&self, rows: &[usize]) -> Result<Vec<PagedKvBlockOwner>> {
        rows.iter()
            .map(|&row| {
                let state = self
                    .slots
                    .get(row)
                    .and_then(Option::as_ref)
                    .ok_or_else(|| anyhow!("block owner row {row} has no request"))?;
                self.request_block_tables
                    .get(&state.id)
                    .map(|table| table.owner)
                    .ok_or_else(|| anyhow!("request {} has no block table", state.id.0))
            })
            .collect()
    }

    fn bind_cache_to_request_rows(&self, cache: &mut [LayerCache], rows: &[usize]) -> Result<()> {
        let owners = self.block_owners_for_rows(rows)?;
        bind_full_paged_cache_owners(cache, &owners)
    }

    fn record_request_owned_kv_layout_rebuild(&mut self, copies_before: u64, copies_after: u64) {
        self.request_owned_kv_layout_rebuilds =
            self.request_owned_kv_layout_rebuilds.saturating_add(1);
        self.request_owned_kv_layout_rebuild_page_copies = self
            .request_owned_kv_layout_rebuild_page_copies
            .saturating_add(copies_after.saturating_sub(copies_before));
    }

    pub fn request_owned_kv_stats(&self) -> RequestOwnedKvStats {
        let mut physical = PagedKvPhysicalStats::default();
        if let Some(cache) = self.cache.as_ref() {
            for layer in cache {
                if let LayerCache::Full(kv) = layer {
                    if let Some(layer_stats) = kv.paged_physical_stats() {
                        add_paged_physical_stats(&mut physical, layer_stats);
                    }
                }
            }
        }
        RequestOwnedKvStats {
            request_tables: self.request_block_tables.len() as u64,
            physical,
            request_forks: self.request_owned_kv_forks,
            layout_rebuilds: self.request_owned_kv_layout_rebuilds,
            layout_rebuild_page_copies: self.request_owned_kv_layout_rebuild_page_copies,
            immutable_prefix: self.immutable_prefix_blocks.as_ref().map_or_else(
                ImmutablePrefixBlockStats::default,
                ImmutablePrefixBlockPool::stats,
            ),
        }
    }

    /// Fork a decoding request into an admitted, empty destination request.
    /// The destination keeps its sampler, PRNG, limits, and stop policy while
    /// inheriting the source's committed decode cursor. FullPaged pages are
    /// shared, while Linear and MLA state is copied into the destination row.
    /// VLM and MTP/drafter side state have separate contracts and are rejected.
    pub fn fork_request_blocks(
        &mut self,
        source_id: RequestId,
        destination_id: RequestId,
        model: &M,
    ) -> Result<bool> {
        self.ensure_not_poisoned()?;
        anyhow::ensure!(
            source_id != destination_id,
            "fork_request_blocks: source and destination must differ"
        );
        let source_state = self
            .slots
            .iter()
            .flatten()
            .find(|state| state.id == source_id)
            .ok_or_else(|| anyhow!("fork_request_blocks: source {} not found", source_id.0))?
            .clone();
        let destination_state = self
            .slots
            .iter()
            .flatten()
            .find(|state| state.id == destination_id)
            .ok_or_else(|| {
                anyhow!(
                    "fork_request_blocks: destination {} not found",
                    destination_id.0
                )
            })?
            .clone();
        anyhow::ensure!(
            !source_state.finished && !destination_state.finished,
            "fork_request_blocks: cannot fork a finished request"
        );
        anyhow::ensure!(
            !source_state.generated_tokens.is_empty(),
            "fork_request_blocks: source has not entered decoding"
        );
        anyhow::ensure!(
            destination_state.generated_tokens.is_empty(),
            "fork_request_blocks: destination decode cursor is not empty"
        );
        anyhow::ensure!(
            source_state.prompt_ids == destination_state.prompt_ids,
            "fork_request_blocks: source and destination prompts differ"
        );
        anyhow::ensure!(
            source_state.pixel_values.is_none()
                && destination_state.pixel_values.is_none()
                && source_state.image_grid_thw.is_none()
                && destination_state.image_grid_thw.is_none(),
            "fork_request_blocks: VLM request fork is not supported"
        );
        anyhow::ensure!(
            source_state.generated_tokens.len() < destination_state.max_new_tokens,
            "fork_request_blocks: destination generation limit is already exhausted"
        );
        anyhow::ensure!(
            source_state
                .generated_tokens
                .iter()
                .all(|token| !destination_state.stop_token_ids.contains(token)),
            "fork_request_blocks: destination stop policy would have finished the copied cursor"
        );
        for row in [source_state.row_idx, destination_state.row_idx] {
            anyhow::ensure!(
                !self
                    .mtp_state
                    .as_ref()
                    .is_some_and(|state| state.rows.contains_key(&row))
                    && !self
                        .gemma4_drafter_state
                        .as_ref()
                        .is_some_and(|state| state.rows.contains_key(&row)),
                "fork_request_blocks: speculative side state is not forkable"
            );
        }
        let prompt_lookup_fork = if let Some(prompt_lookup) = self.prompt_lookup_state.as_ref() {
            if let Some(destination_row) = prompt_lookup.rows.get(&destination_state.row_idx) {
                anyhow::ensure!(
                    destination_row.pending_tokens.is_empty(),
                    "fork_request_blocks: destination prompt lookup queue is not empty"
                );
            }
            prompt_lookup
                .rows
                .get(&source_state.row_idx)
                .map(|source_row| {
                    anyhow::ensure!(
                        source_row.pending_tokens.is_empty(),
                        "fork_request_blocks: source prompt lookup queue is not empty"
                    );
                    Ok(source_row.clone())
                })
                .transpose()?
        } else {
            None
        };
        let source_owner = self
            .request_block_tables
            .get(&source_id)
            .map(|table| table.owner)
            .ok_or_else(|| anyhow!("fork_request_blocks: source block table absent"))?;
        let destination_owner = self
            .request_block_tables
            .get(&destination_id)
            .map(|table| table.owner)
            .ok_or_else(|| anyhow!("fork_request_blocks: destination block table absent"))?;
        let cache = self
            .cache
            .as_ref()
            .ok_or_else(|| anyhow!("fork_request_blocks: scheduler cache is absent"))?;
        let cached_len = full_paged_owner_offset(cache, source_owner)?
            .ok_or_else(|| anyhow!("fork_request_blocks: source has no FullPaged owner"))?;
        anyhow::ensure!(
            cached_len > 0,
            "fork_request_blocks: source FullPaged owner is empty"
        );
        let source_tokens = cached_token_prefix_for_state(&source_state, cached_len)?;
        let mut forked_destination_state = destination_state.clone();
        forked_destination_state.generated_tokens = source_state.generated_tokens.clone();
        forked_destination_state.real_len = source_state.real_len;
        let destination_tokens =
            cached_token_prefix_for_state(&forked_destination_state, cached_len)?;
        anyhow::ensure!(
            source_tokens == destination_tokens,
            "fork_request_blocks: cached token prefixes differ"
        );

        let (mut new_cache, target_rows, copies_before) = self.prepare_forked_cache_layout(
            model,
            source_state.row_idx,
            destination_state.row_idx,
        )?;

        let forked = fork_full_paged_cache_owner(
            self.cache
                .as_mut()
                .expect("cache remained present after preflight"),
            source_owner,
            destination_owner,
        )?;
        if !forked {
            return Ok(false);
        }

        let old_rows = self.cache_rows.clone();
        let owners = self.block_owners_for_rows(&target_rows)?;
        let mut old_cache = self.cache.take().expect("cache checked before fork");
        self.cache_rows.clear();
        let transfer_result = reuse_full_paged_storage(
            &mut new_cache,
            &mut old_cache,
            &owners,
            "fork_request_blocks",
        );
        match transfer_result {
            Ok(true) => {}
            Ok(false) => {
                self.cache = Some(old_cache);
                self.cache_rows = old_rows;
                if let Some(cache) = self.cache.as_mut() {
                    release_full_paged_cache_owner(cache, destination_owner)?;
                }
                anyhow::bail!("fork_request_blocks: FullPaged storage was not reused");
            }
            Err(err) => {
                self.cache = Some(old_cache);
                self.cache_rows = old_rows;
                if let Some(cache) = self.cache.as_mut() {
                    release_full_paged_cache_owner(cache, destination_owner)?;
                }
                return Err(err);
            }
        }
        let copies_after = paged_adopt_page_copies(&new_cache);
        self.record_request_owned_kv_layout_rebuild(copies_before, copies_after);
        self.cache = Some(new_cache);
        self.cache_rows = target_rows;
        let destination_slot = self
            .slots
            .get_mut(destination_state.row_idx)
            .and_then(Option::as_mut)
            .expect("destination slot remained active during fork");
        destination_slot.generated_tokens = forked_destination_state.generated_tokens;
        destination_slot.real_len = forked_destination_state.real_len;
        if let Some(prompt_lookup_row) = prompt_lookup_fork {
            let prompt_lookup = self
                .prompt_lookup_state
                .as_mut()
                .expect("prompt lookup state supplied fork row");
            prompt_lookup
                .rows
                .insert(destination_state.row_idx, prompt_lookup_row);
            Self::refresh_prompt_lookup_index_stats(prompt_lookup);
        }
        self.request_owned_kv_forks = self.request_owned_kv_forks.saturating_add(1);
        self.validate_request_owned_kv_invariants()?;
        Ok(true)
    }

    pub fn validate_request_owned_kv_invariants(&self) -> Result<()> {
        let active_ids = self
            .slots
            .iter()
            .flatten()
            .map(|state| state.id)
            .collect::<HashSet<_>>();
        anyhow::ensure!(
            self.request_block_tables.len() == active_ids.len(),
            "request block registry has {} tables for {} active requests",
            self.request_block_tables.len(),
            active_ids.len()
        );
        for state in self.slots.iter().flatten() {
            let table = self.request_block_tables.get(&state.id).ok_or_else(|| {
                anyhow!("active request {} has no request block table", state.id.0)
            })?;
            anyhow::ensure!(
                table.owner == PagedKvBlockOwner::Request(state.id.0),
                "request {} block owner {:?} does not match request id",
                state.id.0,
                table.owner
            );
        }
        for id in self.request_block_tables.keys() {
            anyhow::ensure!(
                active_ids.contains(id),
                "request block table {} has no active request",
                id.0
            );
        }
        if let Some(cache) = self.cache.as_ref() {
            validate_full_paged_owner_invariants(cache)?;
        }
        if let Some(pool) = self
            .immutable_prefix_blocks
            .as_ref()
            .filter(|pool| !pool.is_empty())
        {
            let cache = self
                .cache
                .as_deref()
                .ok_or_else(|| anyhow!("non-empty immutable prefix pool has no physical cache"))?;
            validate_immutable_prefix_pool_invariants(pool, cache)?;
        }
        Ok(())
    }

    fn make_model_cache(
        &self,
        model: &M,
        batch: i32,
        cap: i32,
        dtype: Dtype,
        turboquant_bits: Option<TurboQuantKVBits>,
    ) -> Result<Vec<LayerCache>> {
        let mut cache = model.make_cache(batch, cap, dtype)?;
        if let Some(bits) = turboquant_bits {
            enable_turboquant_kv_caches(&mut cache, bits)?;
        } else if let Some(config) = &self.paged_prefix_cache {
            enable_paged_kv_caches(&mut cache, config.block_size, config.max_pages)?;
            if self.active_kv_config.enabled {
                let active_kv_soft_limit = self.budget_state.soft_limit();
                let active_kv_bytes_per_token =
                    crate::core::memory_budget::kv_bytes_per_token(&self.meta);
                let hot_window_pages = self
                    .active_kv_config
                    .hot_window_pages_override
                    .unwrap_or_else(|| {
                        active_kv_hot_window_pages_for_budget(
                            config.block_size,
                            cap,
                            batch,
                            active_kv_soft_limit,
                            active_kv_bytes_per_token,
                        )
                    });
                let chunk_pages = self
                    .active_kv_config
                    .chunk_pages_override
                    .unwrap_or_else(|| {
                        active_kv_chunk_pages_for_budget(
                            config.block_size,
                            cap,
                            batch,
                            active_kv_soft_limit,
                            active_kv_bytes_per_token,
                            hot_window_pages,
                        )
                    });
                let hot_cold = PagedKvHotColdConfig::new(
                    self.active_kv_config.root.clone(),
                    hot_window_pages,
                    chunk_pages,
                )?;
                enable_paged_hot_cold_tiering_caches(&mut cache, hot_cold)?;
            }
        }
        Ok(cache)
    }

    fn make_model_cache_for_rows(
        &self,
        model: &M,
        rows: &[usize],
        cap: i32,
        dtype: Dtype,
        turboquant_bits: Option<TurboQuantKVBits>,
    ) -> Result<Vec<LayerCache>> {
        anyhow::ensure!(
            !rows.is_empty(),
            "make_model_cache_for_rows: rows cannot be empty"
        );
        let mut cache =
            self.make_model_cache(model, rows.len() as i32, cap, dtype, turboquant_bits)?;
        self.bind_cache_to_request_rows(&mut cache, rows)?;
        Ok(cache)
    }

    fn install_initial_cache_for_rows(
        &mut self,
        model: &M,
        rows: &[usize],
        cap: i32,
        dtype: Dtype,
        turboquant_bits: Option<TurboQuantKVBits>,
    ) -> Result<()> {
        anyhow::ensure!(
            self.cache_rows.is_empty(),
            "initial cache install found live cache rows {:?}",
            self.cache_rows
        );
        let mut new_cache =
            self.make_model_cache_for_rows(model, rows, cap, dtype, turboquant_bits)?;
        let retain_immutable_pool = turboquant_bits.is_none()
            && self
                .immutable_prefix_blocks
                .as_ref()
                .is_some_and(|pool| !pool.is_empty());
        if self.cache.is_some() && !retain_immutable_pool {
            return Err(anyhow!(
                "prefill_admitted: cache already allocated before prefill"
            ));
        }
        if let Some(mut retained_cache) = self.cache.take() {
            if retain_immutable_pool {
                let owners = self.block_owners_for_rows(rows)?;
                anyhow::ensure!(
                    reuse_full_paged_storage(
                        &mut new_cache,
                        &mut retained_cache,
                        &owners,
                        "install_initial_cache_for_rows",
                    )?,
                    "retained immutable prefix pool has no reusable FullPaged storage"
                );
            } else if let Some(pool) = self.immutable_prefix_blocks.as_mut() {
                pool.lookup.clear();
                pool.entries.clear();
                pool.pending_store_blocks.clear();
            }
        }
        self.cache = Some(new_cache);
        self.cache_rows = rows.to_vec();
        Ok(())
    }

    fn discard_retained_immutable_prefix_cache(&mut self) {
        if !self.cache_rows.is_empty() {
            return;
        }
        if let Some(pool) = self.immutable_prefix_blocks.as_mut() {
            pool.lookup.clear();
            pool.entries.clear();
            pool.pending_store_blocks.clear();
        }
        self.cache = None;
    }

    fn include_fullpaged_owner_in_layout(&mut self, model: &M, row_idx: usize) -> Result<()> {
        anyhow::ensure!(
            !self.cache_rows.contains(&row_idx),
            "FullPaged owner row {row_idx} is already in the execution layout"
        );
        let current_cache = self
            .cache
            .as_ref()
            .ok_or_else(|| anyhow!("FullPaged execution cache is absent"))?;
        anyhow::ensure!(
            cache_is_fullpaged_only(current_cache),
            "immutable in-place layout requires FullPaged-only layers"
        );
        let (cap, dtype) = cache_cap_and_dtype(current_cache)?;
        let mut target_rows = self.cache_rows.clone();
        target_rows.push(row_idx);
        target_rows.sort_unstable();
        let mut new_cache =
            self.make_model_cache_for_rows(model, &target_rows, cap, dtype, None)?;
        let owners = self.block_owners_for_rows(&target_rows)?;
        let mut old_cache = self.cache.take().expect("cache checked above");
        anyhow::ensure!(
            reuse_full_paged_storage(
                &mut new_cache,
                &mut old_cache,
                &owners,
                "include_fullpaged_owner_in_layout",
            )?,
            "immutable in-place layout did not reuse FullPaged storage"
        );
        self.cache = Some(new_cache);
        self.cache_rows = target_rows;
        Ok(())
    }

    fn mtp_position_ids(&mut self, model: &M, start_pos: i32, len: i32) -> Result<Array> {
        if model.requires_position_ids() {
            build_position_ids(start_pos, len)
        } else {
            self.reusable_dummy_position_ids()
        }
    }

    /// Admit a new request. Walks `slots` for the first `None`, fills it
    /// with a freshly-constructed `RequestState`, and returns a new
    /// monotonically-increasing [`RequestId`]. Returns `Err` if the
    /// scheduler is full (B1-p2.3d will replace this with queueing).
    ///
    /// The request's sampler is **cloned** so each row has its own
    /// independent sampler state.
    pub fn admit(&mut self, req: GenerateRequest) -> Result<RequestId> {
        self.ensure_not_poisoned()?;
        // B1-p2.3f: cap check before admission. Reject oversize requests
        // upfront rather than allocating a slot then failing at prefill.
        let cap_needed = req.prompt_ids.len().saturating_add(req.max_new_tokens);
        if cap_needed > self.effective_cap_max {
            return Err(anyhow::Error::new(SchedulerError::RequestTooLarge {
                required_total_tokens: cap_needed,
                input_tokens: req.prompt_ids.len(),
                requested_max_output_tokens: req.max_new_tokens,
                server_max_context_tokens: self.effective_cap_max,
                max_allowed_output_tokens: self
                    .effective_cap_max
                    .saturating_sub(req.prompt_ids.len()),
            }));
        }
        if self.phase == Phase::Finished {
            return Err(anyhow!(
                "scheduler in Finished phase: cannot admit; call evict_all first"
            ));
        }
        // Idle / Admitting / Decoding all allow admit.
        //   Idle -> Admitting (first admit transitions below).
        //   Admitting -> Admitting (subsequent admits during window).
        //   Decoding -> Decoding (mid-batch admit; caller is responsible
        //     for prefilling the new slot via admit_mid in Task 4).
        let row_idx =
            self.slots.iter().position(|s| s.is_none()).ok_or_else(|| {
                anyhow!("scheduler full: no row available (b_max={})", self.b_max)
            })?;

        if self.paged_prefix_cache.is_some() {
            let store_queue = crate::core::cache::process_async_prefix_store_queue();
            if store_queue.is_backpressured() {
                let stats = store_queue.stats();
                return Err(anyhow::Error::new(SchedulerError::StoreBackpressure {
                    pending_jobs: stats.pending_jobs,
                    pending_bytes: stats.pending_bytes,
                }));
            }
        }

        // B1-p2.5: memory budget admission gate.
        let row_cap = req.prompt_ids.len().saturating_add(req.max_new_tokens);
        let charged_cap = self.budget_state.resident_charge_cap(row_cap);
        let requested_bytes =
            crate::core::memory_budget::kv_cache_bytes(1, charged_cap, &self.meta);
        if let Err((active, requested, soft_limit)) = self.budget_state.try_admit(requested_bytes) {
            self.memory_budget_exceeded_count
                .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
            return Err(anyhow::Error::new(SchedulerError::MemoryBudgetExceeded {
                active_bytes: active,
                requested_bytes: requested,
                soft_limit_bytes: soft_limit,
            }));
        }

        let governor_reservation = if let Some(governor) = self.process_memory_governor.as_ref() {
            let snapshot = governor.sample_process();
            if snapshot.pressure_level != crate::core::process_memory::PressureLevel::Normal {
                self.budget_state.release(requested_bytes);
                return Err(anyhow::Error::new(SchedulerError::MemoryPressure {
                    level: snapshot.pressure_level,
                    current_bytes: snapshot.current_usage_bytes,
                    ceiling_bytes: snapshot.effective_ceiling_bytes,
                }));
            }
            match governor.try_reserve(requested_bytes, "scheduler_admission") {
                Ok(reservation) => Some(reservation),
                Err(error) => {
                    self.budget_state.release(requested_bytes);
                    let snapshot = governor.snapshot();
                    tracing::warn!(error = %error, "process memory governor rejected admission");
                    return Err(anyhow::Error::new(SchedulerError::MemoryPressure {
                        level: snapshot.pressure_level,
                        current_bytes: snapshot.current_usage_bytes,
                        ceiling_bytes: snapshot.effective_ceiling_bytes,
                    }));
                }
            }
        } else {
            None
        };

        let id = RequestId(self.next_id);
        self.next_id += 1;

        let prompt_len = req.prompt_ids.len();
        anyhow::ensure!(
            prompt_len <= i32::MAX as usize,
            "prompt too long: {} tokens exceeds i32::MAX",
            prompt_len
        );
        let real_len = prompt_len as i32;
        let constraint_plan = req.constraint.clone();
        let constraint = req
            .constraint
            .as_ref()
            .map(crate::core::constrained::ConstraintPlan::start_session)
            .transpose()?;
        let state = RequestState {
            id,
            row_idx,
            prompt_ids: req.prompt_ids,
            generated_tokens: Vec::new(),
            max_new_tokens: req.max_new_tokens,
            stop_token_ids: req.stop_token_ids,
            sampler: req.sampler,
            constraint_plan,
            constraint,
            real_len,
            finished: false,
            finish_reason: None,
            pixel_values: req.pixel_values,
            image_grid_thw: req.image_grid_thw,
            image_spatial_merge_size: req.image_spatial_merge_size,
            image_token_id: req.image_token_id,
            prefill_chunk_size: i32::try_from(req.prefill_chunk_size).unwrap_or(i32::MAX),
            decode_cadence_mid_chunk_cap: req.decode_cadence_mid_chunk_cap,
            kv_cache_turboquant_bits: req.kv_cache_turboquant_bits,
            kv_bytes_admitted: requested_bytes,
        };
        let seed = state.sampler.seed;
        self.slots[row_idx] = Some(state);
        self.request_block_tables
            .insert(id, RequestBlockTable::new(id));
        if let Some(reservation) = governor_reservation {
            self.governor_admission_reservations.insert(id, reservation);
        }
        // Seed this row's PRNG state from the request's sampler seed.
        if let Err(err) = self.init_row_prng(row_idx, seed) {
            self.request_block_tables.remove(&id);
            self.governor_admission_reservations.remove(&id);
            if let Some(state) = self.slots[row_idx].take() {
                self.budget_state.release(state.kv_bytes_admitted);
            }
            return Err(err);
        }
        if self.phase == Phase::Idle {
            self.phase = Phase::Admitting;
        }
        // Decoding stays Decoding (no transition on mid-batch admit).
        Ok(id)
    }

    /// Evict an in-flight request, freeing its slot for reuse. The slot
    /// index is freed but the [`RequestId`] is **never** reissued (the
    /// counter keeps incrementing).
    pub fn evict(&mut self, id: RequestId) -> Result<()> {
        self.ensure_not_poisoned()?;
        // 3c-3: evict allowed in all phases. Slot is cleared; compact cache
        // rows are reconciled lazily on the next decode step or mid-admit
        // finalize.
        let row_idx = self
            .slots
            .iter()
            .position(|s| matches!(s, Some(r) if r.id == id))
            .ok_or_else(|| anyhow!("request id {} not found", id.0))?;
        let completed_history = self.slots[row_idx]
            .as_ref()
            .and_then(completed_prompt_lookup_history);
        let mtp_certifications = self
            .prompt_lookup_state
            .as_ref()
            .and_then(|state| state.rows.get(&row_idx))
            .filter(|row| row.owner == id)
            .map(|row| row.mtp_certifications.clone())
            .unwrap_or_default();
        if let Some(table) = self.request_block_tables.get(&id).copied() {
            if let Some(cache) = self.cache.as_mut() {
                release_full_paged_cache_owner(cache, table.owner)?;
            }
        }
        if let Some(history) = completed_history.as_deref() {
            self.publish_shared_prompt_lookup_history(history, &mtp_certifications);
        }
        self.request_block_tables.remove(&id);
        // B1-p2.5: release budget before clearing the slot.
        if let Some(state) = self.slots[row_idx].take() {
            self.budget_state.release(state.kv_bytes_admitted);
        }
        self.governor_admission_reservations.remove(&id);
        self.drop_speculative_row_state(row_idx);
        // Phase transitions on evict:
        //   Admitting + active_count==0 -> Idle (pre-3c-3 behavior)
        //   Decoding  + active_count==0 -> Finished (NEW in 3c-3)
        //   Idle / Finished: no transition
        if self.active_count() == 0 {
            self.mtp_state = None;
            self.gemma4_drafter_state = None;
            if self.shared_prompt_lookup_pool.is_some() {
                if let Some(state) = self.prompt_lookup_state.as_mut() {
                    state.rows.clear();
                    Self::refresh_prompt_lookup_index_stats(state);
                }
            } else {
                self.prompt_lookup_state = None;
            }
            if self.phase == Phase::Admitting {
                self.phase = Phase::Idle;
            } else if self.phase == Phase::Decoding {
                self.phase = Phase::Finished;
            }
        }
        Ok(())
    }

    fn drop_speculative_row_state(&mut self, row_idx: usize) {
        if let Some(mtp_state) = self.mtp_state.as_mut() {
            mtp_state.rows.remove(&row_idx);
        }
        if let Some(drafter_state) = self.gemma4_drafter_state.as_mut() {
            drafter_state.rows.remove(&row_idx);
        }
        if let Some(prompt_lookup_state) = self.prompt_lookup_state.as_mut() {
            prompt_lookup_state.rows.remove(&row_idx);
            Self::refresh_prompt_lookup_index_stats(prompt_lookup_state);
        }
    }

    /// Number of occupied slots.
    pub fn active_count(&self) -> usize {
        self.slots.iter().filter(|s| s.is_some()).count()
    }

    /// Borrow every occupied slot's `RequestState`, in slot order.
    pub fn active(&self) -> Vec<&RequestState> {
        self.slots.iter().filter_map(|s| s.as_ref()).collect()
    }

    pub(crate) fn fresh_neural_exact_qualification_regime(
        &self,
        source: NeuralExactSource,
    ) -> Option<NeuralExactRegime> {
        if self.active_count() != 1 {
            return None;
        }
        let state = self.slots.iter().find_map(Option::as_ref)?;
        (!state.finished && state.generated_tokens.is_empty() && !state.sampler.is_pipelinable())
            .then(|| NeuralExactRegime::new(source, state.prompt_ids.len(), state.sampler))
    }

    pub(crate) fn active_batch_finished(&self) -> bool {
        self.active_count() > 0
            && self
                .slots
                .iter()
                .filter_map(Option::as_ref)
                .all(|state| state.finished)
    }

    pub(crate) fn speculative_batch_active_fresh_eligible(&self) -> bool {
        let mut saw_active = false;
        let mut active = 0usize;
        let mut all_greedy = true;
        for state in self.slots.iter().filter_map(|slot| slot.as_ref()) {
            saw_active = true;
            active = active.saturating_add(1);
            if state.finished || !state.generated_tokens.is_empty() {
                return false;
            }
            all_greedy &= state.sampler.is_pipelinable();
        }
        saw_active && (active == 1 || all_greedy)
    }

    fn native_mtp_exact_verify_eligible_for_shape(
        &self,
        model: &M,
        cfg: MtpSpeculativeConfig,
        batch_width: usize,
        context_tokens: usize,
        remaining_tokens: usize,
        kv_bits: Option<TurboQuantKVBits>,
    ) -> bool {
        let max_draft_tokens = cfg.max_draft_tokens.min(remaining_tokens);
        max_draft_tokens > 0
            && model.supports_exact_batched_speculative_verify_for_kv_cache(
                batch_width,
                context_tokens,
                max_draft_tokens.saturating_add(1),
                kv_bits,
            )
    }

    pub(crate) fn native_mtp_fresh_exact_verify_eligible(
        &self,
        model: &M,
        cfg: MtpSpeculativeConfig,
    ) -> Result<bool>
    where
        M: MtpSpeculativeModel,
    {
        let active_rows = self
            .slots
            .iter()
            .enumerate()
            .filter_map(|(row_idx, slot)| {
                matches!(slot, Some(state) if !state.finished).then_some(row_idx)
            })
            .collect::<Vec<_>>();
        if active_rows.is_empty() {
            return Ok(false);
        }
        let context_tokens = active_rows
            .iter()
            .filter_map(|&row_idx| self.slots[row_idx].as_ref())
            .map(|state| state.prompt_ids.len())
            .max()
            .unwrap_or(0);
        let remaining_tokens = active_rows
            .iter()
            .filter_map(|&row_idx| self.slots[row_idx].as_ref())
            .map(|state| state.max_new_tokens)
            .max()
            .unwrap_or(0);
        let kv_bits = self.kv_cache_turboquant_bits_for_rows(&active_rows)?;
        Ok(self.native_mtp_exact_verify_eligible_for_shape(
            model,
            cfg,
            active_rows.len(),
            context_tokens,
            remaining_tokens,
            kv_bits,
        ))
    }

    pub(crate) fn native_mtp_next_window_exact_verify_eligible(&self, model: &M) -> Result<bool>
    where
        M: MtpSpeculativeModel,
    {
        let Some(mtp_state) = self.mtp_state.as_ref() else {
            return Ok(false);
        };
        anyhow::ensure!(
            self.mtp_at_batch_window_boundary(),
            "native MTP exact qualification requires a batch-window boundary"
        );
        let active_rows = self
            .slots
            .iter()
            .enumerate()
            .filter_map(|(row_idx, slot)| {
                (matches!(slot, Some(state) if !state.finished)
                    && mtp_state.rows.contains_key(&row_idx))
                .then_some(row_idx)
            })
            .collect::<Vec<_>>();
        if active_rows.is_empty() {
            return Ok(false);
        }
        let context_tokens = active_rows
            .iter()
            .filter_map(|&row_idx| self.slots[row_idx].as_ref())
            .map(|state| state.real_len.max(0) as usize)
            .max()
            .unwrap_or(0);
        let remaining_tokens = active_rows
            .iter()
            .filter_map(|&row_idx| self.slots[row_idx].as_ref())
            .map(|state| {
                state
                    .max_new_tokens
                    .saturating_sub(state.generated_tokens.len())
            })
            .max()
            .unwrap_or(0);
        let kv_bits = self.kv_cache_turboquant_bits_for_rows(&active_rows)?;
        Ok(self.native_mtp_exact_verify_eligible_for_shape(
            model,
            mtp_state.cfg,
            active_rows.len(),
            context_tokens,
            remaining_tokens,
            kv_bits,
        ))
    }

    pub(crate) fn native_mtp_rolling_admit_exact_verify_eligible(
        &self,
        model: &M,
        cfg: MtpSpeculativeConfig,
        request: &GenerateRequest,
    ) -> Result<bool>
    where
        M: MtpSpeculativeModel,
    {
        let Some(mtp_state) = self.mtp_state.as_ref() else {
            return Ok(false);
        };
        anyhow::ensure!(
            self.mtp_at_batch_window_boundary(),
            "native MTP rolling qualification requires a batch-window boundary"
        );
        let active_rows = self
            .slots
            .iter()
            .enumerate()
            .filter_map(|(row_idx, slot)| {
                (matches!(slot, Some(state) if !state.finished)
                    && mtp_state.rows.contains_key(&row_idx))
                .then_some(row_idx)
            })
            .collect::<Vec<_>>();
        let context_tokens = active_rows
            .iter()
            .filter_map(|&row_idx| self.slots[row_idx].as_ref())
            .map(|state| state.real_len.max(0) as usize)
            .chain(std::iter::once(request.prompt_ids.len()))
            .max()
            .unwrap_or(0);
        let remaining_tokens = active_rows
            .iter()
            .filter_map(|&row_idx| self.slots[row_idx].as_ref())
            .map(|state| {
                state
                    .max_new_tokens
                    .saturating_sub(state.generated_tokens.len())
            })
            .chain(std::iter::once(request.max_new_tokens))
            .max()
            .unwrap_or(0);
        let mut kv_bits = self.kv_cache_turboquant_bits_for_rows(&active_rows)?;
        if let Some(request_bits) = request.kv_cache_turboquant_bits {
            if let Some(existing) = kv_bits {
                anyhow::ensure!(
                    existing == request_bits,
                    "native MTP rolling batch mixes TurboQuant KV configs: {existing} and {request_bits}"
                );
            } else {
                kv_bits = Some(request_bits);
            }
        }
        Ok(self.native_mtp_exact_verify_eligible_for_shape(
            model,
            cfg,
            active_rows.len().saturating_add(1),
            context_tokens,
            remaining_tokens,
            kv_bits,
        ))
    }

    pub(crate) fn retire_mtp_at_batch_window_boundary(&mut self) -> Result<()> {
        if self.mtp_state.is_none() {
            return Ok(());
        }
        anyhow::ensure!(
            self.mtp_at_batch_window_boundary(),
            "native MTP can retire only at a batch-window boundary"
        );
        self.mtp_state = None;
        Ok(())
    }

    /// Look up by id. `None` if the id was never admitted or has been evicted.
    pub fn get(&self, id: RequestId) -> Option<&RequestState> {
        self.slots
            .iter()
            .find_map(|s| s.as_ref().filter(|r| r.id == id))
    }

    /// Mutable lookup by id.
    pub fn get_mut(&mut self, id: RequestId) -> Option<&mut RequestState> {
        self.slots
            .iter_mut()
            .find_map(|s| s.as_mut().filter(|r| r.id == id))
    }

    #[cfg(test)]
    fn emit_pending_token_for_row(
        &mut self,
        row_idx: usize,
        pending_tokens: &mut VecDeque<u32>,
    ) -> Result<StepEvent> {
        let token = pending_tokens
            .pop_front()
            .ok_or_else(|| anyhow!("emit_pending_token_for_row: pending token queue is empty"))?;
        self.emit_token_for_row(row_idx, token)
    }

    fn emit_token_for_row(&mut self, row_idx: usize, token: u32) -> Result<StepEvent> {
        let state = self
            .slots
            .get_mut(row_idx)
            .and_then(Option::as_mut)
            .ok_or_else(|| anyhow!("emit_token_for_row: row {row_idx} slot absent"))?;
        if state.finished {
            return Err(anyhow!(
                "emit_token_for_row: row {row_idx} already finished"
            ));
        }
        state.generated_tokens.push(token);
        if let Some(constraint) = state.constraint.as_mut() {
            constraint.commit_token(token)?;
        }
        state.real_len += 1;
        if state.stop_token_ids.contains(&token) {
            state.finished = true;
            state.finish_reason = Some("stop");
        } else if state.generated_tokens.len() >= state.max_new_tokens {
            state.finished = true;
            state.finish_reason = Some("length");
        }
        Ok(StepEvent {
            id: state.id,
            token,
            finish_reason: state.finish_reason,
        })
    }

    /// `row_idx` of every occupied slot, in slot order. Used by 3b to
    /// build batched inputs.
    pub fn occupied_rows(&self) -> Vec<usize> {
        self.slots
            .iter()
            .enumerate()
            .filter_map(|(idx, s)| s.as_ref().map(|_| idx))
            .collect()
    }

    fn prefill_cache_cap(&self) -> i32 {
        // B1-p2.3f: dynamic cap = max(prompt_len + max_new_tokens) over
        // admitted slots, bounded by effective_cap_max (defense-in-depth;
        // admit gate already rejects oversize).
        //
        // Logical cap is then floored at MIN_KV_CACHE_CAP_FOR_GPU_PERF to
        // avoid the MLX Metal kernel slow-path cliff for tight K/V buffer
        // widths. The floor is a physical-buffer concern; admit-gate
        // semantics still use the user-requested cap.
        let slots_max = self
            .slots
            .iter()
            .filter_map(|s| s.as_ref())
            .map(|r| {
                let max_new_i32 = i32::try_from(r.max_new_tokens).unwrap_or(i32::MAX);
                (r.prompt_ids.len() as i32).saturating_add(max_new_i32)
            })
            .max()
            .unwrap_or(256);
        slots_max
            .min(self.effective_cap_max as i32)
            .max(MIN_KV_CACHE_CAP_FOR_GPU_PERF)
    }

    /// Current scheduler phase. See [`Phase`] for the state machine.
    pub fn phase(&self) -> Phase {
        self.phase
    }

    /// Returns `Err` if the scheduler has been poisoned by a previous `Err`
    /// return from `prefill_admitted` or `step`. Call `evict_all` to recover.
    fn ensure_not_poisoned(&self) -> Result<()> {
        if self.poisoned {
            return Err(anyhow!(
                "scheduler poisoned by a previous Err; call evict_all to recover"
            ));
        }
        Ok(())
    }

    fn compact_prng_state_for_rows(&self, rows: &[usize]) -> Result<Array> {
        let host: Vec<u32> = self.prng_state.to_vec()?;
        let mut compact = Vec::with_capacity(rows.len() * 2);
        for &row in rows {
            anyhow::ensure!(
                row < self.b_max,
                "compact_prng_state_for_rows: row={row} >= b_max={}",
                self.b_max
            );
            let start = row * 2;
            compact.extend_from_slice(&host[start..start + 2]);
        }
        (&compact[..], &[rows.len() as i32, 2_i32][..])
            .try_into()
            .map_err(|e| anyhow!("compact_prng_state_for_rows: Array build failed: {e:?}"))
    }

    fn scatter_prng_state_from_rows(&mut self, rows: &[usize], compact: &Array) -> Result<()> {
        let compact_host: Vec<u32> = compact.to_vec()?;
        anyhow::ensure!(
            compact_host.len() == rows.len() * 2,
            "scatter_prng_state_from_rows: compact len {} != rows*2 {}",
            compact_host.len(),
            rows.len() * 2
        );
        let mut host: Vec<u32> = self.prng_state.to_vec()?;
        for (compact_row, &slot_row) in rows.iter().enumerate() {
            anyhow::ensure!(
                slot_row < self.b_max,
                "scatter_prng_state_from_rows: slot_row={slot_row} >= b_max={}",
                self.b_max
            );
            let dst = slot_row * 2;
            let src = compact_row * 2;
            host[dst] = compact_host[src];
            host[dst + 1] = compact_host[src + 1];
        }
        self.prng_state = (&host[..], &[self.b_max as i32, 2_i32][..])
            .try_into()
            .map_err(|e| anyhow!("scatter_prng_state_from_rows: Array rebuild failed: {e:?}"))?;
        Ok(())
    }

    fn rebuild_cache_layout(&mut self, model: &M, target_rows: &[usize]) -> Result<()> {
        if self.cache_rows == target_rows {
            return Ok(());
        }
        if target_rows.is_empty() {
            if self
                .immutable_prefix_blocks
                .as_ref()
                .is_none_or(ImmutablePrefixBlockPool::is_empty)
            {
                self.cache = None;
            }
            self.cache_rows.clear();
            return Ok(());
        }

        let current_cache = self
            .cache
            .as_ref()
            .ok_or_else(|| anyhow!("rebuild_cache_layout: cache absent"))?;
        let copies_before = paged_adopt_page_copies(current_cache);
        let (cap, dtype) = cache_cap_and_dtype(current_cache)?;
        let old_rows = self.cache_rows.clone();
        for &slot_row in target_rows {
            anyhow::ensure!(
                old_rows.contains(&slot_row),
                "rebuild_cache_layout: target slot row {slot_row} missing from old layout {old_rows:?}"
            );
        }
        let turboquant_bits = self.kv_cache_turboquant_bits_for_rows(target_rows)?;
        let mut new_cache =
            self.make_model_cache_for_rows(model, target_rows, cap, dtype, turboquant_bits)?;
        let mut old_cache = self.cache.take().expect("cache checked above");
        self.cache_rows.clear();
        let owners = self.block_owners_for_rows(target_rows)?;
        let prepare_result = (|| -> Result<()> {
            for (dst_row, &slot_row) in target_rows.iter().enumerate() {
                let src_row = old_rows
                    .iter()
                    .position(|&row| row == slot_row)
                    .expect("target rows prevalidated");
                adopt_cache_row_layers_skipping_reused_paged(
                    &mut new_cache,
                    &old_cache,
                    dst_row,
                    src_row,
                    "rebuild_cache_layout",
                )?;
            }
            reuse_full_paged_storage(
                &mut new_cache,
                &mut old_cache,
                &owners,
                "rebuild_cache_layout",
            )?;
            Ok(())
        })();
        if let Err(err) = prepare_result {
            self.cache = Some(old_cache);
            self.cache_rows = old_rows;
            return Err(err);
        }

        let copies_after = paged_adopt_page_copies(&new_cache);
        self.record_request_owned_kv_layout_rebuild(copies_before, copies_after);
        self.cache = Some(new_cache);
        self.cache_rows = target_rows.to_vec();
        Ok(())
    }

    fn prepare_forked_cache_layout(
        &self,
        model: &M,
        source_slot_row: usize,
        destination_slot_row: usize,
    ) -> Result<(Vec<LayerCache>, Vec<usize>, u64)> {
        let old_cache = self
            .cache
            .as_deref()
            .ok_or_else(|| anyhow!("prepare_forked_cache_layout: cache absent"))?;
        let old_rows = &self.cache_rows;
        anyhow::ensure!(
            old_rows.contains(&source_slot_row),
            "prepare_forked_cache_layout: source slot row {source_slot_row} missing from {old_rows:?}"
        );
        let mut target_rows = old_rows.clone();
        if !target_rows.contains(&destination_slot_row) {
            target_rows.push(destination_slot_row);
            target_rows.sort_unstable();
        }
        let (cap, dtype) = cache_cap_and_dtype(old_cache)?;
        let turboquant_bits = self.kv_cache_turboquant_bits_for_rows(&target_rows)?;
        let mut new_cache =
            self.make_model_cache_for_rows(model, &target_rows, cap, dtype, turboquant_bits)?;
        for (dst_row, &slot_row) in target_rows.iter().enumerate() {
            let source_row = if slot_row == destination_slot_row {
                source_slot_row
            } else {
                slot_row
            };
            let src_row = old_rows
                .iter()
                .position(|&row| row == source_row)
                .ok_or_else(|| {
                    anyhow!(
                        "prepare_forked_cache_layout: source slot row {source_row} missing from {old_rows:?}"
                    )
                })?;
            adopt_cache_row_layers_skipping_reused_paged(
                &mut new_cache,
                old_cache,
                dst_row,
                src_row,
                "prepare_forked_cache_layout",
            )?;
        }
        Ok((new_cache, target_rows, paged_adopt_page_copies(old_cache)))
    }

    fn install_cache_with_temp_row(
        &mut self,
        model: &M,
        temp_cache: &[LayerCache],
        temp_slot_row: usize,
    ) -> Result<()> {
        let old_cache = self
            .cache
            .as_deref()
            .ok_or_else(|| anyhow!("install_cache_with_temp_row: main cache absent"))?;
        let copies_before = paged_adopt_page_copies(old_cache);
        let old_rows = self.cache_rows.clone();
        let (old_cap, dtype) = cache_cap_and_dtype(old_cache)?;
        let (temp_cap, _) = cache_cap_and_dtype(temp_cache)?;
        let cap = old_cap.max(temp_cap);

        let mut target_rows: Vec<usize> = self
            .slots
            .iter()
            .enumerate()
            .filter_map(|(row, slot)| {
                matches!(slot, Some(state) if !state.finished && !state.generated_tokens.is_empty())
                    .then_some(row)
            })
            .collect();
        if !target_rows.contains(&temp_slot_row) {
            target_rows.push(temp_slot_row);
        }
        target_rows.sort_unstable();

        let turboquant_bits = self.kv_cache_turboquant_bits_for_rows(&target_rows)?;
        let mut new_cache =
            self.make_model_cache_for_rows(model, &target_rows, cap, dtype, turboquant_bits)?;
        let owners = self.block_owners_for_rows(&target_rows)?;
        let mut old_cache = self
            .cache
            .take()
            .expect("install cache preflight checked main cache");
        self.cache_rows.clear();
        let reused_paged = reuse_full_paged_storage(
            &mut new_cache,
            &mut old_cache,
            &owners,
            "install_cache_with_temp_row",
        )?;
        let install_result = (|| -> Result<()> {
            for (dst_row, &slot_row) in target_rows.iter().enumerate() {
                if slot_row == temp_slot_row {
                    adopt_cache_row_layers(
                        &mut new_cache,
                        temp_cache,
                        dst_row,
                        0,
                        "install_cache_with_temp_row",
                    )?;
                } else {
                    let src_row = old_rows
                        .iter()
                        .position(|&row| row == slot_row)
                        .ok_or_else(|| {
                            anyhow!(
                                "install_cache_with_temp_row: slot row {slot_row} missing from old layout {:?}",
                                old_rows
                            )
                        })?;
                    if reused_paged {
                        adopt_cache_row_layers_skipping_reused_paged(
                            &mut new_cache,
                            &old_cache,
                            dst_row,
                            src_row,
                            "install_cache_with_temp_row",
                        )?;
                    } else {
                        adopt_cache_row_layers(
                            &mut new_cache,
                            &old_cache,
                            dst_row,
                            src_row,
                            "install_cache_with_temp_row",
                        )?;
                    }
                }
            }
            Ok(())
        })();
        if let Err(err) = install_result {
            if reused_paged {
                let old_owners = self.block_owners_for_rows(&old_rows)?;
                reuse_full_paged_storage(
                    &mut old_cache,
                    &mut new_cache,
                    &old_owners,
                    "install_cache_with_temp_row rollback",
                )?;
                if let Some(table) = self
                    .slots
                    .get(temp_slot_row)
                    .and_then(Option::as_ref)
                    .and_then(|state| self.request_block_tables.get(&state.id))
                    .copied()
                {
                    release_full_paged_cache_owner(&mut old_cache, table.owner)?;
                }
            }
            self.cache = Some(old_cache);
            self.cache_rows = old_rows;
            return Err(err);
        }

        let copies_after = paged_adopt_page_copies(&new_cache);
        self.record_request_owned_kv_layout_rebuild(copies_before, copies_after);
        self.cache = Some(new_cache);
        self.cache_rows = target_rows;
        Ok(())
    }

    fn install_active_kv_payload(
        &mut self,
        slot_row: usize,
        entry: &PagedPrefixEntry,
        cached_len: i32,
        parked_cache_cap: i32,
        parked_cache_dtype: Dtype,
        model: &M,
    ) -> Result<()> {
        let cached_len_usize = usize::try_from(cached_len)
            .map_err(|_| anyhow!("install_active_kv_payload: negative cached length"))?;
        let destination_owner = self
            .slots
            .get(slot_row)
            .and_then(Option::as_ref)
            .and_then(|state| self.request_block_tables.get(&state.id))
            .ok_or_else(|| anyhow!("install_active_kv_payload: request block table absent"))?
            .owner;
        if let (Some(pool), Some(cache)) =
            (self.immutable_prefix_blocks.as_mut(), self.cache.as_mut())
        {
            reclaim_idle_immutable_blocks_for_targets(
                pool,
                cache,
                &[(destination_owner, cached_len_usize)],
            )?;
        }
        let copies_before = self
            .cache
            .as_deref()
            .map(paged_adopt_page_copies)
            .unwrap_or(0);
        let old_rows = self.cache_rows.clone();
        let (cap, dtype) = if let Some(cache) = self.cache.as_deref() {
            let (old_cap, old_dtype) = cache_cap_and_dtype(cache)?;
            (old_cap.max(parked_cache_cap), old_dtype)
        } else {
            (parked_cache_cap, parked_cache_dtype)
        };
        let mut target_rows: Vec<usize> = self
            .slots
            .iter()
            .enumerate()
            .filter_map(|(row, slot)| {
                matches!(slot, Some(state) if !state.finished && !state.generated_tokens.is_empty())
                    .then_some(row)
            })
            .collect();
        if !target_rows.contains(&slot_row) {
            target_rows.push(slot_row);
        }
        target_rows.sort_unstable();

        let turboquant_bits = self.kv_cache_turboquant_bits_for_rows(&target_rows)?;
        let mut new_cache =
            self.make_model_cache_for_rows(model, &target_rows, cap, dtype, turboquant_bits)?;
        let owners = self.block_owners_for_rows(&target_rows)?;
        let mut old_cache = self.cache.take();
        self.cache_rows.clear();
        let reused_paged = if let Some(old_cache) = old_cache.as_mut() {
            reuse_full_paged_storage(
                &mut new_cache,
                old_cache,
                &owners,
                "install_active_kv_payload",
            )?
        } else {
            false
        };
        let install_result = (|| -> Result<()> {
            for (dst_row, &target_slot_row) in target_rows.iter().enumerate() {
                if target_slot_row == slot_row {
                    restore_prefix_entry_for_row(&mut new_cache, entry, dst_row, cached_len)?;
                    continue;
                }
                let old_cache = old_cache.as_ref().ok_or_else(|| {
                    anyhow!("install_active_kv_payload: active rows without cache")
                })?;
                let src_row = old_rows
                    .iter()
                    .position(|&row| row == target_slot_row)
                    .ok_or_else(|| {
                        anyhow!(
                            "install_active_kv_payload: slot row {target_slot_row} missing from old layout {:?}",
                            old_rows
                        )
                    })?;
                if reused_paged {
                    adopt_cache_row_layers_skipping_reused_paged(
                        &mut new_cache,
                        old_cache,
                        dst_row,
                        src_row,
                        "install_active_kv_payload",
                    )?;
                } else {
                    adopt_cache_row_layers(
                        &mut new_cache,
                        old_cache,
                        dst_row,
                        src_row,
                        "install_active_kv_payload",
                    )?;
                }
            }
            Ok(())
        })();
        if let Err(err) = install_result {
            if reused_paged {
                if old_rows.is_empty() {
                    release_full_paged_cache_owner(&mut new_cache, destination_owner)?;
                    self.cache = Some(new_cache);
                    self.cache_rows = old_rows;
                    return Err(err);
                }
                let old_cache = old_cache
                    .as_mut()
                    .expect("paged storage reuse requires an old cache");
                let old_owners = self.block_owners_for_rows(&old_rows)?;
                reuse_full_paged_storage(
                    old_cache,
                    &mut new_cache,
                    &old_owners,
                    "install_active_kv_payload rollback",
                )?;
                if let Some(table) = self
                    .slots
                    .get(slot_row)
                    .and_then(Option::as_ref)
                    .and_then(|state| self.request_block_tables.get(&state.id))
                    .copied()
                {
                    release_full_paged_cache_owner(old_cache, table.owner)?;
                }
            }
            self.cache = old_cache;
            self.cache_rows = old_rows;
            return Err(err);
        }

        let copies_after = paged_adopt_page_copies(&new_cache);
        self.record_request_owned_kv_layout_rebuild(copies_before, copies_after);
        self.cache = Some(new_cache);
        self.cache_rows = target_rows;
        Ok(())
    }

    /// Free all in-flight rows and reset every layer cache to offset 0
    /// (preserves Array allocations for reuse). Legal while admitting, after
    /// prefill entered decoding, or after the batch finished. After this call
    /// the scheduler is back in `Idle` and ready to admit a new batch.
    ///
    /// `next_id` is **not** reset — the monotonic-no-reuse guarantee from
    /// 3a continues across batches.
    pub fn evict_all(&mut self) -> Result<()> {
        match self.phase {
            Phase::Admitting | Phase::Decoding | Phase::Finished => {}
            Phase::Idle => {
                return Err(anyhow!(
                    "evict_all illegal in {:?} phase: no batch is active",
                    self.phase
                ));
            }
        }
        let completed_histories = self
            .slots
            .iter()
            .enumerate()
            .filter_map(|(row_idx, slot)| {
                let state = slot.as_ref()?;
                let history = completed_prompt_lookup_history(state)?;
                let certifications = self
                    .prompt_lookup_state
                    .as_ref()
                    .and_then(|prompt_lookup| prompt_lookup.rows.get(&row_idx))
                    .filter(|row| row.owner == state.id)
                    .map(|row| row.mtp_certifications.clone())
                    .unwrap_or_default();
                Some((history, certifications))
            })
            .collect::<Vec<_>>();
        let owners = self
            .request_block_tables
            .values()
            .map(|table| table.owner)
            .collect::<Vec<_>>();
        if let Some(cache) = self.cache.as_mut() {
            for owner in owners {
                release_full_paged_cache_owner(cache, owner)?;
            }
        }
        for (history, certifications) in &completed_histories {
            self.publish_shared_prompt_lookup_history(history, certifications);
        }
        for slot in self.slots.iter_mut() {
            // B1-p2.5: release budget before clearing slot.
            if let Some(state) = slot.take() {
                self.budget_state.release(state.kv_bytes_admitted);
            }
        }
        self.governor_admission_reservations.clear();
        self.request_block_tables.clear();
        if self
            .immutable_prefix_blocks
            .as_ref()
            .is_none_or(ImmutablePrefixBlockPool::is_empty)
        {
            self.cache = None;
        }
        self.cache_rows.clear();
        self.mtp_state = None;
        self.gemma4_drafter_state = None;
        if self.shared_prompt_lookup_pool.is_some() {
            if let Some(state) = self.prompt_lookup_state.as_mut() {
                state.rows.clear();
                Self::refresh_prompt_lookup_index_stats(state);
            }
        } else {
            self.prompt_lookup_state = None;
        }
        self.phase = Phase::Idle;
        self.poisoned = false;
        Ok(())
    }

    pub fn mtp_stats(&self) -> Option<MtpSpeculativeStats> {
        self.mtp_state.as_ref().map(|state| state.stats.clone())
    }

    pub fn gemma4_drafter_stats(&self) -> Option<MtpSpeculativeStats> {
        self.gemma4_drafter_state
            .as_ref()
            .map(|state| state.stats.clone())
    }

    pub fn prompt_lookup_stats(&self) -> Option<PromptLookupStats> {
        self.prompt_lookup_state.as_ref().map(|state| {
            let mut stats = state.stats;
            if let Some(pool) = self.shared_prompt_lookup_pool.as_ref() {
                stats.shared_entries_current = pool.len() as u64;
                stats.shared_entries_peak =
                    stats.shared_entries_peak.max(pool.entries_peak() as u64);
                stats.shared_estimated_bytes_current = pool.estimated_bytes() as u64;
                stats.shared_estimated_bytes_peak = stats
                    .shared_estimated_bytes_peak
                    .max(pool.estimated_bytes_peak() as u64);
            }
            stats
        })
    }

    pub fn prompt_lookup_can_start_rolling_mid_admit(&self) -> bool {
        self.prompt_lookup_state.as_ref().is_some_and(|state| {
            state.rows.iter().all(|(&row_idx, row)| {
                self.slots
                    .get(row_idx)
                    .and_then(Option::as_ref)
                    .is_none_or(|slot| {
                        slot.finished
                            || (row.pending_tokens.is_empty() && row.prepared_proposal.is_none())
                    })
            })
        })
    }

    pub(crate) fn prompt_lookup_qualification_regime(
        &self,
    ) -> Option<PromptLookupQualificationRegime> {
        let prompt_lookup = self.prompt_lookup_state.as_ref()?;
        let mut batch_width = 0_usize;
        let mut context_tokens = 0_usize;
        let mut sampler = None;
        for (&row_idx, row) in &prompt_lookup.rows {
            let Some(slot) = self
                .slots
                .get(row_idx)
                .and_then(Option::as_ref)
                .filter(|slot| !slot.finished)
            else {
                continue;
            };
            if sampler.is_some_and(|current: Sampler| {
                crate::core::prompt_lookup::PromptLookupSamplerFingerprint::from(current)
                    != crate::core::prompt_lookup::PromptLookupSamplerFingerprint::from(
                        slot.sampler,
                    )
            }) {
                return None;
            }
            sampler = Some(slot.sampler);
            batch_width = batch_width.saturating_add(1);
            context_tokens = context_tokens.max(
                slot.prompt_ids
                    .len()
                    .saturating_add(slot.generated_tokens.len())
                    .saturating_add(row.pending_tokens.len()),
            );
        }
        sampler.map(|sampler| {
            PromptLookupQualificationRegime::new(batch_width, context_tokens, sampler)
        })
    }

    pub(crate) fn prompt_lookup_active_request_ids(&self) -> Vec<RequestId> {
        self.prompt_lookup_active_request_progress()
            .into_iter()
            .map(|(id, _)| id)
            .collect()
    }

    pub(crate) fn prompt_lookup_active_request_progress(&self) -> Vec<(RequestId, usize)> {
        let Some(prompt_lookup) = self.prompt_lookup_state.as_ref() else {
            return Vec::new();
        };
        self.slots
            .iter()
            .enumerate()
            .filter_map(|(row_idx, slot)| {
                let slot = slot.as_ref().filter(|slot| !slot.finished)?;
                prompt_lookup
                    .rows
                    .get(&row_idx)
                    .filter(|row| row.owner == slot.id)
                    .map(|row| {
                        let history_len = row.lookup.as_ref().map_or_else(
                            || {
                                slot.prompt_ids
                                    .len()
                                    .saturating_add(slot.generated_tokens.len())
                            },
                            |lookup| lookup.history().len(),
                        );
                        (slot.id, history_len)
                    })
            })
            .collect()
    }

    pub(crate) fn shared_prompt_lookup_availability_epoch(&self) -> Option<u64> {
        self.shared_prompt_lookup_pool
            .as_ref()
            .map(SharedPromptLookupPool::availability_epoch)
    }

    pub(crate) fn prompt_lookup_prepared_qualification_regime(
        &self,
    ) -> Option<PromptLookupQualificationRegime> {
        let base = self.prompt_lookup_qualification_regime()?;
        let prompt_lookup = self.prompt_lookup_state.as_ref()?;
        let mut saw_local = false;
        let mut saw_shared = false;
        let mut max_verify_width = 1_usize;
        for (&row_idx, row) in &prompt_lookup.rows {
            let slot = self.slots.get(row_idx).and_then(Option::as_ref)?;
            if slot.finished {
                continue;
            }
            if row.owner != slot.id {
                return None;
            }
            let proposal = row.prepared_proposal.as_ref()?;
            if proposal.tokens.is_empty() {
                return None;
            }
            max_verify_width = max_verify_width.max(proposal.tokens.len().saturating_add(1));
            match proposal.source {
                PromptLookupProposalSource::Local => saw_local = true,
                PromptLookupProposalSource::Shared => saw_shared = true,
                PromptLookupProposalSource::Mixed => return None,
            }
        }
        let source = match (saw_local, saw_shared) {
            (true, true) => PromptLookupProposalSource::Mixed,
            (true, false) => PromptLookupProposalSource::Local,
            (false, true) => PromptLookupProposalSource::Shared,
            (false, false) => return None,
        };
        Some(base.with_proposal(source, max_verify_width))
    }

    pub(crate) fn align_prepared_prompt_lookup_to_mtp_verify_shape(&mut self) -> Result<bool> {
        let Some(mtp_state) = self.mtp_state.as_ref() else {
            return Ok(false);
        };
        let max_supported_draft_tokens = mtp_state.cfg.max_draft_tokens;
        let mut draft_budgets = Vec::new();
        for (&row_idx, row_state) in &mtp_state.rows {
            let slot = self
                .slots
                .get(row_idx)
                .and_then(Option::as_ref)
                .ok_or_else(|| {
                    anyhow!(
                        "align_prepared_prompt_lookup_to_mtp_verify_shape: row {row_idx} slot absent"
                    )
                })?;
            if slot.finished {
                continue;
            }
            let remaining = slot
                .max_new_tokens
                .saturating_sub(slot.generated_tokens.len());
            if remaining == 0 {
                continue;
            }
            let draft_budget = row_state
                .adaptive_draft_tokens
                .min(max_supported_draft_tokens)
                .min(remaining);
            if draft_budget == 0 {
                return Ok(false);
            }
            draft_budgets.push((row_idx, slot.id, draft_budget));
        }
        if draft_budgets.is_empty() {
            return Ok(false);
        }

        let Some(prompt_lookup) = self.prompt_lookup_state.as_mut() else {
            return Ok(false);
        };
        let mut saw_local = false;
        let mut saw_shared = false;
        for &(row_idx, owner, draft_budget) in &draft_budgets {
            let Some(row) = prompt_lookup.rows.get(&row_idx) else {
                return Ok(false);
            };
            if row.owner != owner {
                return Ok(false);
            }
            let Some(proposal) = row.prepared_proposal.as_ref() else {
                return Ok(false);
            };
            match proposal.source {
                PromptLookupProposalSource::Local => saw_local = true,
                PromptLookupProposalSource::Shared => saw_shared = true,
                PromptLookupProposalSource::Mixed => return Ok(false),
            }
            if proposal.tokens.len() < draft_budget
                || proposal.mtp_certified_draft_len != draft_budget
                || proposal.mtp_certified_bonus_token.is_none()
                || proposal.mtp_policy_snapshot.is_none()
            {
                return Ok(false);
            }
        }
        if saw_local && saw_shared {
            return Ok(false);
        }
        for (row_idx, _, draft_budget) in draft_budgets {
            let proposal = prompt_lookup
                .rows
                .get_mut(&row_idx)
                .and_then(|row| row.prepared_proposal.as_mut())
                .expect("prepared proposal validated above");
            proposal.tokens.truncate(draft_budget);
            if saw_shared {
                prompt_lookup.stats.shared_mtp_certified_hits = prompt_lookup
                    .stats
                    .shared_mtp_certified_hits
                    .saturating_add(1);
            }
        }
        Ok(true)
    }

    pub(crate) fn clear_shared_prompt_lookup(&mut self) -> usize {
        let Some(pool) = self.shared_prompt_lookup_pool.as_mut() else {
            return 0;
        };
        let cleared = pool.clear();
        if let Some(state) = self.prompt_lookup_state.as_mut() {
            state.stats.shared_clear_count = state.stats.shared_clear_count.saturating_add(1);
            state.stats.shared_cleared_entries = state
                .stats
                .shared_cleared_entries
                .saturating_add(cleared as u64);
            state.stats.shared_entries_current = 0;
            state.stats.shared_estimated_bytes_current = 0;
        }
        cleared
    }

    pub fn prefill_admitted_prompt_lookup(
        &mut self,
        model: &M,
        cfg: PromptLookupConfig,
    ) -> Result<Vec<StepEvent>>
    where
        M: DenseVlMethods,
    {
        let cfg = cfg.validate()?;
        let events = self.prefill_admitted(model)?;
        self.initialize_prompt_lookup_for_active(cfg)?;
        Ok(events)
    }

    pub fn initialize_prompt_lookup_for_active(&mut self, cfg: PromptLookupConfig) -> Result<()> {
        let cfg = cfg.validate()?;
        if cfg.cross_request {
            match self.shared_prompt_lookup_pool.as_ref() {
                Some(pool) => anyhow::ensure!(
                    pool.config() == cfg,
                    "cross-request PromptLookup config changed while scheduler is active"
                ),
                None => {
                    self.shared_prompt_lookup_pool = Some(SharedPromptLookupPool::new(cfg)?);
                }
            }
        }
        let mut rows = HashMap::new();
        for (row_idx, slot) in self.slots.iter().enumerate() {
            let Some(state) = slot.as_ref().filter(|state| !state.finished) else {
                continue;
            };
            rows.insert(
                row_idx,
                SchedulerPromptLookupRowState {
                    owner: state.id,
                    cfg,
                    lookup: None,
                    prepared_proposal: None,
                    mtp_certifications: Vec::new(),
                    pending_tokens: VecDeque::new(),
                },
            );
        }
        let mut state = if let Some(mut state) = self.prompt_lookup_state.take() {
            anyhow::ensure!(
                state.cfg == cfg,
                "prompt lookup config changed while scheduler is active"
            );
            state.rows = rows;
            state
        } else {
            SchedulerPromptLookupState {
                cfg,
                rows,
                stats: PromptLookupStats::default(),
            }
        };
        Self::refresh_prompt_lookup_index_stats(&mut state);
        self.prompt_lookup_state = Some(state);
        Ok(())
    }

    pub fn register_prompt_lookup_request(
        &mut self,
        id: RequestId,
        cfg: PromptLookupConfig,
    ) -> Result<()> {
        let cfg = cfg.validate()?;
        let row_idx = self
            .slots
            .iter()
            .position(|slot| matches!(slot, Some(state) if state.id == id))
            .ok_or_else(|| anyhow!("prompt lookup request {} is not active", id.0))?;
        let state = self.slots[row_idx]
            .as_ref()
            .expect("row_idx found an occupied slot");
        let prompt_lookup = self
            .prompt_lookup_state
            .as_mut()
            .ok_or_else(|| anyhow!("prompt lookup scheduler state is absent"))?;
        anyhow::ensure!(
            prompt_lookup.cfg == cfg,
            "prompt lookup config changed while scheduler is active"
        );
        if state.finished {
            return Ok(());
        }
        prompt_lookup.rows.insert(
            row_idx,
            SchedulerPromptLookupRowState {
                owner: id,
                cfg,
                lookup: None,
                prepared_proposal: None,
                mtp_certifications: Vec::new(),
                pending_tokens: VecDeque::new(),
            },
        );
        Self::refresh_prompt_lookup_index_stats(prompt_lookup);
        Ok(())
    }

    fn publish_shared_prompt_lookup_history(
        &mut self,
        history: &[u32],
        mtp_certifications: &[SharedPromptLookupMtpCertification],
    ) {
        let Some(pool) = self.shared_prompt_lookup_pool.as_mut() else {
            return;
        };
        let result = pool.publish_history_with_mtp_certifications(history, mtp_certifications);
        if let Some(state) = self.prompt_lookup_state.as_mut() {
            state.stats.shared_published_requests =
                state.stats.shared_published_requests.saturating_add(1);
            state.stats.shared_published_tokens = state
                .stats
                .shared_published_tokens
                .saturating_add(result.indexed_tokens as u64);
            state.stats.shared_mtp_certified_published_windows = state
                .stats
                .shared_mtp_certified_published_windows
                .saturating_add(mtp_certifications.len() as u64);
            state.stats.shared_mtp_certified_published_tokens = state
                .stats
                .shared_mtp_certified_published_tokens
                .saturating_add(
                    mtp_certifications
                        .iter()
                        .map(|certification| certification.draft_len as u64)
                        .sum::<u64>(),
                );
            state.stats.shared_evictions = state
                .stats
                .shared_evictions
                .saturating_add(result.evicted_entries as u64);
            state.stats.shared_entries_current = pool.len() as u64;
            state.stats.shared_entries_peak = state
                .stats
                .shared_entries_peak
                .max(pool.entries_peak() as u64);
            state.stats.shared_estimated_bytes_current = pool.estimated_bytes() as u64;
            state.stats.shared_estimated_bytes_peak = state
                .stats
                .shared_estimated_bytes_peak
                .max(pool.estimated_bytes_peak() as u64);
        }
    }

    fn record_prompt_lookup_mtp_certification(
        &mut self,
        row_idx: usize,
        continuation: usize,
        draft_len: usize,
        policy_snapshot: QwenMtpDraftPolicySnapshot,
    ) {
        if draft_len == 0 {
            return;
        }
        let Some(slot) = self.slots.get(row_idx).and_then(Option::as_ref) else {
            return;
        };
        let Some(prompt_lookup) = self.prompt_lookup_state.as_mut() else {
            return;
        };
        let Some(row) = prompt_lookup.rows.get_mut(&row_idx) else {
            return;
        };
        if row.owner != slot.id {
            return;
        }
        if let Some(certification) = row
            .mtp_certifications
            .iter_mut()
            .find(|certification| certification.continuation == continuation)
        {
            certification.draft_len = certification.draft_len.max(draft_len);
            if draft_len >= certification.draft_len {
                certification.policy_snapshot = policy_snapshot;
            }
        } else {
            row.mtp_certifications
                .push(SharedPromptLookupMtpCertification {
                    continuation,
                    draft_len,
                    policy_snapshot,
                });
        }
    }

    pub(crate) fn prepare_prompt_lookup_batch_window(
        &mut self,
        allow_cross_request: bool,
        draft_limits: PromptLookupDraftLimits,
    ) -> Result<bool> {
        self.ensure_not_poisoned()?;
        anyhow::ensure!(
            self.phase == Phase::Decoding,
            "prepare_prompt_lookup_batch_window illegal in {:?} phase",
            self.phase
        );
        let mut prompt_lookup = self
            .prompt_lookup_state
            .take()
            .ok_or_else(|| anyhow!("prompt lookup scheduler state is absent"))?;
        let result = (|| {
            let active_rows = self
                .slots
                .iter()
                .enumerate()
                .filter_map(|(row, slot)| {
                    (matches!(slot, Some(state) if !state.finished)
                        && prompt_lookup.rows.contains_key(&row))
                    .then_some(row)
                })
                .collect::<Vec<_>>();
            if active_rows.is_empty() {
                return Ok(false);
            }
            anyhow::ensure!(
                active_rows.iter().all(|row_idx| {
                    prompt_lookup
                        .rows
                        .get(row_idx)
                        .is_some_and(|row| row.pending_tokens.is_empty())
                }),
                "prompt lookup proposal preparation requires a common batch-window boundary"
            );
            self.prepare_prompt_lookup_rows(
                &active_rows,
                &mut prompt_lookup.stats,
                &mut prompt_lookup.rows,
                allow_cross_request,
                draft_limits,
            )?;
            Ok(active_rows.iter().all(|row_idx| {
                prompt_lookup
                    .rows
                    .get(row_idx)
                    .and_then(|row| row.prepared_proposal.as_ref())
                    .is_some_and(|proposal| !proposal.tokens.is_empty())
            }))
        })();
        Self::refresh_prompt_lookup_index_stats(&mut prompt_lookup);
        self.prompt_lookup_state = Some(prompt_lookup);
        result
    }

    pub fn prompt_lookup_prepared_window_verify_eligible(
        &self,
        model: &M,
        _capture_accepted_hidden: bool,
    ) -> Result<bool> {
        let prompt_lookup = self
            .prompt_lookup_state
            .as_ref()
            .ok_or_else(|| anyhow!("prompt lookup scheduler state is absent"))?;
        let active_rows = self
            .slots
            .iter()
            .enumerate()
            .filter_map(|(row, slot)| {
                (matches!(slot, Some(state) if !state.finished)
                    && prompt_lookup.rows.contains_key(&row))
                .then_some(row)
            })
            .collect::<Vec<_>>();
        if active_rows.is_empty() {
            return Ok(false);
        }

        let mut max_context_tokens = 0_usize;
        let mut max_verify_len = 1_usize;
        for &row_idx in &active_rows {
            let slot = self.slots[row_idx]
                .as_ref()
                .expect("active prompt lookup row retains its slot");
            let Some(proposal) = prompt_lookup
                .rows
                .get(&row_idx)
                .and_then(|row| row.prepared_proposal.as_ref())
            else {
                return Ok(false);
            };
            if proposal.tokens.is_empty() {
                return Ok(false);
            }
            anyhow::ensure!(
                prompt_lookup.rows[&row_idx].owner == slot.id,
                "prepared PromptLookup proposal owner changed for row {row_idx}"
            );
            max_context_tokens = max_context_tokens.max(slot.real_len.max(0) as usize);
            max_verify_len = max_verify_len.max(proposal.tokens.len().saturating_add(1));
        }

        let batch = active_rows.len();
        let verify_kv_bits = self.kv_cache_turboquant_bits_for_rows(&active_rows)?;
        let exact_batched_verify = model.supports_exact_batched_speculative_verify_for_kv_cache(
            batch,
            max_context_tokens,
            max_verify_len,
            verify_kv_bits,
        );
        Ok(exact_batched_verify
            || model.supports_sequential_prompt_lookup_verify(
                batch,
                max_context_tokens,
                max_verify_len,
            ))
    }

    pub fn discard_prepared_prompt_lookup_window(&mut self) {
        if let Some(state) = self.prompt_lookup_state.as_mut() {
            for row in state.rows.values_mut() {
                row.prepared_proposal = None;
            }
        }
    }

    fn take_prompt_lookup_mtp_expectations(&mut self) -> Result<Vec<PromptLookupMtpExpectation>> {
        let Some(prompt_lookup) = self.prompt_lookup_state.as_mut() else {
            return Ok(Vec::new());
        };
        let mut expectations = Vec::new();
        for (&row_idx, row) in &mut prompt_lookup.rows {
            let Some(slot) = self.slots.get(row_idx).and_then(Option::as_ref) else {
                continue;
            };
            if slot.finished {
                row.prepared_proposal = None;
                continue;
            }
            anyhow::ensure!(
                row.owner == slot.id,
                "PromptLookup MTP observation rejected stale request {} for row {row_idx} owned by {}",
                slot.id.0,
                row.owner.0
            );
            let Some(proposal) = row.prepared_proposal.take() else {
                continue;
            };
            anyhow::ensure!(
                proposal.source != PromptLookupProposalSource::Mixed,
                "canonical PromptLookup MTP observation received mixed proposal"
            );
            anyhow::ensure!(
                !proposal.tokens.is_empty()
                    && proposal.mtp_certified_draft_len == proposal.tokens.len(),
                "canonical PromptLookup MTP observation requires a full certified draft"
            );
            let bonus_token = proposal.mtp_certified_bonus_token.ok_or_else(|| {
                anyhow!("canonical PromptLookup MTP observation requires a certified bonus")
            })?;
            expectations.push(PromptLookupMtpExpectation {
                row_idx,
                owner: row.owner,
                source: proposal.source,
                draft_tokens: proposal.tokens,
                bonus_token,
            });
        }
        expectations.sort_unstable_by_key(|expectation| expectation.row_idx);
        Ok(expectations)
    }

    fn record_prompt_lookup_mtp_observations(
        &mut self,
        expectations: &[PromptLookupMtpExpectation],
        observations: &[CanonicalMtpWindowObservation],
    ) -> Result<bool> {
        if expectations.is_empty() {
            return Ok(true);
        }
        let started = Instant::now();
        anyhow::ensure!(
            expectations.len() == observations.len(),
            "canonical MTP produced {} observations for {} shared PromptLookup expectations",
            observations.len(),
            expectations.len()
        );
        let prompt_lookup = self
            .prompt_lookup_state
            .as_mut()
            .ok_or_else(|| anyhow!("prompt lookup scheduler state is absent"))?;
        let mut all_canonical = true;
        for expectation in expectations {
            let slot = self
                .slots
                .get(expectation.row_idx)
                .and_then(Option::as_ref)
                .ok_or_else(|| {
                    anyhow!(
                        "canonical PromptLookup row {} disappeared",
                        expectation.row_idx
                    )
                })?;
            anyhow::ensure!(
                slot.id == expectation.owner,
                "canonical PromptLookup row {} changed owner from {} to {}",
                expectation.row_idx,
                expectation.owner.0,
                slot.id.0
            );
            let observation = observations
                .iter()
                .find(|observation| observation.row_idx == expectation.row_idx)
                .ok_or_else(|| {
                    anyhow!(
                        "canonical MTP observation missing row {}",
                        expectation.row_idx
                    )
                })?;
            let draft_matches = observation.draft_tokens == expectation.draft_tokens;
            let accepted = if draft_matches {
                observation
                    .accepted_draft_len
                    .min(expectation.draft_tokens.len())
            } else {
                0
            };
            let canonical = draft_matches
                && accepted == expectation.draft_tokens.len()
                && observation.bonus_token == Some(expectation.bonus_token);
            all_canonical &= canonical;

            let drafted = expectation.draft_tokens.len() as u64;
            let accepted = accepted as u64;
            prompt_lookup.stats.drafted_tokens =
                prompt_lookup.stats.drafted_tokens.saturating_add(drafted);
            prompt_lookup.stats.accepted_tokens =
                prompt_lookup.stats.accepted_tokens.saturating_add(accepted);
            prompt_lookup.stats.rejected_tokens = prompt_lookup
                .stats
                .rejected_tokens
                .saturating_add(drafted.saturating_sub(accepted));
            let source_stats = match expectation.source {
                PromptLookupProposalSource::Local => &mut prompt_lookup.stats.local_source,
                PromptLookupProposalSource::Shared => &mut prompt_lookup.stats.shared_source,
                PromptLookupProposalSource::Mixed => unreachable!(),
            };
            source_stats.drafted_tokens = source_stats.drafted_tokens.saturating_add(drafted);
            source_stats.accepted_tokens = source_stats.accepted_tokens.saturating_add(accepted);
            source_stats.wasted_verify_tokens = source_stats
                .wasted_verify_tokens
                .saturating_add(drafted.saturating_sub(accepted));
            if drafted > 0 && accepted == 0 {
                prompt_lookup.stats.zero_accept_windows =
                    prompt_lookup.stats.zero_accept_windows.saturating_add(1);
                source_stats.zero_accept_windows =
                    source_stats.zero_accept_windows.saturating_add(1);
            }
            if expectation.source == PromptLookupProposalSource::Shared {
                prompt_lookup.stats.shared_mtp_canonical_validation_windows = prompt_lookup
                    .stats
                    .shared_mtp_canonical_validation_windows
                    .saturating_add(1);
                prompt_lookup.stats.shared_mtp_canonical_validation_tokens = prompt_lookup
                    .stats
                    .shared_mtp_canonical_validation_tokens
                    .saturating_add(drafted);
                if !draft_matches || (accepted == drafted && !canonical) {
                    prompt_lookup
                        .stats
                        .shared_mtp_canonical_validation_mismatches = prompt_lookup
                        .stats
                        .shared_mtp_canonical_validation_mismatches
                        .saturating_add(1);
                }
            }
        }
        let saw_shared = expectations
            .iter()
            .any(|expectation| expectation.source == PromptLookupProposalSource::Shared);
        if !all_canonical && saw_shared {
            prompt_lookup.stats.shared_mtp_canonical_fallbacks = prompt_lookup
                .stats
                .shared_mtp_canonical_fallbacks
                .saturating_add(1);
        }
        if saw_shared {
            add_elapsed_us(
                &mut prompt_lookup.stats.shared_mtp_canonical_validation_us,
                started,
            );
        }
        Ok(all_canonical)
    }

    pub fn commit_prompt_lookup_events(&mut self, events: &[StepEvent]) -> Result<()> {
        let Some(prompt_lookup) = self.prompt_lookup_state.as_mut() else {
            return Ok(());
        };
        for event in events {
            let row_idx = self
                .slots
                .iter()
                .position(|slot| matches!(slot, Some(state) if state.id == event.id))
                .ok_or_else(|| {
                    anyhow!("commit_prompt_lookup_events lost request {}", event.id.0)
                })?;
            let Some(row) = prompt_lookup.rows.get_mut(&row_idx) else {
                continue;
            };
            anyhow::ensure!(
                row.owner == event.id,
                "commit_prompt_lookup_events rejected stale request {} for row {row_idx} owned by {}",
                event.id.0,
                row.owner.0
            );
            let Some(lookup) = row.lookup.as_mut() else {
                continue;
            };
            let update_start = Instant::now();
            lookup.commit(event.token);
            add_elapsed_us(&mut prompt_lookup.stats.index_update_us, update_start);
        }
        Self::refresh_prompt_lookup_index_stats(prompt_lookup);
        Ok(())
    }

    pub fn step_prompt_lookup(&mut self, model: &M) -> Result<Vec<StepEvent>> {
        match self.step_prompt_lookup_with_projection(
            model,
            |model, hidden, target| model.project_hidden_on(hidden, target),
            false,
            false,
            |_, _| Ok(PromptLookupMtpShadowOutput::Done),
        )? {
            PromptLookupMtpStepOutcome::Events { events, .. } => Ok(events),
            PromptLookupMtpStepOutcome::FallbackToNeural => {
                Err(anyhow!("standalone PromptLookup requested neural fallback"))
            }
        }
    }

    pub fn step_prompt_lookup_batch_window(&mut self, model: &M) -> Result<Vec<StepEvent>> {
        match self.step_prompt_lookup_with_projection(
            model,
            |model, hidden, target| model.project_hidden_on(hidden, target),
            false,
            true,
            |_, _| Ok(PromptLookupMtpShadowOutput::Done),
        )? {
            PromptLookupMtpStepOutcome::Events { events, .. } => Ok(events),
            PromptLookupMtpStepOutcome::FallbackToNeural => {
                Err(anyhow!("batch PromptLookup requested neural fallback"))
            }
        }
    }

    pub(crate) fn step_prompt_lookup_with_mtp_verify(
        &mut self,
        model: &M,
        mtp: &M::MtpHead,
    ) -> Result<PromptLookupMtpStepOutcome>
    where
        M: MtpSpeculativeModel,
    {
        let policy_kv_state = MtpDraftPolicyKvState::from_runtime(
            self.paged_prefix_cache.is_some(),
            self.active_kv_config.enabled,
        );
        let mut mtp_state = self
            .mtp_state
            .take()
            .ok_or_else(|| anyhow!("step_prompt_lookup_with_mtp_verify: MTP state absent"))?;
        let mut canonical_transaction = None;
        let result = self.step_prompt_lookup_with_projection(
            model,
            |model, hidden, target| model.project_mtp_verify_hidden_on(hidden, target),
            true,
            true,
            |action, stats| match action {
                PromptLookupMtpShadowAction::Prepare(inputs) => {
                    anyhow::ensure!(
                        canonical_transaction.is_none(),
                        "PromptLookup canonical MTP transaction already prepared"
                    );
                    let (transaction, device_drafts) = Self::prepare_prompt_lookup_mtp_canonical(
                        model,
                        mtp,
                        &mut mtp_state,
                        inputs,
                        stats,
                        policy_kv_state,
                    )?;
                    canonical_transaction = Some(transaction);
                    Ok(PromptLookupMtpShadowOutput::Prepared(device_drafts))
                }
                PromptLookupMtpShadowAction::Commit(accepted) => {
                    if let Some(transaction) = canonical_transaction.take() {
                        Self::commit_prompt_lookup_mtp_canonical(
                            model,
                            mtp,
                            &mut mtp_state,
                            transaction,
                            accepted,
                            stats,
                        )?;
                    } else {
                        Self::commit_prompt_lookup_mtp_shadow(
                            model,
                            mtp,
                            &mut mtp_state,
                            accepted,
                            stats,
                        )?;
                    }
                    Ok(PromptLookupMtpShadowOutput::Done)
                }
                PromptLookupMtpShadowAction::Abort => {
                    if let Some(transaction) = canonical_transaction.take() {
                        Self::abort_prompt_lookup_mtp_canonical(&mut mtp_state, transaction)?;
                    }
                    Ok(PromptLookupMtpShadowOutput::Done)
                }
            },
        );
        if let Some(transaction) = canonical_transaction.take() {
            let abort_result = Self::abort_prompt_lookup_mtp_canonical(&mut mtp_state, transaction);
            if let Err(abort_error) = abort_result {
                self.mtp_state = Some(mtp_state);
                return match result {
                    Ok(_) => Err(abort_error),
                    Err(error) => Err(error.context(format!(
                        "PromptLookup canonical MTP cleanup failed: {abort_error:#}"
                    ))),
                };
            }
        }
        self.mtp_state = Some(mtp_state);
        result
    }

    fn step_prompt_lookup_with_projection<F, C>(
        &mut self,
        model: &M,
        project_hidden: F,
        capture_accepted_hidden: bool,
        common_batch_window: bool,
        mut commit_shadow: C,
    ) -> Result<PromptLookupMtpStepOutcome>
    where
        F: Fn(&M, &Array, mlx::StreamOrDevice) -> Result<Array> + Copy,
        C: for<'b> FnMut(
            PromptLookupMtpShadowAction<'b>,
            &mut PromptLookupStats,
        ) -> Result<PromptLookupMtpShadowOutput>,
    {
        self.ensure_not_poisoned()?;
        match self.step_prompt_lookup_inner(
            model,
            project_hidden,
            capture_accepted_hidden,
            common_batch_window,
            &mut commit_shadow,
        ) {
            Ok(outcome) => Ok(outcome),
            Err(err) => {
                self.poisoned = true;
                Err(err)
            }
        }
    }

    pub fn step_prompt_lookup_ordinary(&mut self, model: &M) -> Result<Vec<StepEvent>> {
        self.ensure_not_poisoned()?;
        match self.step_prompt_lookup_ordinary_inner(model) {
            Ok(events) => Ok(events),
            Err(err) => {
                self.poisoned = true;
                Err(err)
            }
        }
    }

    fn step_prompt_lookup_ordinary_inner(&mut self, model: &M) -> Result<Vec<StepEvent>> {
        if self.phase != Phase::Decoding {
            return Err(anyhow!(
                "step_prompt_lookup_ordinary illegal in {:?} phase",
                self.phase
            ));
        }
        let mut prompt_lookup = self
            .prompt_lookup_state
            .take()
            .ok_or_else(|| anyhow!("step_prompt_lookup_ordinary: scheduler state is absent"))?;
        let result = (|| {
            let events = self.step_inner(model)?;
            for event in &events {
                let row_idx = self
                    .slots
                    .iter()
                    .position(|slot| matches!(slot, Some(state) if state.id == event.id))
                    .ok_or_else(|| {
                        anyhow!("prompt lookup ordinary step lost request {}", event.id.0)
                    })?;
                let Some(lookup) = prompt_lookup
                    .rows
                    .get_mut(&row_idx)
                    .and_then(|row| row.lookup.as_mut())
                else {
                    continue;
                };
                let update_start = Instant::now();
                lookup.commit(event.token);
                add_elapsed_us(&mut prompt_lookup.stats.index_update_us, update_start);
            }
            Self::refresh_prompt_lookup_index_stats(&mut prompt_lookup);
            Ok(events)
        })();
        self.prompt_lookup_state = Some(prompt_lookup);
        result
    }

    fn step_prompt_lookup_inner<F, C>(
        &mut self,
        model: &M,
        project_hidden: F,
        capture_accepted_hidden: bool,
        common_batch_window: bool,
        commit_shadow: &mut C,
    ) -> Result<PromptLookupMtpStepOutcome>
    where
        F: Fn(&M, &Array, mlx::StreamOrDevice) -> Result<Array> + Copy,
        C: for<'b> FnMut(
            PromptLookupMtpShadowAction<'b>,
            &mut PromptLookupStats,
        ) -> Result<PromptLookupMtpShadowOutput>,
    {
        if self.phase != Phase::Decoding {
            return Err(anyhow!(
                "step_prompt_lookup illegal in {:?} phase: call prefill_admitted_prompt_lookup first",
                self.phase
            ));
        }
        let mut prompt_lookup = self
            .prompt_lookup_state
            .take()
            .ok_or_else(|| anyhow!("step_prompt_lookup: scheduler state is absent"))?;
        let result = (|| {
            let active_rows = self
                .slots
                .iter()
                .enumerate()
                .filter_map(|(row, slot)| {
                    (matches!(slot, Some(state) if !state.finished)
                        && prompt_lookup.rows.contains_key(&row))
                    .then_some(row)
                })
                .collect::<Vec<_>>();
            if active_rows.is_empty() {
                self.phase = if self
                    .slots
                    .iter()
                    .any(|slot| matches!(slot, Some(state) if !state.finished))
                {
                    Phase::Decoding
                } else {
                    Phase::Finished
                };
                return Ok(PromptLookupMtpStepOutcome::Events {
                    events: Vec::new(),
                    canonical_shared_full_accept: false,
                });
            }

            let mid_admit_in_flight = self.slots.iter().enumerate().any(|(row_idx, slot)| {
                matches!(slot, Some(state) if !state.finished)
                    && !prompt_lookup.rows.contains_key(&row_idx)
            });
            let all_at_window_boundary = active_rows.iter().all(|row_idx| {
                prompt_lookup
                    .rows
                    .get(row_idx)
                    .is_some_and(|row| row.pending_tokens.is_empty())
            });
            // Keep rolling mid-admission on the ordinary decode contract. A
            // speculative window advances KV beyond the emitted boundary;
            // carrying that lookahead through the admission cache-layout
            // transition is not architecture-stable even when offsets remain
            // correct. Once finalize registers the new row, speculation may
            // resume from the ordinary boundary on the next turn.
            if mid_admit_in_flight && all_at_window_boundary {
                anyhow::ensure!(
                    !capture_accepted_hidden,
                    "PromptLookup MTP shadow mode cannot fall back to ordinary decode during mid-admission"
                );
                let events = self.step_inner(model)?;
                for event in &events {
                    let row_idx = self
                        .slots
                        .iter()
                        .position(|slot| matches!(slot, Some(state) if state.id == event.id))
                        .ok_or_else(|| {
                            anyhow!("prompt lookup batch fallback lost request {}", event.id.0)
                        })?;
                    let update_start = Instant::now();
                    if let Some(lookup) = prompt_lookup
                        .rows
                        .get_mut(&row_idx)
                        .ok_or_else(|| {
                            anyhow!("prompt lookup batch fallback row {row_idx} is absent")
                        })?
                        .lookup
                        .as_mut()
                    {
                        lookup.commit(event.token);
                        add_elapsed_us(&mut prompt_lookup.stats.index_update_us, update_start);
                    }
                }
                Self::refresh_prompt_lookup_index_stats(&mut prompt_lookup);
                return Ok(PromptLookupMtpStepOutcome::Events {
                    events,
                    canonical_shared_full_accept: false,
                });
            }

            let rows_to_fill = if common_batch_window && !all_at_window_boundary {
                Vec::new()
            } else {
                active_rows
                    .iter()
                    .copied()
                    .filter(|row_idx| {
                        prompt_lookup
                            .rows
                            .get(row_idx)
                            .is_some_and(|row| row.pending_tokens.is_empty())
                    })
                    .collect::<Vec<_>>()
            };
            let fill_outcome = self.fill_prompt_lookup_windows(
                &rows_to_fill,
                PromptLookupFillRuntime {
                    stats: &mut prompt_lookup.stats,
                    row_states: &mut prompt_lookup.rows,
                    model,
                    project_hidden,
                    capture_accepted_hidden,
                    commit_shadow,
                },
            )?;
            let canonical_shared_full_accept = match fill_outcome {
                PromptLookupFillOutcome::Filled {
                    canonical_shared_full_accept,
                } => canonical_shared_full_accept,
                PromptLookupFillOutcome::MtpCanonicalFallback => {
                    return Ok(PromptLookupMtpStepOutcome::FallbackToNeural);
                }
                PromptLookupFillOutcome::NoVerify => {
                    anyhow::ensure!(
                        !capture_accepted_hidden,
                        "PromptLookup MTP shadow mode requires a prepared eligible verify window"
                    );
                    let events = self.step_inner(model)?;
                    for event in &events {
                        let row_idx = self
                            .slots
                            .iter()
                            .position(|slot| matches!(slot, Some(state) if state.id == event.id))
                            .ok_or_else(|| {
                                anyhow!("prompt lookup miss fast path lost request {}", event.id.0)
                            })?;
                        let update_start = Instant::now();
                        if let Some(lookup) = prompt_lookup
                            .rows
                            .get_mut(&row_idx)
                            .ok_or_else(|| {
                                anyhow!("prompt lookup miss fast path row {row_idx} is absent")
                            })?
                            .lookup
                            .as_mut()
                        {
                            lookup.commit(event.token);
                            add_elapsed_us(&mut prompt_lookup.stats.index_update_us, update_start);
                        }
                    }
                    Self::refresh_prompt_lookup_index_stats(&mut prompt_lookup);
                    return Ok(PromptLookupMtpStepOutcome::Events {
                        events,
                        canonical_shared_full_accept: false,
                    });
                }
            };

            let mut events = Vec::with_capacity(active_rows.len());
            for row_idx in active_rows {
                let Some(token) = prompt_lookup
                    .rows
                    .get_mut(&row_idx)
                    .ok_or_else(|| anyhow!("step_prompt_lookup: row {row_idx} state is absent"))?
                    .pending_tokens
                    .pop_front()
                else {
                    anyhow::ensure!(
                        common_batch_window && !all_at_window_boundary,
                        "step_prompt_lookup: row {row_idx} pending queue is empty"
                    );
                    continue;
                };
                let event = self.emit_token_for_row(row_idx, token)?;
                let update_start = Instant::now();
                prompt_lookup
                    .rows
                    .get_mut(&row_idx)
                    .expect("row state checked above")
                    .lookup
                    .as_mut()
                    .expect("prompt lookup index initialized before pending tokens")
                    .commit(token);
                add_elapsed_us(&mut prompt_lookup.stats.index_update_us, update_start);
                events.push(event);
            }
            Self::refresh_prompt_lookup_index_stats(&mut prompt_lookup);
            self.phase = if self
                .slots
                .iter()
                .any(|slot| matches!(slot, Some(state) if !state.finished))
            {
                Phase::Decoding
            } else {
                Phase::Finished
            };
            self.refresh_active_kv_residency_stats();
            Ok(PromptLookupMtpStepOutcome::Events {
                events,
                canonical_shared_full_accept,
            })
        })();
        self.prompt_lookup_state = Some(prompt_lookup);
        result
    }

    fn refresh_prompt_lookup_index_stats(state: &mut SchedulerPromptLookupState) {
        state.stats.index_entries_current = state
            .rows
            .values()
            .filter_map(|row| row.lookup.as_ref())
            .map(|lookup| lookup.index_entries() as u64)
            .sum();
        let peak = state
            .rows
            .values()
            .filter_map(|row| row.lookup.as_ref())
            .map(|lookup| lookup.index_entries_peak() as u64)
            .sum();
        state.stats.index_entries_peak = state.stats.index_entries_peak.max(peak);
        state.stats.index_ledger_entries_current = state
            .rows
            .values()
            .filter_map(|row| row.lookup.as_ref())
            .map(|lookup| lookup.ledger_entries() as u64)
            .sum();
        let ledger_peak = state
            .rows
            .values()
            .filter_map(|row| row.lookup.as_ref())
            .map(|lookup| lookup.ledger_entries_peak() as u64)
            .sum();
        state.stats.index_ledger_entries_peak =
            state.stats.index_ledger_entries_peak.max(ledger_peak);
        state.stats.index_estimated_bytes_current = state
            .rows
            .values()
            .filter_map(|row| row.lookup.as_ref())
            .map(|lookup| lookup.estimated_bytes() as u64)
            .sum();
        let estimated_bytes_peak = state
            .rows
            .values()
            .filter_map(|row| row.lookup.as_ref())
            .map(|lookup| lookup.estimated_bytes_peak() as u64)
            .sum();
        state.stats.index_estimated_bytes_peak = state
            .stats
            .index_estimated_bytes_peak
            .max(estimated_bytes_peak);
        state.stats.index_evictions = state
            .rows
            .values()
            .filter_map(|row| row.lookup.as_ref())
            .map(PromptLookupRowState::index_evictions)
            .sum();
    }

    fn prepare_prompt_lookup_rows(
        &mut self,
        rows_to_prepare: &[usize],
        stats: &mut PromptLookupStats,
        row_states: &mut HashMap<usize, SchedulerPromptLookupRowState>,
        allow_cross_request: bool,
        draft_limits: PromptLookupDraftLimits,
    ) -> Result<()> {
        for &row_idx in rows_to_prepare {
            let slot = self.slots[row_idx].as_ref().ok_or_else(|| {
                anyhow!("prepare_prompt_lookup_rows: row {row_idx} slot is absent")
            })?;
            if slot.finished {
                continue;
            }
            let remaining = slot
                .max_new_tokens
                .saturating_sub(slot.generated_tokens.len());
            if remaining == 0 {
                continue;
            }
            let current_token = *slot.generated_tokens.last().ok_or_else(|| {
                anyhow!("prepare_prompt_lookup_rows: row {row_idx} has no current token")
            })?;
            let row_state = row_states.get_mut(&row_idx).ok_or_else(|| {
                anyhow!("prepare_prompt_lookup_rows: row {row_idx} state is absent")
            })?;
            anyhow::ensure!(
                row_state.owner == slot.id,
                "prepare_prompt_lookup_rows: row {row_idx} belongs to stale request {} instead of {}",
                row_state.owner.0,
                slot.id.0
            );
            if row_state.prepared_proposal.is_some() {
                continue;
            }
            if row_state.lookup.is_none() {
                let mut history = Vec::with_capacity(
                    slot.prompt_ids
                        .len()
                        .saturating_add(slot.generated_tokens.len()),
                );
                history.extend_from_slice(&slot.prompt_ids);
                history.extend_from_slice(&slot.generated_tokens);
                let build_start = Instant::now();
                row_state.lookup = Some(PromptLookupRowState::new(&history, row_state.cfg)?);
                add_elapsed_us(&mut stats.index_build_us, build_start);
            }
            let lookup = row_state
                .lookup
                .as_ref()
                .expect("prompt lookup index initialized above");
            lookup.validate_committed_tail(
                slot.prompt_ids
                    .len()
                    .saturating_add(slot.generated_tokens.len()),
                current_token,
            )?;
            stats.queries = stats.queries.saturating_add(1);
            stats.local_source.queries = stats.local_source.queries.saturating_add(1);
            let local_start = Instant::now();
            let local_proposal =
                lookup.propose(remaining.saturating_sub(1).min(draft_limits.local()));
            let local_elapsed_us = elapsed_us_since(local_start);
            stats.propose_us = stats.propose_us.saturating_add(local_elapsed_us);
            stats.local_source.propose_us = stats
                .local_source
                .propose_us
                .saturating_add(local_elapsed_us);
            let proposal = if let Some(proposal) = local_proposal {
                stats.local_source.hits = stats.local_source.hits.saturating_add(1);
                let certification = row_state
                    .mtp_certifications
                    .iter()
                    .filter(|certification| certification.continuation == proposal.continuation)
                    .max_by_key(|certification| certification.draft_len);
                let mtp_certified_draft_len = certification
                    .map(|certification| certification.draft_len.min(proposal.tokens.len()))
                    .unwrap_or(0);
                let mtp_certified_bonus_token = (mtp_certified_draft_len > 0)
                    .then(|| {
                        lookup
                            .history()
                            .get(
                                proposal
                                    .continuation
                                    .saturating_add(mtp_certified_draft_len),
                            )
                            .copied()
                    })
                    .flatten();
                let mtp_policy_snapshot =
                    certification.map(|certification| certification.policy_snapshot.clone());
                Some((
                    proposal.tokens,
                    PromptLookupProposalSource::Local,
                    mtp_certified_draft_len,
                    mtp_certified_bonus_token,
                    mtp_policy_snapshot,
                ))
            } else {
                stats.local_source.misses = stats.local_source.misses.saturating_add(1);
                if row_state.cfg.cross_request && allow_cross_request {
                    stats.shared_queries = stats.shared_queries.saturating_add(1);
                    stats.shared_source.queries = stats.shared_source.queries.saturating_add(1);
                    let shared = self.shared_prompt_lookup_pool.as_mut().ok_or_else(|| {
                        anyhow!("cross-request PromptLookup pool is not initialized")
                    })?;
                    let shared_start = Instant::now();
                    let shared_proposal = shared.propose(
                        lookup.history(),
                        lookup.history_fingerprint(),
                        remaining.saturating_sub(1).min(draft_limits.shared()),
                    );
                    let shared_elapsed_us = elapsed_us_since(shared_start);
                    stats.propose_us = stats.propose_us.saturating_add(shared_elapsed_us);
                    stats.shared_source.propose_us = stats
                        .shared_source
                        .propose_us
                        .saturating_add(shared_elapsed_us);
                    match shared_proposal {
                        Some(proposal) => {
                            stats.shared_hits = stats.shared_hits.saturating_add(1);
                            stats.shared_source.hits = stats.shared_source.hits.saturating_add(1);
                            Some((
                                proposal.tokens,
                                PromptLookupProposalSource::Shared,
                                proposal.mtp_certified_draft_len,
                                proposal.mtp_certified_bonus_token,
                                proposal.mtp_policy_snapshot,
                            ))
                        }
                        None => {
                            stats.shared_misses = stats.shared_misses.saturating_add(1);
                            stats.shared_source.misses =
                                stats.shared_source.misses.saturating_add(1);
                            None
                        }
                    }
                } else {
                    None
                }
            };
            row_state.prepared_proposal = Some(
                if let Some((
                    tokens,
                    source,
                    mtp_certified_draft_len,
                    mtp_certified_bonus_token,
                    mtp_policy_snapshot,
                )) = proposal
                {
                    stats.hits = stats.hits.saturating_add(1);
                    PreparedPromptLookupProposal {
                        tokens,
                        source,
                        mtp_certified_draft_len,
                        mtp_certified_bonus_token,
                        mtp_policy_snapshot,
                    }
                } else {
                    stats.misses = stats.misses.saturating_add(1);
                    PreparedPromptLookupProposal {
                        tokens: Vec::new(),
                        source: PromptLookupProposalSource::Local,
                        mtp_certified_draft_len: 0,
                        mtp_certified_bonus_token: None,
                        mtp_policy_snapshot: None,
                    }
                },
            );
        }
        Ok(())
    }

    fn fill_prompt_lookup_windows<F, C>(
        &mut self,
        rows_to_fill: &[usize],
        runtime: PromptLookupFillRuntime<'_, M, F, C>,
    ) -> Result<PromptLookupFillOutcome>
    where
        F: Fn(&M, &Array, mlx::StreamOrDevice) -> Result<Array> + Copy,
        C: for<'b> FnMut(
            PromptLookupMtpShadowAction<'b>,
            &mut PromptLookupStats,
        ) -> Result<PromptLookupMtpShadowOutput>,
    {
        let PromptLookupFillRuntime {
            stats,
            row_states,
            model,
            project_hidden,
            capture_accepted_hidden,
            commit_shadow,
        } = runtime;
        if rows_to_fill.is_empty() {
            return Ok(PromptLookupFillOutcome::Filled {
                canonical_shared_full_accept: false,
            });
        }

        let max_draft_tokens = row_states
            .values()
            .next()
            .map_or(1, |row| row.cfg.max_draft_tokens);
        self.prepare_prompt_lookup_rows(
            rows_to_fill,
            stats,
            row_states,
            true,
            PromptLookupDraftLimits::uniform(max_draft_tokens),
        )?;
        let mut contexts = Vec::with_capacity(rows_to_fill.len());
        for &row_idx in rows_to_fill {
            let slot = self.slots[row_idx].as_ref().ok_or_else(|| {
                anyhow!("fill_prompt_lookup_windows: row {row_idx} slot is absent")
            })?;
            if slot.finished {
                continue;
            }
            let remaining = slot
                .max_new_tokens
                .saturating_sub(slot.generated_tokens.len());
            if remaining == 0 {
                continue;
            }
            let current_token = *slot.generated_tokens.last().ok_or_else(|| {
                anyhow!("fill_prompt_lookup_windows: row {row_idx} has no current token")
            })?;
            let row_state = row_states.get_mut(&row_idx).ok_or_else(|| {
                anyhow!("fill_prompt_lookup_windows: row {row_idx} state is absent")
            })?;
            anyhow::ensure!(
                row_state.owner == slot.id,
                "fill_prompt_lookup_windows: row {row_idx} belongs to stale request {} instead of {}",
                row_state.owner.0,
                slot.id.0
            );
            let proposal = row_state.prepared_proposal.take().ok_or_else(|| {
                anyhow!("fill_prompt_lookup_windows: row {row_idx} has no prepared proposal")
            })?;
            let mut history =
                Vec::with_capacity(slot.prompt_ids.len() + slot.generated_tokens.len());
            history.extend_from_slice(&slot.prompt_ids);
            history.extend_from_slice(&slot.generated_tokens);
            let mut draft_tokens = proposal.tokens;
            if let Some(constraint) = slot.constraint.as_ref() {
                let valid_prefix = constraint.validate_tokens(&draft_tokens)?;
                draft_tokens.truncate(valid_prefix);
            }
            let mtp_certified_draft_len = proposal.mtp_certified_draft_len.min(draft_tokens.len());
            contexts.push(PromptLookupBatchedFillContext {
                row_idx,
                current_token,
                stop_token_ids: slot.stop_token_ids.clone(),
                remaining,
                verify_start_pos: slot.real_len,
                draft_tokens,
                proposal_source: proposal.source,
                mtp_certified_draft_len,
                mtp_certified_bonus_token: proposal.mtp_certified_bonus_token,
                mtp_policy_snapshot: proposal.mtp_policy_snapshot,
                sampler: slot.sampler,
                history,
            });
        }
        if contexts.is_empty() {
            return Ok(PromptLookupFillOutcome::Filled {
                canonical_shared_full_accept: false,
            });
        }
        // A miss row forces the common emission boundary to one token, so the
        // batch cannot amortize speculative verification. Keep the whole batch
        // on ordinary decode and avoid acceptance packing/host synchronization.
        if contexts.iter().any(|ctx| ctx.draft_tokens.is_empty()) {
            stats.miss_fast_path_steps = stats.miss_fast_path_steps.saturating_add(1);
            return Ok(PromptLookupFillOutcome::NoVerify);
        }
        // A shared Qwen proposal is canonical only when it was certified at
        // this exact committed history and target verification reproduces the
        // complete native MTP window, including its bonus token. Partial
        // acceptance must fall back before emitting because native MTP uses a
        // numerically distinct target projection from ordinary decoding.
        let require_canonical_shared_full_accept = capture_accepted_hidden
            && contexts.iter().all(|ctx| {
                ctx.proposal_source == PromptLookupProposalSource::Shared
                    && ctx.mtp_certified_draft_len == ctx.draft_tokens.len()
                    && ctx.mtp_certified_bonus_token.is_some()
                    && ctx.mtp_policy_snapshot.is_some()
            });

        let active_rows = self
            .slots
            .iter()
            .enumerate()
            .filter_map(|(row, slot)| {
                (matches!(slot, Some(state) if !state.finished) && row_states.contains_key(&row))
                    .then_some(row)
            })
            .collect::<Vec<_>>();
        // Keep the model-facing batch stable while some standalone
        // PromptLookup rows drain pending tokens. Nonparticipant rows receive
        // zero sequence lengths below and therefore do not advance cache.
        self.rebuild_cache_layout(model, &active_rows)?;

        let base_snapshot = self
            .cache
            .as_ref()
            .ok_or_else(|| anyhow!("fill_prompt_lookup_windows: main cache is absent"))?
            .iter()
            .map(LayerCache::snapshot)
            .collect::<Vec<_>>();
        let mut attempted_verify = false;
        let mut canonical_fallback = false;
        let mut prng_commit = None;
        let verify_result = (|| -> Result<()> {
            let cache_row_for_ctx = contexts
                .iter()
                .map(|ctx| {
                    self.cache_rows
                        .iter()
                        .position(|&row| row == ctx.row_idx)
                        .ok_or_else(|| {
                            anyhow!(
                                "fill_prompt_lookup_windows: row {} missing from cache layout {:?}",
                                ctx.row_idx,
                                self.cache_rows
                            )
                        })
                })
                .collect::<Result<Vec<_>>>()?;
            let batch = self.cache_rows.len();
            let max_verify_len = contexts
                .iter()
                .map(|ctx| ctx.draft_tokens.len() + 1)
                .max()
                .unwrap_or(1);
            let mut verify_flat = vec![0_u32; batch * max_verify_len];
            let mut verify_lens = vec![0_i32; batch];
            let mut verify_starts = vec![0_i32; batch];
            for (ctx_idx, ctx) in contexts.iter().enumerate() {
                let compact_row = cache_row_for_ctx[ctx_idx];
                let start = compact_row * max_verify_len;
                verify_flat[start] = ctx.current_token;
                verify_flat[start + 1..start + 1 + ctx.draft_tokens.len()]
                    .copy_from_slice(&ctx.draft_tokens);
                verify_lens[compact_row] = (ctx.draft_tokens.len() + 1) as i32;
                verify_starts[compact_row] = ctx.verify_start_pos;
            }
            let max_context_tokens = verify_starts
                .iter()
                .copied()
                .max()
                .and_then(|value| usize::try_from(value).ok())
                .unwrap_or(usize::MAX);
            let verify_kv_bits = self.kv_cache_turboquant_bits_for_rows(&self.cache_rows)?;
            let exact_batched_verify = model
                .supports_exact_batched_speculative_verify_for_kv_cache(
                    batch,
                    max_context_tokens,
                    max_verify_len,
                    verify_kv_bits,
                );
            if !exact_batched_verify
                && !model.supports_sequential_prompt_lookup_verify(
                    batch,
                    max_context_tokens,
                    max_verify_len,
                )
            {
                return Ok(());
            }
            attempted_verify = true;
            if exact_batched_verify {
                stats.exact_batched_verify_windows =
                    stats.exact_batched_verify_windows.saturating_add(1);
            } else {
                stats.sequential_verify_windows = stats.sequential_verify_windows.saturating_add(1);
            }
            let canonical_device_drafts = if require_canonical_shared_full_accept {
                let inputs = contexts
                    .iter()
                    .map(|ctx| PromptLookupMtpDraftInput {
                        row_idx: ctx.row_idx,
                        current_token: ctx.current_token,
                        verify_start_pos: ctx.verify_start_pos,
                        expected_draft_tokens: ctx.draft_tokens.clone(),
                    })
                    .collect::<Vec<_>>();
                match commit_shadow(PromptLookupMtpShadowAction::Prepare(&inputs), stats) {
                    Ok(PromptLookupMtpShadowOutput::Prepared(device_drafts)) => Some(device_drafts),
                    Ok(PromptLookupMtpShadowOutput::Done) => {
                        return Err(anyhow!(
                            "canonical PromptLookup prepare returned no device drafts"
                        ));
                    }
                    Err(error)
                        if error
                            .downcast_ref::<PromptLookupMtpCanonicalMismatch>()
                            .is_some() =>
                    {
                        stats.shared_mtp_canonical_fallbacks =
                            stats.shared_mtp_canonical_fallbacks.saturating_add(1);
                        canonical_fallback = true;
                        return Ok(());
                    }
                    Err(error) => return Err(error),
                }
            } else {
                None
            };
            let verify_arr = build_prompt_lookup_device_verify_input(
                &contexts,
                &cache_row_for_ctx,
                batch,
                max_verify_len,
                canonical_device_drafts.as_deref(),
                mlx::StreamOrDevice::default(),
            )?;
            let verify_round_start = Instant::now();
            let mut accepted_hidden_source = None;
            let verify_logits = if exact_batched_verify {
                let position_ids = if model.requires_position_ids() {
                    build_mtp_batched_position_ids(
                        &verify_starts,
                        &verify_lens,
                        max_verify_len as i32,
                    )?
                } else {
                    self.reusable_dummy_position_ids()?
                };
                let decode_mask = {
                    let cache = self.cache.as_ref().ok_or_else(|| {
                        anyhow!("fill_prompt_lookup_windows: main cache is absent")
                    })?;
                    maybe_build_sparse_decode_mask(cache, &verify_lens)?
                };
                let verify_start = Instant::now();
                let hidden = {
                    let _verify_qmm = crate::nn::verify_qmm::armed_scope();
                    let cache = self.cache.as_mut().ok_or_else(|| {
                        anyhow!("fill_prompt_lookup_windows: main cache is absent")
                    })?;
                    model.forward_text_hidden(
                        &verify_arr,
                        &position_ids,
                        Some(&verify_lens),
                        decode_mask.as_ref(),
                        Some(cache.as_mut_slice()),
                        mlx::StreamOrDevice::default(),
                    )?
                };
                add_elapsed_us(&mut stats.verify_forward_us, verify_start);
                if capture_accepted_hidden {
                    accepted_hidden_source = Some(hidden.clone());
                }
                let projection_start = Instant::now();
                let logits = project_hidden(model, &hidden, mlx::StreamOrDevice::default())?;
                add_elapsed_us(&mut stats.projection_us, projection_start);
                logits
            } else {
                let mut logits_steps = Vec::with_capacity(max_verify_len);
                let mut hidden_steps =
                    capture_accepted_hidden.then(|| Vec::with_capacity(max_verify_len));
                for depth in 0..max_verify_len {
                    let mut step_tokens = vec![0_i32; batch];
                    let mut step_lens = vec![0_i32; batch];
                    let mut step_starts = vec![0_i32; batch];
                    for row in 0..batch {
                        if depth < verify_lens[row] as usize {
                            step_tokens[row] = verify_flat[row * max_verify_len + depth] as i32;
                            step_lens[row] = 1;
                            step_starts[row] = verify_starts[row] + depth as i32;
                        }
                    }
                    let step_arr: Array =
                        (&step_tokens[..], &[batch as i32, 1_i32][..]).try_into()?;
                    let position_ids = if model.requires_position_ids() {
                        build_mtp_batched_position_ids(&step_starts, &step_lens, 1)?
                    } else {
                        self.reusable_dummy_position_ids()?
                    };
                    let decode_mask = {
                        let cache = self.cache.as_ref().ok_or_else(|| {
                            anyhow!("fill_prompt_lookup_windows: main cache is absent")
                        })?;
                        maybe_build_sparse_decode_mask(cache, &step_lens)?
                    };
                    let verify_start = Instant::now();
                    let (logits, hidden) = {
                        let cache = self.cache.as_mut().ok_or_else(|| {
                            anyhow!("fill_prompt_lookup_windows: main cache is absent")
                        })?;
                        if capture_accepted_hidden {
                            let hidden = model.forward_text_hidden(
                                &step_arr,
                                &position_ids,
                                Some(&step_lens),
                                decode_mask.as_ref(),
                                Some(cache.as_mut_slice()),
                                mlx::StreamOrDevice::default(),
                            )?;
                            let projection_start = Instant::now();
                            let logits =
                                project_hidden(model, &hidden, mlx::StreamOrDevice::default())?;
                            add_elapsed_us(&mut stats.projection_us, projection_start);
                            (logits, Some(hidden))
                        } else {
                            (
                                model.forward_on(
                                    &step_arr,
                                    &position_ids,
                                    Some(&step_lens),
                                    decode_mask.as_ref(),
                                    Some(cache.as_mut_slice()),
                                    mlx::StreamOrDevice::default(),
                                )?,
                                None,
                            )
                        }
                    };
                    add_elapsed_us(&mut stats.verify_forward_us, verify_start);
                    if model.requires_eager_sequential_speculative_verify() {
                        // Some cache/shared-state implementations require
                        // each q=1 write to materialize before host-side
                        // offsets advance.
                        mlx::transforms::eval(&[&logits])?;
                    }
                    if let (Some(hidden_steps), Some(hidden)) = (hidden_steps.as_mut(), hidden) {
                        hidden_steps.push(hidden);
                    }
                    logits_steps.push(logits);
                }
                if let Some(hidden_steps) = hidden_steps {
                    let refs = hidden_steps.iter().collect::<Vec<_>>();
                    accepted_hidden_source = Some(mlx::ops::shape::concatenate_on(
                        &refs,
                        1,
                        mlx::StreamOrDevice::default(),
                    )?);
                }
                let refs = logits_steps.iter().collect::<Vec<_>>();
                mlx::ops::shape::concatenate(&refs, 1)?
            };
            let mut speculative_masks = vec![None; batch];
            for (ctx_idx, ctx) in contexts.iter().enumerate() {
                if let Some(constraint) = self.slots[ctx.row_idx]
                    .as_ref()
                    .and_then(|state| state.constraint.as_ref())
                {
                    speculative_masks[cache_row_for_ctx[ctx_idx]] =
                        Some(constraint.speculative_masks(&ctx.draft_tokens)?);
                }
            }
            let verify_logits = crate::core::constrained::apply_speculative_token_masks(
                &verify_logits,
                &speculative_masks,
            )?;
            let all_greedy = contexts.iter().all(|ctx| ctx.sampler.is_pipelinable());
            let mut resolutions = (0..contexts.len())
                .map(|_| None)
                .collect::<Vec<Option<SpeculativeResolution>>>();
            if all_greedy {
                let verified_ids = mlx::ops::reduction::argmax(&verify_logits, -1, false)?;
                let packed = pack_greedy_acceptance_on(
                    &verify_arr,
                    &verify_lens,
                    &verified_ids,
                    mlx::StreamOrDevice::default(),
                )?;
                let sync_start = Instant::now();
                let packed: Vec<u32> = packed.to_vec()?;
                stats.verify_accept_host_sync_count =
                    stats.verify_accept_host_sync_count.saturating_add(1);
                add_elapsed_us(&mut stats.verify_accept_host_sync_us, sync_start);
                let packed_stride = max_verify_len + 1;
                anyhow::ensure!(
                    packed.len() == batch * packed_stride,
                    "fill_prompt_lookup_windows: packed acceptance len {} != {}",
                    packed.len(),
                    batch * packed_stride
                );
                for (ctx_idx, ctx) in contexts.iter().enumerate() {
                    let resolution = resolve_packed_greedy_acceptance(
                        &packed,
                        packed_stride,
                        cache_row_for_ctx[ctx_idx],
                        ctx.draft_tokens.len(),
                    )?
                    .1;
                    resolutions[ctx_idx] = Some(resolution);
                }
            } else {
                let context_rows = contexts.iter().map(|ctx| ctx.row_idx).collect::<Vec<_>>();
                let compact_prng = self.compact_prng_state_for_rows(&context_rows)?;
                let mut compact_prng_host: Vec<u32> = compact_prng.to_vec()?;
                let vocab = *verify_logits
                    .shape()
                    .as_slice()
                    .last()
                    .ok_or_else(|| anyhow!("prompt lookup verify logits have no vocab axis"))?;
                let sync_start = Instant::now();
                let mut compact_logits_rows = Vec::new();
                let mut compact_samplers = Vec::new();
                let mut compact_histories = Vec::new();
                let mut compact_ranges = Vec::new();
                let mut compact_uniforms = Vec::new();
                for (ctx_idx, ctx) in contexts.iter().enumerate() {
                    let compact_row = cache_row_for_ctx[ctx_idx] as i32;
                    let verify_len = (ctx.draft_tokens.len() + 1) as i32;
                    let row_logits = mlx::ops::indexing::slice(
                        &verify_logits,
                        &[compact_row, 0_i32, 0_i32][..],
                        &[compact_row + 1, verify_len, vocab][..],
                    )?;
                    if ctx.sampler.is_pipelinable() {
                        let verified =
                            mlx::ops::reduction::argmax(&row_logits, -1, false)?.to_vec()?;
                        resolutions[ctx_idx] =
                            Some(resolve_speculative_tokens(&ctx.draft_tokens, &verified)?);
                        continue;
                    }
                    let token_start = compact_samplers.len();
                    compact_samplers.extend(std::iter::repeat_n(&ctx.sampler, verify_len as usize));
                    compact_histories.extend((0..verify_len as usize).map(|position| {
                        let mut position_history = Vec::with_capacity(ctx.history.len() + position);
                        position_history.extend_from_slice(&ctx.history);
                        position_history.extend_from_slice(&ctx.draft_tokens[..position]);
                        position_history
                    }));
                    let key_start = ctx_idx * 2;
                    let mut row_prng: Array =
                        (&compact_prng_host[key_start..key_start + 2], &[2_i32][..]).try_into()?;
                    compact_uniforms.extend(draw_uniforms(&mut row_prng, verify_len as usize)?);
                    let updated_key: Vec<u32> = row_prng.to_vec()?;
                    compact_prng_host[key_start..key_start + 2].copy_from_slice(&updated_key);
                    compact_ranges.push((ctx_idx, token_start, verify_len as usize));
                    compact_logits_rows.push(row_logits.reshape(&[verify_len, vocab][..])?);
                }
                if !compact_logits_rows.is_empty() {
                    let refs = compact_logits_rows.iter().collect::<Vec<_>>();
                    let compact_logits = mlx::ops::shape::concatenate(&refs, 0)?;
                    let compact_history_refs = compact_histories
                        .iter()
                        .map(Vec::as_slice)
                        .collect::<Vec<_>>();
                    let target_tokens = sample_target_tokens_with_uniforms_batch(
                        &compact_samplers,
                        &compact_logits,
                        &compact_history_refs,
                        &compact_uniforms,
                    )?;
                    for &(ctx_idx, token_start, verify_len) in &compact_ranges {
                        let ctx = &contexts[ctx_idx];
                        resolutions[ctx_idx] = Some(resolve_exact_deterministic_target_tokens(
                            &ctx.draft_tokens,
                            &target_tokens[token_start..token_start + verify_len],
                        )?);
                    }
                }
                stats.verify_accept_host_sync_count =
                    stats.verify_accept_host_sync_count.saturating_add(1);
                add_elapsed_us(&mut stats.verify_accept_host_sync_us, sync_start);
                prng_commit = Some((
                    context_rows,
                    (&compact_prng_host[..], &[contexts.len() as i32, 2_i32][..]).try_into()?,
                ));
            }
            let mut resolutions = resolutions
                .into_iter()
                .enumerate()
                .map(|(ctx_idx, resolution)| {
                    resolution.ok_or_else(|| {
                        anyhow!("prompt lookup context {ctx_idx} has no speculative resolution")
                    })
                })
                .collect::<Result<Vec<_>>>()?;
            for (ctx, resolution) in contexts.iter().zip(resolutions.iter_mut()) {
                if let Some(constraint) = self.slots[ctx.row_idx]
                    .as_ref()
                    .and_then(|slot| slot.constraint.as_ref())
                {
                    constraint
                        .truncate_invalid_speculative_bonus(&mut resolution.tokens_to_append)?;
                }
            }
            let verify_round_us = elapsed_us_since(verify_round_start);
            stats.verify_round_us = stats.verify_round_us.saturating_add(verify_round_us);
            let local_verify_weight = contexts
                .iter()
                .filter(|ctx| ctx.proposal_source == PromptLookupProposalSource::Local)
                .map(|ctx| ctx.draft_tokens.len().saturating_add(1) as u64)
                .sum::<u64>();
            let shared_verify_weight = contexts
                .iter()
                .filter(|ctx| ctx.proposal_source == PromptLookupProposalSource::Shared)
                .map(|ctx| ctx.draft_tokens.len().saturating_add(1) as u64)
                .sum::<u64>();
            let total_verify_weight = local_verify_weight.saturating_add(shared_verify_weight);
            if let Some(local_verify_us) = verify_round_us
                .saturating_mul(local_verify_weight)
                .checked_div(total_verify_weight)
            {
                stats.local_source.verify_us =
                    stats.local_source.verify_us.saturating_add(local_verify_us);
                stats.shared_source.verify_us = stats
                    .shared_source
                    .verify_us
                    .saturating_add(verify_round_us.saturating_sub(local_verify_us));
            }

            let common_emit_len = contexts
                .iter()
                .zip(resolutions.iter())
                .map(|(ctx, resolution)| {
                    let mut len = resolution.tokens_to_append.len().min(ctx.remaining);
                    if let Some(stop_idx) = resolution.tokens_to_append[..len]
                        .iter()
                        .position(|token| ctx.stop_token_ids.contains(token))
                    {
                        len = stop_idx + 1;
                    }
                    len
                })
                .min()
                .unwrap_or(1);
            anyhow::ensure!(
                common_emit_len > 0,
                "prompt lookup batch resolved an empty emission window"
            );

            for (ctx, resolution) in contexts.iter().zip(resolutions.iter_mut()) {
                let verified_input_len = ctx.draft_tokens.len() + 1;
                resolution.tokens_to_append.truncate(common_emit_len);
                resolution.accepted_draft_len = resolution
                    .accepted_draft_len
                    .min(common_emit_len.saturating_sub(1));
                resolution.accepted_verify_input_len = common_emit_len;
                resolution.needs_rollback = common_emit_len < verified_input_len;
                let drafted = ctx.draft_tokens.len() as u64;
                let accepted = resolution.accepted_draft_len as u64;
                stats.exact_sampling_windows = stats
                    .exact_sampling_windows
                    .saturating_add(resolution.exact_sampling.windows as u64);
                stats.exact_acceptance_draws = stats
                    .exact_acceptance_draws
                    .saturating_add(resolution.exact_sampling.acceptance_draws as u64);
                stats.exact_residual_corrections = stats
                    .exact_residual_corrections
                    .saturating_add(resolution.exact_sampling.residual_corrections as u64);
                stats.exact_bonus_samples = stats
                    .exact_bonus_samples
                    .saturating_add(resolution.exact_sampling.bonus_samples as u64);
                stats.drafted_tokens = stats.drafted_tokens.saturating_add(drafted);
                stats.accepted_tokens = stats.accepted_tokens.saturating_add(accepted);
                stats.rejected_tokens = stats
                    .rejected_tokens
                    .saturating_add(drafted.saturating_sub(accepted));
                let source_stats = match ctx.proposal_source {
                    PromptLookupProposalSource::Local => &mut stats.local_source,
                    PromptLookupProposalSource::Shared => &mut stats.shared_source,
                    PromptLookupProposalSource::Mixed => {
                        unreachable!("individual PromptLookup proposal cannot have mixed source")
                    }
                };
                source_stats.drafted_tokens = source_stats.drafted_tokens.saturating_add(drafted);
                source_stats.accepted_tokens =
                    source_stats.accepted_tokens.saturating_add(accepted);
                source_stats.wasted_verify_tokens = source_stats
                    .wasted_verify_tokens
                    .saturating_add(drafted.saturating_sub(accepted));
                if drafted > 0 && accepted == 0 {
                    stats.zero_accept_windows = stats.zero_accept_windows.saturating_add(1);
                    source_stats.zero_accept_windows =
                        source_stats.zero_accept_windows.saturating_add(1);
                }
                if resolution.needs_rollback {
                    stats.rollback_count = stats.rollback_count.saturating_add(1);
                }
            }
            if require_canonical_shared_full_accept
                && contexts
                    .iter()
                    .zip(resolutions.iter())
                    .any(|(ctx, resolution)| {
                        resolution.accepted_draft_len != ctx.draft_tokens.len()
                            || resolution
                                .tokens_to_append
                                .get(ctx.draft_tokens.len())
                                .is_some_and(|actual| {
                                    Some(*actual) != ctx.mtp_certified_bonus_token
                                })
                    })
            {
                let rollback_start = Instant::now();
                {
                    let cache = self.cache.as_mut().ok_or_else(|| {
                        anyhow!("fill_prompt_lookup_windows: main cache is absent")
                    })?;
                    restore_layer_cache(cache.as_mut_slice(), &base_snapshot)?;
                }
                let rollback_us = elapsed_us_since(rollback_start);
                stats.rollback_us = stats.rollback_us.saturating_add(rollback_us);
                stats.shared_source.rollback_us =
                    stats.shared_source.rollback_us.saturating_add(rollback_us);
                stats.shared_mtp_canonical_fallbacks =
                    stats.shared_mtp_canonical_fallbacks.saturating_add(1);
                let _ = commit_shadow(PromptLookupMtpShadowAction::Abort, stats)?;
                canonical_fallback = true;
                return Ok(());
            }

            let mismatch_rows = resolutions
                .iter()
                .enumerate()
                .filter_map(|(ctx_idx, resolution)| {
                    resolution.needs_rollback.then_some((
                        cache_row_for_ctx[ctx_idx],
                        resolution.accepted_verify_input_len,
                    ))
                })
                .collect::<Vec<_>>();
            let supports_trim = self
                .cache
                .as_ref()
                .is_some_and(|cache| layer_cache_supports_accepted_prefix_trim(cache))
                && model.supports_speculative_accepted_prefix_trim();
            let canonical_target_replay = require_canonical_shared_full_accept && !supports_trim;
            if !mismatch_rows.is_empty() || canonical_target_replay {
                let rollback_start = Instant::now();
                if supports_trim {
                    let cache = self.cache.as_mut().ok_or_else(|| {
                        anyhow!("fill_prompt_lookup_windows: main cache is absent")
                    })?;
                    trim_full_layer_cache_rows_to_accepted_prefix(
                        cache.as_mut_slice(),
                        &base_snapshot,
                        &mismatch_rows,
                    )?;
                } else {
                    {
                        let cache = self.cache.as_mut().ok_or_else(|| {
                            anyhow!("fill_prompt_lookup_windows: main cache is absent")
                        })?;
                        restore_layer_cache(cache.as_mut_slice(), &base_snapshot)?;
                    }
                    let accepted_lens = resolutions
                        .iter()
                        .map(|resolution| resolution.accepted_verify_input_len)
                        .collect::<Vec<_>>();
                    let max_replay_len = accepted_lens.iter().copied().max().unwrap_or(1);
                    let mut replay_flat = vec![0_i32; batch * max_replay_len];
                    let mut replay_lens = vec![0_i32; batch];
                    let mut replay_starts = vec![0_i32; batch];
                    for (ctx_idx, ctx) in contexts.iter().enumerate() {
                        let compact_row = cache_row_for_ctx[ctx_idx];
                        let accepted_len = accepted_lens[ctx_idx];
                        let start = compact_row * max_replay_len;
                        replay_flat[start] = ctx.current_token as i32;
                        for (dst, &token) in replay_flat[start + 1..start + accepted_len]
                            .iter_mut()
                            .zip(ctx.draft_tokens[..accepted_len.saturating_sub(1)].iter())
                        {
                            *dst = token as i32;
                        }
                        replay_lens[compact_row] = accepted_len as i32;
                        replay_starts[compact_row] = ctx.verify_start_pos;
                    }
                    let mut replay_hidden_steps =
                        capture_accepted_hidden.then(|| Vec::with_capacity(max_replay_len));
                    for depth in 0..max_replay_len {
                        let mut step_tokens = vec![0_i32; batch];
                        let mut step_lens = vec![0_i32; batch];
                        let mut step_starts = vec![0_i32; batch];
                        for row in 0..batch {
                            if depth < replay_lens[row] as usize {
                                step_tokens[row] = replay_flat[row * max_replay_len + depth];
                                step_lens[row] = 1;
                                step_starts[row] = replay_starts[row] + depth as i32;
                            }
                        }
                        let step_arr: Array =
                            (&step_tokens[..], &[batch as i32, 1_i32][..]).try_into()?;
                        let replay_position_ids = if model.requires_position_ids() {
                            build_mtp_batched_position_ids(&step_starts, &step_lens, 1)?
                        } else {
                            self.reusable_dummy_position_ids()?
                        };
                        let replay_mask = {
                            let cache = self.cache.as_ref().ok_or_else(|| {
                                anyhow!("fill_prompt_lookup_windows: main cache is absent")
                            })?;
                            maybe_build_sparse_decode_mask(cache, &step_lens)?
                        };
                        let cache = self.cache.as_mut().ok_or_else(|| {
                            anyhow!("fill_prompt_lookup_windows: main cache is absent")
                        })?;
                        let replay_hidden = model.forward_text_hidden(
                            &step_arr,
                            &replay_position_ids,
                            Some(&step_lens),
                            replay_mask.as_ref(),
                            Some(cache.as_mut_slice()),
                            mlx::StreamOrDevice::default(),
                        )?;
                        mlx::transforms::eval(&[&replay_hidden])?;
                        if let Some(hidden_steps) = replay_hidden_steps.as_mut() {
                            hidden_steps.push(replay_hidden);
                        }
                    }
                    if let Some(hidden_steps) = replay_hidden_steps {
                        let refs = hidden_steps.iter().collect::<Vec<_>>();
                        accepted_hidden_source = Some(mlx::ops::shape::concatenate_on(
                            &refs,
                            1,
                            mlx::StreamOrDevice::default(),
                        )?);
                    }
                }
                let rollback_us = elapsed_us_since(rollback_start);
                stats.rollback_us = stats.rollback_us.saturating_add(rollback_us);
                let local_rollback_weight = contexts
                    .iter()
                    .zip(resolutions.iter())
                    .filter(|(_, resolution)| resolution.needs_rollback || canonical_target_replay)
                    .filter(|(ctx, _)| ctx.proposal_source == PromptLookupProposalSource::Local)
                    .map(|(ctx, _)| ctx.draft_tokens.len().saturating_add(1) as u64)
                    .sum::<u64>();
                let shared_rollback_weight = contexts
                    .iter()
                    .zip(resolutions.iter())
                    .filter(|(_, resolution)| resolution.needs_rollback || canonical_target_replay)
                    .filter(|(ctx, _)| ctx.proposal_source == PromptLookupProposalSource::Shared)
                    .map(|(ctx, _)| ctx.draft_tokens.len().saturating_add(1) as u64)
                    .sum::<u64>();
                let total_rollback_weight =
                    local_rollback_weight.saturating_add(shared_rollback_weight);
                if let Some(local_rollback_us) = rollback_us
                    .saturating_mul(local_rollback_weight)
                    .checked_div(total_rollback_weight)
                {
                    stats.local_source.rollback_us = stats
                        .local_source
                        .rollback_us
                        .saturating_add(local_rollback_us);
                    stats.shared_source.rollback_us = stats
                        .shared_source
                        .rollback_us
                        .saturating_add(rollback_us.saturating_sub(local_rollback_us));
                }
            }

            let mut pending_commits = Vec::with_capacity(contexts.len());
            let mut mtp_shadow_commits = Vec::with_capacity(contexts.len());
            for (ctx, resolution) in contexts.iter().zip(resolutions) {
                let accepted_draft_len = resolution.accepted_draft_len;
                let accepted_verify_input_len = resolution.accepted_verify_input_len;
                let needs_rollback = resolution.needs_rollback;
                let mut tokens = resolution.tokens_to_append;
                if let Some(stop_idx) = tokens
                    .iter()
                    .position(|token| ctx.stop_token_ids.contains(token))
                {
                    tokens.truncate(stop_idx + 1);
                }
                tokens.truncate(ctx.remaining);
                let row_state = row_states.get(&ctx.row_idx).ok_or_else(|| {
                    anyhow!(
                        "fill_prompt_lookup_windows: row {} state disappeared",
                        ctx.row_idx
                    )
                })?;
                anyhow::ensure!(
                    row_state.pending_tokens.is_empty(),
                    "fill_prompt_lookup_windows: row {} pending queue changed during verify",
                    ctx.row_idx
                );
                let slot = self.slots[ctx.row_idx]
                    .as_ref()
                    .expect("prompt lookup context retains its request slot");
                let compact_row = self
                    .cache_rows
                    .iter()
                    .position(|&row| row == ctx.row_idx)
                    .expect("prompt lookup context retains its cache row");
                let cached_len = cache_row_cached_len(
                    self.cache
                        .as_ref()
                        .expect("prompt lookup verification retains main cache"),
                    compact_row,
                )?
                .ok_or_else(|| anyhow!("prompt lookup cache has no sequence offset"))?;
                let expected_cached_len = slot
                    .real_len
                    .saturating_add(tokens.len() as i32)
                    .saturating_sub(1);
                anyhow::ensure!(
                    cached_len == expected_cached_len,
                    "prompt lookup row {} cache offset {cached_len} != emitted real_len {} + pending {} - 1",
                    ctx.row_idx,
                    slot.real_len,
                    tokens.len()
                );
                tracing::debug!(
                    target: "ironmlx::prompt_lookup",
                    row = ctx.row_idx,
                    proposal_source = ?ctx.proposal_source,
                    canonical_shared = require_canonical_shared_full_accept,
                    canonical_target_replay,
                    current_token = ctx.current_token,
                    draft_len = ctx.draft_tokens.len(),
                    accepted_draft_len,
                    accepted_verify_input_len,
                    needs_rollback,
                    real_len = slot.real_len,
                    pending_len = tokens.len(),
                    cached_len,
                    "filled PromptLookup window"
                );
                if capture_accepted_hidden {
                    let hidden_source = accepted_hidden_source.as_ref().ok_or_else(|| {
                        anyhow!(
                            "fill_prompt_lookup_windows: accepted hidden source absent for MTP shadow commit"
                        )
                    })?;
                    let mut input_tokens = Vec::with_capacity(accepted_verify_input_len);
                    input_tokens.push(ctx.current_token);
                    input_tokens.extend_from_slice(
                        &ctx.draft_tokens[..accepted_verify_input_len.saturating_sub(1)],
                    );
                    let input_hidden = slice_hidden_row_prefix(
                        hidden_source,
                        compact_row,
                        accepted_verify_input_len,
                        mlx::StreamOrDevice::default(),
                    )?;
                    let position_ids = self.mtp_position_ids(
                        model,
                        ctx.verify_start_pos,
                        accepted_verify_input_len as i32,
                    )?;
                    mtp_shadow_commits.push(PromptLookupMtpAcceptedInput {
                        row_idx: ctx.row_idx,
                        verify_start_pos: ctx.verify_start_pos,
                        input_tokens,
                        input_hidden,
                        position_ids,
                        canonical_replay: require_canonical_shared_full_accept,
                        mtp_policy_snapshot: require_canonical_shared_full_accept
                            .then_some(ctx.mtp_policy_snapshot.clone())
                            .flatten(),
                    });
                }
                pending_commits.push((ctx.row_idx, tokens));
            }
            if capture_accepted_hidden {
                anyhow::ensure!(
                    mtp_shadow_commits.len() == contexts.len(),
                    "fill_prompt_lookup_windows: MTP shadow commits {} != contexts {}",
                    mtp_shadow_commits.len(),
                    contexts.len()
                );
                if let Err(error) = commit_shadow(
                    PromptLookupMtpShadowAction::Commit(&mtp_shadow_commits),
                    stats,
                ) {
                    if error
                        .downcast_ref::<PromptLookupMtpCanonicalMismatch>()
                        .is_some()
                    {
                        let rollback_start = Instant::now();
                        let cache = self.cache.as_mut().ok_or_else(|| {
                            anyhow!("fill_prompt_lookup_windows: main cache is absent")
                        })?;
                        restore_layer_cache(cache.as_mut_slice(), &base_snapshot)?;
                        let rollback_us = elapsed_us_since(rollback_start);
                        stats.rollback_us = stats.rollback_us.saturating_add(rollback_us);
                        stats.shared_source.rollback_us =
                            stats.shared_source.rollback_us.saturating_add(rollback_us);
                        stats.shared_mtp_canonical_fallbacks =
                            stats.shared_mtp_canonical_fallbacks.saturating_add(1);
                        let _ = commit_shadow(PromptLookupMtpShadowAction::Abort, stats)?;
                        canonical_fallback = true;
                        return Ok(());
                    }
                    return Err(error);
                }
            }
            if let Some((rows, compact_prng)) = prng_commit.take() {
                self.scatter_prng_state_from_rows(&rows, &compact_prng)?;
            }
            for (row_idx, tokens) in pending_commits {
                row_states
                    .get_mut(&row_idx)
                    .expect("prompt lookup row validated before transaction commit")
                    .pending_tokens
                    .extend(tokens);
            }
            Ok(())
        })();

        if let Err(err) = verify_result {
            let abort_result = commit_shadow(PromptLookupMtpShadowAction::Abort, stats);
            let restore_result = self
                .cache
                .as_mut()
                .ok_or_else(|| anyhow!("fill_prompt_lookup_windows: main cache is absent"))
                .and_then(|cache| restore_layer_cache(cache.as_mut_slice(), &base_snapshot));
            return match (restore_result, abort_result) {
                (Ok(()), Ok(_)) => Err(err),
                (Ok(()), Err(abort_err)) => Err(err.context(format!(
                    "prompt lookup MTP transaction rollback failed: {abort_err:#}"
                ))),
                (Err(restore_err), _) => Err(err.context(format!(
                    "prompt lookup verify transaction rollback failed: {restore_err:#}"
                ))),
            };
        }
        if canonical_fallback {
            Ok(PromptLookupFillOutcome::MtpCanonicalFallback)
        } else if attempted_verify {
            Ok(PromptLookupFillOutcome::Filled {
                canonical_shared_full_accept: require_canonical_shared_full_accept,
            })
        } else {
            Ok(PromptLookupFillOutcome::NoVerify)
        }
    }

    fn make_empty_batched_mtp_cache_for_row_indices(
        model: &M,
        mtp: &M::MtpHead,
        row_states: &HashMap<usize, SchedulerMtpRowState>,
        row_indices: &[usize],
    ) -> Result<MtpCache>
    where
        M: MtpSpeculativeModel,
    {
        anyhow::ensure!(
            !row_indices.is_empty(),
            "make_empty_batched_mtp_cache_for_row_indices: rows cannot be empty"
        );
        let mut cap = 0_i32;
        let mut dtype = None;
        for &row_idx in row_indices {
            let row_state = row_states.get(&row_idx).ok_or_else(|| {
                anyhow!("make_empty_batched_mtp_cache_for_row_indices: row {row_idx} state absent")
            })?;
            let layer = row_state.mtp_cache.layer(0);
            cap = cap.max(layer.cap());
            if let Some(expected) = dtype {
                anyhow::ensure!(
                    expected == layer.dtype(),
                    "make_empty_batched_mtp_cache_for_row_indices: dtype mismatch {:?} != {:?}",
                    expected,
                    layer.dtype()
                );
            } else {
                dtype = Some(layer.dtype());
            }
        }
        let dtype = dtype
            .ok_or_else(|| anyhow!("make_empty_batched_mtp_cache_for_row_indices: dtype absent"))?;
        model.make_mtp_cache(mtp, row_indices.len() as i32, cap, dtype)
    }

    fn make_batched_mtp_cache_from_row_indices(
        model: &M,
        mtp: &M::MtpHead,
        row_states: &HashMap<usize, SchedulerMtpRowState>,
        row_indices: &[usize],
    ) -> Result<MtpCache>
    where
        M: MtpSpeculativeModel,
    {
        let mut cache = Self::make_empty_batched_mtp_cache_for_row_indices(
            model,
            mtp,
            row_states,
            row_indices,
        )?;
        for (compact_idx, &row_idx) in row_indices.iter().enumerate() {
            let row_state = row_states.get(&row_idx).ok_or_else(|| {
                anyhow!("make_batched_mtp_cache_from_row_indices: row {row_idx} state absent")
            })?;
            cache.adopt_row_from(&row_state.mtp_cache, compact_idx, 0)?;
        }
        Ok(cache)
    }

    fn restore_prompt_lookup_mtp_canonical_rows(
        mtp_state: &mut SchedulerMtpState,
        snapshots: &[PromptLookupMtpCanonicalRowSnapshot],
    ) -> Result<()> {
        for snapshot in snapshots {
            let row = mtp_state.rows.get_mut(&snapshot.row_idx).ok_or_else(|| {
                anyhow!(
                    "restore_prompt_lookup_mtp_canonical_rows: row {} disappeared",
                    snapshot.row_idx
                )
            })?;
            row.mtp_cache.restore(&snapshot.mtp_cache)?;
            row.last_hidden = snapshot.last_hidden.clone();
            row.deferred_tail_commit = snapshot.deferred_tail_commit.clone();
            row.adaptive_draft_tokens = snapshot.adaptive_draft_tokens;
            row.draft_policy = snapshot.draft_policy.clone();
        }
        Ok(())
    }

    fn abort_prompt_lookup_mtp_canonical(
        mtp_state: &mut SchedulerMtpState,
        transaction: PromptLookupMtpCanonicalTransaction,
    ) -> Result<()> {
        Self::restore_prompt_lookup_mtp_canonical_rows(mtp_state, &transaction.snapshots)
    }

    fn prompt_lookup_mtp_position_ids(model: &M, start_pos: i32, len: i32) -> Result<Array>
    where
        M: MtpSpeculativeModel,
    {
        if model.requires_position_ids() {
            build_position_ids(start_pos, len)
        } else {
            build_position_ids(0, 1)
        }
    }

    fn prepare_prompt_lookup_mtp_canonical(
        model: &M,
        mtp: &M::MtpHead,
        mtp_state: &mut SchedulerMtpState,
        inputs: &[PromptLookupMtpDraftInput],
        stats: &mut PromptLookupStats,
        kv_state: MtpDraftPolicyKvState,
    ) -> Result<(PromptLookupMtpCanonicalTransaction, Vec<Vec<Array>>)>
    where
        M: MtpSpeculativeModel,
    {
        anyhow::ensure!(
            !inputs.is_empty(),
            "prepare_prompt_lookup_mtp_canonical: inputs cannot be empty"
        );
        let mut snapshots = Vec::with_capacity(inputs.len());
        let mut seen_rows = HashSet::with_capacity(inputs.len());
        for input in inputs {
            anyhow::ensure!(
                seen_rows.insert(input.row_idx),
                "prepare_prompt_lookup_mtp_canonical: duplicate row {}",
                input.row_idx
            );
            anyhow::ensure!(
                !input.expected_draft_tokens.is_empty(),
                "prepare_prompt_lookup_mtp_canonical: row {} has no expected drafts",
                input.row_idx
            );
            let row = mtp_state.rows.get(&input.row_idx).ok_or_else(|| {
                anyhow!(
                    "prepare_prompt_lookup_mtp_canonical: row {} MTP state absent",
                    input.row_idx
                )
            })?;
            snapshots.push(PromptLookupMtpCanonicalRowSnapshot {
                row_idx: input.row_idx,
                mtp_cache: row.mtp_cache.snapshot(),
                last_hidden: row.last_hidden.clone(),
                deferred_tail_commit: row.deferred_tail_commit.clone(),
                adaptive_draft_tokens: row.adaptive_draft_tokens,
                draft_policy: row.draft_policy.clone(),
            });
        }

        let mtp_stats_before = mtp_state.stats.clone();
        let prompt_stats_before = *stats;
        let prepare_result =
            (|| -> Result<(Vec<MtpBatchedFillContext>, MtpBatchedTailCommitMode)> {
                let mut contexts = Vec::with_capacity(inputs.len());
                for input in inputs {
                    let row = mtp_state.rows.get_mut(&input.row_idx).ok_or_else(|| {
                        anyhow!(
                            "prepare_prompt_lookup_mtp_canonical: row {} disappeared",
                            input.row_idx
                        )
                    })?;
                    let input_token: Array =
                        (&[input.current_token][..], &[1_i32, 1_i32][..]).try_into()?;
                    contexts.push(MtpBatchedFillContext {
                        row_idx: input.row_idx,
                        current_token: input.current_token,
                        stop_token_ids: Vec::new(),
                        remaining: input.expected_draft_tokens.len().saturating_add(1),
                        draft_budget: input.expected_draft_tokens.len(),
                        verify_start_pos: input.verify_start_pos,
                        input_hidden: row.last_hidden.clone(),
                        input_token,
                        draft_tokens: Vec::with_capacity(input.expected_draft_tokens.len()),
                        mtp_cache_snapshot: row.mtp_cache.snapshot(),
                        deferred_tail_commit: row.deferred_tail_commit.take(),
                    });
                }

                let use_row_cache = contexts
                    .iter()
                    .any(|ctx| ctx.verify_start_pos >= MTP_BATCH_DRAFT_ROW_CACHE_MIN_OFFSET)
                    || contexts
                        .iter()
                        .any(|ctx| ctx.deferred_tail_commit.is_some());
                if use_row_cache {
                    for ctx in &mut contexts {
                        let row = mtp_state.rows.get_mut(&ctx.row_idx).ok_or_else(|| {
                            anyhow!(
                                "prepare_prompt_lookup_mtp_canonical: row {} disappeared",
                                ctx.row_idx
                            )
                        })?;
                        let mut input_hidden = ctx.input_hidden.clone();
                        let mut input_token = ctx.input_token.clone();
                        let mut produced = 0_usize;
                        if let Some(tail) = ctx.deferred_tail_commit.as_ref() {
                            let tail_token: Array =
                                (&[tail.token][..], &[1_i32, 1_i32][..]).try_into()?;
                            let token_arr = mlx::ops::shape::concatenate_on(
                                &[&tail_token, &input_token],
                                1,
                                mlx::StreamOrDevice::default(),
                            )?;
                            let current_position_ids = Self::prompt_lookup_mtp_position_ids(
                                model,
                                ctx.verify_start_pos,
                                1,
                            )?;
                            let position_ids = concatenate_position_id_steps(
                                &tail.position_ids,
                                &current_position_ids,
                                mlx::StreamOrDevice::default(),
                            )?;
                            let hidden = mlx::ops::shape::concatenate_on(
                                &[&tail.prev_hidden, &input_hidden],
                                1,
                                mlx::StreamOrDevice::default(),
                            )?;
                            let draft_started = Instant::now();
                            let output = model.mtp_forward_on(
                                mtp,
                                &hidden,
                                &token_arr,
                                &position_ids,
                                None,
                                Some(&mut row.mtp_cache),
                                mlx::StreamOrDevice::default(),
                            )?;
                            add_elapsed_us(&mut mtp_state.stats.draft_forward_us, draft_started);
                            let sample_started = Instant::now();
                            let sampled = mlx::ops::reduction::argmax(&output.logits, -1, false)?;
                            let next_token = mlx::ops::indexing::slice_strided_on(
                                &sampled,
                                &[0_i32, 1_i32][..],
                                &[1_i32, 2_i32][..],
                                &[1_i32, 1_i32][..],
                                mlx::StreamOrDevice::default(),
                            )?;
                            add_elapsed_us(&mut mtp_state.stats.sampling_us, sample_started);
                            ctx.draft_tokens.push(next_token.clone());
                            input_token = next_token;
                            input_hidden = slice_hidden_position(&output.hidden_states, 1)?;
                            produced = 1;
                        }
                        for offset in produced..ctx.draft_budget {
                            let position_ids = Self::prompt_lookup_mtp_position_ids(
                                model,
                                ctx.verify_start_pos + offset as i32,
                                1,
                            )?;
                            let draft_started = Instant::now();
                            let output = model.mtp_forward_on(
                                mtp,
                                &input_hidden,
                                &input_token,
                                &position_ids,
                                None,
                                Some(&mut row.mtp_cache),
                                mlx::StreamOrDevice::default(),
                            )?;
                            add_elapsed_us(&mut mtp_state.stats.draft_forward_us, draft_started);
                            let sample_started = Instant::now();
                            let next_token =
                                mlx::ops::reduction::argmax(&output.logits, -1, false)?;
                            add_elapsed_us(&mut mtp_state.stats.sampling_us, sample_started);
                            ctx.draft_tokens.push(next_token.clone());
                            input_token = next_token;
                            input_hidden = output.hidden_states;
                        }
                        ctx.input_token = input_token;
                        ctx.input_hidden = input_hidden;
                    }
                    Ok((contexts, MtpBatchedTailCommitMode::PerRowCache))
                } else {
                    let max_draft_budget = contexts
                        .iter()
                        .map(|ctx| ctx.draft_budget)
                        .max()
                        .unwrap_or(0);
                    let mut active_indices = Vec::<usize>::new();
                    let mut active_mtp_cache: Option<MtpCache> = None;
                    for offset in 0..max_draft_budget {
                        let next_active_indices = contexts
                            .iter()
                            .enumerate()
                            .filter_map(|(idx, ctx)| (offset < ctx.draft_budget).then_some(idx))
                            .collect::<Vec<_>>();
                        if next_active_indices.is_empty() {
                            continue;
                        }
                        if active_mtp_cache.is_none() {
                            let rows = next_active_indices
                                .iter()
                                .map(|&idx| contexts[idx].row_idx)
                                .collect::<Vec<_>>();
                            active_mtp_cache = Some(Self::make_batched_mtp_cache_from_row_indices(
                                model,
                                mtp,
                                &mtp_state.rows,
                                &rows,
                            )?);
                            active_indices = next_active_indices.clone();
                        } else if active_indices != next_active_indices {
                            let old_cache = active_mtp_cache
                                .take()
                                .expect("active MTP cache exists above");
                            for (old_compact_idx, &ctx_idx) in active_indices.iter().enumerate() {
                                if !next_active_indices.contains(&ctx_idx) {
                                    let row_idx = contexts[ctx_idx].row_idx;
                                    mtp_state
                                    .rows
                                    .get_mut(&row_idx)
                                    .ok_or_else(|| {
                                        anyhow!(
                                            "prepare_prompt_lookup_mtp_canonical: inactive row {row_idx} disappeared"
                                        )
                                    })?
                                    .mtp_cache
                                    .adopt_row_from(&old_cache, 0, old_compact_idx)?;
                                }
                            }
                            let rows = next_active_indices
                                .iter()
                                .map(|&idx| contexts[idx].row_idx)
                                .collect::<Vec<_>>();
                            let mut new_cache = Self::make_empty_batched_mtp_cache_for_row_indices(
                                model,
                                mtp,
                                &mtp_state.rows,
                                &rows,
                            )?;
                            for (new_compact_idx, &ctx_idx) in
                                next_active_indices.iter().enumerate()
                            {
                                if let Some(old_compact_idx) =
                                    active_indices.iter().position(|&idx| idx == ctx_idx)
                                {
                                    new_cache.adopt_row_from(
                                        &old_cache,
                                        new_compact_idx,
                                        old_compact_idx,
                                    )?;
                                } else {
                                    let row = mtp_state.rows.get(&contexts[ctx_idx].row_idx).ok_or_else(
                                    || {
                                        anyhow!(
                                            "prepare_prompt_lookup_mtp_canonical: active row disappeared"
                                        )
                                    },
                                )?;
                                    new_cache.adopt_row_from(&row.mtp_cache, new_compact_idx, 0)?;
                                }
                            }
                            active_mtp_cache = Some(new_cache);
                            active_indices = next_active_indices.clone();
                        }

                        let cache = active_mtp_cache.as_mut().ok_or_else(|| {
                            anyhow!("prepare_prompt_lookup_mtp_canonical: active cache absent")
                        })?;
                        let token_rows = active_indices
                            .iter()
                            .map(|&idx| &contexts[idx].input_token)
                            .collect::<Vec<_>>();
                        let token_arr = mlx::ops::shape::concatenate_on(
                            &token_rows,
                            0,
                            mlx::StreamOrDevice::default(),
                        )?;
                        let hidden_rows = active_indices
                            .iter()
                            .map(|&idx| &contexts[idx].input_hidden)
                            .collect::<Vec<_>>();
                        let hidden = mlx::ops::shape::concatenate_on(
                            &hidden_rows,
                            0,
                            mlx::StreamOrDevice::default(),
                        )?;
                        let positions = active_indices
                            .iter()
                            .map(|&idx| contexts[idx].verify_start_pos + offset as i32)
                            .collect::<Vec<_>>();
                        let position_ids = if model.requires_position_ids() {
                            build_decode_position_ids(&positions)?
                        } else {
                            build_position_ids(0, 1)?
                        };
                        let draft_started = Instant::now();
                        let output = model.mtp_forward_on(
                            mtp,
                            &hidden,
                            &token_arr,
                            &position_ids,
                            None,
                            Some(cache),
                            mlx::StreamOrDevice::default(),
                        )?;
                        add_elapsed_us(&mut mtp_state.stats.draft_forward_us, draft_started);
                        let sample_started = Instant::now();
                        let sampled = mlx::ops::reduction::argmax(&output.logits, -1, false)?;
                        add_elapsed_us(&mut mtp_state.stats.sampling_us, sample_started);
                        anyhow::ensure!(
                            sampled.size() == active_indices.len(),
                            "prepare_prompt_lookup_mtp_canonical: sampled {} tokens for {} rows",
                            sampled.size(),
                            active_indices.len()
                        );
                        for (compact_idx, &ctx_idx) in active_indices.iter().enumerate() {
                            let next_token = mlx::ops::indexing::slice_strided_on(
                                &sampled,
                                &[compact_idx as i32, 0_i32][..],
                                &[compact_idx as i32 + 1, 1_i32][..],
                                &[1_i32, 1_i32][..],
                                mlx::StreamOrDevice::default(),
                            )?;
                            let ctx = &mut contexts[ctx_idx];
                            ctx.draft_tokens.push(next_token.clone());
                            ctx.input_token = next_token;
                            ctx.input_hidden = slice_hidden_row_position(
                                &output.hidden_states,
                                compact_idx,
                                0,
                                mlx::StreamOrDevice::default(),
                            )?;
                        }
                    }
                    if let Some(final_cache) = active_mtp_cache {
                        for (compact_idx, &ctx_idx) in active_indices.iter().enumerate() {
                            let row_idx = contexts[ctx_idx].row_idx;
                            mtp_state
                            .rows
                            .get_mut(&row_idx)
                            .ok_or_else(|| {
                                anyhow!(
                                    "prepare_prompt_lookup_mtp_canonical: final row {row_idx} disappeared"
                                )
                            })?
                            .mtp_cache
                            .adopt_row_from(&final_cache, 0, compact_idx)?;
                        }
                    }
                    Ok((contexts, MtpBatchedTailCommitMode::BatchedFromRowCaches))
                }
            })();

        let (contexts, tail_commit_mode) = match prepare_result {
            Ok(result) => result,
            Err(error) => {
                let restore_result =
                    Self::restore_prompt_lookup_mtp_canonical_rows(mtp_state, &snapshots);
                return match restore_result {
                    Ok(()) => Err(error),
                    Err(restore_error) => Err(error.context(format!(
                        "canonical MTP prepare failed and rollback failed: {restore_error:#}"
                    ))),
                };
            }
        };

        let mut samples = Vec::new();
        for (ctx, input) in contexts.iter().zip(inputs.iter()) {
            anyhow::ensure!(
                ctx.draft_tokens.len() == input.expected_draft_tokens.len(),
                "prepare_prompt_lookup_mtp_canonical: row {} sampled {} drafts != expected {}",
                ctx.row_idx,
                ctx.draft_tokens.len(),
                input.expected_draft_tokens.len()
            );
            for (depth, (sample, &expected)) in ctx
                .draft_tokens
                .iter()
                .zip(input.expected_draft_tokens.iter())
                .enumerate()
            {
                samples.push((ctx.row_idx, depth, expected, sample));
            }
        }
        let sample_arrays = samples
            .iter()
            .map(|(_, _, _, sample)| *sample)
            .collect::<Vec<_>>();
        let validation_started = Instant::now();
        let packed =
            mlx::ops::shape::concatenate_on(&sample_arrays, 0, mlx::StreamOrDevice::default())?;
        let actual: Vec<u32> = packed.to_vec()?;
        stats.shared_mtp_canonical_validation_windows = stats
            .shared_mtp_canonical_validation_windows
            .saturating_add(inputs.len() as u64);
        stats.shared_mtp_canonical_validation_tokens = stats
            .shared_mtp_canonical_validation_tokens
            .saturating_add(samples.len() as u64);
        add_elapsed_us(
            &mut stats.shared_mtp_canonical_validation_us,
            validation_started,
        );
        for ((row_idx, depth, expected, _), actual) in samples.iter().zip(actual) {
            if *expected != actual {
                stats.shared_mtp_canonical_validation_mismatches = stats
                    .shared_mtp_canonical_validation_mismatches
                    .saturating_add(1);
                let restore_result =
                    Self::restore_prompt_lookup_mtp_canonical_rows(mtp_state, &snapshots);
                return match restore_result {
                    Ok(()) => Err(anyhow::Error::new(PromptLookupMtpCanonicalMismatch {
                        row_idx: *row_idx,
                        depth: *depth,
                    })),
                    Err(restore_error) => Err(anyhow!(
                        "canonical MTP mismatch rollback failed for row {row_idx}: {restore_error:#}"
                    )),
                };
            }
        }
        let device_drafts = contexts
            .iter()
            .map(|ctx| ctx.draft_tokens.clone())
            .collect::<Vec<_>>();
        Ok((
            PromptLookupMtpCanonicalTransaction {
                contexts,
                tail_commit_mode,
                snapshots,
                mtp_stats_before,
                prompt_stats_before,
                kv_state,
            },
            device_drafts,
        ))
    }

    fn commit_prompt_lookup_mtp_canonical(
        model: &M,
        mtp: &M::MtpHead,
        mtp_state: &mut SchedulerMtpState,
        transaction: PromptLookupMtpCanonicalTransaction,
        accepted: &[PromptLookupMtpAcceptedInput],
        stats: &mut PromptLookupStats,
    ) -> Result<()>
    where
        M: MtpSpeculativeModel,
    {
        let commit_started = Instant::now();
        let commit_result = (|| -> Result<()> {
            anyhow::ensure!(
                accepted.len() == transaction.contexts.len(),
                "commit_prompt_lookup_mtp_canonical: accepted rows {} != prepared rows {}",
                accepted.len(),
                transaction.contexts.len()
            );
            let mut tail_commits = Vec::with_capacity(accepted.len());
            for (input, ctx) in accepted.iter().zip(transaction.contexts.iter()) {
                anyhow::ensure!(
                    input.canonical_replay && input.row_idx == ctx.row_idx,
                    "commit_prompt_lookup_mtp_canonical: row ordering or mode changed"
                );
                anyhow::ensure!(
                    input.input_tokens.len() == ctx.draft_tokens.len().saturating_add(1),
                    "commit_prompt_lookup_mtp_canonical: row {} accepted {} inputs != prepared {}",
                    input.row_idx,
                    input.input_tokens.len(),
                    ctx.draft_tokens.len().saturating_add(1)
                );
                let tail_idx = input.input_tokens.len() - 1;
                let tail_prev_hidden = slice_hidden_row_position(
                    &input.input_hidden,
                    0,
                    tail_idx - 1,
                    mlx::StreamOrDevice::default(),
                )?;
                let tail_position_ids = slice_position_ids_row_position(
                    &input.position_ids,
                    0,
                    tail_idx,
                    mlx::StreamOrDevice::default(),
                )?;
                tail_commits.push((
                    input.row_idx,
                    input.input_tokens[tail_idx],
                    tail_prev_hidden,
                    tail_position_ids,
                ));
            }

            match transaction.tail_commit_mode {
                MtpBatchedTailCommitMode::BatchedFromRowCaches => {
                    let rows = tail_commits
                        .iter()
                        .map(|(row_idx, _, _, _)| *row_idx)
                        .collect::<Vec<_>>();
                    let mut cache = Self::make_batched_mtp_cache_from_row_indices(
                        model,
                        mtp,
                        &mtp_state.rows,
                        &rows,
                    )?;
                    let tokens = tail_commits
                        .iter()
                        .map(|(_, token, _, _)| *token)
                        .collect::<Vec<_>>();
                    let token_arr: Array =
                        (&tokens[..], &[tokens.len() as i32, 1_i32][..]).try_into()?;
                    let hidden_rows = tail_commits
                        .iter()
                        .map(|(_, _, hidden, _)| hidden)
                        .collect::<Vec<_>>();
                    let hidden = mlx::ops::shape::concatenate_on(
                        &hidden_rows,
                        0,
                        mlx::StreamOrDevice::default(),
                    )?;
                    let position_ids = if model.requires_position_ids() {
                        let rows = tail_commits
                            .iter()
                            .map(|(_, _, _, position_ids)| position_ids)
                            .collect::<Vec<_>>();
                        mlx::ops::shape::concatenate_on(&rows, 1, mlx::StreamOrDevice::default())?
                    } else {
                        build_position_ids(0, 1)?
                    };
                    let cache_commit_started = Instant::now();
                    let hidden = model.mtp_forward_hidden_on(
                        mtp,
                        &hidden,
                        &token_arr,
                        &position_ids,
                        None,
                        Some(&mut cache),
                        mlx::StreamOrDevice::default(),
                    )?;
                    mlx::transforms::eval(&[&hidden])?;
                    add_mtp_decode_cache_commit_us(&mut mtp_state.stats, cache_commit_started);
                    for (compact_idx, (row_idx, _, _, _)) in tail_commits.iter().enumerate() {
                        let row = mtp_state.rows.get_mut(row_idx).ok_or_else(|| {
                            anyhow!("commit_prompt_lookup_mtp_canonical: row {row_idx} disappeared")
                        })?;
                        row.mtp_cache.adopt_row_from(&cache, 0, compact_idx)?;
                        row.deferred_tail_commit = None;
                    }
                }
                MtpBatchedTailCommitMode::PerRowCache => {
                    for (row_idx, token, prev_hidden, position_ids) in &tail_commits {
                        let row = mtp_state.rows.get_mut(row_idx).ok_or_else(|| {
                            anyhow!("commit_prompt_lookup_mtp_canonical: row {row_idx} disappeared")
                        })?;
                        row.deferred_tail_commit = Some(MtpDeferredTailCommit {
                            token: *token,
                            prev_hidden: prev_hidden.clone(),
                            position_ids: position_ids.clone(),
                        });
                    }
                }
            }

            let mtp_delta = mtp_state
                .stats
                .saturating_delta_since(&transaction.mtp_stats_before);
            let prompt_delta = stats.saturating_delta_since(transaction.prompt_stats_before);
            let divisor = accepted.len() as u64;
            for (input, ctx) in accepted.iter().zip(transaction.contexts.iter()) {
                let row = mtp_state.rows.get_mut(&input.row_idx).ok_or_else(|| {
                    anyhow!(
                        "commit_prompt_lookup_mtp_canonical: row {} disappeared after tail commit",
                        input.row_idx
                    )
                })?;
                row.last_hidden = slice_hidden_row_position(
                    &input.input_hidden,
                    0,
                    input.input_tokens.len() - 1,
                    mlx::StreamOrDevice::default(),
                )?;
                let attempted = ctx.draft_tokens.len();
                mtp_state.stats.windows = mtp_state.stats.windows.saturating_add(1);
                mtp_state.stats.drafted_tokens =
                    mtp_state.stats.drafted_tokens.saturating_add(attempted);
                mtp_state.stats.accepted_draft_tokens = mtp_state
                    .stats
                    .accepted_draft_tokens
                    .saturating_add(attempted);
                mtp_state
                    .stats
                    .record_window_acceptance(attempted, attempted);
                let change = row.draft_policy.observe_window(MtpDraftPolicyWindow {
                    attempted_draft_tokens: attempted,
                    accepted_draft_tokens: attempted,
                    committed_tokens: input.input_tokens.len(),
                    total_us: 0,
                    context_tokens: ctx.verify_start_pos.max(0) as usize + 1,
                    batch_width: accepted.len(),
                    kv_state: transaction.kv_state,
                    draft_forward_us: mtp_delta.draft_forward_us / divisor,
                    verify_forward_us: prompt_delta.verify_forward_us / divisor,
                    projection_us: prompt_delta.projection_us / divisor,
                    sampling_us: mtp_delta.sampling_us / divisor,
                    verify_accept_host_sync_us: prompt_delta.verify_accept_host_sync_us / divisor,
                    main_rollback_us: prompt_delta.rollback_us / divisor,
                    mtp_cache_commit_us: mtp_delta.mtp_cache_commit_us / divisor,
                    mtp_prefill_cache_commit_us: mtp_delta.mtp_prefill_cache_commit_us / divisor,
                    mtp_decode_cache_commit_us: mtp_delta.mtp_decode_cache_commit_us / divisor,
                    mtp_cache_restore_us: mtp_delta.mtp_cache_restore_us / divisor,
                });
                if change.reduced {
                    mtp_state.stats.draft_budget_reductions =
                        mtp_state.stats.draft_budget_reductions.saturating_add(1);
                } else if change.increased {
                    mtp_state.stats.draft_budget_increases =
                        mtp_state.stats.draft_budget_increases.saturating_add(1);
                }
                row.adaptive_draft_tokens = row
                    .draft_policy
                    .current_budget()
                    .min(mtp_state.cfg.max_draft_tokens);
            }
            Ok(())
        })();

        if let Err(error) = commit_result {
            let restore_result =
                Self::restore_prompt_lookup_mtp_canonical_rows(mtp_state, &transaction.snapshots);
            return match restore_result {
                Ok(()) => Err(error),
                Err(restore_error) => Err(error.context(format!(
                    "canonical MTP commit failed and rollback failed: {restore_error:#}"
                ))),
            };
        }
        stats.mtp_shadow_commit_windows = stats.mtp_shadow_commit_windows.saturating_add(1);
        stats.mtp_shadow_commit_tokens = stats.mtp_shadow_commit_tokens.saturating_add(
            accepted
                .iter()
                .map(|input| input.input_tokens.len() as u64)
                .sum::<u64>(),
        );
        add_elapsed_us(&mut stats.mtp_shadow_commit_us, commit_started);
        Ok(())
    }

    fn commit_prompt_lookup_mtp_shadow(
        model: &M,
        mtp: &M::MtpHead,
        mtp_state: &mut SchedulerMtpState,
        accepted: &[PromptLookupMtpAcceptedInput],
        stats: &mut PromptLookupStats,
    ) -> Result<()>
    where
        M: MtpSpeculativeModel,
    {
        anyhow::ensure!(
            !accepted.is_empty(),
            "commit_prompt_lookup_mtp_shadow: accepted rows cannot be empty"
        );
        let mut snapshots = Vec::with_capacity(accepted.len());
        let mut seen_rows = HashSet::with_capacity(accepted.len());
        for input in accepted {
            anyhow::ensure!(
                seen_rows.insert(input.row_idx),
                "commit_prompt_lookup_mtp_shadow: duplicate row {}",
                input.row_idx
            );
            let row = mtp_state.rows.get(&input.row_idx).ok_or_else(|| {
                anyhow!(
                    "commit_prompt_lookup_mtp_shadow: row {} MTP state absent",
                    input.row_idx
                )
            })?;
            snapshots.push((
                input.row_idx,
                row.mtp_cache.snapshot(),
                row.last_hidden.clone(),
                row.deferred_tail_commit.clone(),
                row.adaptive_draft_tokens,
                row.draft_policy.clone(),
            ));
        }

        let commit_started = Instant::now();
        let mut committed_tokens = 0_u64;
        let mut canonical_proposal_samples = Vec::<(usize, usize, u32, Array)>::new();
        let mut canonical_actual_tokens: Option<Vec<u32>> = None;
        let commit_result = (|| -> Result<()> {
            let canonical_replay = accepted[0].canonical_replay;
            anyhow::ensure!(
                accepted
                    .iter()
                    .all(|input| input.canonical_replay == canonical_replay),
                "commit_prompt_lookup_mtp_shadow: canonical and generic rows cannot share one transaction"
            );
            if !canonical_replay {
                let deferred = accepted
                    .iter()
                    .filter_map(|input| {
                        mtp_state
                            .rows
                            .get(&input.row_idx)
                            .and_then(|row| row.deferred_tail_commit.clone())
                            .map(|tail| (input.row_idx, tail))
                    })
                    .collect::<Vec<_>>();
                if !deferred.is_empty() {
                    let row_indices = deferred.iter().map(|(row, _)| *row).collect::<Vec<_>>();
                    let mut cache = Self::make_batched_mtp_cache_from_row_indices(
                        model,
                        mtp,
                        &mtp_state.rows,
                        &row_indices,
                    )?;
                    let tokens = deferred
                        .iter()
                        .map(|(_, tail)| tail.token)
                        .collect::<Vec<_>>();
                    let token_arr: Array =
                        (&tokens[..], &[tokens.len() as i32, 1_i32][..]).try_into()?;
                    let hidden_rows = deferred
                        .iter()
                        .map(|(_, tail)| &tail.prev_hidden)
                        .collect::<Vec<_>>();
                    let hidden = mlx::ops::shape::concatenate_on(
                        &hidden_rows,
                        0,
                        mlx::StreamOrDevice::default(),
                    )?;
                    let position_ids = if model.requires_position_ids() {
                        let position_rows = deferred
                            .iter()
                            .map(|(_, tail)| &tail.position_ids)
                            .collect::<Vec<_>>();
                        mlx::ops::shape::concatenate_on(
                            &position_rows,
                            1,
                            mlx::StreamOrDevice::default(),
                        )?
                    } else {
                        deferred[0].1.position_ids.clone()
                    };
                    let mtp_hidden = model.mtp_forward_hidden_on(
                        mtp,
                        &hidden,
                        &token_arr,
                        &position_ids,
                        None,
                        Some(&mut cache),
                        mlx::StreamOrDevice::default(),
                    )?;
                    mlx::transforms::eval(&[&mtp_hidden])?;
                    for (compact_idx, &row_idx) in row_indices.iter().enumerate() {
                        let row = mtp_state.rows.get_mut(&row_idx).ok_or_else(|| {
                            anyhow!(
                                "commit_prompt_lookup_mtp_shadow: generic deferred row {row_idx} disappeared"
                            )
                        })?;
                        row.mtp_cache.adopt_row_from(&cache, 0, compact_idx)?;
                        row.deferred_tail_commit = None;
                    }
                    committed_tokens = committed_tokens.saturating_add(tokens.len() as u64);
                }

                for input in accepted {
                    anyhow::ensure!(
                        !input.input_tokens.is_empty(),
                        "commit_prompt_lookup_mtp_shadow: row {} generic accepted input cannot be empty",
                        input.row_idx
                    );
                    let row = mtp_state.rows.get_mut(&input.row_idx).ok_or_else(|| {
                        anyhow!(
                            "commit_prompt_lookup_mtp_shadow: generic row {} disappeared",
                            input.row_idx
                        )
                    })?;
                    let prev_hidden = row.last_hidden.clone();
                    commit_mtp_cache_hidden_prefix(
                        model,
                        mtp,
                        &mut row.mtp_cache,
                        &prev_hidden,
                        &input.input_tokens,
                        &input.input_hidden,
                        &input.position_ids,
                        mlx::StreamOrDevice::default(),
                    )?;
                    row.last_hidden = slice_hidden_row_position(
                        &input.input_hidden,
                        0,
                        input.input_tokens.len() - 1,
                        mlx::StreamOrDevice::default(),
                    )?;
                    row.deferred_tail_commit = None;
                    committed_tokens =
                        committed_tokens.saturating_add(input.input_tokens.len() as u64);
                }
                return Ok(());
            }
            let canonical_validation_started = Instant::now();

            for input in accepted {
                anyhow::ensure!(
                    input.input_tokens.len() >= 2,
                    "commit_prompt_lookup_mtp_shadow: row {} canonical input must contain current plus at least one draft token",
                    input.row_idx
                );
            }

            let use_row_cache = accepted
                .iter()
                .any(|input| input.verify_start_pos >= MTP_BATCH_DRAFT_ROW_CACHE_MIN_OFFSET)
                || accepted.iter().any(|input| {
                    mtp_state
                        .rows
                        .get(&input.row_idx)
                        .is_some_and(|row| row.deferred_tail_commit.is_some())
                });

            if use_row_cache {
                for input in accepted {
                    let row = mtp_state.rows.get_mut(&input.row_idx).ok_or_else(|| {
                        anyhow!(
                            "commit_prompt_lookup_mtp_shadow: row {} disappeared",
                            input.row_idx
                        )
                    })?;
                    let draft_len = input.input_tokens.len() - 1;
                    let mut input_hidden = row.last_hidden.clone();
                    let mut produced = 0_usize;

                    if let Some(tail) = row.deferred_tail_commit.take() {
                        let tokens = [tail.token, input.input_tokens[0]];
                        let token_arr: Array = (&tokens[..], &[1_i32, 2_i32][..]).try_into()?;
                        let current_position_ids = slice_position_ids_row_position(
                            &input.position_ids,
                            0,
                            0,
                            mlx::StreamOrDevice::default(),
                        )?;
                        let position_ids = concatenate_position_id_steps(
                            &tail.position_ids,
                            &current_position_ids,
                            mlx::StreamOrDevice::default(),
                        )?;
                        let hidden = mlx::ops::shape::concatenate_on(
                            &[&tail.prev_hidden, &input_hidden],
                            1,
                            mlx::StreamOrDevice::default(),
                        )?;
                        let output = model.mtp_forward_on(
                            mtp,
                            &hidden,
                            &token_arr,
                            &position_ids,
                            None,
                            Some(&mut row.mtp_cache),
                            mlx::StreamOrDevice::default(),
                        )?;
                        let sampled = mlx::ops::reduction::argmax(&output.logits, -1, false)?;
                        let next_token = mlx::ops::indexing::slice_strided_on(
                            &sampled,
                            &[0_i32, 1_i32][..],
                            &[1_i32, 2_i32][..],
                            &[1_i32, 1_i32][..],
                            mlx::StreamOrDevice::default(),
                        )?;
                        canonical_proposal_samples.push((
                            input.row_idx,
                            0,
                            input.input_tokens[1],
                            next_token,
                        ));
                        input_hidden = slice_hidden_row_position(
                            &output.hidden_states,
                            0,
                            1,
                            mlx::StreamOrDevice::default(),
                        )?;
                        produced = 1;
                        committed_tokens = committed_tokens.saturating_add(1);
                    }

                    for depth in produced..draft_len {
                        let token_arr: Array =
                            (&input.input_tokens[depth..depth + 1], &[1_i32, 1_i32][..])
                                .try_into()?;
                        let position_ids = slice_position_ids_row_position(
                            &input.position_ids,
                            0,
                            depth,
                            mlx::StreamOrDevice::default(),
                        )?;
                        let output = model.mtp_forward_on(
                            mtp,
                            &input_hidden,
                            &token_arr,
                            &position_ids,
                            None,
                            Some(&mut row.mtp_cache),
                            mlx::StreamOrDevice::default(),
                        )?;
                        let sampled = mlx::ops::reduction::argmax(&output.logits, -1, false)?;
                        canonical_proposal_samples.push((
                            input.row_idx,
                            depth,
                            input.input_tokens[depth + 1],
                            sampled,
                        ));
                        input_hidden = output.hidden_states;
                    }
                    mlx::transforms::eval(&[&input_hidden])?;

                    let tail_idx = draft_len;
                    let tail_prev_hidden = slice_hidden_row_position(
                        &input.input_hidden,
                        0,
                        tail_idx - 1,
                        mlx::StreamOrDevice::default(),
                    )?;
                    let tail_position_ids = slice_position_ids_row_position(
                        &input.position_ids,
                        0,
                        tail_idx,
                        mlx::StreamOrDevice::default(),
                    )?;
                    row.deferred_tail_commit = Some(MtpDeferredTailCommit {
                        token: input.input_tokens[tail_idx],
                        prev_hidden: tail_prev_hidden,
                        position_ids: tail_position_ids,
                    });
                    committed_tokens =
                        committed_tokens.saturating_add(input.input_tokens.len() as u64);
                }
            } else {
                let draft_lens = accepted
                    .iter()
                    .map(|input| input.input_tokens.len() - 1)
                    .collect::<Vec<_>>();
                let max_draft_len = draft_lens.iter().copied().max().unwrap_or(0);
                let mut chain_hidden = vec![None; accepted.len()];
                let mut active_indices = Vec::<usize>::new();
                let mut active_mtp_cache: Option<MtpCache> = None;

                for depth in 0..max_draft_len {
                    let next_active_indices = draft_lens
                        .iter()
                        .enumerate()
                        .filter_map(|(idx, &draft_len)| (depth < draft_len).then_some(idx))
                        .collect::<Vec<_>>();
                    if next_active_indices.is_empty() {
                        continue;
                    }
                    if active_mtp_cache.is_none() {
                        let row_indices = next_active_indices
                            .iter()
                            .map(|&idx| accepted[idx].row_idx)
                            .collect::<Vec<_>>();
                        active_mtp_cache = Some(Self::make_batched_mtp_cache_from_row_indices(
                            model,
                            mtp,
                            &mtp_state.rows,
                            &row_indices,
                        )?);
                        active_indices = next_active_indices.clone();
                    } else if active_indices != next_active_indices {
                        let old_cache = active_mtp_cache
                            .take()
                            .expect("active MTP cache exists above");
                        for (old_compact_idx, &accepted_idx) in active_indices.iter().enumerate() {
                            if !next_active_indices.contains(&accepted_idx) {
                                let row_idx = accepted[accepted_idx].row_idx;
                                mtp_state
                                    .rows
                                    .get_mut(&row_idx)
                                    .ok_or_else(|| {
                                        anyhow!(
                                            "commit_prompt_lookup_mtp_shadow: inactive row {row_idx} disappeared"
                                        )
                                    })?
                                    .mtp_cache
                                    .adopt_row_from(&old_cache, 0, old_compact_idx)?;
                            }
                        }
                        let next_rows = next_active_indices
                            .iter()
                            .map(|&idx| accepted[idx].row_idx)
                            .collect::<Vec<_>>();
                        let mut new_cache = Self::make_empty_batched_mtp_cache_for_row_indices(
                            model,
                            mtp,
                            &mtp_state.rows,
                            &next_rows,
                        )?;
                        for (new_compact_idx, &accepted_idx) in
                            next_active_indices.iter().enumerate()
                        {
                            if let Some(old_compact_idx) =
                                active_indices.iter().position(|&idx| idx == accepted_idx)
                            {
                                new_cache.adopt_row_from(
                                    &old_cache,
                                    new_compact_idx,
                                    old_compact_idx,
                                )?;
                            } else {
                                let row_idx = accepted[accepted_idx].row_idx;
                                let row = mtp_state.rows.get(&row_idx).ok_or_else(|| {
                                    anyhow!(
                                        "commit_prompt_lookup_mtp_shadow: active row {row_idx} disappeared"
                                    )
                                })?;
                                new_cache.adopt_row_from(&row.mtp_cache, new_compact_idx, 0)?;
                            }
                        }
                        active_mtp_cache = Some(new_cache);
                        active_indices = next_active_indices.clone();
                    }

                    let tokens = active_indices
                        .iter()
                        .map(|&idx| accepted[idx].input_tokens[depth])
                        .collect::<Vec<_>>();
                    let token_arr: Array =
                        (&tokens[..], &[tokens.len() as i32, 1_i32][..]).try_into()?;
                    let hidden_rows = active_indices
                        .iter()
                        .map(|&idx| {
                            if depth == 0 {
                                mtp_state
                                    .rows
                                    .get(&accepted[idx].row_idx)
                                    .map(|row| row.last_hidden.clone())
                                    .ok_or_else(|| {
                                        anyhow!(
                                            "commit_prompt_lookup_mtp_shadow: row {} disappeared before replay",
                                            accepted[idx].row_idx
                                        )
                                    })
                            } else {
                                chain_hidden[idx].clone().ok_or_else(|| {
                                    anyhow!(
                                        "commit_prompt_lookup_mtp_shadow: row {} replay hidden absent at depth {depth}",
                                        accepted[idx].row_idx
                                    )
                                })
                            }
                        })
                        .collect::<Result<Vec<_>>>()?;
                    let hidden_refs = hidden_rows.iter().collect::<Vec<_>>();
                    let hidden = mlx::ops::shape::concatenate_on(
                        &hidden_refs,
                        0,
                        mlx::StreamOrDevice::default(),
                    )?;
                    let position_ids = if model.requires_position_ids() {
                        let position_rows = active_indices
                            .iter()
                            .map(|&idx| {
                                slice_position_ids_row_position(
                                    &accepted[idx].position_ids,
                                    0,
                                    depth,
                                    mlx::StreamOrDevice::default(),
                                )
                            })
                            .collect::<Result<Vec<_>>>()?;
                        let position_refs = position_rows.iter().collect::<Vec<_>>();
                        mlx::ops::shape::concatenate_on(
                            &position_refs,
                            1,
                            mlx::StreamOrDevice::default(),
                        )?
                    } else {
                        accepted[active_indices[0]].position_ids.clone()
                    };
                    let output = model.mtp_forward_on(
                        mtp,
                        &hidden,
                        &token_arr,
                        &position_ids,
                        None,
                        active_mtp_cache.as_mut(),
                        mlx::StreamOrDevice::default(),
                    )?;
                    let sampled = mlx::ops::reduction::argmax(&output.logits, -1, false)?;
                    for (compact_idx, &accepted_idx) in active_indices.iter().enumerate() {
                        let next_token = mlx::ops::indexing::slice_strided_on(
                            &sampled,
                            &[compact_idx as i32, 0_i32][..],
                            &[compact_idx as i32 + 1, 1_i32][..],
                            &[1_i32, 1_i32][..],
                            mlx::StreamOrDevice::default(),
                        )?;
                        canonical_proposal_samples.push((
                            accepted[accepted_idx].row_idx,
                            depth,
                            accepted[accepted_idx].input_tokens[depth + 1],
                            next_token,
                        ));
                        chain_hidden[accepted_idx] = Some(slice_hidden_row_position(
                            &output.hidden_states,
                            compact_idx,
                            0,
                            mlx::StreamOrDevice::default(),
                        )?);
                    }
                }

                if let Some(final_cache) = active_mtp_cache {
                    for (compact_idx, &accepted_idx) in active_indices.iter().enumerate() {
                        let row_idx = accepted[accepted_idx].row_idx;
                        mtp_state
                            .rows
                            .get_mut(&row_idx)
                            .ok_or_else(|| {
                                anyhow!(
                                    "commit_prompt_lookup_mtp_shadow: final row {row_idx} disappeared"
                                )
                            })?
                            .mtp_cache
                            .adopt_row_from(&final_cache, 0, compact_idx)?;
                    }
                }

                let sample_arrays = canonical_proposal_samples
                    .iter()
                    .map(|(_, _, _, sample)| sample)
                    .collect::<Vec<_>>();
                let packed_samples = mlx::ops::shape::concatenate_on(
                    &sample_arrays,
                    0,
                    mlx::StreamOrDevice::default(),
                )?;
                canonical_actual_tokens = Some(packed_samples.to_vec()?);

                let row_indices = accepted
                    .iter()
                    .map(|input| input.row_idx)
                    .collect::<Vec<_>>();
                let mut tail_cache = Self::make_batched_mtp_cache_from_row_indices(
                    model,
                    mtp,
                    &mtp_state.rows,
                    &row_indices,
                )?;
                let tail_tokens = accepted
                    .iter()
                    .map(|input| *input.input_tokens.last().expect("len checked above"))
                    .collect::<Vec<_>>();
                let token_arr: Array =
                    (&tail_tokens[..], &[tail_tokens.len() as i32, 1_i32][..]).try_into()?;
                let tail_prev_hidden = accepted
                    .iter()
                    .map(|input| {
                        slice_hidden_row_position(
                            &input.input_hidden,
                            0,
                            input.input_tokens.len() - 2,
                            mlx::StreamOrDevice::default(),
                        )
                    })
                    .collect::<Result<Vec<_>>>()?;
                let hidden_refs = tail_prev_hidden.iter().collect::<Vec<_>>();
                let hidden = mlx::ops::shape::concatenate_on(
                    &hidden_refs,
                    0,
                    mlx::StreamOrDevice::default(),
                )?;
                let position_ids = if model.requires_position_ids() {
                    let position_rows = accepted
                        .iter()
                        .map(|input| {
                            slice_position_ids_row_position(
                                &input.position_ids,
                                0,
                                input.input_tokens.len() - 1,
                                mlx::StreamOrDevice::default(),
                            )
                        })
                        .collect::<Result<Vec<_>>>()?;
                    let position_refs = position_rows.iter().collect::<Vec<_>>();
                    mlx::ops::shape::concatenate_on(
                        &position_refs,
                        1,
                        mlx::StreamOrDevice::default(),
                    )?
                } else {
                    accepted[0].position_ids.clone()
                };
                let tail_hidden = model.mtp_forward_hidden_on(
                    mtp,
                    &hidden,
                    &token_arr,
                    &position_ids,
                    None,
                    Some(&mut tail_cache),
                    mlx::StreamOrDevice::default(),
                )?;
                mlx::transforms::eval(&[&tail_hidden])?;
                for (compact_idx, input) in accepted.iter().enumerate() {
                    let row = mtp_state.rows.get_mut(&input.row_idx).ok_or_else(|| {
                        anyhow!(
                            "commit_prompt_lookup_mtp_shadow: tail row {} disappeared",
                            input.row_idx
                        )
                    })?;
                    row.mtp_cache.adopt_row_from(&tail_cache, 0, compact_idx)?;
                    row.deferred_tail_commit = None;
                }
                committed_tokens = committed_tokens.saturating_add(
                    accepted
                        .iter()
                        .map(|input| input.input_tokens.len() as u64)
                        .sum::<u64>(),
                );
            }

            let actual_tokens = match canonical_actual_tokens {
                Some(tokens) => tokens,
                None => {
                    let sample_arrays = canonical_proposal_samples
                        .iter()
                        .map(|(_, _, _, sample)| sample)
                        .collect::<Vec<_>>();
                    let packed_samples = mlx::ops::shape::concatenate_on(
                        &sample_arrays,
                        0,
                        mlx::StreamOrDevice::default(),
                    )?;
                    packed_samples.to_vec()?
                }
            };
            stats.shared_mtp_canonical_validation_windows = stats
                .shared_mtp_canonical_validation_windows
                .saturating_add(accepted.len() as u64);
            stats.shared_mtp_canonical_validation_tokens = stats
                .shared_mtp_canonical_validation_tokens
                .saturating_add(canonical_proposal_samples.len() as u64);
            add_elapsed_us(
                &mut stats.shared_mtp_canonical_validation_us,
                canonical_validation_started,
            );
            anyhow::ensure!(
                actual_tokens.len() == canonical_proposal_samples.len(),
                "commit_prompt_lookup_mtp_shadow: canonical proposal samples {} != metadata {}",
                actual_tokens.len(),
                canonical_proposal_samples.len()
            );
            for ((row_idx, depth, expected, _), actual) in
                canonical_proposal_samples.iter().zip(actual_tokens)
            {
                if *expected != actual {
                    stats.shared_mtp_canonical_validation_mismatches = stats
                        .shared_mtp_canonical_validation_mismatches
                        .saturating_add(1);
                    return Err(anyhow::Error::new(PromptLookupMtpCanonicalMismatch {
                        row_idx: *row_idx,
                        depth: *depth,
                    }));
                }
            }

            for input in accepted {
                let row = mtp_state.rows.get_mut(&input.row_idx).ok_or_else(|| {
                    anyhow!(
                        "commit_prompt_lookup_mtp_shadow: row {} disappeared after replay",
                        input.row_idx
                    )
                })?;
                let accepted_last_hidden = slice_hidden_row_position(
                    &input.input_hidden,
                    0,
                    input.input_tokens.len() - 1,
                    mlx::StreamOrDevice::default(),
                )?;
                row.last_hidden = accepted_last_hidden;
                if let Some(policy_snapshot) = input.mtp_policy_snapshot.clone() {
                    row.draft_policy.restore_snapshot(policy_snapshot)?;
                    row.adaptive_draft_tokens = row
                        .draft_policy
                        .current_budget()
                        .min(mtp_state.cfg.max_draft_tokens);
                }
                let attempted = input.input_tokens.len().saturating_sub(1);
                mtp_state.stats.windows = mtp_state.stats.windows.saturating_add(1);
                mtp_state.stats.drafted_tokens =
                    mtp_state.stats.drafted_tokens.saturating_add(attempted);
                mtp_state.stats.accepted_draft_tokens = mtp_state
                    .stats
                    .accepted_draft_tokens
                    .saturating_add(attempted);
                mtp_state
                    .stats
                    .record_window_acceptance(attempted, attempted);
            }
            Ok(())
        })();

        if let Err(error) = commit_result {
            let mut rollback_error = None;
            for (
                row_idx,
                snapshot,
                last_hidden,
                deferred_tail_commit,
                adaptive_draft_tokens,
                draft_policy,
            ) in snapshots
            {
                let Some(row) = mtp_state.rows.get_mut(&row_idx) else {
                    rollback_error = Some(anyhow!(
                        "commit_prompt_lookup_mtp_shadow rollback lost row {row_idx}"
                    ));
                    continue;
                };
                if let Err(error) = row.mtp_cache.restore(&snapshot) {
                    rollback_error = Some(error.context(format!(
                        "commit_prompt_lookup_mtp_shadow rollback row {row_idx}"
                    )));
                }
                row.last_hidden = last_hidden;
                row.deferred_tail_commit = deferred_tail_commit;
                row.adaptive_draft_tokens = adaptive_draft_tokens;
                row.draft_policy = draft_policy;
            }
            return match rollback_error {
                Some(rollback_error) => Err(error.context(format!(
                    "MTP shadow commit failed and rollback failed: {rollback_error:#}"
                ))),
                None => Err(error),
            };
        }

        stats.mtp_shadow_commit_windows = stats.mtp_shadow_commit_windows.saturating_add(1);
        stats.mtp_shadow_commit_tokens = stats
            .mtp_shadow_commit_tokens
            .saturating_add(committed_tokens);
        add_elapsed_us(&mut stats.mtp_shadow_commit_us, commit_started);
        add_mtp_decode_cache_commit_us(&mut mtp_state.stats, commit_started);
        Ok(())
    }

    pub fn prefill_admitted_mtp_single(
        &mut self,
        model: &M,
        mtp: &M::MtpHead,
        cfg: MtpSpeculativeConfig,
    ) -> Result<Vec<StepEvent>>
    where
        M: MtpSpeculativeModel + DenseVlMethods,
    {
        self.prefill_admitted_mtp_single_with_options(
            model,
            mtp,
            cfg,
            None,
            true,
            MtpTargetProjection::Neural,
        )
    }

    fn prefill_admitted_mtp_single_with_options(
        &mut self,
        model: &M,
        mtp: &M::MtpHead,
        cfg: MtpSpeculativeConfig,
        forced_current: Option<u32>,
        fill_initial_window: bool,
        projection: MtpTargetProjection,
    ) -> Result<Vec<StepEvent>>
    where
        M: MtpSpeculativeModel + DenseVlMethods,
    {
        self.ensure_not_poisoned()?;
        match self.prefill_admitted_mtp_single_inner(
            model,
            mtp,
            cfg,
            forced_current,
            fill_initial_window,
            projection,
        ) {
            Ok(events) => {
                self.commit_all_governor_admissions();
                Ok(events)
            }
            Err(e) => {
                self.rollback_all_governor_admissions();
                self.poisoned = true;
                if !matches!(self.phase, Phase::Decoding | Phase::Finished) {
                    self.phase = Phase::Finished;
                }
                Err(e)
            }
        }
    }

    pub fn step_mtp_single(&mut self, model: &M, mtp: &M::MtpHead) -> Result<Vec<StepEvent>>
    where
        M: MtpSpeculativeModel,
    {
        self.ensure_not_poisoned()?;
        match self.step_mtp_single_inner(model, mtp, true, MtpTargetProjection::Neural, None) {
            Ok(events) => Ok(events),
            Err(e) => {
                self.poisoned = true;
                Err(e)
            }
        }
    }

    fn prefill_admitted_mtp_single_inner(
        &mut self,
        model: &M,
        mtp: &M::MtpHead,
        cfg: MtpSpeculativeConfig,
        forced_current: Option<u32>,
        fill_initial_window: bool,
        projection: MtpTargetProjection,
    ) -> Result<Vec<StepEvent>>
    where
        M: MtpSpeculativeModel + DenseVlMethods,
    {
        if self.b_max != 1 {
            return Err(anyhow!(
                "prefill_admitted_mtp_single currently requires b_max 1"
            ));
        }
        match self.phase {
            Phase::Idle | Phase::Admitting => {}
            Phase::Decoding | Phase::Finished => {
                return Err(anyhow!(
                    "prefill_admitted_mtp_single illegal in {:?} phase: call evict_all first",
                    self.phase
                ));
            }
        }
        self.discard_retained_immutable_prefix_cache();

        let active_rows: Vec<usize> = self
            .slots
            .iter()
            .enumerate()
            .filter_map(|(row, slot)| slot.as_ref().map(|_| row))
            .collect();
        if active_rows.len() != 1 {
            return Err(anyhow!(
                "prefill_admitted_mtp_single requires exactly one admitted request, got {}",
                active_rows.len()
            ));
        }
        let row_idx = active_rows[0];
        let (
            id,
            prompt_ids,
            max_new_tokens,
            sampler,
            stop_token_ids,
            prefill_chunk_size,
            pixel_values,
            image_grid_thw,
            image_spatial_merge_size,
            image_token_id,
        ) = {
            let state = self.slots[row_idx]
                .as_ref()
                .expect("active row implies slot is Some");
            (
                state.id,
                state.prompt_ids.clone(),
                state.max_new_tokens,
                state.sampler,
                state.stop_token_ids.clone(),
                state.prefill_chunk_size,
                state.pixel_values.clone(),
                state.image_grid_thw.clone(),
                state.image_spatial_merge_size,
                state.image_token_id,
            )
        };
        if prompt_ids.is_empty() {
            return Err(anyhow!(
                "prefill_admitted_mtp_single: prompt_ids cannot be empty"
            ));
        }
        if pixel_values.is_none() && image_grid_thw.is_some() {
            return Err(anyhow!(
                "prefill_admitted_mtp_single: image_grid_thw present but pixel_values is None"
            ));
        }
        MtpSpeculativeConfig::new(cfg.max_draft_tokens, sampler)?;
        let is_vl = pixel_values.is_some();
        let _vision_reservation = if is_vl {
            reserve_vision_prefill(
                self.process_memory_governor.as_ref(),
                model,
                &[pixel_values.as_deref()],
                &[image_grid_thw.as_deref()],
            )?
        } else {
            None
        };
        let prompt_ids_i32: Vec<i32> = if is_vl {
            prompt_ids.iter().map(|&t| t as i32).collect()
        } else {
            Vec::new()
        };
        let prefix_fingerprint = if self.paged_prefix_cache.is_some() {
            paged_prefix_fingerprint_for_request(
                pixel_values.as_deref(),
                image_grid_thw.as_deref(),
                image_token_id,
                image_spatial_merge_size,
            )?
        } else {
            None
        };
        let vl_position_ids_full = if is_vl {
            if model.requires_position_ids() {
                let grids = image_grid_thw.as_deref().ok_or_else(|| {
                    anyhow!(
                        "prefill_admitted_mtp_single: pixel_values present but grid_thw is None"
                    )
                })?;
                Some(build_position_ids_vl(
                    &prompt_ids_i32,
                    grids,
                    image_token_id,
                    image_spatial_merge_size,
                )?)
            } else {
                Some(self.reusable_dummy_position_ids()?)
            }
        } else {
            None
        };
        let vl_position_ids_is_dummy = is_vl && !model.requires_position_ids();
        let mut vl_vision_embeds_full: Option<Array> = None;

        let prompt_len = prompt_ids.len();
        let cap =
            (prompt_len.saturating_add(max_new_tokens) as i32).max(MIN_KV_CACHE_CAP_FOR_GPU_PERF);
        let dtype = model.cache_dtype();
        if self.cache.is_some() {
            return Err(anyhow!(
                "prefill_admitted_mtp_single: cache already allocated before prefill"
            ));
        }
        let turboquant_bits = self.kv_cache_turboquant_bits_for_rows(&[row_idx])?;
        self.cache =
            Some(self.make_model_cache_for_rows(model, &[row_idx], cap, dtype, turboquant_bits)?);
        self.cache_rows = vec![row_idx];

        let mut mtp_cache = model.make_mtp_cache(mtp, 1, cap, dtype)?;
        let prompt_len_i32 = prompt_len as i32;
        let mut stats = MtpSpeculativeStats::default();
        let mut last_prompt_hidden = None;
        let mut mtp_prev_hidden: Option<Array> = None;
        let mut pos = 0_i32;
        let mut ordinary_prefill_is_adaptive_chunked = false;
        if let Some((restore_len, restored_last_hidden)) =
            try_restore_paged_prefix_for_prompt_with_mtp(
                self.paged_prefix_cache.as_ref(),
                self.prefix_lru_cache.as_ref(),
                self.cache
                    .as_mut()
                    .ok_or_else(|| {
                        anyhow!("prefill_admitted_mtp_single: cache absent after allocate")
                    })?
                    .as_mut_slice(),
                &mut mtp_cache,
                &prompt_ids,
                model.mtp_hidden_size(mtp),
                model.mtp_hidden_dtype(mtp),
                prefix_fingerprint.as_deref(),
            )?
        {
            self.runtime_usage
                .record_prefix_cache_hit_tokens(restore_len as u64);
            pos = restore_len;
            mtp_prev_hidden = Some(restored_last_hidden);
        }
        let mut image_pad_cursor = if is_vl {
            count_image_pad_i32(&prompt_ids_i32[..pos as usize], image_token_id)
        } else {
            0
        };
        while pos < prompt_len_i32 {
            let remaining = prompt_len_i32 - pos;
            let mut n = if prefill_chunk_size == 0 {
                remaining
            } else {
                remaining.min(prefill_chunk_size.max(1))
            };
            let prefill_plan = self.plan_prefill_chunk(n as usize, pos as usize, 1)?;
            if let Some(plan) = prefill_plan.as_ref() {
                n = plan.selected_tokens as i32;
            }
            if pos == 0 && n < prompt_len_i32 {
                ordinary_prefill_is_adaptive_chunked = true;
            }
            // Mirror ordinary Scheduler prefill exactly. A prompt that fits
            // the initial prefill allocation is evaluated as [N - 1] + [1],
            // while an adaptive chunked prompt preserves every selected
            // chunk (except the existing paged-prefix final-token boundary).
            // Affine projections are shape-sensitive, so inventing a final
            // [chunk - 1] + [1] split only on the MTP side can leave the main
            // cache numerically different before speculative decode starts.
            let split_final_token =
                self.paged_prefix_cache.is_some() || !ordinary_prefill_is_adaptive_chunked;
            if split_final_token && pos + n == prompt_len_i32 && pos < prompt_len_i32 - 1 {
                n = prompt_len_i32 - 1 - pos;
            }
            let chunk_ids = &prompt_ids[pos as usize..(pos as usize + n as usize)];
            let (hidden, chunk_pos_ids) = if is_vl {
                let chunk_ids_i32 = &prompt_ids_i32[pos as usize..(pos as usize + n as usize)];
                let chunk_arr: Array = (chunk_ids_i32, &[1_i32, n][..]).try_into()?;
                let position_ids_full = vl_position_ids_full.as_ref().ok_or_else(|| {
                    anyhow!("prefill_admitted_mtp_single: VL position ids absent")
                })?;
                let chunk_pos_ids = if vl_position_ids_is_dummy {
                    position_ids_full.clone()
                } else {
                    slice_pos_ids_axis2(position_ids_full, pos, pos + n)?
                };
                let chunk_image_pads = count_image_pad_i32(chunk_ids_i32, image_token_id);
                if chunk_image_pads > 0 && vl_vision_embeds_full.is_none() {
                    let pv = pixel_values.as_deref().ok_or_else(|| {
                        anyhow!("prefill_admitted_mtp_single: image pads without pixel_values")
                    })?;
                    let grids = image_grid_thw.as_deref().ok_or_else(|| {
                        anyhow!("prefill_admitted_mtp_single: image pads without grid_thw")
                    })?;
                    vl_vision_embeds_full = Some(model.compute_vision_embeds(
                        pv,
                        grids,
                        mlx::StreamOrDevice::default(),
                    )?);
                }
                let chunk_vision_embeds = slice_vision_embeds_for_image_pads(
                    vl_vision_embeds_full.as_ref(),
                    image_pad_cursor,
                    chunk_image_pads,
                )?;
                image_pad_cursor += chunk_image_pads;
                let hidden = {
                    let cache = self
                        .cache
                        .as_mut()
                        .ok_or_else(|| anyhow!("prefill_admitted_mtp_single: cache absent"))?;
                    model.forward_vl_hidden(
                        &chunk_arr,
                        &chunk_pos_ids,
                        None,
                        None,
                        Some(cache.as_mut_slice()),
                        chunk_vision_embeds.as_ref(),
                        image_token_id,
                        mlx::StreamOrDevice::default(),
                    )?
                };
                (hidden, chunk_pos_ids)
            } else {
                let chunk_arr: Array = (chunk_ids, &[1_i32, n][..]).try_into()?;
                let chunk_pos_ids = self.mtp_position_ids(model, pos, n)?;
                let hidden = {
                    let cache = self
                        .cache
                        .as_mut()
                        .ok_or_else(|| anyhow!("prefill_admitted_mtp_single: cache absent"))?;
                    model.forward_text_hidden(
                        &chunk_arr,
                        &chunk_pos_ids,
                        None,
                        None,
                        Some(cache.as_mut_slice()),
                        mlx::StreamOrDevice::default(),
                    )?
                };
                (hidden, chunk_pos_ids)
            };
            let prev_hidden = match mtp_prev_hidden.as_ref() {
                Some(hidden) => hidden.clone(),
                None => zero_hidden_like_position(&hidden)?,
            };
            let commit_start = Instant::now();
            commit_mtp_cache_hidden_prefix(
                model,
                mtp,
                &mut mtp_cache,
                &prev_hidden,
                chunk_ids,
                &hidden,
                &chunk_pos_ids,
                mlx::StreamOrDevice::default(),
            )?;
            add_mtp_prefill_cache_commit_us(&mut stats, commit_start);
            let chunk_last_hidden = slice_hidden_position(&hidden, n - 1)?;
            // `commit_mtp_cache_hidden_prefix` has already evaluated the MTP
            // graph and therefore its `hidden` dependency. Keep the last-row
            // slice lazy until its next real consumer instead of introducing
            // a second host synchronization on every prefill chunk.
            mtp_prev_hidden = Some(chunk_last_hidden.clone());
            let new_pos = pos + n;
            if let Some(cache) = self.cache.as_ref() {
                match try_save_paged_prefix_for_prompt_with_mtp(
                    self.paged_prefix_cache.as_ref(),
                    self.prefix_lru_cache.as_ref(),
                    cache,
                    &mtp_cache,
                    &chunk_last_hidden,
                    &prompt_ids[..new_pos as usize],
                    prefix_fingerprint.as_deref(),
                ) {
                    Ok(Some(key)) => {
                        tracing::debug!("paged SSD prefix cache MTP saved: key={key}");
                    }
                    Ok(None) => {}
                    Err(err) => {
                        tracing::warn!("paged SSD prefix cache MTP save skipped: {err:#}");
                    }
                }
            }
            if new_pos == prompt_len_i32 {
                last_prompt_hidden = Some(chunk_last_hidden);
            }
            drop(prefill_plan);
            pos = new_pos;
        }
        let last_prompt_hidden = last_prompt_hidden
            .ok_or_else(|| anyhow!("prefill_admitted_mtp_single produced no prompt hidden"))?;

        let mut next_constraint = self.slots[row_idx]
            .as_ref()
            .expect("active row implies slot is Some")
            .constraint
            .clone();
        let first_token = match forced_current {
            Some(token) => {
                if let Some(constraint) = next_constraint.as_mut() {
                    let mask = constraint.compute_mask()?;
                    anyhow::ensure!(
                        mask.is_allowed(token),
                        "forced MTP boundary token {token} violates decoding constraint"
                    );
                }
                token
            }
            None => {
                let projection_start = Instant::now();
                let first_logits =
                    model.project_hidden_on(&last_prompt_hidden, mlx::StreamOrDevice::default())?;
                add_elapsed_us(&mut stats.projection_us, projection_start);
                let mut compact_prng = self.compact_prng_state_for_rows(&[row_idx])?;
                let sampling_start = Instant::now();
                let first_tokens = if let Some(constraint) = next_constraint.as_mut() {
                    let row_logits = slice_logits_row(&first_logits, 0)?;
                    let row_logits = crate::core::constrained::apply_token_mask(
                        &row_logits,
                        &constraint.compute_mask()?,
                    )?;
                    vec![sampler.sample(&row_logits, &prompt_ids, &mut compact_prng)?]
                } else {
                    sample_logits_positions(&first_logits, sampler, &prompt_ids, &mut compact_prng)?
                };
                add_elapsed_us(&mut stats.sampling_us, sampling_start);
                self.scatter_prng_state_from_rows(&[row_idx], &compact_prng)?;
                *first_tokens
                    .first()
                    .ok_or_else(|| anyhow!("prefill_admitted_mtp_single produced no first token"))?
            }
        };
        if let Some(constraint) = next_constraint.as_mut() {
            constraint.commit_token(first_token)?;
        }

        let finish_reason = {
            let state = self.slots[row_idx]
                .as_mut()
                .expect("active row implies slot is Some");
            state.constraint = next_constraint;
            state.generated_tokens.push(first_token);
            state.real_len += 1;
            if stop_token_ids.contains(&first_token) {
                state.finished = true;
                state.finish_reason = Some("stop");
            } else if state.generated_tokens.len() >= state.max_new_tokens {
                state.finished = true;
                state.finish_reason = Some("length");
            }
            state.finish_reason
        };

        self.phase = if finish_reason.is_some() {
            Phase::Finished
        } else {
            Phase::Decoding
        };
        self.mtp_state = Some(SchedulerMtpState {
            cfg,
            rows: HashMap::from([(
                row_idx,
                SchedulerMtpRowState {
                    mtp_cache,
                    pending_tokens: VecDeque::new(),
                    last_hidden: last_prompt_hidden,
                    deferred_tail_commit: None,
                    adaptive_draft_tokens: cfg.max_draft_tokens,
                    draft_policy: QwenMtpDraftPolicyState::new(cfg.max_draft_tokens),
                },
            )]),
            stats,
        });

        if finish_reason.is_none() && fill_initial_window {
            self.fill_mtp_window_single_with_projection(row_idx, model, mtp, projection)?;
        }

        Ok(vec![StepEvent {
            id,
            token: first_token,
            finish_reason,
        }])
    }

    pub fn prefill_admitted_mtp_batch(
        &mut self,
        model: &M,
        mtp: &M::MtpHead,
        cfg: MtpSpeculativeConfig,
    ) -> Result<Vec<StepEvent>>
    where
        M: MtpSpeculativeModel + DenseVlMethods,
    {
        self.prefill_admitted_mtp_batch_with_projection(
            model,
            mtp,
            cfg,
            MtpTargetProjection::Neural,
        )
    }

    fn prefill_admitted_mtp_batch_with_projection(
        &mut self,
        model: &M,
        mtp: &M::MtpHead,
        cfg: MtpSpeculativeConfig,
        projection: MtpTargetProjection,
    ) -> Result<Vec<StepEvent>>
    where
        M: MtpSpeculativeModel + DenseVlMethods,
    {
        self.ensure_not_poisoned()?;
        let cold_materialization =
            self.begin_cold_materialization(self.active_materialization_components(true))?;
        match self.prefill_admitted_mtp_batch_inner(model, mtp, cfg, projection) {
            Ok(events) => {
                self.commit_all_governor_admissions();
                if let Some(guard) = cold_materialization {
                    guard.commit();
                }
                Ok(events)
            }
            Err(e) => {
                self.rollback_all_governor_admissions();
                self.poisoned = true;
                if !matches!(self.phase, Phase::Decoding | Phase::Finished) {
                    self.phase = Phase::Finished;
                }
                Err(e)
            }
        }
    }

    fn prefill_admitted_mtp_batch_inner(
        &mut self,
        model: &M,
        mtp: &M::MtpHead,
        cfg: MtpSpeculativeConfig,
        projection: MtpTargetProjection,
    ) -> Result<Vec<StepEvent>>
    where
        M: MtpSpeculativeModel + DenseVlMethods,
    {
        match self.phase {
            Phase::Idle | Phase::Admitting => {}
            Phase::Decoding | Phase::Finished => {
                return Err(anyhow!(
                    "prefill_admitted_mtp_batch illegal in {:?} phase: call evict_all first",
                    self.phase
                ));
            }
        }
        self.discard_retained_immutable_prefix_cache();
        if self.cache.is_some() {
            return Err(anyhow!(
                "prefill_admitted_mtp_batch: cache already allocated before prefill"
            ));
        }
        let active_rows: Vec<usize> = self
            .slots
            .iter()
            .enumerate()
            .filter_map(|(row, slot)| slot.as_ref().map(|_| row))
            .collect();
        if active_rows.is_empty() {
            return Err(anyhow!(
                "prefill_admitted_mtp_batch requires at least one admitted request"
            ));
        }
        let mut final_cap = MIN_KV_CACHE_CAP_FOR_GPU_PERF;
        for &row_idx in &active_rows {
            let state = self.slots[row_idx]
                .as_ref()
                .expect("active row implies slot is Some");
            if state.finished || !state.generated_tokens.is_empty() {
                return Err(anyhow!(
                    "prefill_admitted_mtp_batch requires fresh admitted rows"
                ));
            }
            if state.prompt_ids.is_empty() {
                return Err(anyhow!(
                    "prefill_admitted_mtp_batch: prompt_ids cannot be empty"
                ));
            }
            MtpSpeculativeConfig::new(cfg.max_draft_tokens, state.sampler)?;
            let row_cap = state.prompt_ids.len().saturating_add(state.max_new_tokens);
            let row_cap = i32::try_from(row_cap).unwrap_or(i32::MAX);
            final_cap = final_cap.max(row_cap.max(MIN_KV_CACHE_CAP_FOR_GPU_PERF));
        }

        let mut row_states = HashMap::with_capacity(active_rows.len());
        let mut stats = MtpSpeculativeStats::default();
        let mut events = Vec::with_capacity(active_rows.len());
        let dtype = model.cache_dtype();
        let turboquant_bits = self.kv_cache_turboquant_bits_for_rows(&active_rows)?;
        let mut final_cache =
            self.make_model_cache_for_rows(model, &active_rows, final_cap, dtype, turboquant_bits)?;
        let fill_single_row_initial_window = active_rows.len() == 1;

        for (dst_row, &row_idx) in active_rows.iter().enumerate() {
            let mut temp = self.temp_mtp_scheduler_for_row(row_idx)?;
            let event = temp
                // For B>1, materialize only the prompt and first target token
                // in each temporary scheduler. Drafting here would select
                // tokens with B=1 execution morphology before the rows are
                // assembled into the production batch. A true B=1 request
                // retains the established single-row fast path.
                .prefill_admitted_mtp_single_with_options(
                    model,
                    mtp,
                    cfg,
                    None,
                    fill_single_row_initial_window,
                    projection,
                )
                .map_err(|err| anyhow!("prefill_admitted_mtp_batch row {row_idx}: {err:#}"))?;
            let temp_cache = temp.cache.take().ok_or_else(|| {
                anyhow!("prefill_admitted_mtp_batch row {row_idx}: temp cache absent")
            })?;
            let mut temp_mtp_state = temp.mtp_state.take().ok_or_else(|| {
                anyhow!("prefill_admitted_mtp_batch row {row_idx}: temp MTP state absent")
            })?;
            add_mtp_stats(&mut stats, temp_mtp_state.stats);
            let row_state = temp_mtp_state.rows.remove(&0).ok_or_else(|| {
                anyhow!("prefill_admitted_mtp_batch row {row_idx}: temp row state absent")
            })?;
            row_states.insert(row_idx, row_state);
            let temp_slot = temp.slots[0].as_ref().ok_or_else(|| {
                anyhow!("prefill_admitted_mtp_batch row {row_idx}: temp slot absent")
            })?;
            let slot = self.slots[row_idx]
                .as_mut()
                .expect("active row implies slot is Some");
            slot.generated_tokens = temp_slot.generated_tokens.clone();
            slot.real_len = temp_slot.real_len;
            slot.finished = temp_slot.finished;
            slot.finish_reason = temp_slot.finish_reason;
            slot.constraint = temp_slot.constraint.clone();
            adopt_cache_row_layers(
                &mut final_cache,
                &temp_cache,
                dst_row,
                0,
                "prefill_admitted_mtp_batch",
            )?;
            events.extend(event);
        }

        let all_finished = active_rows.iter().all(|&row| {
            self.slots[row]
                .as_ref()
                .expect("active row implies slot is Some")
                .finished
        });
        self.cache = Some(final_cache);
        self.cache_rows = active_rows.clone();
        self.phase = if all_finished {
            Phase::Finished
        } else {
            Phase::Decoding
        };
        let mtp_state = SchedulerMtpState {
            cfg,
            rows: row_states,
            stats,
        };
        // Return the already-computed first target tokens immediately. The
        // first `step_mtp_batch` call fills the empty speculative queues at
        // the window boundary; doing that work here delays TTFT and charges a
        // decode window to prefill instead of aggregate generation time.
        self.mtp_state = Some(mtp_state);

        Ok(events)
    }

    fn temp_mtp_scheduler_for_row(&self, row_idx: usize) -> Result<Scheduler<M>> {
        let state = self.slots[row_idx]
            .as_ref()
            .ok_or_else(|| anyhow!("temp_mtp_scheduler_for_row: row slot absent"))?;
        let mut temp = self.temp_scheduler_with_parent_budget::<M>()?;
        if let Some(config) = self.paged_prefix_cache.as_ref() {
            temp.enable_paged_prefix_cache(config.clone())?;
        }
        if let Some(prefix_lru_cache) = self.prefix_lru_cache.as_ref() {
            temp.share_prefix_lru_cache(Arc::clone(prefix_lru_cache));
        }
        let temp_id = temp.admit(generate_request_from_state(state)?)?;
        {
            let temp_state = temp.slots[0]
                .as_mut()
                .ok_or_else(|| anyhow!("temp_mtp_scheduler_for_row: temp slot absent"))?;
            temp_state.id = state.id;
            temp_state.generated_tokens = state.generated_tokens.clone();
            temp_state.real_len = state.real_len;
            temp_state.finished = state.finished;
            temp_state.finish_reason = state.finish_reason;
            temp_state.constraint = state.constraint.clone();
        }
        temp.request_block_tables.remove(&temp_id);
        temp.request_block_tables
            .insert(state.id, RequestBlockTable::new(state.id));
        anyhow::ensure!(
            temp_id == RequestId(0),
            "temp_mtp_scheduler_for_row: unexpected temp id {}",
            temp_id.0
        );
        Ok(temp)
    }

    fn temp_mtp_rebase_scheduler_for_row(&self, row_idx: usize) -> Result<Scheduler<M>> {
        let state = self.slots[row_idx]
            .as_ref()
            .ok_or_else(|| anyhow!("temp_mtp_rebase_scheduler_for_row: row slot absent"))?;
        let expected_current = *state
            .generated_tokens
            .last()
            .ok_or_else(|| anyhow!("temp_mtp_rebase_scheduler_for_row: current token absent"))?;
        anyhow::ensure!(
            !state.stop_token_ids.contains(&expected_current),
            "temp_mtp_rebase_scheduler_for_row: unfinished request current token is a stop token"
        );
        let mut temp = self.temp_scheduler_with_parent_budget::<M>()?;
        if let Some(config) = self.paged_prefix_cache.as_ref() {
            temp.enable_paged_prefix_cache(config.clone())?;
        }
        if let Some(prefix_lru_cache) = self.prefix_lru_cache.as_ref() {
            temp.share_prefix_lru_cache(Arc::clone(prefix_lru_cache));
        }
        let temp_id = temp.admit(generate_neural_rebase_request_from_state(state)?)?;
        let temp_state = temp.slots[0]
            .as_mut()
            .ok_or_else(|| anyhow!("temp_mtp_rebase_scheduler_for_row: temp slot absent"))?;
        temp_state.id = state.id;
        temp_state.constraint = state
            .constraint
            .as_ref()
            .map(|constraint| {
                let mut constraint = constraint.fork();
                constraint.rollback(1)?;
                Ok::<_, anyhow::Error>(constraint)
            })
            .transpose()?;
        temp.request_block_tables.remove(&temp_id);
        temp.request_block_tables
            .insert(state.id, RequestBlockTable::new(state.id));
        anyhow::ensure!(
            temp_id == RequestId(0),
            "temp_mtp_rebase_scheduler_for_row: unexpected temp id {}",
            temp_id.0
        );
        Ok(temp)
    }

    pub fn rebase_mtp_from_committed_history(&mut self, model: &M, mtp: &M::MtpHead) -> Result<()>
    where
        M: MtpSpeculativeModel + DenseVlMethods,
    {
        self.ensure_not_poisoned()?;
        anyhow::ensure!(
            self.phase == Phase::Decoding,
            "rebase_mtp_from_committed_history illegal in {:?} phase",
            self.phase
        );
        let mtp_state = self
            .mtp_state
            .as_ref()
            .ok_or_else(|| anyhow!("rebase_mtp_from_committed_history: MTP state absent"))?;
        let cfg = mtp_state.cfg;
        let mut stats = mtp_state.stats.clone();
        let active_rows = self
            .slots
            .iter()
            .enumerate()
            .filter_map(|(row, slot)| matches!(slot, Some(state) if !state.finished).then_some(row))
            .collect::<Vec<_>>();
        anyhow::ensure!(
            !active_rows.is_empty(),
            "rebase_mtp_from_committed_history requires active rows"
        );

        let mut row_states = HashMap::with_capacity(active_rows.len());
        anyhow::ensure!(
            self.cache.is_some(),
            "rebase_mtp_from_committed_history: main cache absent"
        );
        anyhow::ensure!(
            self.cache_rows == active_rows,
            "rebase_mtp_from_committed_history: live cache rows {:?} do not match active rows {:?}",
            self.cache_rows,
            active_rows
        );
        for &row_idx in &active_rows {
            let expected_current = *self.slots[row_idx]
                .as_ref()
                .and_then(|state| state.generated_tokens.last())
                .ok_or_else(|| {
                    anyhow!("rebase_mtp_from_committed_history: row {row_idx} current token absent")
                })?;
            let mut temp = self.temp_mtp_rebase_scheduler_for_row(row_idx)?;
            let events = temp
                .prefill_admitted_mtp_single_with_options(
                    model,
                    mtp,
                    cfg,
                    Some(expected_current),
                    false,
                    MtpTargetProjection::Neural,
                )
                .map_err(|error| {
                    anyhow!("rebase_mtp_from_committed_history row {row_idx}: {error:#}")
                })?;
            anyhow::ensure!(
                events.len() == 1
                    && events[0].token == expected_current
                    && events[0].finish_reason.is_none(),
                "rebase_mtp_from_committed_history row {row_idx}: forced boundary token was not installed"
            );
            let mut temp_state = temp.mtp_state.take().ok_or_else(|| {
                anyhow!("rebase_mtp_from_committed_history row {row_idx}: temp MTP state absent")
            })?;
            add_mtp_stats(&mut stats, temp_state.stats);
            let row_state = temp_state.rows.remove(&0).ok_or_else(|| {
                anyhow!("rebase_mtp_from_committed_history row {row_idx}: temp row state absent")
            })?;
            anyhow::ensure!(
                row_state.pending_tokens.is_empty() && row_state.deferred_tail_commit.is_none(),
                "rebase_mtp_from_committed_history row {row_idx}: rebase must end at a pure batch-window boundary"
            );
            row_states.insert(row_idx, row_state);
        }

        self.mtp_state = Some(SchedulerMtpState {
            cfg,
            rows: row_states,
            stats,
        });
        self.refresh_active_kv_residency_stats();
        Ok(())
    }

    fn install_temp_mtp_step_result(
        &mut self,
        model: &M,
        row_idx: usize,
        mut temp: Scheduler<M>,
    ) -> Result<(SchedulerMtpRowState, MtpSpeculativeStats)> {
        let temp_cache = temp
            .cache
            .take()
            .ok_or_else(|| anyhow!("install_temp_mtp_step_result: temp cache absent"))?;
        self.install_cache_with_temp_row(model, &temp_cache, row_idx)?;
        let temp_slot = temp.slots[0]
            .as_ref()
            .ok_or_else(|| anyhow!("install_temp_mtp_step_result: temp slot absent"))?;
        let slot = self.slots[row_idx]
            .as_mut()
            .ok_or_else(|| anyhow!("install_temp_mtp_step_result: row slot absent"))?;
        slot.generated_tokens = temp_slot.generated_tokens.clone();
        slot.real_len = temp_slot.real_len;
        slot.finished = temp_slot.finished;
        slot.finish_reason = temp_slot.finish_reason;
        slot.constraint = temp_slot.constraint.clone();

        let mut mtp_state = temp
            .mtp_state
            .take()
            .ok_or_else(|| anyhow!("install_temp_mtp_step_result: temp MTP state absent"))?;
        let row_state = mtp_state
            .rows
            .remove(&0)
            .ok_or_else(|| anyhow!("install_temp_mtp_step_result: temp row state absent"))?;
        Ok((row_state, mtp_state.stats))
    }

    fn build_temp_mtp_step_scheduler(
        &mut self,
        model: &M,
        row_idx: usize,
        cfg: MtpSpeculativeConfig,
        stats: MtpSpeculativeStats,
        row_state: SchedulerMtpRowState,
    ) -> Result<Scheduler<M>> {
        let mut temp = self.temp_mtp_scheduler_for_row(row_idx)?;
        let cache = self
            .cache
            .as_ref()
            .ok_or_else(|| anyhow!("build_temp_mtp_step_scheduler: main cache absent"))?;
        let compact_row = self
            .cache_rows
            .iter()
            .position(|&row| row == row_idx)
            .ok_or_else(|| {
                anyhow!(
                    "build_temp_mtp_step_scheduler: slot row {row_idx} missing from layout {:?}",
                    self.cache_rows
                )
            })?;
        let (cap, dtype) = cache_cap_and_dtype(cache)?;
        let turboquant_bits = self.kv_cache_turboquant_bits_for_rows(&[row_idx])?;
        let mut temp_cache =
            self.make_model_cache_for_rows(model, &[row_idx], cap, dtype, turboquant_bits)?;
        adopt_cache_row_layers(
            &mut temp_cache,
            cache,
            0,
            compact_row,
            "build_temp_mtp_step_scheduler",
        )?;
        temp.cache = Some(temp_cache);
        temp.cache_rows = vec![0];
        temp.phase = Phase::Decoding;
        temp.mtp_state = Some(SchedulerMtpState {
            cfg,
            rows: HashMap::from([(0, row_state)]),
            stats,
        });
        Ok(temp)
    }

    pub fn step_mtp_batch(&mut self, model: &M, mtp: &M::MtpHead) -> Result<Vec<StepEvent>>
    where
        M: MtpSpeculativeModel,
    {
        self.ensure_not_poisoned()?;
        match self.step_mtp_batch_inner(model, mtp, true, MtpTargetProjection::Neural) {
            Ok(events) => Ok(events),
            Err(e) => {
                self.poisoned = true;
                Err(e)
            }
        }
    }

    pub fn step_mtp_batch_without_postfill(
        &mut self,
        model: &M,
        mtp: &M::MtpHead,
    ) -> Result<Vec<StepEvent>>
    where
        M: MtpSpeculativeModel,
    {
        self.ensure_not_poisoned()?;
        match self.step_mtp_batch_inner(model, mtp, false, MtpTargetProjection::Neural) {
            Ok(events) => Ok(events),
            Err(e) => {
                self.poisoned = true;
                Err(e)
            }
        }
    }

    pub(crate) fn step_mtp_batch_without_postfill_observing_prompt_lookup(
        &mut self,
        model: &M,
        mtp: &M::MtpHead,
    ) -> Result<Vec<StepEvent>>
    where
        M: MtpSpeculativeModel,
    {
        self.ensure_not_poisoned()?;
        let expectations = self.take_prompt_lookup_mtp_expectations()?;
        let mut observations = Vec::with_capacity(expectations.len());
        let events = match self.step_mtp_batch_inner_observed(
            model,
            mtp,
            false,
            MtpTargetProjection::Neural,
            Some(&mut observations),
        ) {
            Ok(events) => events,
            Err(error) => {
                self.poisoned = true;
                return Err(error);
            }
        };
        self.record_prompt_lookup_mtp_observations(&expectations, &observations)?;
        self.commit_prompt_lookup_events(&events)?;
        Ok(events)
    }

    pub fn mtp_at_batch_window_boundary(&self) -> bool {
        self.mtp_state.as_ref().is_some_and(|state| {
            state.rows.iter().all(|(&row_idx, row)| {
                self.slots
                    .get(row_idx)
                    .and_then(Option::as_ref)
                    .is_none_or(|slot| slot.finished || row.pending_tokens.is_empty())
            })
        })
    }

    fn step_mtp_batch_inner(
        &mut self,
        model: &M,
        mtp: &M::MtpHead,
        refill_after_emit: bool,
        projection: MtpTargetProjection,
    ) -> Result<Vec<StepEvent>>
    where
        M: MtpSpeculativeModel,
    {
        self.step_mtp_batch_inner_observed(model, mtp, refill_after_emit, projection, None)
    }

    fn step_mtp_batch_inner_observed(
        &mut self,
        model: &M,
        mtp: &M::MtpHead,
        refill_after_emit: bool,
        projection: MtpTargetProjection,
        mut observations: Option<&mut Vec<CanonicalMtpWindowObservation>>,
    ) -> Result<Vec<StepEvent>>
    where
        M: MtpSpeculativeModel,
    {
        if self.phase != Phase::Decoding {
            return Err(anyhow!(
                "step_mtp_batch illegal in {:?} phase: call prefill_admitted_mtp_batch first",
                self.phase
            ));
        }
        let mut mtp_state = self
            .mtp_state
            .take()
            .ok_or_else(|| anyhow!("step_mtp_batch: MTP state absent"))?;
        let cfg = mtp_state.cfg;
        let active_rows: Vec<usize> = self
            .slots
            .iter()
            .enumerate()
            .filter_map(|(row, slot)| {
                (matches!(slot, Some(state) if !state.finished)
                    && mtp_state.rows.contains_key(&row))
                .then_some(row)
            })
            .collect();
        if active_rows.is_empty() {
            let any_unfinished = self
                .slots
                .iter()
                .any(|slot| matches!(slot, Some(state) if !state.finished));
            self.phase = if any_unfinished {
                Phase::Decoding
            } else {
                Phase::Finished
            };
            self.mtp_state = Some(mtp_state);
            return Ok(Vec::new());
        }
        let has_ordinary_fallback = active_rows.iter().any(|row_idx| {
            mtp_state
                .rows
                .get(row_idx)
                .is_some_and(|row| row.draft_policy.uses_ordinary_decode())
        });
        let at_window_boundary = active_rows.iter().all(|row_idx| {
            mtp_state
                .rows
                .get(row_idx)
                .is_some_and(|row| row.pending_tokens.is_empty())
        });
        if has_ordinary_fallback && at_window_boundary {
            self.mtp_state = Some(mtp_state);
            return self.step_inner(model);
        }
        if active_rows.len() == 1
            && self.active_count() == 1
            && self.cache_rows.as_slice() == active_rows.as_slice()
        {
            self.mtp_state = Some(mtp_state);
            return self.step_mtp_single_inner(
                model,
                mtp,
                refill_after_emit,
                projection,
                observations,
            );
        }

        let mut events = Vec::with_capacity(active_rows.len());

        let rows_needing_prefill = active_rows
            .iter()
            .copied()
            .filter(|row_idx| {
                mtp_state
                    .rows
                    .get(row_idx)
                    .is_some_and(|row| row.pending_tokens.is_empty())
            })
            .collect::<Vec<_>>();
        self.fill_mtp_windows_batched(
            &rows_needing_prefill,
            cfg,
            &mut mtp_state.stats,
            &mut mtp_state.rows,
            model,
            mtp,
            projection,
            reborrow_mtp_window_observations(&mut observations),
        )?;

        for &row_idx in &active_rows {
            let token = mtp_state
                .rows
                .get_mut(&row_idx)
                .ok_or_else(|| anyhow!("step_mtp_batch: row {row_idx} MTP state absent"))?
                .pending_tokens
                .pop_front()
                .ok_or_else(|| {
                    anyhow!("step_mtp_batch: row {row_idx} pending token queue is empty")
                })?;
            events.push(self.emit_token_for_row(row_idx, token)?);
        }

        let rows_needing_postfill = active_rows
            .iter()
            .zip(events.iter())
            .filter_map(|(&row_idx, event)| event.finish_reason.is_none().then_some(row_idx))
            .filter(|row_idx| {
                mtp_state
                    .rows
                    .get(row_idx)
                    .is_some_and(|row| row.pending_tokens.is_empty())
            })
            .collect::<Vec<_>>();
        if refill_after_emit {
            self.fill_mtp_windows_batched(
                &rows_needing_postfill,
                cfg,
                &mut mtp_state.stats,
                &mut mtp_state.rows,
                model,
                mtp,
                projection,
                reborrow_mtp_window_observations(&mut observations),
            )?;
        }

        let any_unfinished = self
            .slots
            .iter()
            .any(|slot| matches!(slot, Some(state) if !state.finished));
        self.phase = if any_unfinished {
            Phase::Decoding
        } else {
            Phase::Finished
        };
        self.mtp_state = Some(mtp_state);
        self.refresh_active_kv_residency_stats();

        Ok(events)
    }

    fn make_empty_batched_mtp_cache_for_rows(
        &self,
        model: &M,
        mtp: &M::MtpHead,
        contexts: &[MtpBatchedFillContext],
        row_states: &HashMap<usize, SchedulerMtpRowState>,
        ctx_indices: &[usize],
    ) -> Result<MtpCache>
    where
        M: MtpSpeculativeModel,
    {
        if ctx_indices.is_empty() {
            return Err(anyhow!(
                "make_empty_batched_mtp_cache_for_rows: ctx_indices cannot be empty"
            ));
        }
        let mut cap = 0_i32;
        let mut dtype = None;
        for &ctx_idx in ctx_indices {
            let row_idx = contexts
                .get(ctx_idx)
                .ok_or_else(|| {
                    anyhow!("make_empty_batched_mtp_cache_for_rows: ctx_idx {ctx_idx} out of range")
                })?
                .row_idx;
            let row_state = row_states.get(&row_idx).ok_or_else(|| {
                anyhow!("make_empty_batched_mtp_cache_for_rows: row {row_idx} state absent")
            })?;
            let layer = row_state.mtp_cache.layer(0);
            cap = cap.max(layer.cap());
            if let Some(expected) = dtype {
                if expected != layer.dtype() {
                    return Err(anyhow!(
                        "make_empty_batched_mtp_cache_for_rows: dtype mismatch {:?} != {:?}",
                        expected,
                        layer.dtype()
                    ));
                }
            } else {
                dtype = Some(layer.dtype());
            }
        }
        let dtype =
            dtype.ok_or_else(|| anyhow!("make_empty_batched_mtp_cache_for_rows: dtype absent"))?;
        model.make_mtp_cache(mtp, ctx_indices.len() as i32, cap, dtype)
    }

    fn make_batched_mtp_cache_from_rows(
        &self,
        model: &M,
        mtp: &M::MtpHead,
        contexts: &[MtpBatchedFillContext],
        row_states: &HashMap<usize, SchedulerMtpRowState>,
        ctx_indices: &[usize],
    ) -> Result<MtpCache>
    where
        M: MtpSpeculativeModel,
    {
        let mut cache = self.make_empty_batched_mtp_cache_for_rows(
            model,
            mtp,
            contexts,
            row_states,
            ctx_indices,
        )?;
        for (compact_idx, &ctx_idx) in ctx_indices.iter().enumerate() {
            let row_idx = contexts
                .get(ctx_idx)
                .ok_or_else(|| {
                    anyhow!("make_batched_mtp_cache_from_rows: ctx_idx {ctx_idx} out of range")
                })?
                .row_idx;
            let row_state = row_states.get(&row_idx).ok_or_else(|| {
                anyhow!("make_batched_mtp_cache_from_rows: row {row_idx} state absent")
            })?;
            cache.adopt_row_from(&row_state.mtp_cache, compact_idx, 0)?;
        }
        Ok(cache)
    }

    fn should_use_row_cache_mtp_draft(contexts: &[MtpBatchedFillContext]) -> bool {
        contexts
            .iter()
            .map(|ctx| ctx.verify_start_pos)
            .max()
            .unwrap_or(0)
            >= MTP_BATCH_DRAFT_ROW_CACHE_MIN_OFFSET
    }

    #[allow(clippy::too_many_arguments)]
    fn draft_mtp_windows_from_row_caches(
        &mut self,
        contexts: &mut [MtpBatchedFillContext],
        stats: &mut MtpSpeculativeStats,
        row_states: &mut HashMap<usize, SchedulerMtpRowState>,
        model: &M,
        mtp: &M::MtpHead,
        draft_constraints: &mut HashMap<usize, crate::core::constrained::ConstraintSession>,
    ) -> Result<()>
    where
        M: MtpSpeculativeModel,
    {
        for ctx in contexts {
            let row_state = row_states.get_mut(&ctx.row_idx).ok_or_else(|| {
                anyhow!(
                    "draft_mtp_windows_from_row_caches: row {} MTP state absent",
                    ctx.row_idx
                )
            })?;
            let mut input_hidden = ctx.input_hidden.clone();
            let mut input_token = ctx.input_token.clone();
            let mut produced = 0_usize;

            if let Some(tail) = ctx.deferred_tail_commit.as_ref() {
                let tail_token: Array = (&[tail.token][..], &[1_i32, 1_i32][..]).try_into()?;
                if ctx.draft_budget == 0 {
                    let commit_start = Instant::now();
                    let hidden = model.mtp_forward_hidden_on(
                        mtp,
                        &tail.prev_hidden,
                        &tail_token,
                        &tail.position_ids,
                        None,
                        Some(&mut row_state.mtp_cache),
                        mlx::StreamOrDevice::default(),
                    )?;
                    mlx::transforms::eval(&[&hidden])?;
                    add_mtp_decode_cache_commit_us(stats, commit_start);
                    continue;
                }
                let token_arr = mlx::ops::shape::concatenate_on(
                    &[&tail_token, &input_token],
                    1,
                    mlx::StreamOrDevice::default(),
                )?;
                let current_position_ids = self.mtp_position_ids(model, ctx.verify_start_pos, 1)?;
                let position_ids = concatenate_position_id_steps(
                    &tail.position_ids,
                    &current_position_ids,
                    mlx::StreamOrDevice::default(),
                )?;
                let hidden = mlx::ops::shape::concatenate_on(
                    &[&tail.prev_hidden, &input_hidden],
                    1,
                    mlx::StreamOrDevice::default(),
                )?;
                let draft_forward_start = Instant::now();
                let output = model.mtp_forward_on(
                    mtp,
                    &hidden,
                    &token_arr,
                    &position_ids,
                    None,
                    Some(&mut row_state.mtp_cache),
                    mlx::StreamOrDevice::default(),
                )?;
                add_elapsed_us(&mut stats.draft_forward_us, draft_forward_start);

                let sampling_start = Instant::now();
                let next_token = if let Some(constraint) = draft_constraints.get_mut(&ctx.row_idx) {
                    let logits = slice_logits_row_position(&output.logits, 0, 1)?;
                    let logits = crate::core::constrained::apply_token_mask(
                        &logits,
                        &constraint.compute_mask()?,
                    )?;
                    let sampled = mlx::ops::reduction::argmax(&logits, -1, false)?;
                    let token: u32 = sampled.item()?;
                    constraint.commit_token(token)?;
                    (&[token][..], &[1_i32, 1_i32][..]).try_into()?
                } else {
                    let sampled = mlx::ops::reduction::argmax(&output.logits, -1, false)?;
                    mlx::ops::indexing::slice_strided_on(
                        &sampled,
                        &[0_i32, 1_i32][..],
                        &[1_i32, 2_i32][..],
                        &[1_i32, 1_i32][..],
                        mlx::StreamOrDevice::default(),
                    )?
                };
                add_elapsed_us(&mut stats.sampling_us, sampling_start);

                ctx.draft_tokens.push(next_token.clone());
                input_token = next_token;
                input_hidden = slice_hidden_position(&output.hidden_states, 1)?;
                produced = 1;
            }

            for offset in produced..ctx.draft_budget {
                let position_ids =
                    self.mtp_position_ids(model, ctx.verify_start_pos + offset as i32, 1)?;
                let draft_forward_start = Instant::now();
                let output = model.mtp_forward_on(
                    mtp,
                    &input_hidden,
                    &input_token,
                    &position_ids,
                    None,
                    Some(&mut row_state.mtp_cache),
                    mlx::StreamOrDevice::default(),
                )?;
                add_elapsed_us(&mut stats.draft_forward_us, draft_forward_start);

                let sampling_start = Instant::now();
                let next_token = if let Some(constraint) = draft_constraints.get_mut(&ctx.row_idx) {
                    let logits = slice_logits_row(&output.logits, 0)?;
                    let logits = crate::core::constrained::apply_token_mask(
                        &logits,
                        &constraint.compute_mask()?,
                    )?;
                    let sampled = mlx::ops::reduction::argmax(&logits, -1, false)?;
                    let token: u32 = sampled.item()?;
                    constraint.commit_token(token)?;
                    (&[token][..], &[1_i32, 1_i32][..]).try_into()?
                } else {
                    mlx::ops::reduction::argmax(&output.logits, -1, false)?
                };
                add_elapsed_us(&mut stats.sampling_us, sampling_start);

                ctx.draft_tokens.push(next_token.clone());
                input_token = next_token;
                input_hidden = output.hidden_states;
            }

            ctx.input_token = input_token;
            ctx.input_hidden = input_hidden;
        }
        Ok(())
    }

    #[allow(clippy::too_many_arguments)]
    fn fill_mtp_windows_batched(
        &mut self,
        rows_to_fill: &[usize],
        cfg: MtpSpeculativeConfig,
        stats: &mut MtpSpeculativeStats,
        row_states: &mut HashMap<usize, SchedulerMtpRowState>,
        model: &M,
        mtp: &M::MtpHead,
        projection: MtpTargetProjection,
        observations: Option<&mut Vec<CanonicalMtpWindowObservation>>,
    ) -> Result<()>
    where
        M: MtpSpeculativeModel,
    {
        if rows_to_fill.is_empty() {
            return Ok(());
        }
        let window_started = Instant::now();
        let max_supported_draft_tokens = cfg.max_draft_tokens;
        let stats_before_batch = stats.clone();
        let timing_before = stats.draft_cap_timing();
        let kv_state = MtpDraftPolicyKvState::from_runtime(
            self.paged_prefix_cache.is_some(),
            self.active_kv_config.enabled,
        );
        let mut contexts = Vec::with_capacity(rows_to_fill.len());
        for &row_idx in rows_to_fill {
            let slot = self.slots[row_idx]
                .as_ref()
                .ok_or_else(|| anyhow!("fill_mtp_windows_batched: row {row_idx} slot absent"))?;
            if slot.finished {
                continue;
            }
            let emitted = slot.generated_tokens.len();
            let remaining = slot.max_new_tokens.saturating_sub(emitted);
            if remaining == 0 {
                continue;
            }
            let current_token = *slot.generated_tokens.last().ok_or_else(|| {
                anyhow!("fill_mtp_windows_batched: row {row_idx} has no current token")
            })?;
            let row_state = row_states.get_mut(&row_idx).ok_or_else(|| {
                anyhow!("fill_mtp_windows_batched: row {row_idx} MTP state absent")
            })?;
            let mut history =
                Vec::with_capacity(slot.prompt_ids.len() + slot.generated_tokens.len());
            history.extend_from_slice(&slot.prompt_ids);
            history.extend_from_slice(&slot.generated_tokens);
            let draft_budget = row_state
                .adaptive_draft_tokens
                .min(max_supported_draft_tokens)
                .min(remaining);
            let input_token: Array = (&[current_token][..], &[1_i32, 1_i32][..]).try_into()?;
            contexts.push(MtpBatchedFillContext {
                row_idx,
                current_token,
                stop_token_ids: slot.stop_token_ids.clone(),
                remaining,
                draft_budget,
                verify_start_pos: (history.len() - 1) as i32,
                input_hidden: row_state.last_hidden.clone(),
                input_token,
                draft_tokens: Vec::with_capacity(draft_budget),
                mtp_cache_snapshot: row_state.mtp_cache.snapshot(),
                deferred_tail_commit: row_state.deferred_tail_commit.take(),
            });
        }
        if contexts.is_empty() {
            return Ok(());
        }
        let policy_batch_width = self
            .slots
            .iter()
            .enumerate()
            .filter(|(row_idx, slot)| {
                matches!(slot, Some(state) if !state.finished) && row_states.contains_key(row_idx)
            })
            .count()
            .max(1);
        let mut draft_constraints = contexts
            .iter()
            .filter_map(|ctx| {
                self.slots[ctx.row_idx]
                    .as_ref()
                    .and_then(|state| state.constraint.clone())
                    .map(|constraint| (ctx.row_idx, constraint))
            })
            .collect::<HashMap<_, _>>();
        let tail_commit_mode = if Self::should_use_row_cache_mtp_draft(&contexts) {
            self.draft_mtp_windows_from_row_caches(
                &mut contexts,
                stats,
                row_states,
                model,
                mtp,
                &mut draft_constraints,
            )?;
            MtpBatchedTailCommitMode::PerRowCache
        } else {
            let max_draft_budget = contexts
                .iter()
                .map(|ctx| ctx.draft_budget)
                .max()
                .unwrap_or(0);
            let mut active_indices = Vec::<usize>::new();
            let mut active_mtp_cache: Option<MtpCache> = None;
            for offset in 0..max_draft_budget {
                let next_active_indices = contexts
                    .iter()
                    .enumerate()
                    .filter_map(|(idx, ctx)| (offset < ctx.draft_budget).then_some(idx))
                    .collect::<Vec<_>>();
                if next_active_indices.is_empty() {
                    continue;
                }

                if active_mtp_cache.is_none() {
                    active_mtp_cache = Some(self.make_batched_mtp_cache_from_rows(
                        model,
                        mtp,
                        &contexts,
                        row_states,
                        &next_active_indices,
                    )?);
                    active_indices = next_active_indices.clone();
                } else if active_indices != next_active_indices {
                    let old_cache = active_mtp_cache
                        .take()
                        .expect("active_mtp_cache is Some above");
                    for (old_compact_idx, &ctx_idx) in active_indices.iter().enumerate() {
                        if !next_active_indices.contains(&ctx_idx) {
                            let row_idx = contexts[ctx_idx].row_idx;
                            row_states
                                .get_mut(&row_idx)
                                .ok_or_else(|| {
                                    anyhow!(
                                        "fill_mtp_windows_batched: row {row_idx} state absent while saving inactive MTP row"
                                    )
                                })?
                                .mtp_cache
                                .adopt_row_from(&old_cache, 0, old_compact_idx)?;
                        }
                    }

                    let mut new_cache = self.make_empty_batched_mtp_cache_for_rows(
                        model,
                        mtp,
                        &contexts,
                        row_states,
                        &next_active_indices,
                    )?;
                    for (new_compact_idx, &ctx_idx) in next_active_indices.iter().enumerate() {
                        if let Some(old_compact_idx) =
                            active_indices.iter().position(|&idx| idx == ctx_idx)
                        {
                            new_cache.adopt_row_from(
                                &old_cache,
                                new_compact_idx,
                                old_compact_idx,
                            )?;
                        } else {
                            let row_idx = contexts[ctx_idx].row_idx;
                            let row_state = row_states.get(&row_idx).ok_or_else(|| {
                                anyhow!(
                                    "fill_mtp_windows_batched: row {row_idx} state absent while adding MTP row"
                                )
                            })?;
                            new_cache.adopt_row_from(&row_state.mtp_cache, new_compact_idx, 0)?;
                        }
                    }
                    active_mtp_cache = Some(new_cache);
                    active_indices = next_active_indices.clone();
                }

                let active_mtp_cache = active_mtp_cache
                    .as_mut()
                    .ok_or_else(|| anyhow!("fill_mtp_windows_batched: active MTP cache absent"))?;
                let token_rows = active_indices
                    .iter()
                    .map(|&idx| &contexts[idx].input_token)
                    .collect::<Vec<_>>();
                let token_arr = mlx::ops::shape::concatenate_on(
                    &token_rows,
                    0,
                    mlx::StreamOrDevice::default(),
                )?;
                let hidden_rows = active_indices
                    .iter()
                    .map(|&idx| &contexts[idx].input_hidden)
                    .collect::<Vec<_>>();
                let hidden = mlx::ops::shape::concatenate_on(
                    &hidden_rows[..],
                    0,
                    mlx::StreamOrDevice::default(),
                )?;
                let positions = active_indices
                    .iter()
                    .map(|&idx| contexts[idx].verify_start_pos + offset as i32)
                    .collect::<Vec<_>>();
                let position_ids = if model.requires_position_ids() {
                    build_decode_position_ids(&positions)?
                } else {
                    self.reusable_dummy_position_ids()?
                };

                let draft_forward_start = Instant::now();
                let output = model.mtp_forward_on(
                    mtp,
                    &hidden,
                    &token_arr,
                    &position_ids,
                    None,
                    Some(active_mtp_cache),
                    mlx::StreamOrDevice::default(),
                )?;
                add_elapsed_us(&mut stats.draft_forward_us, draft_forward_start);

                let sampling_start = Instant::now();
                let sampled_arr = if draft_constraints.is_empty() {
                    mlx::ops::reduction::argmax(&output.logits, -1, false)?
                } else {
                    let vocab = output.logits.shape().as_slice()[2];
                    let logits = output
                        .logits
                        .reshape(&[active_indices.len() as i32, vocab][..])?;
                    let masks = active_indices
                        .iter()
                        .map(|&ctx_idx| {
                            draft_constraints
                                .get_mut(&contexts[ctx_idx].row_idx)
                                .map(crate::core::constrained::ConstraintSession::compute_mask)
                                .transpose()
                        })
                        .collect::<Result<Vec<_>>>()?;
                    let logits =
                        crate::core::constrained::apply_batch_token_masks(&logits, &masks)?;
                    mlx::ops::reduction::argmax(&logits, -1, false)?
                        .reshape(&[active_indices.len() as i32, 1_i32][..])?
                };
                add_elapsed_us(&mut stats.sampling_us, sampling_start);
                if sampled_arr.size() != active_indices.len() {
                    return Err(anyhow!(
                        "fill_mtp_windows_batched: sampled {} draft tokens for {} rows",
                        sampled_arr.size(),
                        active_indices.len()
                    ));
                }
                for (compact_idx, &ctx_idx) in active_indices.iter().enumerate() {
                    let next_token = mlx::ops::indexing::slice_strided_on(
                        &sampled_arr,
                        &[compact_idx as i32, 0_i32][..],
                        &[compact_idx as i32 + 1, 1_i32][..],
                        &[1_i32, 1_i32][..],
                        mlx::StreamOrDevice::default(),
                    )?;
                    let ctx = &mut contexts[ctx_idx];
                    if let Some(constraint) = draft_constraints.get_mut(&ctx.row_idx) {
                        let token: u32 = next_token.item()?;
                        constraint.commit_token(token)?;
                    }
                    ctx.draft_tokens.push(next_token.clone());
                    ctx.input_token = next_token;
                    ctx.input_hidden = slice_hidden_row_position(
                        &output.hidden_states,
                        compact_idx,
                        0,
                        mlx::StreamOrDevice::default(),
                    )?;
                }
            }

            if let Some(final_mtp_cache) = active_mtp_cache {
                for (compact_idx, &ctx_idx) in active_indices.iter().enumerate() {
                    let row_idx = contexts[ctx_idx].row_idx;
                    row_states
                        .get_mut(&row_idx)
                        .ok_or_else(|| {
                            anyhow!(
                                "fill_mtp_windows_batched: row {row_idx} state absent while saving final MTP cache"
                            )
                        })?
                        .mtp_cache
                        .adopt_row_from(&final_mtp_cache, 0, compact_idx)?;
                }
            }
            MtpBatchedTailCommitMode::BatchedFromRowCaches
        };

        let active_rows = self
            .slots
            .iter()
            .enumerate()
            .filter_map(|(row, slot)| {
                (matches!(slot, Some(state) if !state.finished) && row_states.contains_key(&row))
                    .then_some(row)
            })
            .collect::<Vec<_>>();
        let max_verify_len = contexts
            .iter()
            .map(|ctx| ctx.draft_tokens.len() + 1)
            .max()
            .unwrap_or(0);
        if max_verify_len == 0 {
            return Ok(());
        }

        // Preserve the qualified model-facing batch width. Rows without a new
        // draft window use zero sequence lengths in the verify tensors.
        self.rebuild_cache_layout(model, &active_rows)?;
        let has_draft_tokens = contexts.iter().any(|ctx| !ctx.draft_tokens.is_empty());

        let verify_result = (|| -> Result<()> {
            let cache_row_for_ctx = contexts
                .iter()
                .map(|ctx| {
                    self.cache_rows
                        .iter()
                        .position(|&row| row == ctx.row_idx)
                        .ok_or_else(|| {
                            anyhow!(
                                "fill_mtp_windows_batched: row {} missing from cache layout {:?}",
                                ctx.row_idx,
                                self.cache_rows
                            )
                        })
                })
                .collect::<Result<Vec<_>>>()?;

            let base_snapshot = if has_draft_tokens {
                let cache = self
                    .cache
                    .as_ref()
                    .ok_or_else(|| anyhow!("fill_mtp_windows_batched: main cache absent"))?;
                Some(cache.iter().map(LayerCache::snapshot).collect::<Vec<_>>())
            } else {
                None
            };
            let b = self.cache_rows.len();
            let affine8_b4_exact_hot_path =
                has_draft_tokens && model.supports_affine8_b4_mtp_exact_hot_path(b, max_verify_len);
            let _exact_affine8_b4_q2 = affine8_b4_exact_hot_path
                .then(crate::nn::position_stable_qmm::exact_affine8_b4_q2_scope);
            // The direct recurrent-prefix restore path is calibrated for B2/Q2
            // and the explicitly qualified Qwen affine8 B4/Q2 shape. Rows that
            // did not open a new MTP window are represented by accepted_len=0;
            // recurrent caches restore those rows to the captured base while
            // rebuilding only the participating rows.
            let accepted_prefix_capture = has_draft_tokens
                && ((b == 2 && max_verify_len == 2) || affine8_b4_exact_hot_path)
                && model.supports_mtp_accepted_prefix_restore();
            if accepted_prefix_capture {
                let cache = self
                    .cache
                    .as_mut()
                    .ok_or_else(|| anyhow!("fill_mtp_windows_batched: main cache absent"))?;
                model.begin_mtp_accepted_prefix_capture(cache.as_mut_slice())?;
            }
            let mut verify_starts = vec![0_i32; b];
            for (ctx, &compact_row) in contexts.iter().zip(cache_row_for_ctx.iter()) {
                verify_starts[compact_row] = ctx.verify_start_pos;
            }
            let (verify_arr, verify_lens) = build_mtp_device_verify_input(
                &contexts,
                &cache_row_for_ctx,
                b,
                max_verify_len,
                mlx::StreamOrDevice::default(),
            )?;
            let verify_pos_ids = if model.requires_position_ids() {
                build_mtp_batched_position_ids(&verify_starts, &verify_lens, max_verify_len as i32)?
            } else {
                self.reusable_dummy_position_ids()?
            };
            let decode_mask = {
                let cache = self
                    .cache
                    .as_ref()
                    .ok_or_else(|| anyhow!("fill_mtp_windows_batched: main cache absent"))?;
                maybe_build_sparse_decode_mask(cache, &verify_lens)?
            };
            let verify_forward_start = Instant::now();
            let verified_hidden = {
                // Once every row selected draft=0, this is an ordinary
                // batched target decode. Exact speculative QMM and rollback
                // snapshots are needed only while at least one row drafts.
                let _verify_qmm = has_draft_tokens.then(crate::nn::verify_qmm::armed_scope);
                let cache = self
                    .cache
                    .as_mut()
                    .ok_or_else(|| anyhow!("fill_mtp_windows_batched: main cache absent"))?;
                model.forward_text_hidden(
                    &verify_arr,
                    &verify_pos_ids,
                    Some(&verify_lens),
                    decode_mask.as_ref(),
                    Some(cache.as_mut_slice()),
                    mlx::StreamOrDevice::default(),
                )?
            };
            add_elapsed_us(&mut stats.verify_forward_us, verify_forward_start);
            let projection_start = Instant::now();
            let verified_logits = project_mtp_target_hidden(
                model,
                &verified_hidden,
                projection,
                mlx::StreamOrDevice::default(),
            )?;
            add_elapsed_us(&mut stats.projection_us, projection_start);
            let logits_shape = verified_logits.shape();
            let logits_dims = logits_shape.as_slice();
            if logits_dims.len() != 3
                || logits_dims[0] as usize != b
                || logits_dims[1] as usize != max_verify_len
            {
                return Err(anyhow!(
                    "fill_mtp_windows_batched: verified logits shape {:?} does not match batch {} max_verify_len {}",
                    logits_dims,
                    b,
                    max_verify_len
                ));
            }
            let mut speculative_masks = vec![None; b];
            for (ctx_idx, ctx) in contexts.iter().enumerate() {
                let Some(constraint) = self.slots[ctx.row_idx]
                    .as_ref()
                    .and_then(|state| state.constraint.as_ref())
                else {
                    continue;
                };
                let sync_start = Instant::now();
                let draft_tokens = ctx
                    .draft_tokens
                    .iter()
                    .map(Array::item::<u32>)
                    .collect::<std::result::Result<Vec<_>, _>>()?;
                stats.draft_host_sync_count = stats.draft_host_sync_count.saturating_add(1);
                add_elapsed_us(&mut stats.draft_host_sync_us, sync_start);
                speculative_masks[cache_row_for_ctx[ctx_idx]] =
                    Some(constraint.speculative_masks(&draft_tokens)?);
            }
            let verified_logits = crate::core::constrained::apply_speculative_token_masks(
                &verified_logits,
                &speculative_masks,
            )?;
            let sampling_start = Instant::now();
            let verified_ids = mlx::ops::reduction::argmax(&verified_logits, -1, false)?;
            add_elapsed_us(&mut stats.sampling_us, sampling_start);
            if verified_ids.size() != b * max_verify_len {
                return Err(anyhow!(
                    "fill_mtp_windows_batched: argmax returned {} tokens for batch {} max_verify_len {}",
                    verified_ids.size(),
                    b,
                    max_verify_len
                ));
            }

            let packed_acceptance = pack_greedy_acceptance_on(
                &verify_arr,
                &verify_lens,
                &verified_ids,
                mlx::StreamOrDevice::default(),
            )?;
            let accept_sync_start = Instant::now();
            let packed_acceptance: Vec<u32> = packed_acceptance.to_vec()?;
            stats.verify_accept_host_sync_count =
                stats.verify_accept_host_sync_count.saturating_add(1);
            add_elapsed_us(&mut stats.verify_accept_host_sync_us, accept_sync_start);
            let packed_stride = max_verify_len + 1;
            if packed_acceptance.len() != b * packed_stride {
                return Err(anyhow!(
                    "fill_mtp_windows_batched: packed acceptance len {} != batch {} * stride {}",
                    packed_acceptance.len(),
                    b,
                    packed_stride
                ));
            }

            let mut resolutions = Vec::with_capacity(contexts.len());
            let mut resolved_draft_tokens = Vec::with_capacity(contexts.len());
            for (ctx_idx, ctx) in contexts.iter().enumerate() {
                let compact_row = cache_row_for_ctx[ctx_idx];
                let (draft_tokens, resolution) = resolve_packed_greedy_acceptance(
                    &packed_acceptance,
                    packed_stride,
                    compact_row,
                    ctx.draft_tokens.len(),
                )?;
                stats.windows += 1;
                stats.drafted_tokens += draft_tokens.len();
                stats.accepted_draft_tokens += resolution.accepted_draft_len;
                stats.record_window_acceptance(draft_tokens.len(), resolution.accepted_draft_len);
                if resolution.needs_rollback {
                    stats.rollback_count += 1;
                }
                resolved_draft_tokens.push(draft_tokens);
                resolutions.push(resolution);
            }
            if let Some(observations) = observations {
                for (ctx_idx, ctx) in contexts.iter().enumerate() {
                    let draft_tokens = &resolved_draft_tokens[ctx_idx];
                    let resolution = &resolutions[ctx_idx];
                    observations.push(CanonicalMtpWindowObservation {
                        row_idx: ctx.row_idx,
                        draft_tokens: draft_tokens.clone(),
                        accepted_draft_len: resolution.accepted_draft_len,
                        bonus_token: resolution.tokens_to_append.get(draft_tokens.len()).copied(),
                    });
                }
            }

            let mismatch_rows = resolutions
                .iter()
                .enumerate()
                .filter_map(|(ctx_idx, resolution)| {
                    resolution.needs_rollback.then_some((
                        cache_row_for_ctx[ctx_idx],
                        resolution.accepted_verify_input_len,
                    ))
                })
                .collect::<Vec<_>>();
            let main_cache_supports_trim = {
                let cache = self
                    .cache
                    .as_ref()
                    .ok_or_else(|| anyhow!("fill_mtp_windows_batched: main cache absent"))?;
                layer_cache_supports_accepted_prefix_trim(cache.as_slice())
            };
            if mismatch_rows.is_empty() && accepted_prefix_capture && !affine8_b4_exact_hot_path {
                let cache = self
                    .cache
                    .as_mut()
                    .ok_or_else(|| anyhow!("fill_mtp_windows_batched: main cache absent"))?;
                model.discard_mtp_accepted_prefix_capture(cache.as_mut_slice());
            }
            let (accepted_hidden_source, accepted_position_ids_source) =
                if accepted_prefix_capture
                    && (affine8_b4_exact_hot_path || !mismatch_rows.is_empty())
                {
                    let rollback_start = Instant::now();
                    let mut accepted_lens = vec![0_usize; b];
                    for (ctx_idx, resolution) in resolutions.iter().enumerate() {
                        accepted_lens[cache_row_for_ctx[ctx_idx]] =
                            resolution.accepted_verify_input_len;
                    }
                    {
                        let cache = self.cache.as_mut().ok_or_else(|| {
                            anyhow!("fill_mtp_windows_batched: main cache absent")
                        })?;
                        model.restore_mtp_accepted_prefix_rows_on(
                            cache.as_mut_slice(),
                            base_snapshot.as_ref().ok_or_else(|| {
                                anyhow!("fill_mtp_windows_batched: rollback snapshot absent")
                            })?,
                            &accepted_lens,
                            mlx::StreamOrDevice::default(),
                        )?;
                    }
                    add_elapsed_us(&mut stats.main_rollback_us, rollback_start);
                    (verified_hidden.clone(), verify_pos_ids.clone())
                } else if mismatch_rows.is_empty() {
                    (verified_hidden.clone(), verify_pos_ids.clone())
                } else if main_cache_supports_trim {
                    let rollback_start = Instant::now();
                    {
                        let cache = self.cache.as_mut().ok_or_else(|| {
                            anyhow!("fill_mtp_windows_batched: main cache absent")
                        })?;
                        trim_full_layer_cache_rows_to_accepted_prefix(
                            cache.as_mut_slice(),
                            base_snapshot.as_ref().ok_or_else(|| {
                                anyhow!("fill_mtp_windows_batched: rollback snapshot absent")
                            })?,
                            &mismatch_rows,
                        )?;
                    }
                    add_elapsed_us(&mut stats.main_rollback_us, rollback_start);
                    (verified_hidden.clone(), verify_pos_ids.clone())
                } else {
                    let rollback_start = Instant::now();
                    {
                        let cache = self.cache.as_mut().ok_or_else(|| {
                            anyhow!("fill_mtp_windows_batched: main cache absent")
                        })?;
                        restore_layer_cache(
                            cache.as_mut_slice(),
                            base_snapshot.as_ref().ok_or_else(|| {
                                anyhow!("fill_mtp_windows_batched: replay snapshot absent")
                            })?,
                        )?;
                    }

                    let accepted_lens = resolutions
                        .iter()
                        .map(|resolution| resolution.accepted_verify_input_len)
                        .collect::<Vec<_>>();
                    let max_replay_len = accepted_lens.iter().copied().max().unwrap_or(0);
                    if max_replay_len == 0 {
                        return Err(anyhow!(
                            "fill_mtp_windows_batched: accepted replay length cannot be zero"
                        ));
                    }
                    let mut replay_flat = vec![0_u32; b * max_replay_len];
                    let mut replay_lens = vec![0_i32; b];
                    let mut replay_starts = vec![0_i32; b];
                    for (ctx_idx, ctx) in contexts.iter().enumerate() {
                        let compact_row = cache_row_for_ctx[ctx_idx];
                        let accepted_len = accepted_lens[ctx_idx];
                        let verify_len = resolved_draft_tokens[ctx_idx].len() + 1;
                        if accepted_len == 0 || accepted_len > verify_len {
                            return Err(anyhow!(
                                "fill_mtp_windows_batched: row {} accepted_len={} verify_len={}",
                                ctx.row_idx,
                                accepted_len,
                                verify_len
                            ));
                        }
                        let start = compact_row * max_replay_len;
                        replay_flat[start] = ctx.current_token;
                        replay_flat[start + 1..start + accepted_len]
                            .copy_from_slice(&resolved_draft_tokens[ctx_idx][..accepted_len - 1]);
                        replay_lens[compact_row] = accepted_len as i32;
                        replay_starts[compact_row] = ctx.verify_start_pos;
                    }
                    let mut replay_hidden_steps = Vec::with_capacity(max_replay_len);
                    for depth in 0..max_replay_len {
                        let mut step_tokens = vec![0_u32; b];
                        let mut step_lens = vec![0_i32; b];
                        let mut step_starts = vec![0_i32; b];
                        for row in 0..b {
                            if depth < replay_lens[row] as usize {
                                step_tokens[row] = replay_flat[row * max_replay_len + depth];
                                step_lens[row] = 1;
                                step_starts[row] = replay_starts[row] + depth as i32;
                            }
                        }
                        let step_arr: Array =
                            (&step_tokens[..], &[b as i32, 1_i32][..]).try_into()?;
                        let replay_position_ids = if model.requires_position_ids() {
                            build_mtp_batched_position_ids(&step_starts, &step_lens, 1)?
                        } else {
                            self.reusable_dummy_position_ids()?
                        };
                        let replay_decode_mask = {
                            let cache = self.cache.as_ref().ok_or_else(|| {
                                anyhow!("fill_mtp_windows_batched: main cache absent")
                            })?;
                            maybe_build_sparse_decode_mask(cache, &step_lens)?
                        };
                        let replay_hidden = {
                            let _verify_qmm = crate::nn::verify_qmm::armed_scope();
                            let cache = self.cache.as_mut().ok_or_else(|| {
                                anyhow!("fill_mtp_windows_batched: main cache absent")
                            })?;
                            model.forward_text_hidden(
                                &step_arr,
                                &replay_position_ids,
                                Some(&step_lens),
                                replay_decode_mask.as_ref(),
                                Some(cache.as_mut_slice()),
                                mlx::StreamOrDevice::default(),
                            )?
                        };
                        mlx::transforms::eval(&[&replay_hidden])?;
                        replay_hidden_steps.push(replay_hidden);
                    }
                    let replay_hidden_refs = replay_hidden_steps.iter().collect::<Vec<_>>();
                    let replay_hidden = mlx::ops::shape::concatenate_on(
                        &replay_hidden_refs,
                        1,
                        mlx::StreamOrDevice::default(),
                    )?;
                    add_elapsed_us(&mut stats.main_rollback_us, rollback_start);
                    (replay_hidden, verify_pos_ids.clone())
                };

            let mut policy_inputs = Vec::with_capacity(contexts.len());
            let mut full_accept_tail_commits: Vec<(usize, u32, Array, Array)> = Vec::new();
            for (ctx_idx, resolution) in resolutions.into_iter().enumerate() {
                let ctx = &contexts[ctx_idx];
                let compact_row = cache_row_for_ctx[ctx_idx];
                let accepted_len = resolution.accepted_verify_input_len;
                let accepted_last_hidden = slice_hidden_row_position(
                    &accepted_hidden_source,
                    compact_row,
                    accepted_len - 1,
                    mlx::StreamOrDevice::default(),
                )?;
                let mut accepted_input = Vec::with_capacity(accepted_len);
                accepted_input.push(ctx.current_token);
                accepted_input.extend_from_slice(
                    &resolved_draft_tokens[ctx_idx][..accepted_len.saturating_sub(1)],
                );

                let row_state = row_states.get_mut(&ctx.row_idx).ok_or_else(|| {
                    anyhow!(
                        "fill_mtp_windows_batched: row {} MTP state absent after verify",
                        ctx.row_idx
                    )
                })?;
                let pre_window_hidden = row_state.last_hidden.clone();
                let maintain_mtp_cache = row_state.draft_policy.should_maintain_mtp_cache();
                if resolution.needs_rollback {
                    let trim_start = Instant::now();
                    let accepted_mtp_input_len =
                        accepted_input.len() + usize::from(ctx.deferred_tail_commit.is_some());
                    row_state.mtp_cache.trim_row_to_snapshot_prefix_len(
                        &ctx.mtp_cache_snapshot,
                        0,
                        accepted_mtp_input_len,
                    )?;
                    add_elapsed_us(&mut stats.mtp_cache_restore_us, trim_start);
                } else if maintain_mtp_cache {
                    let tail_idx = accepted_input.len() - 1;
                    let tail_prev_hidden = if tail_idx == 0 {
                        pre_window_hidden.clone()
                    } else {
                        slice_hidden_row_position(
                            &accepted_hidden_source,
                            compact_row,
                            tail_idx - 1,
                            mlx::StreamOrDevice::default(),
                        )?
                    };
                    let tail_position_ids = slice_position_ids_row_position(
                        &accepted_position_ids_source,
                        compact_row,
                        tail_idx,
                        mlx::StreamOrDevice::default(),
                    )?;
                    full_accept_tail_commits.push((
                        ctx_idx,
                        accepted_input[tail_idx],
                        tail_prev_hidden,
                        tail_position_ids,
                    ));
                    stats.mtp_cache_reuse_count = stats.mtp_cache_reuse_count.saturating_add(1);
                    stats.mtp_cache_reused_tokens = stats
                        .mtp_cache_reused_tokens
                        .saturating_add(accepted_input.len().saturating_sub(1));
                }
                row_state.last_hidden = accepted_last_hidden;

                let mut tokens_to_append = resolution.tokens_to_append;
                if let Some(stop_idx) = tokens_to_append
                    .iter()
                    .position(|token| ctx.stop_token_ids.contains(token))
                {
                    tokens_to_append.truncate(stop_idx + 1);
                }
                tokens_to_append.truncate(ctx.remaining);
                if let Some(constraint) = self.slots[ctx.row_idx]
                    .as_ref()
                    .and_then(|slot| slot.constraint.as_ref())
                {
                    constraint.truncate_invalid_speculative_bonus(&mut tokens_to_append)?;
                }
                let committed_tokens = tokens_to_append.len();
                row_state.pending_tokens.extend(tokens_to_append);
                policy_inputs.push((
                    ctx.row_idx,
                    resolved_draft_tokens[ctx_idx].len(),
                    resolution.accepted_draft_len,
                    ctx.verify_start_pos.max(0) as usize + 1,
                    committed_tokens,
                ));
            }

            if !full_accept_tail_commits.is_empty() {
                match tail_commit_mode {
                    MtpBatchedTailCommitMode::BatchedFromRowCaches => {
                        let ctx_indices = full_accept_tail_commits
                            .iter()
                            .map(|(ctx_idx, _, _, _)| *ctx_idx)
                            .collect::<Vec<_>>();
                        let mut tail_cache = self.make_batched_mtp_cache_from_rows(
                            model,
                            mtp,
                            &contexts,
                            row_states,
                            &ctx_indices,
                        )?;
                        let tail_tokens = full_accept_tail_commits
                            .iter()
                            .map(|(_, token, _, _)| *token)
                            .collect::<Vec<_>>();
                        let token_arr: Array =
                            (&tail_tokens[..], &[tail_tokens.len() as i32, 1_i32][..])
                                .try_into()?;
                        let prev_hidden_rows = full_accept_tail_commits
                            .iter()
                            .map(|(_, _, hidden, _)| hidden)
                            .collect::<Vec<_>>();
                        let prev_hidden = mlx::ops::shape::concatenate_on(
                            &prev_hidden_rows[..],
                            0,
                            mlx::StreamOrDevice::default(),
                        )?;
                        let position_ids = if model.requires_position_ids() {
                            let pos_rows = full_accept_tail_commits
                                .iter()
                                .map(|(_, _, _, pos)| pos)
                                .collect::<Vec<_>>();
                            mlx::ops::shape::concatenate_on(
                                &pos_rows[..],
                                1,
                                mlx::StreamOrDevice::default(),
                            )?
                        } else {
                            self.reusable_dummy_position_ids()?
                        };

                        let commit_start = Instant::now();
                        let mtp_hidden = model.mtp_forward_hidden_on(
                            mtp,
                            &prev_hidden,
                            &token_arr,
                            &position_ids,
                            None,
                            Some(&mut tail_cache),
                            mlx::StreamOrDevice::default(),
                        )?;
                        // The qualified affine8 B4 graph is consumed by the
                        // next draft window before its existing acceptance
                        // synchronization. Keeping the tail state lazy avoids
                        // a second per-window GPU barrier without changing the
                        // cache graph or numerical path.
                        if !affine8_b4_exact_hot_path {
                            mlx::transforms::eval(&[&mtp_hidden])?;
                        }
                        add_mtp_decode_cache_commit_us(stats, commit_start);

                        for (compact_idx, (ctx_idx, _, _, _)) in
                            full_accept_tail_commits.iter().enumerate()
                        {
                            let row_idx = contexts[*ctx_idx].row_idx;
                            row_states
                            .get_mut(&row_idx)
                            .ok_or_else(|| {
                                anyhow!(
                                    "fill_mtp_windows_batched: row {row_idx} state absent after batched tail commit"
                                )
                            })?
                            .mtp_cache
                            .adopt_row_from(&tail_cache, 0, compact_idx)?;
                        }
                    }
                    MtpBatchedTailCommitMode::PerRowCache => {
                        for (ctx_idx, token, prev_hidden, position_ids) in &full_accept_tail_commits
                        {
                            let row_idx = contexts[*ctx_idx].row_idx;
                            let row_state = row_states.get_mut(&row_idx).ok_or_else(|| {
                            anyhow!(
                                "fill_mtp_windows_batched: row {row_idx} state absent for row-cache tail commit"
                            )
                        })?;
                            row_state.deferred_tail_commit = Some(MtpDeferredTailCommit {
                                token: *token,
                                prev_hidden: prev_hidden.clone(),
                                position_ids: position_ids.clone(),
                            });
                        }
                    }
                }
            }

            let stats_delta = stats.saturating_delta_since(&stats_before_batch);
            let divisor = contexts.len() as u64;
            let batch_total_us = elapsed_us_since(window_started);
            let per_row_total_us = batch_total_us / divisor;
            for &(row_idx, attempted, accepted, context_tokens, committed_tokens) in &policy_inputs
            {
                let row_state = row_states.get_mut(&row_idx).ok_or_else(|| {
                    anyhow!(
                        "fill_mtp_windows_batched: row {row_idx} state absent for policy update"
                    )
                })?;
                let per_row_delta = divided_mtp_stats_timing(&stats_delta, divisor);
                let change =
                    row_state
                        .draft_policy
                        .observe_window(MtpDraftPolicyWindow::from_stats_delta(
                            attempted,
                            accepted,
                            committed_tokens,
                            per_row_total_us,
                            context_tokens,
                            policy_batch_width,
                            kv_state,
                            &per_row_delta,
                        ));
                if change.reduced {
                    stats.draft_budget_reductions = stats.draft_budget_reductions.saturating_add(1);
                } else if change.increased {
                    stats.draft_budget_increases = stats.draft_budget_increases.saturating_add(1);
                }
                row_state.adaptive_draft_tokens = row_state
                    .draft_policy
                    .current_budget()
                    .min(max_supported_draft_tokens);
                let policy_snapshot = row_state.draft_policy.snapshot();
                if attempted > 0 && accepted == attempted {
                    self.record_prompt_lookup_mtp_certification(
                        row_idx,
                        context_tokens,
                        attempted,
                        policy_snapshot,
                    );
                }
            }
            let timing_delta = stats
                .draft_cap_timing()
                .saturating_delta_since(timing_before);
            let draft_tokens_by_row = policy_inputs
                .iter()
                .map(|(_, attempted, _, _, _)| *attempted)
                .collect::<Vec<_>>();
            let context_tokens_by_row = policy_inputs
                .iter()
                .map(|(_, _, _, context_tokens, _)| *context_tokens)
                .collect::<Vec<_>>();
            let accepted_draft_tokens = policy_inputs
                .iter()
                .map(|(_, _, accepted, _, _)| *accepted)
                .sum();
            let committed_tokens = policy_inputs
                .iter()
                .map(|(_, _, _, _, committed)| *committed)
                .sum();
            stats.record_draft_cap_observation(
                max_supported_draft_tokens,
                &draft_tokens_by_row,
                &context_tokens_by_row,
                accepted_draft_tokens,
                committed_tokens,
                stats_delta.rollback_count,
                batch_total_us,
                timing_delta,
            );

            Ok(())
        })();

        verify_result?;

        self.refresh_active_kv_residency_stats();
        Ok(())
    }

    fn step_mtp_single_inner(
        &mut self,
        model: &M,
        mtp: &M::MtpHead,
        refill_after_emit: bool,
        projection: MtpTargetProjection,
        mut observations: Option<&mut Vec<CanonicalMtpWindowObservation>>,
    ) -> Result<Vec<StepEvent>>
    where
        M: MtpSpeculativeModel,
    {
        if self.phase != Phase::Decoding {
            return Err(anyhow!(
                "step_mtp_single illegal in {:?} phase: call prefill_admitted_mtp_single first",
                self.phase
            ));
        }
        let row_idx = self
            .slots
            .iter()
            .position(|slot| matches!(slot, Some(state) if !state.finished))
            .ok_or_else(|| anyhow!("step_mtp_single: no unfinished row"))?;
        anyhow::ensure!(
            self.active_count() == 1 && self.cache_rows.as_slice() == [row_idx],
            "step_mtp_single requires one active row with matching cache layout"
        );

        let ordinary_fallback = self
            .mtp_state
            .as_ref()
            .and_then(|state| state.rows.get(&row_idx))
            .is_some_and(|row| {
                row.pending_tokens.is_empty() && row.draft_policy.uses_ordinary_decode()
            });
        if ordinary_fallback {
            return self.step_inner(model);
        }

        if self
            .mtp_state
            .as_ref()
            .ok_or_else(|| anyhow!("step_mtp_single: MTP state absent"))?
            .rows
            .get(&row_idx)
            .ok_or_else(|| anyhow!("step_mtp_single: row MTP state absent"))?
            .pending_tokens
            .is_empty()
        {
            self.fill_mtp_window_single_with_projection_observed(
                row_idx,
                model,
                mtp,
                projection,
                reborrow_mtp_window_observations(&mut observations),
            )?;
        }

        let token = {
            let mtp_state = self
                .mtp_state
                .as_mut()
                .ok_or_else(|| anyhow!("step_mtp_single: MTP state absent"))?;
            mtp_state
                .rows
                .get_mut(&row_idx)
                .ok_or_else(|| anyhow!("step_mtp_single: row MTP state absent"))?
                .pending_tokens
                .pop_front()
                .ok_or_else(|| anyhow!("step_mtp_single: pending token queue is empty"))?
        };

        let event = self.emit_token_for_row(row_idx, token)?;
        let finish_reason = event.finish_reason;

        if finish_reason.is_some() {
            self.phase = Phase::Finished;
        } else if refill_after_emit
            && self
                .mtp_state
                .as_ref()
                .and_then(|state| state.rows.get(&row_idx))
                .is_some_and(|state| state.pending_tokens.is_empty())
        {
            self.fill_mtp_window_single_with_projection_observed(
                row_idx,
                model,
                mtp,
                projection,
                reborrow_mtp_window_observations(&mut observations),
            )?;
        }

        Ok(vec![event])
    }

    fn fill_mtp_window_single(&mut self, row_idx: usize, model: &M, mtp: &M::MtpHead) -> Result<()>
    where
        M: MtpSpeculativeModel,
    {
        self.fill_mtp_window_single_with_projection(
            row_idx,
            model,
            mtp,
            MtpTargetProjection::Neural,
        )
    }

    fn fill_mtp_window_single_with_projection(
        &mut self,
        row_idx: usize,
        model: &M,
        mtp: &M::MtpHead,
        projection: MtpTargetProjection,
    ) -> Result<()>
    where
        M: MtpSpeculativeModel,
    {
        self.fill_mtp_window_single_with_projection_observed(row_idx, model, mtp, projection, None)
    }

    fn fill_mtp_window_single_with_projection_observed(
        &mut self,
        row_idx: usize,
        model: &M,
        mtp: &M::MtpHead,
        projection: MtpTargetProjection,
        observation: Option<&mut Vec<CanonicalMtpWindowObservation>>,
    ) -> Result<()>
    where
        M: MtpSpeculativeModel,
    {
        let mut mtp_state = self
            .mtp_state
            .take()
            .ok_or_else(|| anyhow!("fill_mtp_window_single: MTP state absent"))?;
        let mut row_state = mtp_state
            .rows
            .remove(&row_idx)
            .ok_or_else(|| anyhow!("fill_mtp_window_single: row MTP state absent"))?;
        let result = self.fill_mtp_window_single_with_state(
            row_idx,
            MtpSingleWindowConfig {
                speculative: mtp_state.cfg,
                projection,
            },
            model,
            mtp,
            MtpSingleWindowState {
                stats: &mut mtp_state.stats,
                row: &mut row_state,
                observations: observation,
            },
        );
        mtp_state.rows.insert(row_idx, row_state);
        self.mtp_state = Some(mtp_state);
        result
    }

    fn fill_mtp_window_single_with_state(
        &mut self,
        row_idx: usize,
        window: MtpSingleWindowConfig,
        model: &M,
        mtp: &M::MtpHead,
        state: MtpSingleWindowState<'_>,
    ) -> Result<()>
    where
        M: MtpSpeculativeModel,
    {
        let MtpSingleWindowState {
            stats,
            row: row_state,
            observations,
        } = state;
        let (prompt_ids, generated_tokens, max_new_tokens, sampler, stop_token_ids, constraint) = {
            let state = self.slots[row_idx]
                .as_ref()
                .ok_or_else(|| anyhow!("fill_mtp_window_single: row slot absent"))?;
            (
                state.prompt_ids.clone(),
                state.generated_tokens.clone(),
                state.max_new_tokens,
                state.sampler,
                state.stop_token_ids.clone(),
                state.constraint.clone(),
            )
        };
        let emitted = generated_tokens.len();
        let remaining = max_new_tokens.saturating_sub(emitted);
        if remaining == 0 {
            return Ok(());
        }
        let current_token = *generated_tokens
            .last()
            .ok_or_else(|| anyhow!("fill_mtp_window_single: no current token"))?;
        let mut history = Vec::with_capacity(prompt_ids.len() + generated_tokens.len());
        history.extend_from_slice(&prompt_ids);
        history.extend_from_slice(&generated_tokens);

        let window_started = Instant::now();
        let stats_before_window = stats.clone();
        let timing_before = stats.draft_cap_timing();
        let context_tokens = history.len();
        let kv_state = MtpDraftPolicyKvState::from_runtime(
            self.paged_prefix_cache.is_some(),
            self.active_kv_config.enabled,
        );

        let max_supported_draft_tokens = window.speculative.max_draft_tokens;
        let draft_budget = row_state
            .adaptive_draft_tokens
            .min(max_supported_draft_tokens)
            .min(remaining);
        let maintain_mtp_cache = row_state.draft_policy.should_maintain_mtp_cache();
        let mut compact_prng = self.compact_prng_state_for_rows(&[row_idx])?;
        let mut draft_constraint = constraint.clone();
        let draft_result = self.draft_mtp_tokens_single_greedy_device(
            stats,
            row_state,
            model,
            mtp,
            current_token,
            draft_budget,
            history.len(),
            draft_constraint.as_mut(),
        )?;
        let current: Array = (&[current_token][..], &[1_i32, 1_i32][..]).try_into()?;
        let verify_arr = if draft_result.tokens.is_empty() {
            current.clone()
        } else {
            let mut token_steps = Vec::with_capacity(draft_result.tokens.len() + 1);
            token_steps.push(&current);
            token_steps.extend(draft_result.tokens.iter());
            mlx::ops::shape::concatenate_on(&token_steps, 1, mlx::StreamOrDevice::default())?
        };
        let draft_arr = if sampler.is_pipelinable() && constraint.is_none() {
            None
        } else {
            Some(mlx::ops::indexing::slice(
                &verify_arr,
                &[0_i32, 1_i32][..],
                &[1_i32, i32::try_from(draft_budget + 1)?][..],
            )?)
        };
        let mtp_cache_snapshot = draft_result.cache_snapshot;
        let verify_len = draft_budget + 1;
        let verify_start_pos = (prompt_ids.len() + generated_tokens.len() - 1) as i32;
        let verify_pos_ids = self.mtp_position_ids(model, verify_start_pos, verify_len as i32)?;
        let pre_window_hidden = row_state.last_hidden.clone();

        let base_snapshot = (draft_budget > 0).then(|| {
            let cache = self
                .cache
                .as_ref()
                .expect("main cache was initialized before MTP decode");
            cache.iter().map(LayerCache::snapshot).collect::<Vec<_>>()
        });
        let verify_forward_start = Instant::now();
        // A zero-draft window is an ordinary single-token target decode. Do
        // not force it through the exact speculative QMM path; there is no
        // drafted position whose result needs cross-shape verification.
        let _verify_qmm = (draft_budget > 0).then(crate::nn::verify_qmm::armed_scope);
        let verified_hidden = {
            let cache = self
                .cache
                .as_mut()
                .ok_or_else(|| anyhow!("fill_mtp_window_single: main cache absent"))?;
            model.forward_text_hidden(
                &verify_arr,
                &verify_pos_ids,
                None,
                None,
                Some(cache.as_mut_slice()),
                mlx::StreamOrDevice::default(),
            )?
        };
        add_elapsed_us(&mut stats.verify_forward_us, verify_forward_start);
        let (draft_tokens, resolution) =
            if draft_budget == 0 && sampler.is_pipelinable() && constraint.is_none() {
                let resolution = resolve_greedy_verified_hidden_until_mismatch(
                    model,
                    &verified_hidden,
                    &[],
                    stats,
                    mlx::StreamOrDevice::default(),
                )?;
                (Vec::new(), resolution)
            } else if sampler.is_pipelinable() {
                let projection_start = Instant::now();
                let verified_logits = project_mtp_target_hidden(
                    model,
                    &verified_hidden,
                    window.projection,
                    mlx::StreamOrDevice::default(),
                )?;
                let verified_logits = if let Some(constraint) = constraint.as_ref() {
                    let draft_arr = draft_arr
                        .as_ref()
                        .ok_or_else(|| anyhow!("constrained MTP draft array is absent"))?;
                    let sync_start = Instant::now();
                    let draft_tokens: Vec<u32> = draft_arr.to_vec()?;
                    stats.draft_host_sync_count = stats.draft_host_sync_count.saturating_add(1);
                    add_elapsed_us(&mut stats.draft_host_sync_us, sync_start);
                    crate::core::constrained::apply_speculative_token_masks(
                        &verified_logits,
                        &[Some(constraint.speculative_masks(&draft_tokens)?)],
                    )?
                } else {
                    verified_logits
                };
                add_elapsed_us(&mut stats.projection_us, projection_start);
                let sampling_start = Instant::now();
                let verified_ids = mlx::ops::reduction::argmax(&verified_logits, -1, false)?;
                let packed = pack_greedy_acceptance_on(
                    &verify_arr,
                    &[verify_len as i32],
                    &verified_ids,
                    mlx::StreamOrDevice::default(),
                )?;
                add_elapsed_us(&mut stats.sampling_us, sampling_start);
                let accept_sync_start = Instant::now();
                let packed: Vec<u32> = packed.to_vec()?;
                stats.verify_accept_host_sync_count =
                    stats.verify_accept_host_sync_count.saturating_add(1);
                add_elapsed_us(&mut stats.verify_accept_host_sync_us, accept_sync_start);
                resolve_packed_greedy_acceptance(&packed, verify_len + 1, 0, draft_budget)?
            } else {
                let projection_start = Instant::now();
                let verified_logits = project_mtp_target_hidden(
                    model,
                    &verified_hidden,
                    window.projection,
                    mlx::StreamOrDevice::default(),
                )?;
                add_elapsed_us(&mut stats.projection_us, projection_start);
                let sampling_start = Instant::now();
                let draft_arr = draft_arr.as_ref().ok_or_else(|| {
                    anyhow!("fill_mtp_window_single: non-greedy draft array absent")
                })?;
                let sync_start = Instant::now();
                let draft_tokens: Vec<u32> = draft_arr.to_vec()?;
                stats.draft_host_sync_count = stats.draft_host_sync_count.saturating_add(1);
                add_elapsed_us(&mut stats.draft_host_sync_us, sync_start);
                let verified_logits = if let Some(constraint) = constraint.as_ref() {
                    crate::core::constrained::apply_speculative_token_masks(
                        &verified_logits,
                        &[Some(constraint.speculative_masks(&draft_tokens)?)],
                    )?
                } else {
                    verified_logits
                };
                let resolution = resolve_exact_deterministic_target_logits(
                    &draft_tokens,
                    &verified_logits,
                    sampler,
                    &history,
                    &mut compact_prng,
                )?;
                let (draft_tokens, resolution) = (draft_tokens, resolution);
                add_elapsed_us(&mut stats.sampling_us, sampling_start);
                (draft_tokens, resolution)
            };
        let verify_input = verify_input(current_token, &draft_tokens);
        if let Some(observations) = observations {
            observations.push(CanonicalMtpWindowObservation {
                row_idx,
                draft_tokens: draft_tokens.clone(),
                accepted_draft_len: resolution.accepted_draft_len,
                bonus_token: resolution.tokens_to_append.get(draft_tokens.len()).copied(),
            });
        }

        stats.windows += 1;
        stats.drafted_tokens += draft_tokens.len();
        stats.accepted_draft_tokens += resolution.accepted_draft_len;
        stats.record_exact_sampling(resolution.exact_sampling);
        stats.record_window_acceptance(draft_tokens.len(), resolution.accepted_draft_len);
        if resolution.needs_rollback {
            stats.rollback_count += 1;
        }
        let accepted_len = resolution.accepted_verify_input_len;
        let (accepted_hidden, accepted_position_ids, accepted_last_hidden) = if resolution
            .needs_rollback
        {
            let accepted_position_ids = slice_position_ids_prefix(&verify_pos_ids, accepted_len)?;
            let rollback_start = Instant::now();
            let accepted_hidden = {
                let cache = self
                    .cache
                    .as_mut()
                    .ok_or_else(|| anyhow!("fill_mtp_window_single: main cache absent"))?;
                let base_snapshot = base_snapshot
                    .as_ref()
                    .ok_or_else(|| anyhow!("fill_mtp_window_single: rollback snapshot absent"))?;
                rollback_main_cache_to_accepted_prefix(
                    model,
                    cache.as_mut_slice(),
                    base_snapshot,
                    MainCacheRollbackInput {
                        accepted_by_row: &[(0, accepted_len)],
                        verify_input: &verify_input,
                        accepted_position_ids: &accepted_position_ids,
                        verified_hidden: &verified_hidden,
                    },
                    mlx::StreamOrDevice::default(),
                )?
            };
            add_elapsed_us(&mut stats.main_rollback_us, rollback_start);
            (
                accepted_hidden.clone(),
                accepted_position_ids,
                slice_hidden_position(&accepted_hidden, accepted_len as i32 - 1)?,
            )
        } else {
            (
                verified_hidden.clone(),
                verify_pos_ids.clone(),
                slice_hidden_position(&verified_hidden, accepted_len as i32 - 1)?,
            )
        };
        let accepted_input = verify_input[..accepted_len].to_vec();

        if resolution.needs_rollback {
            let trim_start = Instant::now();
            row_state.mtp_cache.trim_row_to_snapshot_prefix_len(
                &mtp_cache_snapshot,
                0,
                accepted_input.len(),
            )?;
            add_elapsed_us(&mut stats.mtp_cache_restore_us, trim_start);
        } else if maintain_mtp_cache {
            let commit_start = Instant::now();
            commit_mtp_cache_hidden_tail(
                model,
                mtp,
                &mut row_state.mtp_cache,
                &pre_window_hidden,
                &accepted_input,
                &accepted_hidden,
                &accepted_position_ids,
                mlx::StreamOrDevice::default(),
            )?;
            add_mtp_decode_cache_commit_us(stats, commit_start);
            stats.mtp_cache_reuse_count = stats.mtp_cache_reuse_count.saturating_add(1);
            stats.mtp_cache_reused_tokens = stats
                .mtp_cache_reused_tokens
                .saturating_add(accepted_input.len().saturating_sub(1));
        }
        row_state.last_hidden = accepted_last_hidden;

        let mut tokens_to_append = resolution.tokens_to_append;
        if let Some(stop_idx) = tokens_to_append
            .iter()
            .position(|token| stop_token_ids.contains(token))
        {
            tokens_to_append.truncate(stop_idx + 1);
        }
        tokens_to_append.truncate(remaining);
        if let Some(constraint) = constraint.as_ref() {
            constraint.truncate_invalid_speculative_bonus(&mut tokens_to_append)?;
        }
        let committed_tokens = tokens_to_append.len();
        row_state.pending_tokens.extend(tokens_to_append);
        let total_us = elapsed_us_since(window_started);
        let stats_delta = stats.saturating_delta_since(&stats_before_window);
        let change = row_state
            .draft_policy
            .observe_window(MtpDraftPolicyWindow::from_stats_delta(
                draft_tokens.len(),
                resolution.accepted_draft_len,
                committed_tokens,
                total_us,
                context_tokens,
                1,
                kv_state,
                &stats_delta,
            ));
        if change.reduced {
            stats.draft_budget_reductions = stats.draft_budget_reductions.saturating_add(1);
        } else if change.increased {
            stats.draft_budget_increases = stats.draft_budget_increases.saturating_add(1);
        }
        row_state.adaptive_draft_tokens = row_state
            .draft_policy
            .current_budget()
            .min(max_supported_draft_tokens);
        let timing_delta = stats
            .draft_cap_timing()
            .saturating_delta_since(timing_before);
        stats.record_draft_cap_observation(
            max_supported_draft_tokens,
            &[draft_tokens.len()],
            &[context_tokens],
            resolution.accepted_draft_len,
            committed_tokens,
            stats_delta.rollback_count,
            total_us,
            timing_delta,
        );
        if !draft_tokens.is_empty() && resolution.accepted_draft_len == draft_tokens.len() {
            self.record_prompt_lookup_mtp_certification(
                row_idx,
                verify_start_pos.max(0) as usize + 1,
                draft_tokens.len(),
                row_state.draft_policy.snapshot(),
            );
        }
        self.scatter_prng_state_from_rows(&[row_idx], &compact_prng)?;
        Ok(())
    }

    #[allow(clippy::too_many_arguments)]
    fn draft_mtp_tokens_single_greedy_device(
        &mut self,
        stats: &mut MtpSpeculativeStats,
        row_state: &mut SchedulerMtpRowState,
        model: &M,
        mtp: &M::MtpHead,
        current_token: u32,
        draft_budget: usize,
        history_len: usize,
        mut constraint: Option<&mut crate::core::constrained::ConstraintSession>,
    ) -> Result<MtpDeviceDraftResult>
    where
        M: MtpSpeculativeModel,
    {
        let cache_snapshot = row_state.mtp_cache.snapshot();
        let mut tokens = Vec::with_capacity(draft_budget);
        let mut input_hidden = row_state.last_hidden.clone();
        let mut input_token: Array = (&[current_token][..], &[1_i32, 1_i32][..]).try_into()?;
        let start_pos = history_len
            .checked_sub(1)
            .and_then(|value| i32::try_from(value).ok())
            .ok_or_else(|| anyhow!("draft_mtp_tokens_single_greedy_device: invalid history len"))?;

        for offset in 0..draft_budget {
            let position_ids = self.mtp_position_ids(model, start_pos + offset as i32, 1)?;
            let draft_forward_start = Instant::now();
            let output = model.mtp_forward_on(
                mtp,
                &input_hidden,
                &input_token,
                &position_ids,
                None,
                Some(&mut row_state.mtp_cache),
                mlx::StreamOrDevice::default(),
            )?;
            add_elapsed_us(&mut stats.draft_forward_us, draft_forward_start);
            let sampling_start = Instant::now();
            let next_token = if let Some(constraint) = constraint.as_mut() {
                let row_logits = slice_logits_row(&output.logits, 0)?;
                let row_logits = crate::core::constrained::apply_token_mask(
                    &row_logits,
                    &constraint.compute_mask()?,
                )?;
                let next = mlx::ops::reduction::argmax(&row_logits, -1, false)?;
                let token = next.item::<u32>()?;
                constraint.commit_token(token)?;
                (&[token][..], &[1_i32, 1_i32][..]).try_into()?
            } else {
                mlx::ops::reduction::argmax(&output.logits, -1, false)?
            };
            add_elapsed_us(&mut stats.sampling_us, sampling_start);
            tokens.push(next_token.clone());
            input_hidden = output.hidden_states;
            input_token = next_token;
        }

        Ok(MtpDeviceDraftResult {
            tokens,
            cache_snapshot,
        })
    }

    /// Run batched prefill for every currently-admitted request. Only legal
    /// in `Idle`/`Admitting` phase with `active_count() >= 1`.
    ///
    /// Allocates the batched KV cache on first call using the compact occupied
    /// row count (`B_prefill`, not `b_max`). Capacity is
    /// `min(max(prompt_len + max_new_tokens) over slots, effective_cap_max)`,
    /// bf16. Subsequent calls after `evict_all` allocate fresh — `evict_all`
    /// drops the cache (3f) so the next batch's cap is sized to its slots, not
    /// inherited from the prior batch.
    ///
    /// Builds a model-facing batch over occupied rows only. Its tensors are
    /// `[B_prefill, T_max]` input_ids and `[3, B_prefill, T_max]` position_ids.
    /// Equal-length rows use causal attention without an explicit mask;
    /// right-padded rows additionally build `[B_prefill, 1, T_max, T_max]`
    /// attention and `[B_prefill, T_max]` linear masks. The resulting cache
    /// remains compact; decode uses the same scheduler-row mapping rather than
    /// padding up to `b_max`.
    ///
    /// After prefill, samples the first token via a three-stage dispatch:
    /// Stage A collects per-row `sampler` refs + prompt histories in compact
    /// prefill order. Stage B reshapes `[B_prefill, 1, vocab]` →
    /// `[B_prefill, vocab]` and calls `sample_batch` once — coalescing
    /// all-greedy batches into a single GPU op rather than B serial kernel
    /// launches. Stage C distributes tokens back to their scheduler rows,
    /// checks EOS / `max_new_tokens`, and emits one [`StepEvent`] per occupied
    /// row. Transitions to `Decoding` (or `Finished` if every first token was
    /// EOS). See spec §4.5.
    pub fn prefill_admitted(&mut self, model: &M) -> Result<Vec<StepEvent>>
    where
        M: DenseVlMethods,
    {
        self.ensure_not_poisoned()?;
        let cold_materialization =
            self.begin_cold_materialization(self.active_materialization_components(false))?;
        match self.prefill_admitted_inner(model) {
            Ok(events) => {
                self.commit_all_governor_admissions();
                if let Some(guard) = cold_materialization {
                    guard.commit();
                }
                Ok(events)
            }
            Err(e) => {
                self.rollback_all_governor_admissions();
                self.poisoned = true;
                Err(e)
            }
        }
    }

    fn prefill_admitted_row_isolated(
        &mut self,
        model: &M,
        active_rows: &[usize],
    ) -> Result<Vec<StepEvent>>
    where
        M: DenseVlMethods,
    {
        self.discard_retained_immutable_prefix_cache();
        anyhow::ensure!(
            self.cache.is_none(),
            "prefill_admitted_row_isolated: cache already allocated before prefill"
        );
        let final_cap = self.prefill_cache_cap();
        let turboquant_bits = self.kv_cache_turboquant_bits_for_rows(active_rows)?;
        let mut final_cache = self.make_model_cache_for_rows(
            model,
            active_rows,
            final_cap,
            model.cache_dtype(),
            turboquant_bits,
        )?;
        let mut events = Vec::with_capacity(active_rows.len());

        for (compact_row, &row_idx) in active_rows.iter().enumerate() {
            let mut temp = self.temp_mtp_scheduler_for_row(row_idx)?;
            let row_events = temp.prefill_admitted_inner(model).map_err(|error| {
                anyhow!("prefill_admitted_row_isolated row {row_idx}: {error:#}")
            })?;
            temp.commit_all_governor_admissions();
            let temp_prng_key = temp.prng_key_for_row(0)?;
            let temp_cache = temp.cache.take().ok_or_else(|| {
                anyhow!("prefill_admitted_row_isolated row {row_idx}: temp cache absent")
            })?;
            let temp_slot = temp.slots[0].as_ref().ok_or_else(|| {
                anyhow!("prefill_admitted_row_isolated row {row_idx}: temp slot absent")
            })?;
            let slot = self.slots[row_idx]
                .as_mut()
                .expect("active row implies slot is Some");
            slot.generated_tokens = temp_slot.generated_tokens.clone();
            slot.real_len = temp_slot.real_len;
            slot.finished = temp_slot.finished;
            slot.finish_reason = temp_slot.finish_reason;
            slot.constraint = temp_slot.constraint.clone();
            adopt_cache_row_layers(
                &mut final_cache,
                &temp_cache,
                compact_row,
                0,
                "prefill_admitted_row_isolated",
            )?;
            self.write_row_prng_host(row_idx, temp_prng_key)?;
            events.extend(row_events);
        }

        let all_finished = active_rows.iter().all(|&row| {
            self.slots[row]
                .as_ref()
                .expect("active row implies slot is Some")
                .finished
        });
        self.cache = Some(final_cache);
        self.cache_rows = active_rows.to_vec();
        self.phase = if all_finished {
            Phase::Finished
        } else {
            Phase::Decoding
        };
        Ok(events)
    }

    fn prefill_admitted_inner(&mut self, model: &M) -> Result<Vec<StepEvent>>
    where
        M: DenseVlMethods,
    {
        match self.phase {
            Phase::Idle | Phase::Admitting => {}
            Phase::Decoding | Phase::Finished => {
                return Err(anyhow!(
                    "prefill_admitted illegal in {:?} phase: call evict_all first",
                    self.phase
                ));
            }
        }
        let active_rows: Vec<usize> = self
            .slots
            .iter()
            .enumerate()
            .filter_map(|(row, slot)| slot.as_ref().map(|_| row))
            .collect();
        if active_rows.is_empty() {
            return Err(anyhow!("prefill_admitted: no admitted requests to prefill"));
        }

        if active_rows.len() > 1
            && model.requires_split_batched_prefill_for_token_parity()
            && active_rows.iter().all(|&row| {
                self.slots[row]
                    .as_ref()
                    .is_some_and(|state| state.pixel_values.is_none())
            })
        {
            return self.prefill_admitted_row_isolated(model, &active_rows);
        }

        let prefill_rows = active_rows;

        // Build the model-facing prefill batch in active slot order. When
        // there are empty scheduler slots, the model and cache see only
        // occupied rows.
        let prompt_lens: Vec<i32> = prefill_rows
            .iter()
            .map(|&row| {
                self.slots[row]
                    .as_ref()
                    .expect("prefill_rows contain only occupied slots")
                    .prompt_ids
                    .len() as i32
            })
            .collect();
        let max_len = prompt_lens.iter().copied().max().unwrap_or(0);
        if max_len <= 0 {
            return Err(anyhow!(
                "prefill_admitted: max prompt length is 0 — all admitted prompts are empty"
            ));
        }

        // Build [B_prefill, T_max] right-padded input_ids (pad value 0).
        let b = prefill_rows.len();
        let t = max_len as usize;
        let configured_chunk_size = (b == 1)
            .then(|| {
                self.slots[prefill_rows[0]]
                    .as_ref()
                    .expect("prefill row is occupied")
                    .prefill_chunk_size
            })
            .filter(|&chunk_size| chunk_size > 0)
            .and_then(|chunk_size| usize::try_from(chunk_size).ok());
        let requested_tokens = configured_chunk_size.map_or(t, |chunk_size| t.min(chunk_size));
        let prefill_plan = self.plan_prefill_chunk(requested_tokens, 0, b)?;
        let selected_tokens = prefill_plan
            .as_ref()
            .map_or(requested_tokens, |plan| plan.selected_tokens);
        if selected_tokens < t {
            if b == 1 {
                drop(prefill_plan);
                return self.prefill_single_adaptive_chunks(
                    model,
                    prefill_rows[0],
                    selected_tokens,
                );
            }
            let plan = prefill_plan.as_ref().expect("batched prefill plan exists");
            return Err(anyhow::Error::new(SchedulerError::PrefillPeakUnsafe {
                requested_tokens: t,
                selected_tokens: plan.selected_tokens,
                target_bytes: plan.target_bytes,
            }));
        }
        let mut flat: Vec<i32> = vec![0; b * t];
        for (batch_row, &slot_row) in prefill_rows.iter().enumerate() {
            let state = self.slots[slot_row]
                .as_ref()
                .expect("prefill_rows contain only occupied slots");
            for (j, &tok) in state.prompt_ids.iter().enumerate() {
                flat[batch_row * t + j] = tok as i32;
            }
            // positions [state.prompt_ids.len() .. t] stay 0 (pad)
        }
        let input_ids: Array = (&flat[..], &[b as i32, max_len][..])
            .try_into()
            .map_err(|e| anyhow!("input_ids try_into Array failed: {e:?}"))?;

        // B1-p2.4: detect any VL row. Dispatch determines both position_ids
        // builder and prefill entry point.
        let any_vl = prefill_rows.iter().any(|&row| {
            self.slots[row]
                .as_ref()
                .is_some_and(|r| r.pixel_values.is_some())
        });
        let per_row_pv_owned: Vec<Option<Vec<Array>>> = prefill_rows
            .iter()
            .map(|&row| {
                self.slots[row]
                    .as_ref()
                    .expect("prefill_rows contain only occupied slots")
                    .pixel_values
                    .clone()
            })
            .collect();
        let per_row_grids_owned: Vec<Option<Vec<(i32, i32, i32)>>> = prefill_rows
            .iter()
            .map(|&row| {
                self.slots[row]
                    .as_ref()
                    .expect("prefill_rows contain only occupied slots")
                    .image_grid_thw
                    .clone()
            })
            .collect();
        let per_row_pv: Vec<PixelValuesSlice<'_>> =
            per_row_pv_owned.iter().map(|opt| opt.as_deref()).collect();
        let per_row_grids: Vec<GridThwSlice<'_>> = per_row_grids_owned
            .iter()
            .map(|opt| opt.as_deref())
            .collect();
        let _vision_reservation = if any_vl {
            reserve_vision_prefill(
                self.process_memory_governor.as_ref(),
                model,
                &per_row_pv,
                &per_row_grids,
            )?
        } else {
            None
        };

        // Allocate the compact cache exactly to the occupied scheduler rows.
        let cap = self.prefill_cache_cap();
        let turboquant_bits = self.kv_cache_turboquant_bits_for_rows(&prefill_rows)?;
        self.install_initial_cache_for_rows(
            model,
            &prefill_rows,
            cap,
            model.cache_dtype(),
            turboquant_bits,
        )?;
        let dummy_position_ids = if model.requires_position_ids() {
            None
        } else {
            Some(self.reusable_dummy_position_ids()?)
        };
        let paged_prefix_cache_config = self.paged_prefix_cache.clone();
        let prefix_lru_cache = self.prefix_lru_cache.clone();
        let mut immutable_replay_from = vec![0_usize; b];
        let mut prefix_restore_attempted = vec![false; b];
        let immutable_fullpaged_enabled = !any_vl
            && turboquant_bits.is_none()
            && self.cache.as_deref().is_some_and(cache_is_fullpaged_only);
        if immutable_fullpaged_enabled {
            let prompt_ids = prefill_rows
                .iter()
                .map(|&slot_row| {
                    self.slots[slot_row]
                        .as_ref()
                        .expect("prefill row remained occupied")
                        .prompt_ids
                        .clone()
                })
                .collect::<Vec<_>>();
            if let Some(cache) = self.cache.as_mut() {
                for group in prefix_restore_groups(&prompt_ids, None)? {
                    let first_row = group[0];
                    let group_len = group.len();
                    let restored = try_restore_paged_prefix_for_prompt_rows(
                        paged_prefix_cache_config.as_ref(),
                        prefix_lru_cache.as_ref(),
                        cache,
                        &group,
                        &prompt_ids[first_row],
                        None,
                    )?
                    .unwrap_or(0) as usize;
                    self.runtime_usage.record_prefix_cache_hit_tokens(
                        (restored as u64).saturating_mul(group_len as u64),
                    );
                    for row in group {
                        immutable_replay_from[row] = restored;
                        prefix_restore_attempted[row] = true;
                    }
                }
            }
            let restore_inputs = prefill_rows
                .iter()
                .map(|&slot_row| {
                    let state = self.slots[slot_row]
                        .as_ref()
                        .expect("prefill row remained occupied");
                    let owner = self
                        .request_block_tables
                        .get(&state.id)
                        .expect("prefill request block table exists")
                        .owner;
                    (owner, state.prompt_ids.clone())
                })
                .collect::<Vec<_>>();
            let prefix_config = self.paged_prefix_cache.clone();
            let memory_governor = self.process_memory_governor.clone();
            if let (Some(pool), Some(cache)) =
                (self.immutable_prefix_blocks.as_mut(), self.cache.as_mut())
            {
                for (cache_row, (owner, prompt_ids)) in restore_inputs.iter().enumerate() {
                    if immutable_replay_from[cache_row] > 0 {
                        continue;
                    }
                    if let Some(restored) = restore_immutable_prefix_blocks(
                        pool,
                        cache,
                        prefix_config.as_ref(),
                        memory_governor.as_ref(),
                        *owner,
                        prompt_ids,
                    )? {
                        self.runtime_usage
                            .record_prefix_cache_hit_tokens(restored as u64);
                        immutable_replay_from[cache_row] = usize::try_from(restored)
                            .map_err(|_| anyhow!("negative immutable restore length"))?;
                        tracing::debug!(
                            cache_row,
                            restored,
                            "FullPaged immutable prefix block hit"
                        );
                    }
                }
            }
        }
        if immutable_fullpaged_enabled {
            let targets = prefill_rows
                .iter()
                .map(|&slot_row| {
                    let state = self.slots[slot_row]
                        .as_ref()
                        .expect("prefill row remained occupied");
                    let owner = self
                        .request_block_tables
                        .get(&state.id)
                        .ok_or_else(|| anyhow!("prefill request block table absent"))?
                        .owner;
                    Ok((owner, state.prompt_ids.len()))
                })
                .collect::<Result<Vec<_>>>()?;
            if let (Some(pool), Some(cache)) =
                (self.immutable_prefix_blocks.as_mut(), self.cache.as_mut())
            {
                reclaim_idle_immutable_blocks_for_targets(pool, cache, &targets)?;
            }
        }

        // Run prefill. Capture [B, 1, vocab] logits (sequence axis already
        // collapsed via slice_last_and_project) for first-token sampling.
        // Single-row batches use the single-stream model API so text and VL
        // requests avoid right-pad masks that have no semantic work at B=1.

        let logits_result: anyhow::Result<Array> = (|| -> anyhow::Result<Array> {
            let prefill_cache = self
                .cache
                .as_mut()
                .ok_or_else(|| anyhow!("cache missing after allocation — internal bug"))?
                .as_mut_slice();
            let logits = if any_vl {
                // Collect per-row prompt ids, vision args, and tokenizer constants in compact cache order.
                let per_row_ids_i32: Vec<Vec<i32>> = prefill_rows
                    .iter()
                    .map(|&row| {
                        self.slots[row]
                            .as_ref()
                            .expect("prefill_rows contain only occupied slots")
                            .prompt_ids
                            .iter()
                            .map(|&t| t as i32)
                            .collect()
                    })
                    .collect();
                let per_row_ids_refs: Vec<&[i32]> =
                    per_row_ids_i32.iter().map(|v| v.as_slice()).collect();
                // Tokenizer-defined constants from the first VL slot.
                let (img_token_id, merge_size) = prefill_rows
                    .iter()
                    .find_map(|&row| {
                        self.slots[row]
                            .as_ref()
                            .filter(|r| r.pixel_values.is_some())
                            .map(|r| (r.image_token_id, r.image_spatial_merge_size))
                    })
                    .expect("any_vl == true implies at least one VL slot");

                if b == 1 {
                    let grids = per_row_grids[0].ok_or_else(|| {
                        anyhow!("single-row VL prefill: pixel_values present but grid_thw is None")
                    })?;
                    let position_ids_full = if let Some(dummy) = dummy_position_ids.as_ref() {
                        dummy.clone()
                    } else if grids.is_empty() {
                        build_position_ids(0, max_len)?
                    } else {
                        build_position_ids_vl(&per_row_ids_i32[0], grids, img_token_id, merge_size)?
                    };
                    let vision_embeds_full = if grids.is_empty() {
                        None
                    } else {
                        let pv = per_row_pv[0].ok_or_else(|| {
                            anyhow!(
                                "single-row VL prefill: grid_thw present but pixel_values is None"
                            )
                        })?;
                        Some(model.compute_vision_embeds(
                            pv,
                            grids,
                            mlx::StreamOrDevice::default(),
                        )?)
                    };
                    let prompt_ids_u32: Vec<u32> =
                        per_row_ids_i32[0].iter().map(|&tok| tok as u32).collect();
                    let vl_prefix_fingerprint = if paged_prefix_cache_config.is_some() {
                        paged_prefix_fingerprint_for_request(
                            per_row_pv[0],
                            per_row_grids[0],
                            img_token_id,
                            merge_size,
                        )?
                    } else {
                        None
                    };
                    if let Some(start_pos) = try_restore_paged_prefix_for_prompt(
                        paged_prefix_cache_config.as_ref(),
                        prefix_lru_cache.as_ref(),
                        prefill_cache,
                        &prompt_ids_u32,
                        vl_prefix_fingerprint.as_deref(),
                    )? {
                        self.runtime_usage
                            .record_prefix_cache_hit_tokens(start_pos as u64);
                        forward_single_vl_suffix(
                            model,
                            prefill_cache,
                            SingleVlSuffixInput {
                                prompt_ids: &per_row_ids_i32[0],
                                start_pos,
                                end_pos: max_len,
                                position_ids_full: &position_ids_full,
                                position_ids_is_dummy: dummy_position_ids.is_some(),
                                vision_embeds_full: vision_embeds_full.as_ref(),
                                image_token_id: img_token_id,
                            },
                        )?
                    } else if max_len > 1 {
                        let prefix_len = max_len - 1;
                        let prefix_input_ids = mlx::ops::indexing::slice_strided(
                            &input_ids,
                            &[0_i32, 0][..],
                            &[1_i32, prefix_len][..],
                            &[1_i32, 1][..],
                        )?;
                        let last_input_ids = mlx::ops::indexing::slice_strided(
                            &input_ids,
                            &[0_i32, prefix_len][..],
                            &[1_i32, max_len][..],
                            &[1_i32, 1][..],
                        )?;
                        let (prefix_position_ids, last_position_ids) =
                            if dummy_position_ids.is_some() {
                                (position_ids_full.clone(), position_ids_full.clone())
                            } else {
                                (
                                    slice_pos_ids_axis2(&position_ids_full, 0, prefix_len)?,
                                    slice_pos_ids_axis2(&position_ids_full, prefix_len, max_len)?,
                                )
                            };

                        let prompt_ids = &per_row_ids_i32[0];
                        let prefix_image_pads = prompt_ids[..prefix_len as usize]
                            .iter()
                            .filter(|&&tok| tok == img_token_id)
                            .count();
                        let last_image_pads = prompt_ids[prefix_len as usize..max_len as usize]
                            .iter()
                            .filter(|&&tok| tok == img_token_id)
                            .count();
                        let prefix_vision_embeds = match vision_embeds_full.as_ref() {
                            Some(ve) if prefix_image_pads > 0 => {
                                Some(slice_vision_embeds_rows(ve, 0, prefix_image_pads)?)
                            }
                            // Mla: matches on vision_embeds_full Option (VL-only path), not LayerCache — GLM is text-only, never reaches here.
                            _ => None,
                        };
                        let last_vision_embeds = match vision_embeds_full.as_ref() {
                            Some(ve) if last_image_pads > 0 => Some(slice_vision_embeds_rows(
                                ve,
                                prefix_image_pads,
                                prefix_image_pads + last_image_pads,
                            )?),
                            // Mla: matches on vision_embeds_full Option (VL-only path), not LayerCache — GLM is text-only, never reaches here.
                            _ => None,
                        };

                        let prefix_hidden = model.forward_vl_hidden(
                            &prefix_input_ids,
                            &prefix_position_ids,
                            None,
                            None,
                            Some(&mut *prefill_cache),
                            prefix_vision_embeds.as_ref(),
                            img_token_id,
                            mlx::StreamOrDevice::default(),
                        )?;
                        // Commit the prefix chunk's lazy KV-cache writes before the
                        // last-token chunk reads the SAME cache. Without this barrier the
                        // prefix-write → last-read chain fuses into one lazy graph whose
                        // read-after-write on the shared mutable cache buffer MLX
                        // intermittently miscomputes to all-NaN logits (→ argmax 0 = <pad>
                        // → empty output) on all-KVCache models such as Gemma4. Evaluating
                        // the prefix hidden transitively materializes the per-layer
                        // slice_update/concatenate cache writes it depends on via attention.
                        mlx::transforms::eval(&[&prefix_hidden])?;

                        match try_save_paged_prefix_for_prompt(
                            paged_prefix_cache_config.as_ref(),
                            prefix_lru_cache.as_ref(),
                            prefill_cache,
                            &prompt_ids_u32[..prefix_len as usize],
                            vl_prefix_fingerprint.as_deref(),
                        ) {
                            Ok(Some(key)) => {
                                tracing::debug!(
                                    "paged SSD prefix cache saved VL prefix: key={key}"
                                );
                            }
                            Ok(None) => {}
                            Err(err) => {
                                tracing::warn!(
                                    "paged SSD prefix cache VL prefix save skipped: {err:#}"
                                );
                            }
                        }

                        model.forward_vl_chunk(
                            &last_input_ids,
                            &last_position_ids,
                            None,
                            None,
                            Some(&mut *prefill_cache),
                            last_vision_embeds.as_ref(),
                            img_token_id,
                            mlx::StreamOrDevice::default(),
                        )?
                    } else {
                        model.forward_vl_chunk(
                            &input_ids,
                            &position_ids_full,
                            None,
                            None,
                            Some(prefill_cache),
                            vision_embeds_full.as_ref(),
                            img_token_id,
                            mlx::StreamOrDevice::default(),
                        )?
                    }
                } else if paged_prefix_cache_config.is_some() {
                    forward_batched_vl_with_paged_prefix(
                        model,
                        prefill_cache,
                        BatchedVlPrefixReplay {
                            prompt_ids: &per_row_ids_i32,
                            pixel_values: &per_row_pv,
                            grid_thw: &per_row_grids,
                            image_token_id: img_token_id,
                            image_spatial_merge_size: merge_size,
                            dummy_position_ids: dummy_position_ids.as_ref(),
                            prefix_cache_config: paged_prefix_cache_config.as_ref(),
                            prefix_lru_cache: prefix_lru_cache.as_ref(),
                            runtime_usage: &self.runtime_usage,
                        },
                    )?
                } else {
                    let attention_mask =
                        build_batch_attention_mask(&prompt_lens, max_len, Dtype::Bfloat16)?;
                    let linear_attention_mask = build_batch_linear_mask(&prompt_lens, max_len)?;
                    let position_ids = if let Some(dummy) = dummy_position_ids.as_ref() {
                        dummy.clone()
                    } else {
                        build_position_ids_vl_batched(
                            &per_row_ids_refs,
                            &per_row_grids,
                            img_token_id,
                            merge_size,
                            max_len,
                        )?
                    };

                    model.batched_prefill_vl(
                        &input_ids,
                        &position_ids,
                        &attention_mask,
                        &linear_attention_mask,
                        &prompt_lens,
                        &per_row_pv,
                        &per_row_grids,
                        img_token_id,
                        Some(prefill_cache),
                        mlx::StreamOrDevice::default(),
                    )?
                }
            } else if b == 1 {
                let prompt_ids = &self.slots[prefill_rows[0]]
                    .as_ref()
                    .expect("prefill_rows contain only occupied slots")
                    .prompt_ids;
                if immutable_replay_from[0] > 0 {
                    forward_single_text_suffix(
                        model,
                        prefill_cache,
                        prompt_ids,
                        immutable_replay_from[0] as i32,
                        max_len,
                        dummy_position_ids.as_ref(),
                    )?
                } else if let Some(start_pos) = try_restore_paged_prefix_for_prompt(
                    paged_prefix_cache_config.as_ref(),
                    prefix_lru_cache.as_ref(),
                    prefill_cache,
                    prompt_ids,
                    None,
                )? {
                    self.runtime_usage
                        .record_prefix_cache_hit_tokens(start_pos as u64);
                    forward_single_text_suffix(
                        model,
                        prefill_cache,
                        prompt_ids,
                        start_pos,
                        max_len,
                        dummy_position_ids.as_ref(),
                    )?
                } else if max_len > 1 {
                    let prefix_len = max_len - 1;
                    let prefix_input_ids = mlx::ops::indexing::slice_strided(
                        &input_ids,
                        &[0_i32, 0][..],
                        &[1_i32, prefix_len][..],
                        &[1_i32, 1][..],
                    )?;
                    let prefix_position_ids = if let Some(dummy) = dummy_position_ids.as_ref() {
                        dummy.clone()
                    } else {
                        build_position_ids(0, prefix_len)?
                    };
                    let prefix_hidden = model.forward_text_hidden(
                        &prefix_input_ids,
                        &prefix_position_ids,
                        None,
                        None,
                        Some(&mut *prefill_cache),
                        mlx::StreamOrDevice::default(),
                    )?;
                    // Commit the prefix chunk's lazy KV-cache writes before the last-token
                    // chunk reads the shared cache (see the VL split site above for the
                    // all-NaN read-after-write rationale; same b==1 split-prefill hazard).
                    mlx::transforms::eval(&[&prefix_hidden])?;

                    match try_save_paged_prefix_for_prompt(
                        paged_prefix_cache_config.as_ref(),
                        prefix_lru_cache.as_ref(),
                        prefill_cache,
                        &prompt_ids[..prefix_len as usize],
                        None,
                    ) {
                        Ok(Some(key)) => {
                            tracing::debug!("paged SSD prefix cache saved prefix: key={key}");
                        }
                        Ok(None) => {}
                        Err(err) => {
                            tracing::warn!("paged SSD prefix cache prefix save skipped: {err:#}");
                        }
                    }

                    let last_input_ids = mlx::ops::indexing::slice_strided(
                        &input_ids,
                        &[0_i32, prefix_len][..],
                        &[1_i32, max_len][..],
                        &[1_i32, 1][..],
                    )?;
                    let last_position_ids = if let Some(dummy) = dummy_position_ids.as_ref() {
                        dummy.clone()
                    } else {
                        build_position_ids(prefix_len, 1)?
                    };
                    model.forward_on(
                        &last_input_ids,
                        &last_position_ids,
                        None,
                        None,
                        Some(&mut *prefill_cache),
                        mlx::StreamOrDevice::default(),
                    )?
                } else {
                    let position_ids = if let Some(dummy) = dummy_position_ids.as_ref() {
                        dummy.clone()
                    } else {
                        build_position_ids(0, max_len)?
                    };
                    model.forward_on(
                        &input_ids,
                        &position_ids,
                        None,
                        None,
                        Some(prefill_cache),
                        mlx::StreamOrDevice::default(),
                    )?
                }
            } else if paged_prefix_cache_config.is_some() {
                let per_row_prompt_ids: Vec<Vec<u32>> = prefill_rows
                    .iter()
                    .map(|&row| {
                        self.slots[row]
                            .as_ref()
                            .expect("prefill_rows contain only occupied slots")
                            .prompt_ids
                            .clone()
                    })
                    .collect();
                forward_batched_text_with_paged_prefix(
                    model,
                    prefill_cache,
                    BatchedTextPrefixReplay {
                        prompt_ids: &per_row_prompt_ids,
                        initial_replay_from: &immutable_replay_from,
                        prefix_restore_attempted: &prefix_restore_attempted,
                        dummy_position_ids: dummy_position_ids.as_ref(),
                        prefix_cache_config: paged_prefix_cache_config.as_ref(),
                        prefix_lru_cache: prefix_lru_cache.as_ref(),
                        runtime_usage: &self.runtime_usage,
                    },
                )?
            } else {
                let position_ids = if let Some(dummy) = dummy_position_ids.as_ref() {
                    dummy.clone()
                } else {
                    build_position_ids_batched(&prompt_lens, max_len)?
                };
                forward_batched_text_prefill(
                    model,
                    &input_ids,
                    &position_ids,
                    &prompt_lens,
                    max_len,
                    Some(prefill_cache),
                    mlx::StreamOrDevice::default(),
                )?
            };
            Ok(logits)
        })();
        let logits = logits_result?;
        if b == 1 {
            let (prompt_ids, prefix_fingerprint) = {
                let state = self.slots[prefill_rows[0]]
                    .as_ref()
                    .expect("prefill_rows contain only occupied slots");
                let prefix_fingerprint = if paged_prefix_cache_config.is_some() {
                    paged_prefix_fingerprint_for_request(
                        state.pixel_values.as_deref(),
                        state.image_grid_thw.as_deref(),
                        state.image_token_id,
                        state.image_spatial_merge_size,
                    )?
                } else {
                    None
                };
                (state.prompt_ids.clone(), prefix_fingerprint)
            };
            if let Some(cache) = self.cache.as_ref() {
                match try_save_paged_prefix_for_prompt(
                    paged_prefix_cache_config.as_ref(),
                    prefix_lru_cache.as_ref(),
                    cache,
                    &prompt_ids,
                    prefix_fingerprint.as_deref(),
                ) {
                    Ok(Some(key)) => {
                        tracing::debug!("paged SSD prefix cache saved: key={key}");
                    }
                    Ok(None) => {}
                    Err(err) => {
                        tracing::warn!("paged SSD prefix cache save skipped: {err:#}");
                    }
                }
            }
        }

        // After per-row prefill, row i's cache is filled up to position
        // prompt_lens[i] - 1. The first decode step must use position
        // prompt_lens[i] for that row.
        for (&slot_row, &plen) in prefill_rows.iter().zip(prompt_lens.iter()) {
            let state = self.slots[slot_row]
                .as_mut()
                .expect("prefill_rows contain only occupied slots");
            state.real_len = plen;
        }

        // Sample first token per occupied row from logits[:, 0, :].
        // batched_prefill returns [B, 1, vocab]. Reshape to [B, vocab] for
        // sample_batch, then dispatch once to coalesce all-greedy batches.

        let logits_shape = logits.shape();
        let vocab = logits_shape.as_slice()[2];
        let logits_bv_result = logits.reshape(&[b as i32, vocab][..]).map_err(|e| {
            anyhow!("prefill_admitted: reshape logits [B,1,vocab]->[B,vocab] failed: {e:?}")
        });

        let logits_bv = match logits_bv_result {
            Ok(value) => value,
            Err(err) => {
                return Err(err);
            }
        };
        let constraint_masks = prefill_rows
            .iter()
            .map(|&slot_row| {
                self.slots[slot_row]
                    .as_mut()
                    .expect("prefill row is occupied")
                    .constraint
                    .as_mut()
                    .map(crate::core::constrained::ConstraintSession::compute_mask)
                    .transpose()
            })
            .collect::<Result<Vec<_>>>()?;
        let logits_bv =
            crate::core::constrained::apply_batch_token_masks(&logits_bv, &constraint_masks)?;

        // Stage A — collect per-row sampler refs + histories in compact prefill order.
        let mut row_samplers: Vec<&Sampler> = Vec::with_capacity(b);
        let mut row_histories: Vec<Vec<u32>> = Vec::with_capacity(b);
        for &slot_row in &prefill_rows {
            let state = self.slots[slot_row]
                .as_ref()
                .expect("prefill_rows contain only occupied slots");
            row_samplers.push(&state.sampler);
            row_histories.push(state.prompt_ids.clone());
        }

        // Close the prepare span BEFORE opening the materialize sibling so
        // both intervals stay strictly contained under root and disjoint
        // from each other (per § 2.5a interval containment).

        // Stage B — dispatch sample_batch once over [B, vocab]. `sample_batch`
        // internally calls `.to_vec()` which forces the entire prefill graph
        // to materialize; this wrapper makes that cost attributable.
        let mut compact_prng = self.compact_prng_state_for_rows(&prefill_rows)?;
        let history_refs: Vec<&[u32]> = row_histories.iter().map(|h| h.as_slice()).collect();
        let sample_result = crate::core::sampler::sample_batch(
            &row_samplers,
            &logits_bv,
            &history_refs,
            &mut compact_prng,
        )
        .map_err(|e| anyhow!("prefill_admitted: sample_batch failed: {e:?}"));

        let tokens = sample_result?;
        drop(prefill_plan);
        drop(history_refs);
        drop(row_samplers);
        self.scatter_prng_state_from_rows(&prefill_rows, &compact_prng)?;

        if immutable_fullpaged_enabled {
            let publish_inputs = prefill_rows
                .iter()
                .map(|&slot_row| {
                    let state = self.slots[slot_row]
                        .as_ref()
                        .expect("prefill row remained occupied");
                    let owner = self
                        .request_block_tables
                        .get(&state.id)
                        .expect("prefill request block table exists")
                        .owner;
                    (owner, state.prompt_ids.clone())
                })
                .collect::<Vec<_>>();
            let prefix_config = self.paged_prefix_cache.clone();
            if let (Some(pool), Some(cache)) =
                (self.immutable_prefix_blocks.as_mut(), self.cache.as_mut())
            {
                for (owner, prompt_ids) in publish_inputs {
                    let reusable_len = prompt_ids.len().saturating_sub(1);
                    let published = publish_immutable_prefix_blocks(
                        pool,
                        cache,
                        prefix_config.as_ref(),
                        owner,
                        &prompt_ids[..reusable_len],
                    )?;
                    if published > 0 {
                        tracing::debug!(
                            published,
                            request_owner = ?owner,
                            "FullPaged immutable prefix blocks published"
                        );
                    }
                }
            }
        }

        // Stage C — distribute tokens + termination per occupied row.
        let mut events: Vec<StepEvent> = Vec::new();
        for (batch_row, &token) in tokens.iter().enumerate() {
            let slot_row = prefill_rows[batch_row];
            let state = self.slots[slot_row]
                .as_mut()
                .expect("prefill_rows contain only occupied slots");

            state.generated_tokens.push(token);
            if let Some(constraint) = state.constraint.as_mut() {
                constraint.commit_token(token)?;
            }
            state.real_len += 1;

            if state.stop_token_ids.contains(&token) {
                state.finished = true;
                state.finish_reason = Some("stop");
            } else if state.generated_tokens.len() >= state.max_new_tokens {
                state.finished = true;
                state.finish_reason = Some("length");
            }

            events.push(StepEvent {
                id: state.id,
                token,
                finish_reason: state.finish_reason,
            });
        }

        // Phase transition: Finished if every occupied row already done (rare
        // corner case — first token of every prompt was EOS), else Decoding.
        let any_unfinished = self
            .slots
            .iter()
            .any(|s| matches!(s, Some(r) if !r.finished));
        self.phase = if any_unfinished {
            Phase::Decoding
        } else {
            Phase::Finished
        };

        Ok(events)
    }

    fn prefill_single_adaptive_chunks(
        &mut self,
        model: &M,
        row_idx: usize,
        chunk_size: usize,
    ) -> Result<Vec<StepEvent>>
    where
        M: DenseVlMethods,
    {
        let id = self.slots[row_idx]
            .as_ref()
            .ok_or_else(|| anyhow!("adaptive prefill row is absent"))?
            .id;
        self.discard_retained_immutable_prefix_cache();
        let cap = self.prefill_cache_cap();
        let turboquant_bits = self.kv_cache_turboquant_bits_for_rows(&[row_idx])?;
        self.cache = Some(self.make_model_cache_for_rows(
            model,
            &[row_idx],
            cap,
            model.cache_dtype(),
            turboquant_bits,
        )?);
        self.cache_rows = vec![row_idx];
        let mut handle = self.admit_mid_begin_inner(id, row_idx, model)?;
        handle.chunk_size = i32::try_from(chunk_size)
            .map_err(|_| anyhow!("adaptive prefill chunk exceeds i32"))?
            .max(1);
        loop {
            if self.admit_mid_chunk(&mut handle, model)? {
                break;
            }
        }
        let (_, event) = self.admit_mid_finalize(handle, model)?;
        self.phase = if self
            .slots
            .iter()
            .any(|slot| matches!(slot, Some(state) if !state.finished))
        {
            Phase::Decoding
        } else {
            Phase::Finished
        };
        self.refresh_active_kv_residency_stats();
        Ok(vec![event])
    }

    /// Advance every non-finished active row by exactly one decode token.
    /// Only legal in `Decoding` phase.
    ///
    /// Advance every non-finished active row by one decode token using a
    /// compact cache layout and a three-stage sample_batch dispatch rather
    /// than per-row sampler calls. Stage A collects compact active rows and
    /// builds per-row sampler refs + histories. Stage B packs
    /// `[B_active, 1]` input_ids, runs `forward_on`, reshapes
    /// `[B_active, 1, vocab]` → `[B_active, vocab]`, and calls
    /// `sample_batch` once. Stage C distributes tokens back to scheduler
    /// rows, advances `real_len`, checks EOS / `max_new_tokens`, and collects
    /// events.
    ///
    /// Finished, evicted, empty, and mid-admit-reserved rows are excluded
    /// from the model-facing decode batch. Transitions phase to `Finished`
    /// when all occupied rows are done.
    pub fn step(&mut self, model: &M) -> Result<Vec<StepEvent>> {
        self.ensure_not_poisoned()?;
        match self.step_inner(model) {
            Ok(events) => Ok(events),
            Err(e) => {
                self.poisoned = true;
                Err(e)
            }
        }
    }

    fn reclaim_idle_immutable_blocks_for_decode_rows(
        &mut self,
        rows: &[usize],
        pre_offsets: &[i32],
    ) -> Result<()> {
        let Some(block_size) = self
            .immutable_prefix_blocks
            .as_ref()
            .map(|pool| pool.block_size)
        else {
            return Ok(());
        };
        anyhow::ensure!(
            rows.len() == pre_offsets.len(),
            "decode reclaim rows {} != offsets {}",
            rows.len(),
            pre_offsets.len()
        );
        let mut targets = Vec::new();
        for (&row, &offset) in rows.iter().zip(pre_offsets.iter()) {
            let offset = usize::try_from(offset)
                .map_err(|_| anyhow!("decode reclaim row {row} has negative offset"))?;
            if offset % block_size != 0 {
                continue;
            }
            let request_id = self
                .slots
                .get(row)
                .and_then(Option::as_ref)
                .map(|state| state.id)
                .ok_or_else(|| anyhow!("decode reclaim row {row} has no request"))?;
            let owner = self
                .request_block_tables
                .get(&request_id)
                .map(|table| table.owner)
                .ok_or_else(|| {
                    anyhow!("decode reclaim request {} has no block table", request_id.0)
                })?;
            targets.push((owner, offset.saturating_add(1)));
        }
        if targets.is_empty() {
            return Ok(());
        }
        if let (Some(pool), Some(cache)) =
            (self.immutable_prefix_blocks.as_mut(), self.cache.as_mut())
        {
            reclaim_idle_immutable_blocks_for_targets(pool, cache, &targets)?;
        }
        Ok(())
    }

    fn step_inner(&mut self, model: &M) -> Result<Vec<StepEvent>> {
        if self.phase != Phase::Decoding {
            return Err(anyhow!(
                "step illegal in {:?} phase: call prefill_admitted first",
                self.phase
            ));
        }

        // Capture which rows are eligible to step at the start of this
        // call. Eligible = `Some` slot AND not finished AND already has
        // at least one generated token. The `!generated_tokens.is_empty()`
        // guard excludes B1-p2.3c+ admit_mid chunk-loop rows: those have
        // an inserted `RequestState` (slot reserved by `admit_mid_begin`)
        // but no first token until `admit_mid_finalize` runs (which
        // adopts the temp cache + samples the first token). Treating
        // them as pad here makes the interleaved step a no-op for the
        // mid-admit row — the main cache slot stays empty until
        // finalize's adopt overwrites it.
        //
        let active_rows: Vec<usize> = self
            .slots
            .iter()
            .enumerate()
            .filter_map(|(row, slot)| {
                matches!(slot, Some(r) if !r.finished && !r.generated_tokens.is_empty())
                    .then_some(row)
            })
            .collect();
        if active_rows.is_empty() {
            return Ok(Vec::new());
        }

        self.rebuild_cache_layout(model, &active_rows)?;
        let b = active_rows.len();

        let pre_offsets = first_full_layer_offsets(
            self.cache
                .as_ref()
                .ok_or_else(|| anyhow!("step: cache absent after layout rebuild"))?,
        )?
        .to_vec();
        anyhow::ensure!(
            pre_offsets.len() == b,
            "step: cache offset rows {} != active rows {}",
            pre_offsets.len(),
            b
        );
        self.reclaim_idle_immutable_blocks_for_decode_rows(&active_rows, &pre_offsets)?;

        // Build [B_active, 1] input_ids in compact cache order.
        let last_tokens: Vec<i32> = active_rows
            .iter()
            .map(|&slot_row| {
                let r = self.slots[slot_row]
                    .as_ref()
                    .expect("active row implies Some");
                *r.generated_tokens
                    .last()
                    .expect("active_rows guarantees generated_tokens is non-empty")
                    as i32
            })
            .collect();
        let input_ids: Array = (&last_tokens[..], &[b as i32, 1][..])
            .try_into()
            .map_err(|e| anyhow!("step: build input_ids Array failed: {e:?}"))?;

        // Build [3, B_active, 1] decode position ids only for models that consume
        // them. Gemma4 derives positions from KV offsets, so the hot path can
        // reuse a placeholder without changing model semantics.
        let position_ids = if model.requires_position_ids() {
            // The cache offset is the zero-based position where the current
            // token will be written. `RequestState::real_len` already includes
            // that emitted-but-not-yet-cached token, so using it directly here
            // shifts every ordinary Scheduler decode position by one.
            build_decode_position_ids(&pre_offsets)?
        } else {
            self.reusable_dummy_position_ids()?
        };

        // Per-row lens for compact decode: every model-facing row writes
        // exactly one token.
        let per_row_lens: Vec<i32> = vec![1; b];

        let cache_ref = self
            .cache
            .as_mut()
            .ok_or_else(|| anyhow!("step: cache absent — was prefill_admitted called?"))?;

        // Build per-row decode mask BEFORE the forward — necessary so
        // SDPA correctly masks stale K/V cells for rows whose cache
        // offsets have diverged from max(offsets).
        let mask_row_lens: Vec<i32> = pre_offsets
            .iter()
            .zip(per_row_lens.iter())
            .map(|(o, n)| o + n)
            .collect();
        let max_real_len = mask_row_lens
            .iter()
            .copied()
            .max()
            .expect("active_rows is non-empty");
        let decode_mask = maybe_build_decode_mask(&mask_row_lens, max_real_len)?;

        let logits = model.forward_on(
            &input_ids,
            &position_ids,
            Some(&per_row_lens),
            decode_mask.as_ref(),
            Some(cache_ref),
            mlx::StreamOrDevice::default(),
        )?;

        // logits shape: [B, 1, vocab]. Reshape to [B, vocab] for sample_batch.
        let logits_shape = logits.shape();
        let vocab = logits_shape.as_slice()[2];
        let logits_bv = logits
            .reshape(&[b as i32, vocab][..])
            .map_err(|e| anyhow!("step: reshape logits [B,1,vocab]->[B,vocab] failed: {e:?}"))?;
        let constraint_masks = active_rows
            .iter()
            .map(|&slot_row| {
                self.slots[slot_row]
                    .as_mut()
                    .expect("active row is occupied")
                    .constraint
                    .as_mut()
                    .map(crate::core::constrained::ConstraintSession::compute_mask)
                    .transpose()
            })
            .collect::<Result<Vec<_>>>()?;
        let logits_bv =
            crate::core::constrained::apply_batch_token_masks(&logits_bv, &constraint_masks)?;

        // Stage A — collect per-row sampler refs + histories in compact
        // active-row order.
        let mut row_samplers: Vec<&Sampler> = Vec::with_capacity(b);
        let mut row_histories: Vec<Vec<u32>> = Vec::with_capacity(b);
        for &slot_row in &active_rows {
            let state = self.slots[slot_row]
                .as_ref()
                .expect("active_rows guaranteed Some");
            row_samplers.push(&state.sampler);
            let mut hist: Vec<u32> =
                Vec::with_capacity(state.prompt_ids.len() + state.generated_tokens.len());
            hist.extend_from_slice(&state.prompt_ids);
            hist.extend_from_slice(&state.generated_tokens);
            row_histories.push(hist);
        }

        // Stage B — dispatch sample_batch once over [B, vocab].
        let mut compact_prng = self.compact_prng_state_for_rows(&active_rows)?;
        let history_refs: Vec<&[u32]> = row_histories.iter().map(|h| h.as_slice()).collect();
        let tokens = crate::core::sampler::sample_batch(
            &row_samplers,
            &logits_bv,
            &history_refs,
            &mut compact_prng,
        )
        .map_err(|e| anyhow!("step: sample_batch failed: {e:?}"))?;
        drop(history_refs);
        drop(row_samplers);
        self.scatter_prng_state_from_rows(&active_rows, &compact_prng)?;

        // Stage C — distribute tokens + termination per active row.
        let mut events: Vec<StepEvent> = Vec::new();
        for (batch_row, &slot_row) in active_rows.iter().enumerate() {
            let token = tokens[batch_row];
            let state = self.slots[slot_row]
                .as_mut()
                .expect("active_rows guaranteed Some");

            state.generated_tokens.push(token);
            if let Some(constraint) = state.constraint.as_mut() {
                constraint.commit_token(token)?;
            }
            state.real_len += 1;

            // Termination: EOS check first, then max_new_tokens.
            if state.stop_token_ids.contains(&token) {
                state.finished = true;
                state.finish_reason = Some("stop");
            } else if state.generated_tokens.len() >= state.max_new_tokens {
                state.finished = true;
                state.finish_reason = Some("length");
            }

            events.push(StepEvent {
                id: state.id,
                token,
                finish_reason: state.finish_reason,
            });
        }

        // If every active slot is now finished, transition to Finished.
        let all_done = self
            .slots
            .iter()
            .all(|s| matches!(s, Some(r) if r.finished) || s.is_none());
        let any_present = self.slots.iter().any(|s| s.is_some());
        if all_done && any_present {
            self.phase = Phase::Finished;
        }

        Ok(events)
    }

    /// Begin a chunked mid-batch admit (B1-p2.3c+).
    ///
    /// Reserves a slot, allocates a B=1 temp cache sized to
    /// `prompt_len + max_new_tokens` (floored at
    /// [`MIN_KV_CACHE_CAP_FOR_GPU_PERF`] for the same Metal-kernel reason
    /// as the main cache), and pre-computes the full-prompt MRoPE
    /// position ids so subsequent `admit_mid_chunk` calls can slice
    /// without rebuilding.
    ///
    /// Returns an [`AdmitMidHandle`] the caller passes to
    /// `admit_mid_chunk` (looped until `is_last=true`) and finally
    /// `admit_mid_finalize`. The caller interleaves
    /// [`Scheduler::step`] between chunks so active rows continue
    /// emitting tokens.
    ///
    /// # VL chunk boundaries
    /// VL chunking keeps each contiguous `image_pad` run in one chunk by
    /// extending a fixed boundary when it lands inside an image span. This
    /// preserves chunked prefill semantics while avoiding extra text forwards
    /// for one logical image.
    ///
    /// # Errors
    /// - [`SchedulerError::RequestTooLarge`] when
    ///   `prompt_len + max_new_tokens > effective_cap_max`.
    /// - `phase != Decoding` (`admit_mid_begin` is only callable
    ///   mid-batch; use `admit` for fresh batches).
    /// - `scheduler full` when no slot is free (admission queue is
    ///   `driver_loop`'s concern; here we surface the raw error).
    /// - dtype / make_cache failures bubble up; the orphan slot is
    ///   rolled back via `evict` so the next `step()` does not panic.
    pub fn admit_mid_begin(&mut self, req: GenerateRequest, model: &M) -> Result<AdmitMidHandle>
    where
        M: DenseVlMethods,
    {
        self.ensure_not_poisoned()?;

        // Cap gate — mirror admit's, otherwise queue drain could push an
        // oversize request through.
        let cap_needed = req.prompt_ids.len().saturating_add(req.max_new_tokens);
        if cap_needed > self.effective_cap_max {
            return Err(anyhow::Error::new(SchedulerError::RequestTooLarge {
                required_total_tokens: cap_needed,
                input_tokens: req.prompt_ids.len(),
                requested_max_output_tokens: req.max_new_tokens,
                server_max_context_tokens: self.effective_cap_max,
                max_allowed_output_tokens: self
                    .effective_cap_max
                    .saturating_sub(req.prompt_ids.len()),
            }));
        }
        if self.phase != Phase::Decoding {
            return Err(anyhow!(
                "admit_mid_begin illegal in {:?} phase: only Decoding (use admit for Idle/Admitting)",
                self.phase
            ));
        }
        let row_idx =
            self.slots.iter().position(|s| s.is_none()).ok_or_else(|| {
                anyhow!("scheduler full: no row available (b_max={})", self.b_max)
            })?;

        // 1. Reserve slot via the relaxed admit() path. Phase stays Decoding.
        let id = self.admit(req)?;

        // From here on, any Err must roll back the slot.
        match self.admit_mid_begin_inner(id, row_idx, model) {
            Ok(h) => Ok(h),
            Err(e) => {
                let _ = self.evict(id);
                Err(e)
            }
        }
    }

    /// Body of `admit_mid_begin` separated so the caller can centralise
    /// rollback. Steps: extract per-row state, compute floored
    /// `cap_for_temp`, detect dtype, allocate temp_cache, pre-build
    /// full-prompt position ids, and compute full-prompt vision embeddings.
    fn admit_mid_begin_inner(
        &mut self,
        id: RequestId,
        row_idx: usize,
        model: &M,
    ) -> Result<AdmitMidHandle>
    where
        M: DenseVlMethods,
    {
        let (
            prompt_ids,
            prompt_len_usz,
            max_new_tokens,
            pixel_values,
            image_grid_thw,
            image_token_id,
            image_spatial_merge_size,
            prefill_chunk_size,
            decode_cadence_mid_chunk_cap,
        ) = {
            let state = self.slots[row_idx].as_ref().expect("admit inserted");
            (
                state.prompt_ids.clone(),
                state.prompt_ids.len(),
                state.max_new_tokens,
                state.pixel_values.clone(),
                state.image_grid_thw.clone(),
                state.image_token_id,
                state.image_spatial_merge_size,
                state.prefill_chunk_size,
                state.decode_cadence_mid_chunk_cap,
            )
        };
        let prompt_len = prompt_len_usz as i32;
        // Saturate max_new to i32 then floor cap for GPU-perf (same reason
        // as prefill_admitted_inner main cache; spec §4.5.5).
        let max_new_i32 = i32::try_from(max_new_tokens).unwrap_or(i32::MAX);
        let cap_for_temp = prompt_len
            .saturating_add(max_new_i32)
            .max(prompt_len)
            .max(MIN_KV_CACHE_CAP_FOR_GPU_PERF);

        // Dtype from the first cache layer (Full or Mla).
        let dtype = {
            let main_cache = self
                .cache
                .as_ref()
                .ok_or_else(|| anyhow!("admit_mid_begin: main cache absent"))?;
            main_cache
                .iter()
                .find_map(|c| match c {
                    LayerCache::Full(kv) => Some(kv.dtype()),
                    LayerCache::Mla(mla) => Some(mla.dtype()),
                    _ => None,
                })
                .unwrap_or(Dtype::Bfloat16)
        };

        let is_vl = pixel_values.is_some();
        let turboquant_bits = self.kv_cache_turboquant_bits_for_rows(&[row_idx])?;
        let prefix_fingerprint = if self.paged_prefix_cache.is_some() {
            paged_prefix_fingerprint_for_request(
                pixel_values.as_deref(),
                image_grid_thw.as_deref(),
                image_token_id,
                image_spatial_merge_size,
            )?
        } else {
            None
        };
        let destination_owner = self
            .request_block_tables
            .get(&id)
            .ok_or_else(|| anyhow!("admit_mid_begin: request block table absent"))?
            .owner;
        let can_restore_in_place = !is_vl
            && turboquant_bits.is_none()
            && self.cache.as_deref().is_some_and(cache_is_fullpaged_only);
        let prefix_config = self.paged_prefix_cache.clone();
        let memory_governor = self.process_memory_governor.clone();
        let immutable_restored_start = if can_restore_in_place {
            match (self.immutable_prefix_blocks.as_mut(), self.cache.as_mut()) {
                (Some(pool), Some(cache)) => restore_immutable_prefix_blocks(
                    pool,
                    cache,
                    prefix_config.as_ref(),
                    memory_governor.as_ref(),
                    destination_owner,
                    &prompt_ids,
                )?,
                _ => None,
            }
        } else {
            None
        };
        if immutable_restored_start.is_some() {
            if let (Some(pool), Some(cache)) =
                (self.immutable_prefix_blocks.as_mut(), self.cache.as_mut())
            {
                reclaim_idle_immutable_blocks_for_targets(
                    pool,
                    cache,
                    &[(destination_owner, prompt_len_usz)],
                )?;
            }
        }
        let immutable_in_place = immutable_restored_start.is_some();
        let mut temp_cache = if immutable_in_place {
            Vec::new()
        } else {
            self.make_model_cache_for_rows(model, &[row_idx], cap_for_temp, dtype, turboquant_bits)?
        };
        let prefix_restored_start = if let Some(restored) = immutable_restored_start {
            restored
        } else {
            try_restore_paged_prefix_for_prompt(
                self.paged_prefix_cache.as_ref(),
                self.prefix_lru_cache.as_ref(),
                &mut temp_cache,
                &prompt_ids,
                prefix_fingerprint.as_deref(),
            )?
            .unwrap_or(0)
        };
        self.runtime_usage
            .record_prefix_cache_hit_tokens(prefix_restored_start as u64);
        let position_ids_required = model.requires_position_ids();

        let chunk_size = if prefill_chunk_size == 0 {
            prompt_len.max(1)
        } else {
            prefill_chunk_size.max(1)
        };

        // Pre-build full-prompt MRoPE position ids only for models that
        // consume them. Others carry a reusable placeholder and skip slicing
        // in `admit_mid_chunk`.
        let position_ids_full = if !position_ids_required {
            self.reusable_dummy_position_ids()?
        } else if is_vl {
            let prompt_ids_i32: Vec<i32> = prompt_ids.iter().map(|&t| t as i32).collect();
            build_position_ids_vl(
                &prompt_ids_i32,
                image_grid_thw
                    .as_deref()
                    .expect("is_vl implies image_grid_thw is Some"),
                image_token_id,
                image_spatial_merge_size,
            )?
        } else {
            build_position_ids(0, prompt_len)?
        };

        // For VL: pre-compute vision embeddings once (`[N_image_pad_total,
        // hidden]`). Each chunk slices the rows it consumes; tracking the
        // running offset via `image_pad_consumed`.
        let cold_materialization_guard = if is_vl {
            self.begin_cold_materialization(
                crate::core::process_memory::MaterializationComponents {
                    text: false,
                    vision: true,
                    speculative: false,
                },
            )?
            .map(Box::new)
        } else {
            None
        };
        let vision_reservation = if is_vl {
            reserve_vision_prefill(
                self.process_memory_governor.as_ref(),
                model,
                &[pixel_values.as_deref()],
                &[image_grid_thw.as_deref()],
            )?
        } else {
            None
        };
        let vision_embeds_full = if is_vl {
            let pv = pixel_values
                .as_deref()
                .expect("is_vl implies pixel_values is Some");
            let grids = image_grid_thw
                .as_deref()
                .expect("is_vl implies image_grid_thw is Some");
            Some(model.compute_vision_embeds(pv, grids, mlx::StreamOrDevice::default())?)
        } else {
            None
        };
        let image_pad_consumed = if is_vl {
            count_image_pad(
                &prompt_ids[..prefix_restored_start as usize],
                image_token_id,
            )
        } else {
            0
        };

        Ok(AdmitMidHandle {
            request_id: id,
            row_idx,
            prompt_ids,
            prompt_len,
            chunk_size,
            decode_cadence_mid_chunk_cap,
            chunk_start: prefix_restored_start,
            temp_cache,
            immutable_in_place,
            prefix_fingerprint,
            is_vl,
            image_token_id,
            position_ids_required,
            position_ids_full,
            vision_embeds_full,
            vision_reservation,
            cold_materialization_guard,
            image_pad_consumed,
            last_logits: None,
        })
    }

    /// Run one chunk of admit_mid prefill into `handle.temp_cache`.
    /// Returns `true` if this was the last chunk (`chunk_end ==
    /// prompt_len`); caller then proceeds to `admit_mid_finalize`.
    /// Otherwise caller should run one `Scheduler::step` against the
    /// main cache before the next `admit_mid_chunk` call so active rows
    /// continue emitting tokens (spec §4.5.5 chunk:step = 1:1).
    ///
    /// On the last chunk this method stashes the `[1, 1, vocab]` logits
    /// into `handle.last_logits` for first-token sampling in
    /// `admit_mid_finalize`.
    fn admit_mid_chunk_immutable_in_place(
        &mut self,
        handle: &mut AdmitMidHandle,
        model: &M,
        input_ids: &Array,
        position_ids: &Array,
        chunk_end: i32,
        is_last: bool,
    ) -> Result<bool>
    where
        M: DenseVlMethods,
    {
        anyhow::ensure!(
            !handle.is_vl && handle.temp_cache.is_empty(),
            "in-place immutable mid-admit is text-only and owns no detached cache"
        );
        let previous_rows = self.cache_rows.clone();
        anyhow::ensure!(
            !previous_rows.contains(&handle.row_idx),
            "in-place immutable mid-admit destination is already an execution row"
        );
        let restore_owners = self.block_owners_for_rows(&previous_rows)?;
        let destination_owner = self
            .request_block_tables
            .get(&handle.request_id)
            .ok_or_else(|| anyhow!("in-place immutable mid-admit block table absent"))?
            .owner;
        {
            let cache = self
                .cache
                .as_mut()
                .ok_or_else(|| anyhow!("in-place immutable mid-admit cache absent"))?;
            bind_full_paged_cache_owners(cache, &[destination_owner])?;
        }
        self.cache_rows = vec![handle.row_idx];

        let forward_result = (|| -> Result<Option<Array>> {
            let cache = self
                .cache
                .as_mut()
                .ok_or_else(|| anyhow!("in-place immutable mid-admit cache absent"))?;
            if is_last {
                let logits = model.forward_on(
                    input_ids,
                    position_ids,
                    None,
                    None,
                    Some(cache),
                    mlx::StreamOrDevice::default(),
                )?;
                mlx::transforms::eval(&[&logits])?;
                Ok(Some(logits))
            } else {
                let hidden = model.forward_text_hidden(
                    input_ids,
                    position_ids,
                    None,
                    None,
                    Some(cache),
                    mlx::StreamOrDevice::default(),
                )?;
                mlx::transforms::eval(&[&hidden])?;
                Ok(None)
            }
        })();

        let restore_result = if restore_owners.is_empty() {
            self.cache_rows.clear();
            Ok(())
        } else {
            let cache = self
                .cache
                .as_mut()
                .ok_or_else(|| anyhow!("in-place immutable mid-admit cache absent"))?;
            let result = bind_full_paged_cache_owners(cache, &restore_owners);
            if result.is_ok() {
                self.cache_rows = previous_rows;
            }
            result
        };
        let result_logits = match (forward_result, restore_result) {
            (Ok(logits), Ok(())) => logits,
            (Err(forward), Ok(())) => return Err(forward),
            (Ok(_), Err(restore)) => return Err(restore),
            (Err(forward), Err(restore)) => {
                return Err(forward.context(format!(
                "failed to restore execution rows after in-place immutable mid-admit: {restore:#}"
            )))
            }
        };
        if let Some(logits) = result_logits {
            handle.last_logits = Some(logits);
        }
        handle.chunk_start = chunk_end;
        Ok(is_last)
    }

    pub fn admit_mid_chunk(
        &mut self,
        handle: &mut AdmitMidHandle,
        model: &M,
    ) -> Result<bool /* is_last */>
    where
        M: DenseVlMethods,
    {
        self.ensure_not_poisoned()?;

        let requested_tokens = handle
            .chunk_size
            .min(handle.prompt_len.saturating_sub(handle.chunk_start))
            .max(1) as usize;
        let mut prefill_plan =
            self.plan_prefill_chunk(requested_tokens, handle.chunk_start as usize, 1)?;
        let selected_tokens = prefill_plan
            .as_ref()
            .map_or(requested_tokens, |plan| plan.selected_tokens);
        let base_chunk_end = handle
            .chunk_start
            .saturating_add(selected_tokens as i32)
            .min(handle.prompt_len);
        let mut chunk_end = if handle.is_vl {
            extend_vl_chunk_end_for_image_pad(
                &handle.prompt_ids,
                handle.image_token_id,
                handle.chunk_start,
                base_chunk_end,
            )
        } else {
            base_chunk_end
        };
        let actual_tokens = (chunk_end - handle.chunk_start).max(0) as usize;
        if actual_tokens > selected_tokens {
            // VL image-pad runs are atomic and may extend the proposed chunk.
            // Re-reserve the true peak; never silently exceed the governor's
            // selected size.
            drop(prefill_plan.take());
            prefill_plan =
                self.plan_prefill_chunk(actual_tokens, handle.chunk_start as usize, 1)?;
            if prefill_plan
                .as_ref()
                .is_some_and(|plan| plan.selected_tokens < actual_tokens)
            {
                return Err(anyhow::Error::new(SchedulerError::PrefillPeakUnsafe {
                    requested_tokens: actual_tokens,
                    selected_tokens: prefill_plan.as_ref().map_or(0, |plan| plan.selected_tokens),
                    target_bytes: prefill_plan.as_ref().map_or(0, |plan| plan.target_bytes),
                }));
            }
        }
        if self.paged_prefix_cache.is_some()
            && chunk_end == handle.prompt_len
            && handle.chunk_start < handle.prompt_len - 1
        {
            chunk_end = handle.prompt_len - 1;
        }
        let is_last = chunk_end == handle.prompt_len;
        let chunk_len = chunk_end - handle.chunk_start;
        if chunk_len <= 0 {
            return Err(anyhow!(
                "admit_mid_chunk: chunk_len <= 0 (chunk_start={}, chunk_end={})",
                handle.chunk_start,
                chunk_end
            ));
        }

        // Build chunk-local input_ids [1, chunk_len].
        let chunk_ids_u32 = &handle.prompt_ids[handle.chunk_start as usize..chunk_end as usize];
        let chunk_ids_i32: Vec<i32> = chunk_ids_u32.iter().map(|&t| t as i32).collect();
        let input_ids: Array = (&chunk_ids_i32[..], &[1_i32, chunk_len][..])
            .try_into()
            .map_err(|e| anyhow!("admit_mid_chunk: input_ids try_into Array failed: {e:?}"))?;

        // Slice axis 2 only when real caller-built position ids are required.
        // Models that derive positions internally carry a reusable placeholder.
        let position_ids = if handle.position_ids_required {
            slice_pos_ids_axis2(&handle.position_ids_full, handle.chunk_start, chunk_end)?
        } else {
            handle.position_ids_full.clone()
        };
        if handle.immutable_in_place {
            drop(prefill_plan);
            return self.admit_mid_chunk_immutable_in_place(
                handle,
                model,
                &input_ids,
                &position_ids,
                chunk_end,
                is_last,
            );
        }

        // Forward via the B=1 single-stream API (same path GS chunked
        // prefill uses). The pre-3c+ implementation went through
        // `batched_prefill` (a B>1 path) which adds per-row mask and
        // B-loop overhead that dominated cold + warm runs alike
        // (3c+ T4 finding: chunks ran 10-25× slower than expected with
        // batched_prefill). Going through `forward_on` removes the
        // overhead AND removes the need for caller-built attention /
        // linear masks — the B=1 path derives them internally from
        // input shape + cache state.
        //
        // - Last chunk: `forward_on` returns `[1, 1, vocab]` logits via
        //   lm_head, captured for first-token sampling in
        //   `admit_mid_finalize`.
        // - Intermediate chunk: text and VL paths use hidden-only forwards
        //   (skips lm_head; we don't need logits). Either way the result is
        //   `eval`-d before return so the
        //   chunk's lazy graph materialises here rather than ballooning
        //   into the interleaved `Scheduler::step` call. (GenerationStream
        //   chunked prefill at core/generate.rs ~line 1053 uses the
        //   same `eval(hidden)` pattern for the same reason.)
        let materializes_vision = handle.is_vl
            && count_image_pad(chunk_ids_u32, handle.image_token_id) > 0
            && handle.vision_reservation.is_some();
        let result_logits: Option<Array> = if handle.is_vl {
            // VL chunk: slice the rows of `vision_embeds_full` that
            // correspond to this chunk's `image_pad` token count.
            let k_i = count_image_pad(chunk_ids_u32, handle.image_token_id);
            let image_rows_start = handle.image_pad_consumed;
            let ve_slice = if k_i > 0 {
                let ve_full = handle
                    .vision_embeds_full
                    .as_ref()
                    .expect("is_vl implies vision_embeds_full was computed in admit_mid_begin");
                let start = handle.image_pad_consumed;
                let slice = slice_vision_embeds_rows(ve_full, start, start + k_i)?;
                handle.image_pad_consumed += k_i;
                Some(slice)
            } else {
                None
            };
            log_vl_chunk_composition(
                "scheduler",
                handle.chunk_start..chunk_end,
                is_last,
                chunk_ids_u32,
                handle.image_token_id,
                image_rows_start..image_rows_start + k_i,
            );

            if is_last {
                let logits = model.forward_vl_chunk(
                    &input_ids,
                    &position_ids,
                    None, // per_row_lens (B=1 path derives from input shape)
                    None, // decode_mask (prefill — model builds its own causal mask)
                    Some(&mut handle.temp_cache),
                    ve_slice.as_ref(),
                    handle.image_token_id,
                    mlx::StreamOrDevice::default(),
                )?;
                Some(logits)
            } else {
                let hidden = model.forward_vl_hidden(
                    &input_ids,
                    &position_ids,
                    None, // per_row_lens (B=1 path derives from input shape)
                    None, // decode_mask (prefill — model builds its own causal mask)
                    Some(&mut handle.temp_cache),
                    ve_slice.as_ref(),
                    handle.image_token_id,
                    mlx::StreamOrDevice::default(),
                )?;
                mlx::transforms::eval(&[&hidden])?;
                None
            }
        } else if is_last {
            // Text last chunk: full forward returns logits.
            Some(model.forward_on(
                &input_ids,
                &position_ids,
                None,
                None,
                Some(&mut handle.temp_cache),
                mlx::StreamOrDevice::default(),
            )?)
        } else {
            // Text intermediate chunk: skip lm_head, just update KV cache.
            let hidden = model.forward_text_hidden(
                &input_ids,
                &position_ids,
                None,
                None,
                Some(&mut handle.temp_cache),
                mlx::StreamOrDevice::default(),
            )?;
            mlx::transforms::eval(&[&hidden])?;
            None
        };

        if let Some(logits) = result_logits {
            // The reservation covers materialization, not merely lazy graph
            // construction. This is also the hand-off barrier to finalize.
            mlx::transforms::eval(&[&logits])?;
            handle.last_logits = Some(logits);
        } else {
            match try_save_paged_prefix_for_prompt(
                self.paged_prefix_cache.as_ref(),
                self.prefix_lru_cache.as_ref(),
                &handle.temp_cache,
                &handle.prompt_ids[..chunk_end as usize],
                handle.prefix_fingerprint.as_deref(),
            ) {
                Ok(Some(key)) => {
                    tracing::debug!(
                        "paged SSD prefix cache saved during mid-admit chunk: key={key}"
                    );
                }
                Ok(None) => {}
                Err(err) => {
                    tracing::warn!("paged SSD prefix cache mid-admit chunk save skipped: {err:#}");
                }
            }
        }
        if materializes_vision {
            drop(handle.vision_reservation.take());
            if let Some(guard) = handle.cold_materialization_guard.take() {
                (*guard).commit();
            }
        }
        drop(prefill_plan);
        handle.chunk_start = chunk_end;
        Ok(is_last)
    }

    /// Finalise a chunked mid-batch admit: rebuild the compact main-cache
    /// layout from still-live decode rows plus `temp_cache` row 0 at
    /// `handle.row_idx`, sample the new row's first token from
    /// `handle.last_logits`, then update the row's termination state.
    ///
    /// Returns `(request_id, first_event)`; caller routes the event
    /// to its `event_rx`.
    pub fn admit_mid_finalize(
        &mut self,
        handle: AdmitMidHandle,
        model: &M,
    ) -> Result<(RequestId, StepEvent)> {
        self.ensure_not_poisoned()?;
        let AdmitMidHandle {
            request_id: id,
            row_idx,
            temp_cache,
            immutable_in_place,
            prefix_fingerprint,
            last_logits,
            prompt_ids,
            ..
        } = handle;

        let logits = last_logits
            .ok_or_else(|| anyhow!("admit_mid_finalize: last_logits absent (no chunks ran?)"))?;

        if immutable_in_place {
            self.include_fullpaged_owner_in_layout(model, row_idx)?;
            let owner = self
                .request_block_tables
                .get(&id)
                .ok_or_else(|| anyhow!("mid-admit request block table absent"))?
                .owner;
            let prefix_config = self.paged_prefix_cache.clone();
            if let (Some(pool), Some(cache)) =
                (self.immutable_prefix_blocks.as_mut(), self.cache.as_mut())
            {
                let reusable_len = prompt_ids.len().saturating_sub(1);
                publish_immutable_prefix_blocks(
                    pool,
                    cache,
                    prefix_config.as_ref(),
                    owner,
                    &prompt_ids[..reusable_len],
                )?;
            }
        } else {
            match try_save_paged_prefix_for_prompt(
                self.paged_prefix_cache.as_ref(),
                self.prefix_lru_cache.as_ref(),
                &temp_cache,
                &prompt_ids,
                prefix_fingerprint.as_deref(),
            ) {
                Ok(Some(key)) => {
                    tracing::debug!("paged SSD prefix cache saved during mid-admit: key={key}");
                }
                Ok(None) => {}
                Err(err) => {
                    tracing::warn!("paged SSD prefix cache mid-admit save skipped: {err:#}");
                }
            }

            self.install_cache_with_temp_row(model, &temp_cache, row_idx)?;
        }

        // Sample first generated token using centralized PRNG state.
        let row_logits = slice_logits_row(&logits, 0)?;
        let row_logits = if let Some(constraint) = self.slots[row_idx]
            .as_mut()
            .expect("admit_mid_begin reserved the slot")
            .constraint
            .as_mut()
        {
            crate::core::constrained::apply_token_mask(&row_logits, &constraint.compute_mask()?)?
        } else {
            row_logits
        };
        let token = {
            let history: Vec<u32> = prompt_ids.clone();
            // Copy the sampler (Sampler: Copy post-3e.2) so we release the borrow on self.slots before
            // calling write_row_prng (which needs &mut self).
            let sampler = self.slots[row_idx]
                .as_ref()
                .expect("admit_mid_begin reserved the slot")
                .sampler;
            // Extract this row's PRNG key from centralized state.
            let prng_host: Vec<u32> = self.prng_state.to_vec()?;
            let row_bytes = &prng_host[row_idx * 2..(row_idx + 1) * 2];
            let mut row_key: Array = (row_bytes, &[2_i32][..]).try_into()?;
            let tok = sampler.sample(&row_logits, &history, &mut row_key)?;
            // Write updated key back (releases sampler borrow, &mut self OK now).
            self.write_row_prng(row_idx, &row_key)?;
            tok
        };

        // Update RequestState + termination.
        let state = self.slots[row_idx]
            .as_mut()
            .expect("admit_mid_begin reserved the slot");
        state.generated_tokens.push(token);
        if let Some(constraint) = state.constraint.as_mut() {
            constraint.commit_token(token)?;
        }
        state.real_len += 1;
        if state.stop_token_ids.contains(&token) {
            state.finished = true;
            state.finish_reason = Some("stop");
        } else if state.generated_tokens.len() >= state.max_new_tokens {
            state.finished = true;
            state.finish_reason = Some("length");
        }
        let finish_reason = state.finish_reason;
        self.commit_governor_admission(id);

        Ok((
            id,
            StepEvent {
                id,
                token,
                finish_reason,
            },
        ))
    }

    pub fn admit_mid_begin_mtp(
        &mut self,
        req: GenerateRequest,
        model: &M,
        mtp: &M::MtpHead,
        cfg: MtpSpeculativeConfig,
    ) -> Result<MtpAdmitMidHandle>
    where
        M: DenseVlMethods + MtpSpeculativeModel,
    {
        self.ensure_not_poisoned()?;
        if self.phase != Phase::Decoding {
            return Err(anyhow!(
                "admit_mid_begin_mtp illegal in {:?} phase: only Decoding",
                self.phase
            ));
        }
        let id = self.admit(req)?;
        let row_idx = self
            .slots
            .iter()
            .position(|slot| matches!(slot, Some(state) if state.id == id))
            .expect("admit inserted request id");

        match self.admit_mid_begin_mtp_inner(id, row_idx, model, mtp, cfg) {
            Ok(handle) => Ok(handle),
            Err(err) => {
                let _ = self.evict(id);
                Err(err)
            }
        }
    }

    fn admit_mid_begin_mtp_inner(
        &mut self,
        id: RequestId,
        row_idx: usize,
        model: &M,
        mtp: &M::MtpHead,
        cfg: MtpSpeculativeConfig,
    ) -> Result<MtpAdmitMidHandle>
    where
        M: DenseVlMethods + MtpSpeculativeModel,
    {
        let (
            prompt_ids,
            prompt_len_usz,
            max_new_tokens,
            sampler,
            pixel_values,
            image_grid_thw,
            image_token_id,
            image_spatial_merge_size,
            prefill_chunk_size,
            decode_cadence_mid_chunk_cap,
        ) = {
            let state = self.slots[row_idx]
                .as_ref()
                .ok_or_else(|| anyhow!("admit_mid_begin_mtp: row slot absent"))?;
            (
                state.prompt_ids.clone(),
                state.prompt_ids.len(),
                state.max_new_tokens,
                state.sampler,
                state.pixel_values.clone(),
                state.image_grid_thw.clone(),
                state.image_token_id,
                state.image_spatial_merge_size,
                state.prefill_chunk_size,
                state.decode_cadence_mid_chunk_cap,
            )
        };
        if prompt_ids.is_empty() {
            return Err(anyhow!("admit_mid_begin_mtp: prompt_ids cannot be empty"));
        }
        if pixel_values.is_none() && image_grid_thw.is_some() {
            return Err(anyhow!(
                "admit_mid_begin_mtp: image_grid_thw present but pixel_values is None"
            ));
        }
        MtpSpeculativeConfig::new(cfg.max_draft_tokens, sampler)?;

        let prompt_len = prompt_len_usz as i32;
        let max_new_i32 = i32::try_from(max_new_tokens).unwrap_or(i32::MAX);
        let cap_for_temp = prompt_len
            .saturating_add(max_new_i32)
            .max(prompt_len)
            .max(MIN_KV_CACHE_CAP_FOR_GPU_PERF);
        let dtype = {
            let main_cache = self
                .cache
                .as_ref()
                .ok_or_else(|| anyhow!("admit_mid_begin_mtp: main cache absent"))?;
            main_cache
                .iter()
                .find_map(|cache| match cache {
                    LayerCache::Full(kv) => Some(kv.dtype()),
                    LayerCache::Mla(mla) => Some(mla.dtype()),
                    _ => None,
                })
                .unwrap_or(Dtype::Bfloat16)
        };
        let turboquant_bits = self.kv_cache_turboquant_bits_for_rows(&[row_idx])?;
        let mut temp_cache = self.make_model_cache_for_rows(
            model,
            &[row_idx],
            cap_for_temp,
            dtype,
            turboquant_bits,
        )?;
        let mut mtp_cache = model.make_mtp_cache(mtp, 1, cap_for_temp, dtype)?;

        let is_vl = pixel_values.is_some();
        let prefix_fingerprint = if self.paged_prefix_cache.is_some() {
            paged_prefix_fingerprint_for_request(
                pixel_values.as_deref(),
                image_grid_thw.as_deref(),
                image_token_id,
                image_spatial_merge_size,
            )?
        } else {
            None
        };
        let mut chunk_start = 0_i32;
        let mut image_pad_consumed = 0usize;
        let mut mtp_prev_hidden = None;
        let mut last_prompt_hidden = None;
        if let Some((restore_len, restored_last_hidden)) =
            try_restore_paged_prefix_for_prompt_with_mtp(
                self.paged_prefix_cache.as_ref(),
                self.prefix_lru_cache.as_ref(),
                &mut temp_cache,
                &mut mtp_cache,
                &prompt_ids,
                model.mtp_hidden_size(mtp),
                model.mtp_hidden_dtype(mtp),
                prefix_fingerprint.as_deref(),
            )?
        {
            self.runtime_usage
                .record_prefix_cache_hit_tokens(restore_len as u64);
            chunk_start = restore_len;
            image_pad_consumed = if is_vl {
                count_image_pad(&prompt_ids[..chunk_start as usize], image_token_id)
            } else {
                0
            };
            mtp_prev_hidden = Some(restored_last_hidden.clone());
            if chunk_start >= prompt_len {
                last_prompt_hidden = Some(restored_last_hidden);
            }
        }

        let position_ids_required = model.requires_position_ids();
        let position_ids_full = if !position_ids_required {
            self.reusable_dummy_position_ids()?
        } else if is_vl {
            let prompt_ids_i32: Vec<i32> = prompt_ids.iter().map(|&id| id as i32).collect();
            build_position_ids_vl(
                &prompt_ids_i32,
                image_grid_thw
                    .as_deref()
                    .expect("is_vl implies image_grid_thw is Some"),
                image_token_id,
                image_spatial_merge_size,
            )?
        } else {
            build_position_ids(0, prompt_len)?
        };

        let cold_materialization_guard = if is_vl {
            self.begin_cold_materialization(
                crate::core::process_memory::MaterializationComponents {
                    text: false,
                    vision: true,
                    speculative: false,
                },
            )?
            .map(Box::new)
        } else {
            None
        };
        let vision_reservation = if is_vl {
            reserve_vision_prefill(
                self.process_memory_governor.as_ref(),
                model,
                &[pixel_values.as_deref()],
                &[image_grid_thw.as_deref()],
            )?
        } else {
            None
        };
        let vision_embeds_full = if is_vl {
            let pv = pixel_values
                .as_deref()
                .expect("is_vl implies pixel_values is Some");
            let grids = image_grid_thw
                .as_deref()
                .expect("is_vl implies image_grid_thw is Some");
            Some(model.compute_vision_embeds(pv, grids, mlx::StreamOrDevice::default())?)
        } else {
            None
        };

        let chunk_size = if prefill_chunk_size == 0 {
            prompt_len.max(1)
        } else {
            prefill_chunk_size.max(1)
        };

        Ok(MtpAdmitMidHandle {
            request_id: id,
            row_idx,
            prompt_ids,
            prompt_len,
            chunk_size,
            decode_cadence_mid_chunk_cap,
            chunk_start,
            temp_cache,
            mtp_cache,
            prefix_fingerprint,
            is_vl,
            image_token_id,
            position_ids_required,
            position_ids_full,
            vision_embeds_full,
            vision_reservation,
            cold_materialization_guard,
            image_pad_consumed,
            mtp_prev_hidden,
            last_prompt_hidden,
            stats: MtpSpeculativeStats::default(),
        })
    }

    pub fn admit_mid_chunk_mtp(
        &mut self,
        handle: &mut MtpAdmitMidHandle,
        model: &M,
        mtp: &M::MtpHead,
    ) -> Result<bool>
    where
        M: DenseVlMethods + MtpSpeculativeModel,
    {
        self.ensure_not_poisoned()?;
        if handle.chunk_start >= handle.prompt_len {
            anyhow::ensure!(
                handle.last_prompt_hidden.is_some(),
                "admit_mid_chunk_mtp: restored full prompt without last hidden"
            );
            return Ok(true);
        }

        let requested_tokens = handle
            .chunk_size
            .min(handle.prompt_len.saturating_sub(handle.chunk_start))
            .max(1) as usize;
        let mut prefill_plan =
            self.plan_prefill_chunk(requested_tokens, handle.chunk_start as usize, 1)?;
        let selected_tokens = prefill_plan
            .as_ref()
            .map_or(requested_tokens, |plan| plan.selected_tokens);
        let base_chunk_end = handle
            .chunk_start
            .saturating_add(selected_tokens as i32)
            .min(handle.prompt_len);
        let mut chunk_end = if handle.is_vl {
            extend_vl_chunk_end_for_image_pad(
                &handle.prompt_ids,
                handle.image_token_id,
                handle.chunk_start,
                base_chunk_end,
            )
        } else {
            base_chunk_end
        };
        let actual_tokens = (chunk_end - handle.chunk_start).max(0) as usize;
        if actual_tokens > selected_tokens {
            drop(prefill_plan.take());
            prefill_plan =
                self.plan_prefill_chunk(actual_tokens, handle.chunk_start as usize, 1)?;
            if prefill_plan
                .as_ref()
                .is_some_and(|plan| plan.selected_tokens < actual_tokens)
            {
                return Err(anyhow::Error::new(SchedulerError::PrefillPeakUnsafe {
                    requested_tokens: actual_tokens,
                    selected_tokens: prefill_plan.as_ref().map_or(0, |plan| plan.selected_tokens),
                    target_bytes: prefill_plan.as_ref().map_or(0, |plan| plan.target_bytes),
                }));
            }
        }
        if self.paged_prefix_cache.is_some()
            && chunk_end == handle.prompt_len
            && handle.chunk_start < handle.prompt_len - 1
        {
            chunk_end = handle.prompt_len - 1;
        }
        let is_last = chunk_end == handle.prompt_len;
        let chunk_len = chunk_end - handle.chunk_start;
        if chunk_len <= 0 {
            return Err(anyhow!(
                "admit_mid_chunk_mtp: chunk_len <= 0 (chunk_start={}, chunk_end={})",
                handle.chunk_start,
                chunk_end
            ));
        }

        let chunk_ids = &handle.prompt_ids[handle.chunk_start as usize..chunk_end as usize];
        let chunk_pos_ids = if handle.position_ids_required {
            slice_pos_ids_axis2(&handle.position_ids_full, handle.chunk_start, chunk_end)?
        } else {
            handle.position_ids_full.clone()
        };

        let materializes_vision = handle.is_vl
            && count_image_pad(chunk_ids, handle.image_token_id) > 0
            && handle.vision_reservation.is_some();
        let hidden = if handle.is_vl {
            let chunk_ids_i32: Vec<i32> = chunk_ids.iter().map(|&t| t as i32).collect();
            let chunk_arr: Array = (&chunk_ids_i32[..], &[1_i32, chunk_len][..]).try_into()?;
            let image_tokens = count_image_pad(chunk_ids, handle.image_token_id);
            let image_rows_start = handle.image_pad_consumed;
            let vision_slice = match handle.vision_embeds_full.as_ref() {
                Some(embeds) if image_tokens > 0 => {
                    let slice = slice_vision_embeds_rows(
                        embeds,
                        image_rows_start,
                        image_rows_start + image_tokens,
                    )?;
                    handle.image_pad_consumed += image_tokens;
                    Some(slice)
                }
                _ => None,
            };
            log_vl_chunk_composition(
                "scheduler-mtp-mid",
                handle.chunk_start..chunk_end,
                is_last,
                chunk_ids,
                handle.image_token_id,
                image_rows_start..image_rows_start + image_tokens,
            );
            model.forward_vl_hidden(
                &chunk_arr,
                &chunk_pos_ids,
                None,
                None,
                Some(handle.temp_cache.as_mut_slice()),
                vision_slice.as_ref(),
                handle.image_token_id,
                mlx::StreamOrDevice::default(),
            )?
        } else {
            let chunk_arr: Array = (chunk_ids, &[1_i32, chunk_len][..]).try_into()?;
            model.forward_text_hidden(
                &chunk_arr,
                &chunk_pos_ids,
                None,
                None,
                Some(handle.temp_cache.as_mut_slice()),
                mlx::StreamOrDevice::default(),
            )?
        };

        let prev_hidden = match handle.mtp_prev_hidden.as_ref() {
            Some(hidden) => hidden.clone(),
            None => zero_hidden_like_position(&hidden)?,
        };
        let commit_start = Instant::now();
        commit_mtp_cache_hidden_prefix(
            model,
            mtp,
            &mut handle.mtp_cache,
            &prev_hidden,
            chunk_ids,
            &hidden,
            &chunk_pos_ids,
            mlx::StreamOrDevice::default(),
        )?;
        add_mtp_prefill_cache_commit_us(&mut handle.stats, commit_start);

        let chunk_last_hidden = slice_hidden_position(&hidden, chunk_len - 1)?;
        mlx::transforms::eval(&[&hidden, &chunk_last_hidden])?;
        if materializes_vision {
            drop(handle.vision_reservation.take());
            if let Some(guard) = handle.cold_materialization_guard.take() {
                (*guard).commit();
            }
        }
        let new_pos = chunk_end;
        handle.mtp_prev_hidden = Some(chunk_last_hidden.clone());
        handle.last_prompt_hidden = Some(chunk_last_hidden.clone());
        match try_save_paged_prefix_for_prompt_with_mtp(
            self.paged_prefix_cache.as_ref(),
            self.prefix_lru_cache.as_ref(),
            &handle.temp_cache,
            &handle.mtp_cache,
            &chunk_last_hidden,
            &handle.prompt_ids[..new_pos as usize],
            handle.prefix_fingerprint.as_deref(),
        ) {
            Ok(Some(key)) => {
                tracing::debug!("paged SSD prefix cache MTP mid-admit saved: key={key}");
            }
            Ok(None) => {}
            Err(err) => {
                tracing::warn!("paged SSD prefix cache MTP mid-admit save skipped: {err:#}");
            }
        }
        drop(prefill_plan);
        handle.chunk_start = chunk_end;
        Ok(is_last)
    }

    pub fn admit_mid_finalize_mtp(
        &mut self,
        handle: MtpAdmitMidHandle,
        model: &M,
        mtp: &M::MtpHead,
    ) -> Result<(RequestId, StepEvent)>
    where
        M: DenseVlMethods + MtpSpeculativeModel,
    {
        self.ensure_not_poisoned()?;
        let MtpAdmitMidHandle {
            request_id: id,
            row_idx,
            prompt_ids,
            temp_cache,
            mtp_cache,
            last_prompt_hidden,
            mut stats,
            ..
        } = handle;

        let last_prompt_hidden = last_prompt_hidden
            .ok_or_else(|| anyhow!("admit_mid_finalize_mtp: last_prompt_hidden absent"))?;
        self.install_cache_with_temp_row(model, &temp_cache, row_idx)?;

        let (sampler, stop_token_ids, max_new_tokens) = {
            let state = self.slots[row_idx]
                .as_ref()
                .ok_or_else(|| anyhow!("admit_mid_finalize_mtp: row slot absent"))?;
            (
                state.sampler,
                state.stop_token_ids.clone(),
                state.max_new_tokens,
            )
        };
        let projection_start = Instant::now();
        let first_logits =
            model.project_hidden_on(&last_prompt_hidden, mlx::StreamOrDevice::default())?;
        add_elapsed_us(&mut stats.projection_us, projection_start);
        let mut compact_prng = self.compact_prng_state_for_rows(&[row_idx])?;
        let sampling_start = Instant::now();
        let first_tokens = if let Some(constraint) = self.slots[row_idx]
            .as_mut()
            .and_then(|state| state.constraint.as_mut())
        {
            let row_logits = slice_logits_row(&first_logits, 0)?;
            let row_logits = crate::core::constrained::apply_token_mask(
                &row_logits,
                &constraint.compute_mask()?,
            )?;
            vec![sampler.sample(&row_logits, &prompt_ids, &mut compact_prng)?]
        } else {
            sample_logits_positions(&first_logits, sampler, &prompt_ids, &mut compact_prng)?
        };
        add_elapsed_us(&mut stats.sampling_us, sampling_start);
        self.scatter_prng_state_from_rows(&[row_idx], &compact_prng)?;
        let first_token = *first_tokens
            .first()
            .ok_or_else(|| anyhow!("admit_mid_finalize_mtp produced no first token"))?;

        let finish_reason = {
            let state = self.slots[row_idx]
                .as_mut()
                .ok_or_else(|| anyhow!("admit_mid_finalize_mtp: row slot absent"))?;
            state.generated_tokens.push(first_token);
            if let Some(constraint) = state.constraint.as_mut() {
                constraint.commit_token(first_token)?;
            }
            state.real_len += 1;
            if stop_token_ids.contains(&first_token) {
                state.finished = true;
                state.finish_reason = Some("stop");
            } else if state.generated_tokens.len() >= max_new_tokens {
                state.finished = true;
                state.finish_reason = Some("length");
            }
            state.finish_reason
        };

        let mut mtp_state = self
            .mtp_state
            .take()
            .ok_or_else(|| anyhow!("admit_mid_finalize_mtp: MTP state absent"))?;
        add_mtp_stats(&mut mtp_state.stats, stats);
        if finish_reason.is_none() {
            let row_state = SchedulerMtpRowState {
                mtp_cache,
                pending_tokens: VecDeque::new(),
                last_hidden: last_prompt_hidden,
                deferred_tail_commit: None,
                adaptive_draft_tokens: mtp_state.cfg.max_draft_tokens,
                draft_policy: QwenMtpDraftPolicyState::new(mtp_state.cfg.max_draft_tokens),
            };
            let fill_result = (|| {
                let mut temp = self.build_temp_mtp_step_scheduler(
                    model,
                    row_idx,
                    mtp_state.cfg,
                    mtp_state.stats.clone(),
                    row_state,
                )?;
                temp.fill_mtp_window_single(0, model, mtp)?;
                self.install_temp_mtp_step_result(model, row_idx, temp)
            })();
            match fill_result {
                Ok((row_state, stats)) => {
                    mtp_state.stats = stats;
                    mtp_state.rows.insert(row_idx, row_state);
                }
                Err(err) => {
                    self.mtp_state = Some(mtp_state);
                    return Err(err);
                }
            }
        }
        self.mtp_state = Some(mtp_state);
        let any_unfinished = self
            .slots
            .iter()
            .any(|slot| matches!(slot, Some(state) if !state.finished));
        self.phase = if any_unfinished {
            Phase::Decoding
        } else {
            Phase::Finished
        };
        self.commit_governor_admission(id);

        Ok((
            id,
            StepEvent {
                id,
                token: first_token,
                finish_reason,
            },
        ))
    }

    /// Sweep finished rows: clear their slot, drop their event channel,
    /// and return the evicted IDs. The compact cache is reconciled lazily
    /// by the next decode step or mid-admit finalize.
    ///
    /// Phase transition: Decoding -> Finished if `active_count == 0`
    /// after the sweep. This duplicates `step_inner`'s end-of-loop
    /// Phase transition (both call `phase = Finished` when no active
    /// rows remain after the last row finishes). The duplication is
    /// idempotent: in the rolling decode loop (Task 4), step runs
    /// first (may transition Phase) and gc_finished_rows runs second
    /// (re-affirms transition + clears slots). Either path alone is
    /// correct; the redundancy is harmless and preserves backward
    /// compatibility with direct-step callers (3b-1 integration tests).
    ///
    /// Called by `SchedulerActor::driver_loop` after every successful
    /// `step` invocation in 3c-3's rolling decode loop (Task 4).
    ///
    /// Generic over the event-payload type `S` so the Scheduler does
    /// not need to import `StepEvent`'s concrete channel type; in
    /// production `S = StepEvent`.
    pub fn gc_finished_rows<S>(
        &mut self,
        event_txs: &mut HashMap<RequestId, mpsc::UnboundedSender<S>>,
    ) -> Result<Vec<RequestId>> {
        let mut evicted: Vec<RequestId> = Vec::new();
        let mut evicted_rows: Vec<usize> = Vec::new();
        let finished_ids = self
            .slots
            .iter()
            .filter_map(|slot| {
                slot.as_ref()
                    .filter(|state| state.finished)
                    .map(|state| state.id)
            })
            .collect::<Vec<_>>();
        let completed_histories = self
            .slots
            .iter()
            .enumerate()
            .filter_map(|(row_idx, slot)| {
                let state = slot.as_ref()?;
                let history = completed_prompt_lookup_history(state)?;
                let certifications = self
                    .prompt_lookup_state
                    .as_ref()
                    .and_then(|prompt_lookup| prompt_lookup.rows.get(&row_idx))
                    .filter(|row| row.owner == state.id)
                    .map(|row| row.mtp_certifications.clone())
                    .unwrap_or_default();
                Some((history, certifications))
            })
            .collect::<Vec<_>>();
        for id in finished_ids {
            if let Some(table) = self.request_block_tables.get(&id).copied() {
                if let Some(cache) = self.cache.as_mut() {
                    release_full_paged_cache_owner(cache, table.owner)?;
                }
            }
            self.request_block_tables.remove(&id);
        }
        for (history, certifications) in &completed_histories {
            self.publish_shared_prompt_lookup_history(history, certifications);
        }
        for (row_idx, slot) in self.slots.iter_mut().enumerate() {
            if slot.as_ref().is_some_and(|s| s.finished) {
                // B1-p2.5: release budget on slot clear.
                if let Some(state) = slot.take() {
                    event_txs.remove(&state.id);
                    evicted.push(state.id);
                    evicted_rows.push(row_idx);
                    self.budget_state.release(state.kv_bytes_admitted);
                }
            }
        }
        for row_idx in evicted_rows {
            self.drop_speculative_row_state(row_idx);
        }
        if self.phase == Phase::Decoding && self.active_count() == 0 {
            self.phase = Phase::Finished;
        }
        Ok(evicted)
    }

    /// Test-only seam to flip the scheduler's phase without driving a
    /// model forward. Used to verify phase-guard error paths from unit
    /// tests; never called by production code.
    #[cfg(test)]
    pub(crate) fn force_phase(&mut self, p: Phase) {
        self.phase = p;
    }

    /// cfg(test)-only accessor: compute the cap that `prefill_admitted_inner`
    /// passes to `model.make_cache`, including the GPU-perf floor.
    /// Mirrors the production formula
    /// `slots_max.min(effective_cap_max).max(MIN_KV_CACHE_CAP_FOR_GPU_PERF)`.
    /// Used by 3f unit tests to verify cap-formula correctness without
    /// invoking a real model.
    #[cfg(test)]
    pub(crate) fn computed_cap_for_prefill(&self) -> i32 {
        self.prefill_cache_cap()
    }
}

impl Scheduler<crate::models::Gemma4Model> {
    pub fn admit_mid_begin_gemma4_drafter(
        &mut self,
        req: GenerateRequest,
        model: &crate::models::Gemma4Model,
    ) -> Result<Gemma4DrafterAdmitMidHandle> {
        self.ensure_not_poisoned()?;
        if self.phase != Phase::Decoding {
            return Err(anyhow!(
                "admit_mid_begin_gemma4_drafter illegal in {:?} phase: only Decoding",
                self.phase
            ));
        }
        let id = self.admit(req)?;
        let row_idx = self
            .slots
            .iter()
            .position(|slot| matches!(slot, Some(state) if state.id == id))
            .expect("admit inserted request id");

        match self.admit_mid_begin_gemma4_drafter_inner(id, row_idx, model) {
            Ok(handle) => Ok(handle),
            Err(err) => {
                let _ = self.evict(id);
                Err(err)
            }
        }
    }

    fn admit_mid_begin_gemma4_drafter_inner(
        &mut self,
        id: RequestId,
        row_idx: usize,
        model: &crate::models::Gemma4Model,
    ) -> Result<Gemma4DrafterAdmitMidHandle> {
        let (
            prompt_ids,
            prompt_len_usz,
            max_new_tokens,
            pixel_values,
            image_grid_thw,
            image_token_id,
            image_spatial_merge_size,
            prefill_chunk_size,
            decode_cadence_mid_chunk_cap,
        ) = {
            let state = self.slots[row_idx]
                .as_ref()
                .ok_or_else(|| anyhow!("admit_mid_begin_gemma4_drafter: row slot absent"))?;
            (
                state.prompt_ids.clone(),
                state.prompt_ids.len(),
                state.max_new_tokens,
                state.pixel_values.clone(),
                state.image_grid_thw.clone(),
                state.image_token_id,
                state.image_spatial_merge_size,
                state.prefill_chunk_size,
                state.decode_cadence_mid_chunk_cap,
            )
        };
        if prompt_ids.is_empty() {
            return Err(anyhow!(
                "admit_mid_begin_gemma4_drafter: prompt_ids cannot be empty"
            ));
        }
        if pixel_values.is_none() && image_grid_thw.is_some() {
            return Err(anyhow!(
                "admit_mid_begin_gemma4_drafter: image_grid_thw present but pixel_values is None"
            ));
        }

        let prompt_len = prompt_len_usz as i32;
        let max_new_i32 = i32::try_from(max_new_tokens).unwrap_or(i32::MAX);
        let cap_for_temp = prompt_len
            .saturating_add(max_new_i32)
            .max(prompt_len)
            .max(MIN_KV_CACHE_CAP_FOR_GPU_PERF);
        let dtype = {
            let main_cache = self
                .cache
                .as_ref()
                .ok_or_else(|| anyhow!("admit_mid_begin_gemma4_drafter: main cache absent"))?;
            main_cache
                .iter()
                .find_map(|cache| match cache {
                    LayerCache::Full(kv) => Some(kv.dtype()),
                    LayerCache::Mla(mla) => Some(mla.dtype()),
                    _ => None,
                })
                .unwrap_or(Dtype::Bfloat16)
        };
        let turboquant_bits = self.kv_cache_turboquant_bits_for_rows(&[row_idx])?;
        let mut temp_cache = self.make_model_cache_for_rows(
            model,
            &[row_idx],
            cap_for_temp,
            dtype,
            turboquant_bits,
        )?;

        let prefix_cache = self.gemma4_drafter_prefix_cache();
        let is_vl = pixel_values.is_some();
        let prefix_fingerprint = if prefix_cache.is_enabled() {
            paged_prefix_fingerprint_for_request(
                pixel_values.as_deref(),
                image_grid_thw.as_deref(),
                image_token_id,
                image_spatial_merge_size,
            )?
        } else {
            None
        };
        let mut chunk_start = 0_i32;
        let mut image_pad_consumed = 0usize;
        let mut last_prompt_hidden = None;
        let mut last_shared_kv = None;
        if let Some(restored) = prefix_cache.try_restore(
            model,
            &mut temp_cache,
            &prompt_ids,
            prefix_fingerprint.as_deref(),
        )? {
            chunk_start = restored.cached_len;
            image_pad_consumed =
                count_image_pad(&prompt_ids[..chunk_start as usize], image_token_id);
            last_prompt_hidden = Some(restored.last_hidden);
            last_shared_kv = Some(restored.shared_kv);
            self.refresh_active_kv_residency_stats();
        }

        let dummy_position_ids = if model.requires_position_ids() {
            None
        } else {
            Some(self.reusable_dummy_position_ids()?)
        };
        let position_ids_full = if is_vl && dummy_position_ids.is_none() {
            let grids = image_grid_thw.as_deref().ok_or_else(|| {
                anyhow!("admit_mid_begin_gemma4_drafter: pixel_values present but image_grid_thw is None")
            })?;
            if model.vl_positions_sequential() {
                Some(build_position_ids(0, prompt_len)?)
            } else {
                let prompt_ids_i32: Vec<i32> = prompt_ids.iter().map(|&id| id as i32).collect();
                Some(build_position_ids_vl(
                    &prompt_ids_i32,
                    grids,
                    image_token_id,
                    image_spatial_merge_size,
                )?)
            }
        } else {
            None
        };

        let cold_materialization_guard = if is_vl {
            self.begin_cold_materialization(
                crate::core::process_memory::MaterializationComponents {
                    text: false,
                    vision: true,
                    speculative: false,
                },
            )?
            .map(Box::new)
        } else {
            None
        };
        let vision_reservation = if is_vl {
            reserve_vision_prefill(
                self.process_memory_governor.as_ref(),
                model,
                &[pixel_values.as_deref()],
                &[image_grid_thw.as_deref()],
            )?
        } else {
            None
        };
        let vision_embeds_full = if is_vl {
            let pv = pixel_values
                .as_deref()
                .ok_or_else(|| anyhow!("admit_mid_begin_gemma4_drafter: pixel_values absent"))?;
            let grids = image_grid_thw.as_deref().ok_or_else(|| {
                anyhow!("admit_mid_begin_gemma4_drafter: pixel_values present but image_grid_thw is None")
            })?;
            Some(model.compute_vision_embeds(pv, grids, mlx::StreamOrDevice::default())?)
        } else {
            None
        };

        let chunk_size = if prefill_chunk_size == 0 {
            prompt_len.max(1)
        } else {
            prefill_chunk_size.max(1)
        };
        let decode_cadence_mid_chunk_cap = gemma4_drafter_mid_admit_chunk_cap(
            turboquant_bits,
            prompt_len_usz,
            chunk_size,
            decode_cadence_mid_chunk_cap,
        );

        Ok(Gemma4DrafterAdmitMidHandle {
            request_id: id,
            row_idx,
            prompt_ids,
            prompt_len,
            chunk_size,
            decode_cadence_mid_chunk_cap,
            chunk_start,
            temp_cache,
            prefix_fingerprint,
            is_vl,
            image_token_id,
            dummy_position_ids,
            position_ids_full,
            vision_embeds_full,
            vision_reservation,
            cold_materialization_guard,
            image_pad_consumed,
            last_prompt_hidden,
            last_shared_kv,
            stats: MtpSpeculativeStats::default(),
        })
    }

    pub fn admit_mid_chunk_gemma4_drafter(
        &mut self,
        handle: &mut Gemma4DrafterAdmitMidHandle,
        model: &crate::models::Gemma4Model,
    ) -> Result<bool> {
        self.ensure_not_poisoned()?;
        if handle.chunk_start >= handle.prompt_len {
            anyhow::ensure!(
                handle.last_prompt_hidden.is_some() && handle.last_shared_kv.is_some(),
                "admit_mid_chunk_gemma4_drafter: restored full prompt without drafter state"
            );
            return Ok(true);
        }

        let requested_tokens = handle
            .chunk_size
            .min(handle.prompt_len.saturating_sub(handle.chunk_start))
            .max(1) as usize;
        let mut prefill_plan =
            self.plan_prefill_chunk(requested_tokens, handle.chunk_start as usize, 1)?;
        let selected_tokens = prefill_plan
            .as_ref()
            .map_or(requested_tokens, |plan| plan.selected_tokens);
        let base_chunk_end = handle
            .chunk_start
            .saturating_add(selected_tokens as i32)
            .min(handle.prompt_len);
        let chunk_end = if handle.is_vl {
            extend_vl_chunk_end_for_image_pad(
                &handle.prompt_ids,
                handle.image_token_id,
                handle.chunk_start,
                base_chunk_end,
            )
        } else {
            base_chunk_end
        };
        let actual_tokens = (chunk_end - handle.chunk_start).max(0) as usize;
        if actual_tokens > selected_tokens {
            drop(prefill_plan.take());
            prefill_plan =
                self.plan_prefill_chunk(actual_tokens, handle.chunk_start as usize, 1)?;
            if prefill_plan
                .as_ref()
                .is_some_and(|plan| plan.selected_tokens < actual_tokens)
            {
                return Err(anyhow::Error::new(SchedulerError::PrefillPeakUnsafe {
                    requested_tokens: actual_tokens,
                    selected_tokens: prefill_plan.as_ref().map_or(0, |plan| plan.selected_tokens),
                    target_bytes: prefill_plan.as_ref().map_or(0, |plan| plan.target_bytes),
                }));
            }
        }
        let is_last = chunk_end == handle.prompt_len;
        let chunk_len = chunk_end - handle.chunk_start;
        if chunk_len <= 0 {
            return Err(anyhow!(
                "admit_mid_chunk_gemma4_drafter: chunk_len <= 0 (chunk_start={}, chunk_end={})",
                handle.chunk_start,
                chunk_end
            ));
        }

        let chunk_ids = &handle.prompt_ids[handle.chunk_start as usize..chunk_end as usize];
        let chunk_arr: Array = (chunk_ids, &[1_i32, chunk_len][..]).try_into()?;
        let chunk_pos_ids = match (
            handle.dummy_position_ids.as_ref(),
            handle.position_ids_full.as_ref(),
        ) {
            (Some(dummy), _) => dummy.clone(),
            (None, Some(full)) => slice_pos_ids_axis2(full, handle.chunk_start, chunk_end)?,
            (None, None) => build_position_ids(handle.chunk_start, chunk_len)?,
        };

        let materializes_vision = handle.is_vl
            && count_image_pad(chunk_ids, handle.image_token_id) > 0
            && handle.vision_reservation.is_some();
        let forward_start = Instant::now();
        let out = if handle.is_vl {
            let image_tokens = count_image_pad(chunk_ids, handle.image_token_id);
            let image_rows_start = handle.image_pad_consumed;
            let vision_slice = match handle.vision_embeds_full.as_ref() {
                Some(embeds) if image_tokens > 0 => {
                    let slice = slice_vision_embeds_rows(
                        embeds,
                        image_rows_start,
                        image_rows_start + image_tokens,
                    )?;
                    handle.image_pad_consumed += image_tokens;
                    Some(slice)
                }
                _ => None,
            };
            log_vl_chunk_composition(
                "scheduler-gemma4-drafter-mid",
                handle.chunk_start..chunk_end,
                is_last,
                chunk_ids,
                handle.image_token_id,
                image_rows_start..image_rows_start + image_tokens,
            );
            model.forward_vl_hidden_with_shared_kv_on(
                &chunk_arr,
                &chunk_pos_ids,
                None,
                None,
                Some(handle.temp_cache.as_mut_slice()),
                vision_slice.as_ref(),
                handle.image_token_id,
                mlx::StreamOrDevice::default(),
            )?
        } else {
            model.forward_text_hidden_with_shared_kv_on(
                &chunk_arr,
                &chunk_pos_ids,
                None,
                None,
                Some(handle.temp_cache.as_mut_slice()),
                mlx::StreamOrDevice::default(),
            )?
        };
        add_elapsed_us(&mut handle.stats.verify_forward_us, forward_start);

        let chunk_last_hidden = slice_hidden_position(&out.hidden, chunk_len - 1)?;
        mlx::transforms::eval(&[&out.hidden, &chunk_last_hidden])?;
        if materializes_vision {
            drop(handle.vision_reservation.take());
            if let Some(guard) = handle.cold_materialization_guard.take() {
                (*guard).commit();
            }
        }
        let new_pos = chunk_end;
        let prefix_cache = self.gemma4_drafter_prefix_cache();
        match prefix_cache.try_save(
            model,
            &handle.temp_cache,
            &chunk_last_hidden,
            &handle.prompt_ids[..new_pos as usize],
            handle.prefix_fingerprint.as_deref(),
        ) {
            Ok(Some(key)) => {
                tracing::debug!("paged SSD prefix cache Gemma4 drafter mid-admit saved: key={key}");
            }
            Ok(None) => {}
            Err(err) => {
                tracing::warn!(
                    "paged SSD prefix cache Gemma4 drafter mid-admit save skipped: {err:#}"
                );
            }
        }
        self.refresh_active_kv_residency_stats();
        handle.last_prompt_hidden = Some(chunk_last_hidden);
        handle.last_shared_kv = Some(out.shared_kv);
        drop(prefill_plan);
        handle.chunk_start = chunk_end;
        Ok(is_last)
    }

    pub fn admit_mid_finalize_gemma4_drafter(
        &mut self,
        handle: Gemma4DrafterAdmitMidHandle,
        model: &crate::models::Gemma4Model,
    ) -> Result<(RequestId, StepEvent)> {
        self.ensure_not_poisoned()?;
        let Gemma4DrafterAdmitMidHandle {
            request_id: id,
            row_idx,
            prompt_ids,
            temp_cache,
            last_prompt_hidden,
            last_shared_kv,
            mut stats,
            ..
        } = handle;

        let last_prompt_hidden = last_prompt_hidden.ok_or_else(|| {
            anyhow!("admit_mid_finalize_gemma4_drafter: last_prompt_hidden absent")
        })?;
        let shared_kv = last_shared_kv
            .ok_or_else(|| anyhow!("admit_mid_finalize_gemma4_drafter: shared KV absent"))?;

        self.install_cache_with_temp_row(model, &temp_cache, row_idx)?;

        let (sampler, stop_token_ids, max_new_tokens) = {
            let state = self.slots[row_idx]
                .as_ref()
                .ok_or_else(|| anyhow!("admit_mid_finalize_gemma4_drafter: row slot absent"))?;
            (
                state.sampler,
                state.stop_token_ids.clone(),
                state.max_new_tokens,
            )
        };
        let projection_start = Instant::now();
        let first_logits =
            model.project_hidden_on(&last_prompt_hidden, mlx::StreamOrDevice::default())?;
        add_elapsed_us(&mut stats.projection_us, projection_start);
        let mut compact_prng = self.compact_prng_state_for_rows(&[row_idx])?;
        let sampling_start = Instant::now();
        let first_tokens = if let Some(constraint) = self.slots[row_idx]
            .as_mut()
            .and_then(|state| state.constraint.as_mut())
        {
            let row_logits = slice_logits_row(&first_logits, 0)?;
            let row_logits = crate::core::constrained::apply_token_mask(
                &row_logits,
                &constraint.compute_mask()?,
            )?;
            vec![sampler.sample(&row_logits, &prompt_ids, &mut compact_prng)?]
        } else {
            sample_logits_positions(&first_logits, sampler, &prompt_ids, &mut compact_prng)?
        };
        add_elapsed_us(&mut stats.sampling_us, sampling_start);
        self.scatter_prng_state_from_rows(&[row_idx], &compact_prng)?;
        let first_token = *first_tokens
            .first()
            .ok_or_else(|| anyhow!("admit_mid_finalize_gemma4_drafter produced no first token"))?;

        let finish_reason = {
            let state = self.slots[row_idx]
                .as_mut()
                .ok_or_else(|| anyhow!("admit_mid_finalize_gemma4_drafter: row slot absent"))?;
            state.generated_tokens.push(first_token);
            if let Some(constraint) = state.constraint.as_mut() {
                constraint.commit_token(first_token)?;
            }
            state.real_len += 1;
            if stop_token_ids.contains(&first_token) {
                state.finished = true;
                state.finish_reason = Some("stop");
            } else if state.generated_tokens.len() >= max_new_tokens {
                state.finished = true;
                state.finish_reason = Some("length");
            }
            state.finish_reason
        };

        let mut drafter_state = self
            .gemma4_drafter_state
            .take()
            .ok_or_else(|| anyhow!("admit_mid_finalize_gemma4_drafter: drafter state absent"))?;
        add_mtp_stats(&mut drafter_state.stats, stats);
        if finish_reason.is_none() {
            drafter_state.rows.insert(
                row_idx,
                SchedulerGemma4DrafterRowState {
                    pending_tokens: VecDeque::new(),
                    last_hidden: last_prompt_hidden,
                    shared_kv,
                    adaptive_draft_tokens: drafter_state.cfg.max_draft_tokens,
                    draft_policy: Gemma4DrafterPolicyState::new(drafter_state.cfg.max_draft_tokens),
                },
            );
        }
        self.gemma4_drafter_state = Some(drafter_state);
        let any_unfinished = self
            .slots
            .iter()
            .any(|slot| matches!(slot, Some(state) if !state.finished));
        self.phase = if any_unfinished {
            Phase::Decoding
        } else {
            Phase::Finished
        };
        self.refresh_active_kv_residency_stats();
        self.commit_governor_admission(id);

        Ok((
            id,
            StepEvent {
                id,
                token: first_token,
                finish_reason,
            },
        ))
    }

    pub fn prefill_admitted_gemma4_drafter_batch(
        &mut self,
        model: &crate::models::Gemma4Model,
        drafter: &crate::models::gemma4::Gemma4AssistantModel,
        cfg: MtpSpeculativeConfig,
    ) -> Result<Vec<StepEvent>> {
        self.ensure_not_poisoned()?;
        let cold_materialization =
            self.begin_cold_materialization(self.active_materialization_components(true))?;
        match self.prefill_admitted_gemma4_drafter_batch_inner(model, drafter, cfg) {
            Ok(events) => {
                self.commit_all_governor_admissions();
                if let Some(guard) = cold_materialization {
                    guard.commit();
                }
                Ok(events)
            }
            Err(e) => {
                self.rollback_all_governor_admissions();
                self.poisoned = true;
                if !matches!(self.phase, Phase::Decoding | Phase::Finished) {
                    self.phase = Phase::Finished;
                }
                Err(e)
            }
        }
    }

    pub fn step_gemma4_drafter_batch(
        &mut self,
        model: &crate::models::Gemma4Model,
        drafter: &crate::models::gemma4::Gemma4AssistantModel,
    ) -> Result<Vec<StepEvent>> {
        self.ensure_not_poisoned()?;
        match self.step_gemma4_drafter_batch_inner(model, drafter, true) {
            Ok(events) => Ok(events),
            Err(e) => {
                self.poisoned = true;
                Err(e)
            }
        }
    }

    pub fn step_gemma4_drafter_batch_without_postfill(
        &mut self,
        model: &crate::models::Gemma4Model,
        drafter: &crate::models::gemma4::Gemma4AssistantModel,
    ) -> Result<Vec<StepEvent>> {
        self.ensure_not_poisoned()?;
        match self.step_gemma4_drafter_batch_inner(model, drafter, false) {
            Ok(events) => Ok(events),
            Err(e) => {
                self.poisoned = true;
                Err(e)
            }
        }
    }

    pub fn gemma4_drafter_at_batch_window_boundary(&self) -> bool {
        self.gemma4_drafter_state.as_ref().is_some_and(|state| {
            state.rows.iter().all(|(&row_idx, row)| {
                self.slots
                    .get(row_idx)
                    .and_then(Option::as_ref)
                    .is_none_or(|slot| slot.finished || row.pending_tokens.is_empty())
            })
        })
    }

    fn prefill_admitted_gemma4_drafter_batch_inner(
        &mut self,
        model: &crate::models::Gemma4Model,
        drafter: &crate::models::gemma4::Gemma4AssistantModel,
        cfg: MtpSpeculativeConfig,
    ) -> Result<Vec<StepEvent>> {
        match self.phase {
            Phase::Idle | Phase::Admitting => {}
            Phase::Decoding | Phase::Finished => {
                return Err(anyhow!(
                    "prefill_admitted_gemma4_drafter_batch illegal in {:?} phase: call evict_all first",
                    self.phase
                ));
            }
        }
        self.discard_retained_immutable_prefix_cache();
        if self.cache.is_some() {
            return Err(anyhow!(
                "prefill_admitted_gemma4_drafter_batch: cache already allocated before prefill"
            ));
        }

        let active_rows: Vec<usize> = self
            .slots
            .iter()
            .enumerate()
            .filter_map(|(row, slot)| slot.as_ref().map(|_| row))
            .collect();
        if active_rows.is_empty() {
            return Err(anyhow!(
                "prefill_admitted_gemma4_drafter_batch requires at least one admitted request"
            ));
        }
        if active_rows.len() == 1 {
            return self.prefill_admitted_gemma4_drafter_single(model, drafter, cfg, true);
        }
        for &row_idx in &active_rows {
            let state = self.slots[row_idx]
                .as_ref()
                .expect("active row implies slot is Some");
            if state.finished || !state.generated_tokens.is_empty() {
                return Err(anyhow!(
                    "prefill_admitted_gemma4_drafter_batch requires fresh admitted rows"
                ));
            }
            if state.prompt_ids.is_empty() {
                return Err(anyhow!(
                    "prefill_admitted_gemma4_drafter_batch: prompt_ids cannot be empty"
                ));
            }
            MtpSpeculativeConfig::new(cfg.max_draft_tokens, state.sampler)?;
        }
        if active_rows.iter().all(|&row_idx| {
            self.slots[row_idx]
                .as_ref()
                .is_some_and(|state| state.pixel_values.is_none())
        }) {
            return self.prefill_admitted_gemma4_drafter_text_batch_direct(
                &active_rows,
                model,
                drafter,
                cfg,
            );
        }

        let mut temp_rows = Vec::with_capacity(active_rows.len());
        let mut row_states = HashMap::with_capacity(active_rows.len());
        let mut stats = MtpSpeculativeStats::default();
        let mut events = Vec::with_capacity(active_rows.len());
        let mut final_cap = MIN_KV_CACHE_CAP_FOR_GPU_PERF;
        let dtype = model.cache_dtype();
        for &row_idx in &active_rows {
            let mut temp = self.temp_gemma4_drafter_scheduler_for_row(row_idx)?;
            let event = temp
                // Only materialize each row's prompt and first target token
                // here. Filling an initial speculative window inside the
                // temporary B=1 scheduler would select tokens using B=1
                // execution morphology before the rows are assembled into
                // the production batch.
                .prefill_admitted_gemma4_drafter_single(model, drafter, cfg, false)
                .map_err(|err| {
                    anyhow!("prefill_admitted_gemma4_drafter_batch row {row_idx}: {err:#}")
                })?;
            let temp_cache = temp.cache.take().ok_or_else(|| {
                anyhow!("prefill_admitted_gemma4_drafter_batch row {row_idx}: temp cache absent")
            })?;
            let (cap, _) = cache_cap_and_dtype(&temp_cache)?;
            final_cap = final_cap.max(cap);
            let mut temp_state = temp.gemma4_drafter_state.take().ok_or_else(|| {
                anyhow!(
                    "prefill_admitted_gemma4_drafter_batch row {row_idx}: temp drafter state absent"
                )
            })?;
            add_mtp_stats(&mut stats, temp_state.stats);
            let row_state = temp_state.rows.remove(&0).ok_or_else(|| {
                anyhow!(
                    "prefill_admitted_gemma4_drafter_batch row {row_idx}: temp row state absent"
                )
            })?;
            row_states.insert(row_idx, row_state);
            let temp_slot = temp.slots[0].as_ref().ok_or_else(|| {
                anyhow!("prefill_admitted_gemma4_drafter_batch row {row_idx}: temp slot absent")
            })?;
            let slot = self.slots[row_idx]
                .as_mut()
                .expect("active row implies slot is Some");
            slot.generated_tokens = temp_slot.generated_tokens.clone();
            slot.real_len = temp_slot.real_len;
            slot.finished = temp_slot.finished;
            slot.finish_reason = temp_slot.finish_reason;
            slot.constraint = temp_slot.constraint.clone();
            temp_rows.push((row_idx, temp_cache));
            events.extend(event);
        }

        let turboquant_bits = self.kv_cache_turboquant_bits_for_rows(&active_rows)?;
        let mut final_cache =
            self.make_model_cache_for_rows(model, &active_rows, final_cap, dtype, turboquant_bits)?;
        for (dst_row, &slot_row) in active_rows.iter().enumerate() {
            let (_, temp_cache) = temp_rows
                .iter()
                .find(|(row, _)| *row == slot_row)
                .ok_or_else(|| {
                    anyhow!(
                        "prefill_admitted_gemma4_drafter_batch: missing temp cache for slot row {slot_row}"
                    )
                })?;
            adopt_cache_row_layers(
                &mut final_cache,
                temp_cache,
                dst_row,
                0,
                "prefill_admitted_gemma4_drafter_batch",
            )?;
        }

        let all_finished = active_rows.iter().all(|&row| {
            self.slots[row]
                .as_ref()
                .expect("active row implies slot is Some")
                .finished
        });
        self.cache = Some(final_cache);
        self.cache_rows = active_rows.clone();
        self.phase = if all_finished {
            Phase::Finished
        } else {
            Phase::Decoding
        };
        let mut drafter_state = SchedulerGemma4DrafterState {
            cfg,
            rows: row_states,
            stats,
        };
        if !all_finished {
            self.fill_gemma4_drafter_windows_batched(
                &active_rows,
                cfg,
                &mut drafter_state.stats,
                &mut drafter_state.rows,
                model,
                drafter,
            )?;
        }
        self.gemma4_drafter_state = Some(drafter_state);
        self.refresh_active_kv_residency_stats();

        Ok(events)
    }

    fn prefill_admitted_gemma4_drafter_text_batch_direct(
        &mut self,
        active_rows: &[usize],
        model: &crate::models::Gemma4Model,
        drafter: &crate::models::gemma4::Gemma4AssistantModel,
        cfg: MtpSpeculativeConfig,
    ) -> Result<Vec<StepEvent>> {
        let prompt_lens = active_rows
            .iter()
            .map(|&row_idx| {
                i32::try_from(
                    self.slots[row_idx]
                        .as_ref()
                        .expect("active Gemma4 row is occupied")
                        .prompt_ids
                        .len(),
                )
                .map_err(anyhow::Error::from)
            })
            .collect::<Result<Vec<_>>>()?;
        let max_prompt_len = prompt_lens.iter().copied().max().unwrap_or(0);
        anyhow::ensure!(
            max_prompt_len > 0,
            "Gemma4 drafter direct batch prefill requires non-empty prompts"
        );
        let batch = active_rows.len();
        let max_prompt_len_usize = usize::try_from(max_prompt_len)?;
        let mut flat = vec![0_u32; batch * max_prompt_len_usize];
        for (compact_row, &row_idx) in active_rows.iter().enumerate() {
            let prompt_ids = &self.slots[row_idx]
                .as_ref()
                .expect("active Gemma4 row is occupied")
                .prompt_ids;
            let start = compact_row * max_prompt_len_usize;
            flat[start..start + prompt_ids.len()].copy_from_slice(prompt_ids);
        }
        let input_ids: Array =
            (&flat[..], &[i32::try_from(batch)?, max_prompt_len][..]).try_into()?;
        let cap = self.prefill_cache_cap();
        let turboquant_bits = self.kv_cache_turboquant_bits_for_rows(active_rows)?;
        self.install_initial_cache_for_rows(
            model,
            active_rows,
            cap,
            model.cache_dtype(),
            turboquant_bits,
        )?;
        let position_ids = self.reusable_dummy_position_ids()?;
        let mut stats = MtpSpeculativeStats::default();
        let forward_start = Instant::now();
        let uniform_prompt_lens = prompt_lens.iter().all(|&len| len == max_prompt_len);
        let (output, output_start) = if uniform_prompt_lens && max_prompt_len > 2_048 {
            let mut start = 0_i32;
            let mut final_output = None;
            let mut final_start = 0_i32;
            while start < max_prompt_len {
                let requested_tokens = usize::try_from((max_prompt_len - start).min(2_048))?;
                let prefill_plan =
                    self.plan_prefill_chunk(requested_tokens, usize::try_from(start)?, batch)?;
                let selected_tokens = prefill_plan
                    .as_ref()
                    .map_or(requested_tokens, |plan| plan.selected_tokens);
                let end = start + i32::try_from(selected_tokens)?;
                let chunk = mlx::ops::indexing::slice_strided_on(
                    &input_ids,
                    &[0_i32, start][..],
                    &[i32::try_from(batch)?, end][..],
                    &[1_i32, 1][..],
                    mlx::StreamOrDevice::default(),
                )?;
                let output = {
                    let cache = self.cache.as_mut().ok_or_else(|| {
                        anyhow!("Gemma4 drafter direct batch prefill cache is absent")
                    })?;
                    model.forward_text_hidden_with_shared_kv_on(
                        &chunk,
                        &position_ids,
                        None,
                        None,
                        Some(cache.as_mut_slice()),
                        mlx::StreamOrDevice::default(),
                    )?
                };
                mlx::transforms::eval(&[&output.hidden])?;
                drop(prefill_plan);
                final_start = start;
                final_output = Some(output);
                start = end;
            }
            (
                final_output
                    .ok_or_else(|| anyhow!("Gemma4 drafter batch prefill produced no output"))?,
                final_start,
            )
        } else {
            let cache = self
                .cache
                .as_mut()
                .ok_or_else(|| anyhow!("Gemma4 drafter direct batch prefill cache is absent"))?;
            (
                model.forward_text_hidden_with_shared_kv_on(
                    &input_ids,
                    &position_ids,
                    (!uniform_prompt_lens).then_some(prompt_lens.as_slice()),
                    None,
                    Some(cache.as_mut_slice()),
                    mlx::StreamOrDevice::default(),
                )?,
                0,
            )
        };
        let mut last_hidden_rows = Vec::with_capacity(batch);
        for (compact_row, &prompt_len) in prompt_lens.iter().enumerate() {
            last_hidden_rows.push(slice_hidden_row_position(
                &output.hidden,
                compact_row,
                usize::try_from(prompt_len - output_start - 1)?,
                mlx::StreamOrDevice::default(),
            )?);
        }
        mlx::transforms::eval(&[&output.hidden])?;
        add_elapsed_us(&mut stats.verify_forward_us, forward_start);
        let last_hidden_refs = last_hidden_rows.iter().collect::<Vec<_>>();
        let last_hidden =
            mlx::ops::shape::concatenate_on(&last_hidden_refs, 0, mlx::StreamOrDevice::default())?;
        let projection_start = Instant::now();
        let first_logits = model.project_hidden_on(&last_hidden, mlx::StreamOrDevice::default())?;
        add_elapsed_us(&mut stats.projection_us, projection_start);

        let constraint_masks = active_rows
            .iter()
            .map(|&row_idx| {
                self.slots[row_idx]
                    .as_mut()
                    .expect("active Gemma4 row is occupied")
                    .constraint
                    .as_mut()
                    .map(crate::core::constrained::ConstraintSession::compute_mask)
                    .transpose()
            })
            .collect::<Result<Vec<_>>>()?;
        let logits_shape = first_logits.shape();
        let vocab = logits_shape.as_slice()[2];
        let first_logits = first_logits.reshape(&[i32::try_from(batch)?, vocab][..])?;
        let first_logits =
            crate::core::constrained::apply_batch_token_masks(&first_logits, &constraint_masks)?;
        let row_samplers = active_rows
            .iter()
            .map(|&row_idx| {
                &self.slots[row_idx]
                    .as_ref()
                    .expect("active Gemma4 row is occupied")
                    .sampler
            })
            .collect::<Vec<_>>();
        let row_histories = active_rows
            .iter()
            .map(|&row_idx| {
                self.slots[row_idx]
                    .as_ref()
                    .expect("active Gemma4 row is occupied")
                    .prompt_ids
                    .as_slice()
            })
            .collect::<Vec<_>>();
        let mut compact_prng = self.compact_prng_state_for_rows(active_rows)?;
        let sampling_start = Instant::now();
        let first_tokens = crate::core::sampler::sample_batch(
            &row_samplers,
            &first_logits,
            &row_histories,
            &mut compact_prng,
        )?;
        add_elapsed_us(&mut stats.sampling_us, sampling_start);
        self.scatter_prng_state_from_rows(active_rows, &compact_prng)?;

        let mut row_states = HashMap::with_capacity(batch);
        let mut events = Vec::with_capacity(batch);
        for (compact_row, (&row_idx, &first_token)) in
            active_rows.iter().zip(first_tokens.iter()).enumerate()
        {
            let prompt_len = prompt_lens[compact_row];
            let shared_kv = crate::models::gemma4::shared_kv_row_prefix_on(
                &output.shared_kv,
                compact_row,
                prompt_len,
                mlx::StreamOrDevice::default(),
            )?;
            row_states.insert(
                row_idx,
                SchedulerGemma4DrafterRowState {
                    pending_tokens: VecDeque::new(),
                    last_hidden: last_hidden_rows[compact_row].clone(),
                    shared_kv,
                    adaptive_draft_tokens: cfg.max_draft_tokens,
                    draft_policy: Gemma4DrafterPolicyState::new(cfg.max_draft_tokens),
                },
            );
            let event = self.emit_token_for_row(row_idx, first_token)?;
            events.push(event);
        }
        self.cache_rows = active_rows.to_vec();
        let all_finished = active_rows.iter().all(|&row_idx| {
            self.slots[row_idx]
                .as_ref()
                .expect("active Gemma4 row is occupied")
                .finished
        });
        self.phase = if all_finished {
            Phase::Finished
        } else {
            Phase::Decoding
        };
        let mut drafter_state = SchedulerGemma4DrafterState {
            cfg,
            rows: row_states,
            stats,
        };
        if !all_finished {
            self.fill_gemma4_drafter_windows_batched(
                active_rows,
                cfg,
                &mut drafter_state.stats,
                &mut drafter_state.rows,
                model,
                drafter,
            )?;
        }
        self.gemma4_drafter_state = Some(drafter_state);
        self.refresh_active_kv_residency_stats();
        Ok(events)
    }

    fn prefill_admitted_gemma4_drafter_single(
        &mut self,
        model: &crate::models::Gemma4Model,
        drafter: &crate::models::gemma4::Gemma4AssistantModel,
        cfg: MtpSpeculativeConfig,
        fill_initial_window: bool,
    ) -> Result<Vec<StepEvent>> {
        match self.phase {
            Phase::Idle | Phase::Admitting => {}
            Phase::Decoding | Phase::Finished => {
                return Err(anyhow!(
                    "prefill_admitted_gemma4_drafter_single illegal in {:?} phase: call evict_all first",
                    self.phase
                ));
            }
        }
        self.discard_retained_immutable_prefix_cache();

        let active_rows: Vec<usize> = self
            .slots
            .iter()
            .enumerate()
            .filter_map(|(row, slot)| slot.as_ref().map(|_| row))
            .collect();
        if active_rows.len() != 1 {
            return Err(anyhow!(
                "prefill_admitted_gemma4_drafter_single requires exactly one admitted request, got {}",
                active_rows.len()
            ));
        }
        let row_idx = active_rows[0];
        let (
            id,
            prompt_ids,
            max_new_tokens,
            sampler,
            stop_token_ids,
            prefill_chunk_size,
            pixel_values,
            image_grid_thw,
            image_spatial_merge_size,
            image_token_id,
        ) = {
            let state = self.slots[row_idx]
                .as_ref()
                .expect("active row implies slot is Some");
            (
                state.id,
                state.prompt_ids.clone(),
                state.max_new_tokens,
                state.sampler,
                state.stop_token_ids.clone(),
                state.prefill_chunk_size,
                state.pixel_values.clone(),
                state.image_grid_thw.clone(),
                state.image_spatial_merge_size,
                state.image_token_id,
            )
        };
        if prompt_ids.is_empty() {
            return Err(anyhow!(
                "prefill_admitted_gemma4_drafter_single: prompt_ids cannot be empty"
            ));
        }
        if pixel_values.is_none() && image_grid_thw.is_some() {
            return Err(anyhow!(
                "prefill_admitted_gemma4_drafter_single: image_grid_thw present but pixel_values is None"
            ));
        }
        MtpSpeculativeConfig::new(cfg.max_draft_tokens, sampler)?;

        let prompt_len = prompt_ids.len();
        let cap =
            (prompt_len.saturating_add(max_new_tokens) as i32).max(MIN_KV_CACHE_CAP_FOR_GPU_PERF);
        let dtype = model.cache_dtype();
        if self.cache.is_some() {
            return Err(anyhow!(
                "prefill_admitted_gemma4_drafter_single: cache already allocated before prefill"
            ));
        }
        let turboquant_bits = self.kv_cache_turboquant_bits_for_rows(&[row_idx])?;
        self.cache =
            Some(self.make_model_cache_for_rows(model, &[row_idx], cap, dtype, turboquant_bits)?);
        self.cache_rows = vec![row_idx];

        let prefix_cache = self.gemma4_drafter_prefix_cache();
        let is_vl = pixel_values.is_some();
        let _vision_reservation = if is_vl {
            reserve_vision_prefill(
                self.process_memory_governor.as_ref(),
                model,
                &[pixel_values.as_deref()],
                &[image_grid_thw.as_deref()],
            )?
        } else {
            None
        };
        let prefix_fingerprint = if prefix_cache.is_enabled() {
            paged_prefix_fingerprint_for_request(
                pixel_values.as_deref(),
                image_grid_thw.as_deref(),
                image_token_id,
                image_spatial_merge_size,
            )?
        } else {
            None
        };
        let dummy_position_ids = if model.requires_position_ids() {
            None
        } else {
            Some(self.reusable_dummy_position_ids()?)
        };
        let prompt_len_i32 = prompt_len as i32;
        let mut pos = 0_i32;
        let mut image_pad_consumed = 0usize;
        let mut stats = MtpSpeculativeStats::default();
        let mut vision_embeds_full = None;
        let position_ids_full = if is_vl && dummy_position_ids.is_none() {
            let grids = image_grid_thw.as_deref().ok_or_else(|| {
                anyhow!(
                    "prefill_admitted_gemma4_drafter_single: pixel_values present but image_grid_thw is None"
                )
            })?;
            if model.vl_positions_sequential() {
                Some(build_position_ids(0, prompt_len_i32)?)
            } else {
                let prompt_ids_i32: Vec<i32> = prompt_ids.iter().map(|&id| id as i32).collect();
                Some(build_position_ids_vl(
                    &prompt_ids_i32,
                    grids,
                    image_token_id,
                    image_spatial_merge_size,
                )?)
            }
        } else {
            None
        };
        let mut last_prompt_hidden = None;
        let mut last_shared_kv = None;
        let mut ordinary_prefill_is_adaptive_chunked = false;

        if let Some(restored) = {
            let cache = self
                .cache
                .as_mut()
                .ok_or_else(|| anyhow!("prefill_admitted_gemma4_drafter_single: cache absent"))?;
            prefix_cache.try_restore(
                model,
                cache.as_mut_slice(),
                &prompt_ids,
                prefix_fingerprint.as_deref(),
            )?
        } {
            pos = restored.cached_len;
            image_pad_consumed = count_image_pad(&prompt_ids[..pos as usize], image_token_id);
            last_prompt_hidden = Some(restored.last_hidden);
            last_shared_kv = Some(restored.shared_kv);
            self.refresh_active_kv_residency_stats();
        }

        while pos < prompt_len_i32 {
            let remaining = prompt_len_i32 - pos;
            let mut n = if prefill_chunk_size == 0 {
                remaining
            } else {
                remaining.min(prefill_chunk_size.max(1))
            };
            let mut prefill_plan = self.plan_prefill_chunk(n as usize, pos as usize, 1)?;
            if let Some(plan) = prefill_plan.as_ref() {
                n = plan.selected_tokens as i32;
            }
            if pos == 0 && n < prompt_len_i32 {
                ordinary_prefill_is_adaptive_chunked = true;
            }
            // Match ordinary Scheduler prefill morphology. A prompt that fits
            // the initial prefill allocation is evaluated as [N - 1] + [1].
            // Shape-sensitive Gemma4 MoE projections otherwise leave the
            // drafter path with a different main/shared KV state before the
            // first speculative window.
            let split_final_token =
                prefix_cache.is_enabled() || !ordinary_prefill_is_adaptive_chunked;
            if split_final_token && pos + n == prompt_len_i32 && pos < prompt_len_i32 - 1 {
                n = prompt_len_i32 - 1 - pos;
            }
            if n <= 0 {
                return Err(anyhow!(
                    "prefill_admitted_gemma4_drafter_single: invalid prefill chunk length {n}"
                ));
            }
            if is_vl && prefill_chunk_size != 0 {
                let adjusted_end =
                    extend_vl_chunk_end_for_image_pad(&prompt_ids, image_token_id, pos, pos + n);
                n = adjusted_end - pos;
                if prefill_plan
                    .as_ref()
                    .is_some_and(|plan| plan.selected_tokens < n as usize)
                {
                    drop(prefill_plan.take());
                    prefill_plan = self.plan_prefill_chunk(n as usize, pos as usize, 1)?;
                    if prefill_plan
                        .as_ref()
                        .is_some_and(|plan| plan.selected_tokens < n as usize)
                    {
                        return Err(anyhow::Error::new(SchedulerError::PrefillPeakUnsafe {
                            requested_tokens: n as usize,
                            selected_tokens: prefill_plan
                                .as_ref()
                                .map_or(0, |plan| plan.selected_tokens),
                            target_bytes: prefill_plan.as_ref().map_or(0, |plan| plan.target_bytes),
                        }));
                    }
                }
            }

            let chunk_ids = &prompt_ids[pos as usize..(pos as usize + n as usize)];
            let chunk_arr: Array = (chunk_ids, &[1_i32, n][..]).try_into()?;
            let chunk_pos_ids = match (dummy_position_ids.as_ref(), position_ids_full.as_ref()) {
                (Some(dummy), _) => dummy.clone(),
                (None, Some(full)) => slice_pos_ids_axis2(full, pos, pos + n)?,
                (None, None) => build_position_ids(pos, n)?,
            };

            let forward_start = Instant::now();
            let out = if is_vl {
                let image_tokens = count_image_pad(chunk_ids, image_token_id);
                if image_tokens > 0 && vision_embeds_full.is_none() {
                    let pv = pixel_values.as_deref().ok_or_else(|| {
                        anyhow!(
                            "prefill_admitted_gemma4_drafter_single: image tokens without pixel_values"
                        )
                    })?;
                    let grids = image_grid_thw.as_deref().ok_or_else(|| {
                        anyhow!(
                            "prefill_admitted_gemma4_drafter_single: image tokens without image_grid_thw"
                        )
                    })?;
                    vision_embeds_full = Some(model.compute_vision_embeds(
                        pv,
                        grids,
                        mlx::StreamOrDevice::default(),
                    )?);
                }
                let vision_slice = match vision_embeds_full.as_ref() {
                    Some(embeds) if image_tokens > 0 => Some(slice_vision_embeds_rows(
                        embeds,
                        image_pad_consumed,
                        image_pad_consumed + image_tokens,
                    )?),
                    _ => None,
                };
                image_pad_consumed += image_tokens;
                let cache = self.cache.as_mut().ok_or_else(|| {
                    anyhow!("prefill_admitted_gemma4_drafter_single: cache absent")
                })?;
                model.forward_vl_hidden_with_shared_kv_on(
                    &chunk_arr,
                    &chunk_pos_ids,
                    None,
                    None,
                    Some(cache.as_mut_slice()),
                    vision_slice.as_ref(),
                    image_token_id,
                    mlx::StreamOrDevice::default(),
                )?
            } else {
                let cache = self.cache.as_mut().ok_or_else(|| {
                    anyhow!("prefill_admitted_gemma4_drafter_single: cache absent")
                })?;
                model.forward_text_hidden_with_shared_kv_on(
                    &chunk_arr,
                    &chunk_pos_ids,
                    None,
                    None,
                    Some(cache.as_mut_slice()),
                    mlx::StreamOrDevice::default(),
                )?
            };
            add_elapsed_us(&mut stats.verify_forward_us, forward_start);
            let chunk_last_hidden = slice_hidden_position(&out.hidden, n - 1)?;
            mlx::transforms::eval(&[&out.hidden, &chunk_last_hidden])?;
            self.commit_governor_admission_after_materialization(id);
            let new_pos = pos + n;
            if let Some(cache) = self.cache.as_ref() {
                match prefix_cache.try_save(
                    model,
                    cache,
                    &chunk_last_hidden,
                    &prompt_ids[..new_pos as usize],
                    prefix_fingerprint.as_deref(),
                ) {
                    Ok(Some(key)) => {
                        tracing::debug!("paged SSD prefix cache Gemma4 drafter saved: key={key}");
                    }
                    Ok(None) => {}
                    Err(err) => {
                        tracing::warn!(
                            "paged SSD prefix cache Gemma4 drafter save skipped: {err:#}"
                        );
                    }
                }
            }
            self.refresh_active_kv_residency_stats();
            if new_pos == prompt_len_i32 {
                last_prompt_hidden = Some(chunk_last_hidden);
                last_shared_kv = Some(out.shared_kv);
            }
            drop(prefill_plan);
            pos = new_pos;
        }

        let last_prompt_hidden = last_prompt_hidden.ok_or_else(|| {
            anyhow!("prefill_admitted_gemma4_drafter_single produced no prompt hidden")
        })?;
        let shared_kv = last_shared_kv.ok_or_else(|| {
            anyhow!("prefill_admitted_gemma4_drafter_single produced no shared KV")
        })?;
        let projection_start = Instant::now();
        let first_logits =
            model.project_hidden_on(&last_prompt_hidden, mlx::StreamOrDevice::default())?;
        add_elapsed_us(&mut stats.projection_us, projection_start);
        let mut compact_prng = self.compact_prng_state_for_rows(&[row_idx])?;
        let sampling_start = Instant::now();
        let first_tokens = if let Some(constraint) = self.slots[row_idx]
            .as_mut()
            .and_then(|state| state.constraint.as_mut())
        {
            let row_logits = slice_logits_row(&first_logits, 0)?;
            let row_logits = crate::core::constrained::apply_token_mask(
                &row_logits,
                &constraint.compute_mask()?,
            )?;
            vec![sampler.sample(&row_logits, &prompt_ids, &mut compact_prng)?]
        } else {
            sample_logits_positions(&first_logits, sampler, &prompt_ids, &mut compact_prng)?
        };
        add_elapsed_us(&mut stats.sampling_us, sampling_start);
        self.scatter_prng_state_from_rows(&[row_idx], &compact_prng)?;
        let first_token = *first_tokens.first().ok_or_else(|| {
            anyhow!("prefill_admitted_gemma4_drafter_single produced no first token")
        })?;

        let finish_reason = {
            let state = self.slots[row_idx]
                .as_mut()
                .expect("active row implies slot is Some");
            state.generated_tokens.push(first_token);
            if let Some(constraint) = state.constraint.as_mut() {
                constraint.commit_token(first_token)?;
            }
            state.real_len += 1;
            if stop_token_ids.contains(&first_token) {
                state.finished = true;
                state.finish_reason = Some("stop");
            } else if state.generated_tokens.len() >= state.max_new_tokens {
                state.finished = true;
                state.finish_reason = Some("length");
            }
            state.finish_reason
        };

        self.phase = if finish_reason.is_some() {
            Phase::Finished
        } else {
            Phase::Decoding
        };
        self.gemma4_drafter_state = Some(SchedulerGemma4DrafterState {
            cfg,
            rows: HashMap::from([(
                row_idx,
                SchedulerGemma4DrafterRowState {
                    pending_tokens: VecDeque::new(),
                    last_hidden: last_prompt_hidden,
                    shared_kv,
                    adaptive_draft_tokens: cfg.max_draft_tokens,
                    draft_policy: Gemma4DrafterPolicyState::new(cfg.max_draft_tokens),
                },
            )]),
            stats,
        });

        if finish_reason.is_none() && fill_initial_window {
            self.fill_gemma4_drafter_window_single(row_idx, model, drafter)?;
        }

        Ok(vec![StepEvent {
            id,
            token: first_token,
            finish_reason,
        }])
    }

    fn step_gemma4_drafter_batch_inner(
        &mut self,
        model: &crate::models::Gemma4Model,
        drafter: &crate::models::gemma4::Gemma4AssistantModel,
        refill_after_emit: bool,
    ) -> Result<Vec<StepEvent>> {
        if self.phase != Phase::Decoding {
            return Err(anyhow!(
                "step_gemma4_drafter_batch illegal in {:?} phase: call prefill_admitted_gemma4_drafter_batch first",
                self.phase
            ));
        }
        let mut drafter_state = self
            .gemma4_drafter_state
            .take()
            .ok_or_else(|| anyhow!("step_gemma4_drafter_batch: drafter state absent"))?;
        let cfg = drafter_state.cfg;
        let active_rows: Vec<usize> = self
            .slots
            .iter()
            .enumerate()
            .filter_map(|(row, slot)| {
                (matches!(slot, Some(state) if !state.finished)
                    && drafter_state.rows.contains_key(&row))
                .then_some(row)
            })
            .collect();
        if active_rows.is_empty() {
            let any_unfinished = self
                .slots
                .iter()
                .any(|slot| matches!(slot, Some(state) if !state.finished));
            self.phase = if any_unfinished {
                Phase::Decoding
            } else {
                Phase::Finished
            };
            self.gemma4_drafter_state = Some(drafter_state);
            return Ok(Vec::new());
        }
        let has_ordinary_fallback = active_rows.iter().any(|row_idx| {
            drafter_state
                .rows
                .get(row_idx)
                .is_some_and(|row| row.draft_policy.uses_ordinary_decode())
        });
        let at_window_boundary = active_rows.iter().all(|row_idx| {
            drafter_state
                .rows
                .get(row_idx)
                .is_some_and(|row| row.pending_tokens.is_empty())
        });
        if has_ordinary_fallback && at_window_boundary {
            self.gemma4_drafter_state = Some(drafter_state);
            return self.step_inner(model);
        }
        if active_rows.len() == 1
            && self.active_count() == 1
            && self.cache_rows.as_slice() == active_rows.as_slice()
        {
            self.gemma4_drafter_state = Some(drafter_state);
            return self.step_gemma4_drafter_single(model, drafter, refill_after_emit);
        }

        let rows_needing_prefill = active_rows
            .iter()
            .copied()
            .filter(|row_idx| {
                drafter_state
                    .rows
                    .get(row_idx)
                    .is_some_and(|row| row.pending_tokens.is_empty())
            })
            .collect::<Vec<_>>();
        self.fill_gemma4_drafter_windows_batched(
            &rows_needing_prefill,
            cfg,
            &mut drafter_state.stats,
            &mut drafter_state.rows,
            model,
            drafter,
        )?;

        let mut events = Vec::with_capacity(active_rows.len());

        for row_idx in active_rows.iter().copied() {
            let token = drafter_state
                .rows
                .get_mut(&row_idx)
                .ok_or_else(|| anyhow!("step_gemma4_drafter_batch: row {row_idx} state absent"))?
                .pending_tokens
                .pop_front()
                .ok_or_else(|| {
                    anyhow!("step_gemma4_drafter_batch: row {row_idx} pending token queue is empty")
                })?;
            events.push(self.emit_token_for_row(row_idx, token)?);
        }

        let rows_needing_postfill = events
            .iter()
            .filter(|event| event.finish_reason.is_none())
            .filter_map(|event| {
                self.slots.iter().enumerate().find_map(|(row_idx, slot)| {
                    slot.as_ref()
                        .filter(|state| state.id == event.id)
                        .map(|_| row_idx)
                })
            })
            .filter(|row_idx| {
                drafter_state
                    .rows
                    .get(row_idx)
                    .is_some_and(|row| row.pending_tokens.is_empty())
            })
            .collect::<Vec<_>>();
        if refill_after_emit && !has_ordinary_fallback {
            self.fill_gemma4_drafter_windows_batched(
                &rows_needing_postfill,
                cfg,
                &mut drafter_state.stats,
                &mut drafter_state.rows,
                model,
                drafter,
            )?;
        }

        let any_unfinished = self
            .slots
            .iter()
            .any(|slot| matches!(slot, Some(state) if !state.finished));
        self.phase = if any_unfinished {
            Phase::Decoding
        } else {
            Phase::Finished
        };
        self.gemma4_drafter_state = Some(drafter_state);
        self.refresh_active_kv_residency_stats();

        Ok(events)
    }

    fn fill_gemma4_drafter_windows_batched(
        &mut self,
        rows_to_fill: &[usize],
        cfg: MtpSpeculativeConfig,
        stats: &mut MtpSpeculativeStats,
        row_states: &mut HashMap<usize, SchedulerGemma4DrafterRowState>,
        model: &crate::models::Gemma4Model,
        drafter: &crate::models::gemma4::Gemma4AssistantModel,
    ) -> Result<()> {
        if rows_to_fill.is_empty() {
            return Ok(());
        }
        if model.requires_position_ids() {
            return Err(anyhow!(
                "fill_gemma4_drafter_windows_batched: Gemma4 drafter batched decode requires model-derived positions"
            ));
        }

        let window_started = Instant::now();
        let stats_before_window = stats.clone();
        let timing_before = stats.draft_cap_timing();
        let kv_state = MtpDraftPolicyKvState::from_runtime(
            self.paged_prefix_cache.is_some(),
            self.active_kv_config.enabled,
        );
        let kv_bits = self.kv_cache_turboquant_bits_for_rows(rows_to_fill)?;

        let mut contexts = Vec::with_capacity(rows_to_fill.len());
        for &row_idx in rows_to_fill {
            let slot = self.slots[row_idx].as_ref().ok_or_else(|| {
                anyhow!("fill_gemma4_drafter_windows_batched: row {row_idx} slot absent")
            })?;
            if slot.finished {
                continue;
            }
            let emitted = slot.generated_tokens.len();
            let remaining = slot.max_new_tokens.saturating_sub(emitted);
            if remaining == 0 {
                continue;
            }
            let current_token = *slot.generated_tokens.last().ok_or_else(|| {
                anyhow!("fill_gemma4_drafter_windows_batched: row {row_idx} has no current token")
            })?;
            let row_state = row_states.get_mut(&row_idx).ok_or_else(|| {
                anyhow!("fill_gemma4_drafter_windows_batched: row {row_idx} state absent")
            })?;
            let mut history =
                Vec::with_capacity(slot.prompt_ids.len() + slot.generated_tokens.len());
            history.extend_from_slice(&slot.prompt_ids);
            history.extend_from_slice(&slot.generated_tokens);
            if history.len() > 32_768 && row_state.draft_policy.seed_initial_budget(1) {
                row_state.adaptive_draft_tokens = row_state.draft_policy.current_budget();
            }
            let effective_max_draft_tokens = cfg.max_draft_tokens;
            let draft_budget = row_state
                .adaptive_draft_tokens
                .min(effective_max_draft_tokens)
                .min(remaining);
            let kv_valid_len = (history.len() - 1) as i32;
            contexts.push(Gemma4DrafterBatchedFillContext {
                row_idx,
                current_token,
                stop_token_ids: slot.stop_token_ids.clone(),
                remaining,
                effective_max_draft_tokens,
                draft_budget,
                kv_valid_len,
                draft_position: crate::models::gemma4::draft_position_for_shared_kv(kv_valid_len),
                shared_kv: row_state.shared_kv.clone(),
                input_hidden: row_state.last_hidden.clone(),
                input_token: current_token,
                draft_history: history,
                draft_tokens: Vec::with_capacity(draft_budget),
                verify_input: Vec::new(),
            });
        }
        if contexts.is_empty() {
            return Ok(());
        }
        let policy_batch_width = self
            .slots
            .iter()
            .enumerate()
            .filter(|(row_idx, slot)| {
                matches!(slot, Some(state) if !state.finished) && row_states.contains_key(row_idx)
            })
            .count()
            .max(1);
        let mut draft_constraints = contexts
            .iter()
            .filter_map(|ctx| {
                self.slots[ctx.row_idx]
                    .as_ref()
                    .and_then(|state| state.constraint.clone())
                    .map(|constraint| (ctx.row_idx, constraint))
            })
            .collect::<HashMap<_, _>>();

        let max_draft_budget = contexts
            .iter()
            .map(|ctx| ctx.draft_budget)
            .max()
            .unwrap_or(0);
        for offset in 0..max_draft_budget {
            let active_indices = contexts
                .iter()
                .enumerate()
                .filter_map(|(idx, ctx)| (offset < ctx.draft_budget).then_some(idx))
                .collect::<Vec<_>>();
            if active_indices.is_empty() {
                continue;
            }

            let tokens = active_indices
                .iter()
                .map(|&idx| contexts[idx].input_token)
                .collect::<Vec<_>>();
            let token_arr: Array = (&tokens[..], &[tokens.len() as i32, 1_i32][..]).try_into()?;
            let token_embed = model.embed_on(&token_arr, mlx::StreamOrDevice::default())?;
            let hidden_rows = active_indices
                .iter()
                .map(|&idx| &contexts[idx].input_hidden)
                .collect::<Vec<_>>();
            let hidden = mlx::ops::shape::concatenate_on(
                &hidden_rows[..],
                0,
                mlx::StreamOrDevice::default(),
            )?;
            let inputs_embeds = mlx::ops::shape::concatenate_on(
                &[&token_embed, &hidden],
                2,
                mlx::StreamOrDevice::default(),
            )?;
            let shared_rows = active_indices
                .iter()
                .map(|&idx| &contexts[idx].shared_kv)
                .collect::<Vec<_>>();
            let positions = active_indices
                .iter()
                .map(|&idx| contexts[idx].draft_position)
                .collect::<Vec<_>>();
            let kv_valid_lens = active_indices
                .iter()
                .map(|&idx| contexts[idx].kv_valid_len)
                .collect::<Vec<_>>();

            let draft_forward_start = Instant::now();
            let output = drafter.forward_batched_on(
                &inputs_embeds,
                &shared_rows[..],
                &positions,
                &kv_valid_lens,
                mlx::StreamOrDevice::default(),
            )?;
            add_elapsed_us(&mut stats.draft_forward_us, draft_forward_start);

            let sampling_start = Instant::now();
            let draft_logits = if draft_constraints.is_empty() {
                output.logits.clone()
            } else {
                let vocab = output.logits.shape().as_slice()[2];
                let logits = output
                    .logits
                    .reshape(&[active_indices.len() as i32, vocab][..])?;
                let masks = active_indices
                    .iter()
                    .map(|&ctx_idx| {
                        draft_constraints
                            .get_mut(&contexts[ctx_idx].row_idx)
                            .map(crate::core::constrained::ConstraintSession::compute_mask)
                            .transpose()
                    })
                    .collect::<Result<Vec<_>>>()?;
                crate::core::constrained::apply_batch_token_masks(&logits, &masks)?
            };
            let sampled_arr = mlx::ops::reduction::argmax(&draft_logits, -1, false)?;
            let sampled: Vec<u32> = sampled_arr.to_vec()?;
            add_elapsed_us(&mut stats.sampling_us, sampling_start);
            if sampled.len() != active_indices.len() {
                return Err(anyhow!(
                    "fill_gemma4_drafter_windows_batched: sampled {} tokens for {} rows",
                    sampled.len(),
                    active_indices.len()
                ));
            }
            for (compact_idx, &ctx_idx) in active_indices.iter().enumerate() {
                let next_token = sampled[compact_idx];
                let ctx = &mut contexts[ctx_idx];
                if let Some(constraint) = draft_constraints.get_mut(&ctx.row_idx) {
                    constraint.commit_token(next_token)?;
                }
                ctx.draft_tokens.push(next_token);
                ctx.draft_history.push(next_token);
                ctx.input_token = next_token;
                ctx.input_hidden = slice_hidden_row_position(
                    &output.hidden_states,
                    compact_idx,
                    0,
                    mlx::StreamOrDevice::default(),
                )?;
            }
        }

        for ctx in &mut contexts {
            ctx.verify_input = verify_input(ctx.current_token, &ctx.draft_tokens);
        }

        let active_rows = self
            .slots
            .iter()
            .enumerate()
            .filter_map(|(row, slot)| {
                (matches!(slot, Some(state) if !state.finished) && row_states.contains_key(&row))
                    .then_some(row)
            })
            .collect::<Vec<_>>();
        self.rebuild_cache_layout(model, &active_rows)?;
        let cache_row_for_ctx = contexts
            .iter()
            .map(|ctx| {
                self.cache_rows
                    .iter()
                    .position(|&row| row == ctx.row_idx)
                    .ok_or_else(|| {
                        anyhow!(
                            "fill_gemma4_drafter_windows_batched: row {} missing from cache layout {:?}",
                            ctx.row_idx,
                            self.cache_rows
                        )
                    })
            })
            .collect::<Result<Vec<_>>>()?;
        let max_verify_len = contexts
            .iter()
            .map(|ctx| ctx.verify_input.len())
            .max()
            .unwrap_or(0);
        if max_verify_len == 0 {
            return Ok(());
        }

        let base_snapshot = {
            let cache = self
                .cache
                .as_ref()
                .ok_or_else(|| anyhow!("fill_gemma4_drafter_windows_batched: main cache absent"))?;
            cache
                .iter()
                .map(LayerCache::append_snapshot)
                .collect::<Result<Vec<_>>>()?
        };
        let (verify_arr, verify_lens) = build_gemma4_drafter_batched_verify_input(
            &active_rows,
            &contexts,
            &cache_row_for_ctx,
            max_verify_len,
        )?;
        let verify_pos_ids = self.reusable_dummy_position_ids()?;
        let verify_forward_start = Instant::now();
        let stable_attention = gemma4_long_verify_needs_stable_attention(
            kv_bits,
            contexts
                .iter()
                .map(|ctx| ctx.draft_history.len())
                .max()
                .unwrap_or(0),
            max_verify_len,
            active_rows.len(),
        );
        let stable_k3v4_verify = gemma4_verify_needs_batch_stable_qmm(
            self.kv_cache_turboquant_bits_for_rows(rows_to_fill)?,
            active_rows.len(),
            max_verify_len,
        );
        // Preserve repeated [B, 1] target-decode numerics for every packed
        // verify position. These guards intentionally remain alive through
        // lm_head projection as that projection is also shape-sensitive.
        let position_stable_verify = max_verify_len > 1;
        let _position_stable_linear =
            position_stable_verify.then(crate::nn::position_stable_linear::scope);
        let _position_stable_qmm =
            position_stable_verify.then(crate::nn::position_stable_qmm::scope);
        let max_context_tokens = contexts
            .iter()
            .map(|ctx| ctx.draft_history.len())
            .max()
            .unwrap_or(0);
        let exact_batched_qualified = model.supports_exact_batched_speculative_verify_for_kv_cache(
            active_rows.len(),
            max_context_tokens,
            max_verify_len,
            kv_bits,
        );
        let sequential_q1_verify = gemma4_verify_requires_sequential_q1(
            exact_batched_qualified,
            kv_bits,
            active_rows.len(),
            &verify_lens,
            max_verify_len,
        );
        let verified = {
            let _stable_qmm = stable_k3v4_verify.then(crate::nn::batch_stable_qmm::context_scope);
            let _stable_attention =
                stable_attention.then(crate::nn::gemma4_verify_attention::scope);
            let cache = self
                .cache
                .as_mut()
                .ok_or_else(|| anyhow!("fill_gemma4_drafter_windows_batched: main cache absent"))?;
            // A zero-draft B=1 window is the cost-aware control path and
            // must retain ordinary single-token decode morphology. Passing
            // `Some(&[1])` disables Gemma4's single-row decode fast path,
            // builds explicit masks, and makes the control path roughly 3x
            // slower than the actual Scheduler baseline.
            let verify_lens = if active_rows.len() == 1 && max_verify_len == 1 {
                None
            } else {
                Some(verify_lens.as_slice())
            };
            if sequential_q1_verify {
                // Quantized KV profiles outside the model's exact batched
                // qualification must retain the complete ordinary [B, 1]
                // target shape, not only position-stable projections or
                // attention. This preserves strict argmax parity without a
                // context-length hard limit; accepted drafts and the online
                // cost policy remain active above the sequential verifier.
                let mut hidden_positions = Vec::with_capacity(max_verify_len);
                let mut final_output = None;
                // B1 ordinary decode deliberately omits per-row lengths so
                // Gemma4 keeps its single-row decode fast path and exact
                // numerical morphology. Multi-row Q1 still needs explicit
                // lengths to describe every compact cache row.
                let step_lens = (active_rows.len() > 1).then(|| vec![1_i32; active_rows.len()]);
                for position in 0..max_verify_len as i32 {
                    let input = mlx::ops::indexing::slice_strided_on(
                        &verify_arr,
                        &[0_i32, position][..],
                        &[active_rows.len() as i32, position + 1][..],
                        &[1_i32, 1][..],
                        mlx::StreamOrDevice::default(),
                    )?;
                    let output = model.forward_text_hidden_with_shared_kv_on(
                        &input,
                        &verify_pos_ids,
                        step_lens.as_deref(),
                        None,
                        Some(cache.as_mut_slice()),
                        mlx::StreamOrDevice::default(),
                    )?;
                    mlx::transforms::eval(&[&output.hidden])?;
                    hidden_positions.push(output.hidden.clone());
                    final_output = Some(output);
                }
                let hidden_refs = hidden_positions.iter().collect::<Vec<_>>();
                let mut output = final_output.ok_or_else(|| {
                    anyhow!("Gemma4 sequential Q1 verify produced no target positions")
                })?;
                output.hidden = mlx::ops::shape::concatenate_on(
                    &hidden_refs,
                    1,
                    mlx::StreamOrDevice::default(),
                )?;
                output
            } else {
                model.forward_text_hidden_with_shared_kv_on(
                    &verify_arr,
                    &verify_pos_ids,
                    verify_lens,
                    None,
                    Some(cache.as_mut_slice()),
                    mlx::StreamOrDevice::default(),
                )?
            }
        };
        self.refresh_active_kv_residency_stats();
        add_elapsed_us(&mut stats.verify_forward_us, verify_forward_start);

        let projection_start = Instant::now();
        let verified_logits =
            model.project_hidden_on(&verified.hidden, mlx::StreamOrDevice::default())?;
        let mut speculative_masks = vec![None; active_rows.len()];
        for (ctx_idx, ctx) in contexts.iter().enumerate() {
            let Some(constraint) = self.slots[ctx.row_idx]
                .as_ref()
                .and_then(|state| state.constraint.as_ref())
            else {
                continue;
            };
            speculative_masks[cache_row_for_ctx[ctx_idx]] =
                Some(constraint.speculative_masks(&ctx.draft_tokens)?);
        }
        let verified_logits = crate::core::constrained::apply_speculative_token_masks(
            &verified_logits,
            &speculative_masks,
        )?;
        add_elapsed_us(&mut stats.projection_us, projection_start);
        let sampling_start = Instant::now();
        let verified_ids = mlx::ops::reduction::argmax(&verified_logits, -1, false)?;
        let verified_tokens_flat: Vec<u32> = verified_ids.to_vec()?;
        add_elapsed_us(&mut stats.sampling_us, sampling_start);

        let mut resolutions = Vec::with_capacity(contexts.len());
        for (ctx_idx, ctx) in contexts.iter().enumerate() {
            let compact_row = cache_row_for_ctx[ctx_idx];
            let verify_len = ctx.verify_input.len();
            let verified_tokens = row_tokens_from_flat(
                &verified_tokens_flat,
                compact_row,
                max_verify_len,
                verify_len,
            )?;
            let resolution = resolve_speculative_tokens(&ctx.draft_tokens, &verified_tokens)?;
            stats.windows += 1;
            stats.drafted_tokens += ctx.draft_tokens.len();
            stats.accepted_draft_tokens += resolution.accepted_draft_len;
            stats.record_window_acceptance(ctx.draft_tokens.len(), resolution.accepted_draft_len);
            if resolution.needs_rollback {
                stats.rollback_count += 1;
            }
            resolutions.push(resolution);
        }

        let mismatch_rows = resolutions
            .iter()
            .enumerate()
            .filter_map(|(ctx_idx, resolution)| {
                resolution.needs_rollback.then_some((
                    cache_row_for_ctx[ctx_idx],
                    resolution.accepted_verify_input_len,
                ))
            })
            .collect::<Vec<_>>();
        let accepted_draft_tokens = resolutions
            .iter()
            .map(|resolution| resolution.accepted_draft_len)
            .sum();
        let rollback_count = mismatch_rows.len();
        if !mismatch_rows.is_empty() {
            let rollback_start = Instant::now();
            {
                let cache = self.cache.as_mut().ok_or_else(|| {
                    anyhow!("fill_gemma4_drafter_windows_batched: main cache absent")
                })?;
                trim_full_layer_cache_rows_to_accepted_prefix(
                    cache.as_mut_slice(),
                    &base_snapshot,
                    &mismatch_rows,
                )?;
            }
            self.refresh_active_kv_residency_stats();
            add_elapsed_us(&mut stats.main_rollback_us, rollback_start);
        }

        // B=1 sliding attention returns a tail-aligned view, so removing the
        // rejected suffix preserves its absolute start. Batched attention
        // returns the full padded cache view and must use each row's offset.
        let single_row_layout = active_rows.len() == 1;
        let mut committed_tokens = 0usize;
        let mut policy_inputs = Vec::with_capacity(contexts.len());
        for (ctx_idx, (ctx, resolution)) in contexts.iter().zip(resolutions).enumerate() {
            let compact_row = cache_row_for_ctx[ctx_idx];
            let accepted_len = resolution.accepted_verify_input_len;
            let row_state = row_states.get_mut(&ctx.row_idx).ok_or_else(|| {
                anyhow!(
                    "fill_gemma4_drafter_windows_batched: row {} state absent after verify",
                    ctx.row_idx
                )
            })?;
            let accepted_draft_len = resolution.accepted_draft_len;
            row_state.last_hidden = slice_hidden_row_position(
                &verified.hidden,
                compact_row,
                accepted_len - 1,
                mlx::StreamOrDevice::default(),
            )?;
            row_state.shared_kv = if single_row_layout {
                let rejected_len = ctx.verify_input.len().checked_sub(accepted_len).ok_or_else(|| {
                    anyhow!(
                        "fill_gemma4_drafter_windows_batched: row {} accepted length {accepted_len} exceeds verify length {}",
                        ctx.row_idx,
                        ctx.verify_input.len()
                    )
                })?;
                crate::models::gemma4::shared_kv_row_trim_suffix_on(
                    &verified.shared_kv,
                    compact_row,
                    rejected_len,
                    mlx::StreamOrDevice::default(),
                )?
            } else {
                let accepted_cache_len = {
                    let cache = self.cache.as_ref().ok_or_else(|| {
                        anyhow!("fill_gemma4_drafter_windows_batched: main cache absent")
                    })?;
                    full_layer_cache_row_offset(cache.as_slice(), compact_row)?
                };
                crate::models::gemma4::shared_kv_row_prefix_on(
                    &verified.shared_kv,
                    compact_row,
                    accepted_cache_len,
                    mlx::StreamOrDevice::default(),
                )?
            };
            let constraint = self.slots[ctx.row_idx]
                .as_ref()
                .and_then(|state| state.constraint.as_ref());
            let row_committed_tokens =
                append_resolved_gemma4_tokens(row_state, ctx, constraint, resolution)?;
            committed_tokens = committed_tokens.saturating_add(row_committed_tokens);
            policy_inputs.push((
                ctx.row_idx,
                ctx.draft_tokens.len(),
                accepted_draft_len,
                usize::try_from(ctx.kv_valid_len)
                    .unwrap_or(0)
                    .saturating_add(1),
                row_committed_tokens,
                ctx.effective_max_draft_tokens,
            ));
        }

        self.refresh_active_kv_residency_stats();
        let stats_delta = stats.saturating_delta_since(&stats_before_window);
        let divisor = contexts.len() as u64;
        let per_row_delta = divided_mtp_stats_timing(&stats_delta, divisor);
        let total_us = elapsed_us_since(window_started);
        for (row_idx, attempted, accepted, context_tokens, committed, max_draft_tokens) in
            policy_inputs
        {
            let row_state = row_states.get_mut(&row_idx).ok_or_else(|| {
                anyhow!(
                    "fill_gemma4_drafter_windows_batched: row {row_idx} state absent for policy update"
                )
            })?;
            let policy_window = MtpDraftPolicyWindow::from_stats_delta(
                attempted,
                accepted,
                committed,
                total_us / divisor,
                context_tokens,
                policy_batch_width,
                kv_state,
                &per_row_delta,
            );
            let change = row_state.draft_policy.observe_window(policy_window);
            if change.reduced {
                stats.draft_budget_reductions = stats.draft_budget_reductions.saturating_add(1);
            } else if change.increased {
                stats.draft_budget_increases = stats.draft_budget_increases.saturating_add(1);
            }
            row_state.adaptive_draft_tokens = row_state
                .draft_policy
                .current_budget()
                .min(max_draft_tokens);
        }
        let timing_delta = stats
            .draft_cap_timing()
            .saturating_delta_since(timing_before);
        let draft_tokens_by_row = contexts
            .iter()
            .map(|ctx| ctx.draft_tokens.len())
            .collect::<Vec<_>>();
        let context_tokens_by_row = contexts
            .iter()
            .map(|ctx| {
                usize::try_from(ctx.kv_valid_len)
                    .unwrap_or(0)
                    .saturating_add(1)
            })
            .collect::<Vec<_>>();
        stats.record_draft_cap_observation(
            cfg.max_draft_tokens,
            &draft_tokens_by_row,
            &context_tokens_by_row,
            accepted_draft_tokens,
            committed_tokens,
            rollback_count,
            total_us,
            timing_delta,
        );
        Ok(())
    }

    fn step_gemma4_drafter_single(
        &mut self,
        model: &crate::models::Gemma4Model,
        drafter: &crate::models::gemma4::Gemma4AssistantModel,
        refill_after_emit: bool,
    ) -> Result<Vec<StepEvent>> {
        if self.phase != Phase::Decoding {
            return Err(anyhow!(
                "step_gemma4_drafter_single illegal in {:?} phase: call prefill_admitted_gemma4_drafter_single first",
                self.phase
            ));
        }
        let active_rows: Vec<usize> = self
            .slots
            .iter()
            .enumerate()
            .filter_map(|(row, slot)| matches!(slot, Some(state) if !state.finished).then_some(row))
            .collect();
        if active_rows.len() != 1 {
            return Err(anyhow!(
                "step_gemma4_drafter_single requires exactly one unfinished row, got {}",
                active_rows.len()
            ));
        }
        let row_idx = active_rows[0];
        let ordinary_fallback = self
            .gemma4_drafter_state
            .as_ref()
            .and_then(|state| state.rows.get(&row_idx))
            .is_some_and(|row| {
                row.pending_tokens.is_empty() && row.draft_policy.uses_ordinary_decode()
            });
        if ordinary_fallback {
            return self.step_inner(model);
        }
        if self.cache_rows.as_slice() != active_rows.as_slice() {
            return Err(anyhow!(
                "step_gemma4_drafter_single requires single-row cache layout for row {row_idx}, got {:?}",
                self.cache_rows
            ));
        }
        if self
            .gemma4_drafter_state
            .as_ref()
            .ok_or_else(|| anyhow!("step_gemma4_drafter_single: drafter state absent"))?
            .rows
            .get(&row_idx)
            .ok_or_else(|| anyhow!("step_gemma4_drafter_single: row state absent"))?
            .pending_tokens
            .is_empty()
        {
            self.fill_gemma4_drafter_window_single(row_idx, model, drafter)?;
        }

        let token = {
            let drafter_state = self
                .gemma4_drafter_state
                .as_mut()
                .ok_or_else(|| anyhow!("step_gemma4_drafter_single: drafter state absent"))?;
            drafter_state
                .rows
                .get_mut(&row_idx)
                .ok_or_else(|| anyhow!("step_gemma4_drafter_single: row state absent"))?
                .pending_tokens
                .pop_front()
                .ok_or_else(|| {
                    anyhow!("step_gemma4_drafter_single: pending token queue is empty")
                })?
        };

        let event = self.emit_token_for_row(row_idx, token)?;
        let finish_reason = event.finish_reason;

        if finish_reason.is_some() {
            self.phase = Phase::Finished;
        } else if refill_after_emit
            && self
                .gemma4_drafter_state
                .as_ref()
                .and_then(|state| state.rows.get(&row_idx))
                .is_some_and(|state| {
                    state.pending_tokens.is_empty() && !state.draft_policy.uses_ordinary_decode()
                })
        {
            self.fill_gemma4_drafter_window_single(row_idx, model, drafter)?;
        }

        Ok(vec![event])
    }

    fn fill_gemma4_drafter_window_single(
        &mut self,
        row_idx: usize,
        model: &crate::models::Gemma4Model,
        drafter: &crate::models::gemma4::Gemma4AssistantModel,
    ) -> Result<()> {
        let mut drafter_state = self
            .gemma4_drafter_state
            .take()
            .ok_or_else(|| anyhow!("fill_gemma4_drafter_window_single: drafter state absent"))?;
        let mut row_state = drafter_state.rows.remove(&row_idx).ok_or_else(|| {
            anyhow!("fill_gemma4_drafter_window_single: row {row_idx} state absent")
        })?;
        let result = self.fill_gemma4_drafter_window_single_with_state(
            row_idx,
            Gemma4DrafterWindowPolicy {
                cfg: drafter_state.cfg,
            },
            &mut drafter_state.stats,
            &mut row_state,
            model,
            drafter,
        );
        drafter_state.rows.insert(row_idx, row_state);
        self.gemma4_drafter_state = Some(drafter_state);
        result
    }

    fn fill_gemma4_drafter_window_single_with_state(
        &mut self,
        row_idx: usize,
        policy: Gemma4DrafterWindowPolicy,
        stats: &mut MtpSpeculativeStats,
        row_state: &mut SchedulerGemma4DrafterRowState,
        model: &crate::models::Gemma4Model,
        drafter: &crate::models::gemma4::Gemma4AssistantModel,
    ) -> Result<()> {
        let Gemma4DrafterWindowPolicy { cfg } = policy;
        let (prompt_ids, generated_tokens, max_new_tokens, sampler, stop_token_ids, constraint) = {
            let state = self.slots[row_idx]
                .as_ref()
                .ok_or_else(|| anyhow!("fill_gemma4_drafter_window_single: row slot absent"))?;
            (
                state.prompt_ids.clone(),
                state.generated_tokens.clone(),
                state.max_new_tokens,
                state.sampler,
                state.stop_token_ids.clone(),
                state.constraint.clone(),
            )
        };
        let emitted = generated_tokens.len();
        let remaining = max_new_tokens.saturating_sub(emitted);
        if remaining == 0 {
            return Ok(());
        }
        let current_token = *generated_tokens
            .last()
            .ok_or_else(|| anyhow!("fill_gemma4_drafter_window_single: no current token"))?;
        let mut history = Vec::with_capacity(prompt_ids.len() + generated_tokens.len());
        history.extend_from_slice(&prompt_ids);
        history.extend_from_slice(&generated_tokens);

        let window_started = Instant::now();
        let stats_before_window = stats.clone();
        let timing_before = stats.draft_cap_timing();
        let context_tokens = history.len();
        let kv_state = MtpDraftPolicyKvState::from_runtime(
            self.paged_prefix_cache.is_some(),
            self.active_kv_config.enabled,
        );

        if context_tokens > 32_768 && row_state.draft_policy.seed_initial_budget(1) {
            row_state.adaptive_draft_tokens = row_state.draft_policy.current_budget();
        }
        let effective_max_draft_tokens = cfg.max_draft_tokens;
        let draft_budget = row_state
            .adaptive_draft_tokens
            .min(effective_max_draft_tokens)
            .min(remaining);
        let mut compact_prng = self.compact_prng_state_for_rows(&[row_idx])?;
        let mut draft_prng = if sampler.is_pipelinable() {
            None
        } else {
            Some(split_speculative_draft_prng(&mut compact_prng)?)
        };
        let mut draft_constraint = constraint.clone();
        let (draft_tokens, _draft_distributions) = self.draft_gemma4_drafter_tokens_single(
            stats,
            row_state,
            model,
            drafter,
            current_token,
            draft_budget,
            &history,
            sampler,
            draft_prng.as_mut(),
            draft_constraint.as_mut(),
        )?;
        let verify_input = verify_input(current_token, &draft_tokens);
        let verify_start_pos = (history.len() - 1) as i32;
        let verify_pos_ids =
            self.gemma4_drafter_position_ids(model, verify_start_pos, verify_input.len() as i32)?;
        let verify_arr: Array =
            (&verify_input[..], &[1_i32, verify_input.len() as i32][..]).try_into()?;
        let kv_bits = self.kv_cache_turboquant_bits_for_rows(&[row_idx])?;
        let exact_batched_qualified = model.supports_exact_batched_speculative_verify_for_kv_cache(
            1,
            context_tokens,
            verify_input.len(),
            kv_bits,
        );
        let verify_lens = [i32::try_from(verify_input.len())?];
        let sequential_q1_verify = gemma4_verify_requires_sequential_q1(
            exact_batched_qualified,
            kv_bits,
            1,
            &verify_lens,
            verify_input.len(),
        );

        let base_snapshot = {
            let cache = self
                .cache
                .as_ref()
                .ok_or_else(|| anyhow!("fill_gemma4_drafter_window_single: main cache absent"))?;
            cache
                .iter()
                .map(LayerCache::append_snapshot)
                .collect::<Result<Vec<_>>>()?
        };
        let verify_forward_start = Instant::now();
        let position_stable_verify = verify_input.len() > 1;
        let _position_stable_linear =
            position_stable_verify.then(crate::nn::position_stable_linear::scope);
        let _position_stable_qmm =
            position_stable_verify.then(crate::nn::position_stable_qmm::scope);
        let verified = {
            let stable_attention = gemma4_long_verify_needs_stable_attention(
                kv_bits,
                context_tokens,
                verify_input.len(),
                1,
            );
            let _stable_attention =
                stable_attention.then(crate::nn::gemma4_verify_attention::scope);
            let cache = self
                .cache
                .as_mut()
                .ok_or_else(|| anyhow!("fill_gemma4_drafter_window_single: main cache absent"))?;
            if sequential_q1_verify {
                let mut hidden_positions = Vec::with_capacity(verify_input.len());
                let mut final_output = None;
                for position in 0..i32::try_from(verify_input.len())? {
                    let input = mlx::ops::indexing::slice_strided_on(
                        &verify_arr,
                        &[0_i32, position][..],
                        &[1_i32, position + 1][..],
                        &[1_i32, 1][..],
                        mlx::StreamOrDevice::default(),
                    )?;
                    let output = model.forward_text_hidden_with_shared_kv_on(
                        &input,
                        &verify_pos_ids,
                        None,
                        None,
                        Some(cache.as_mut_slice()),
                        mlx::StreamOrDevice::default(),
                    )?;
                    mlx::transforms::eval(&[&output.hidden])?;
                    hidden_positions.push(output.hidden.clone());
                    final_output = Some(output);
                }
                let hidden_refs = hidden_positions.iter().collect::<Vec<_>>();
                let mut output = final_output.ok_or_else(|| {
                    anyhow!("Gemma4 sequential B1 verify produced no target positions")
                })?;
                output.hidden = mlx::ops::shape::concatenate_on(
                    &hidden_refs,
                    1,
                    mlx::StreamOrDevice::default(),
                )?;
                output
            } else {
                model.forward_text_hidden_with_shared_kv_on(
                    &verify_arr,
                    &verify_pos_ids,
                    None,
                    None,
                    Some(cache.as_mut_slice()),
                    mlx::StreamOrDevice::default(),
                )?
            }
        };
        self.refresh_active_kv_residency_stats();
        add_elapsed_us(&mut stats.verify_forward_us, verify_forward_start);
        let projection_start = Instant::now();
        let verified_logits =
            model.project_hidden_on(&verified.hidden, mlx::StreamOrDevice::default())?;
        let verified_logits = if let Some(constraint) = constraint.as_ref() {
            crate::core::constrained::apply_speculative_token_masks(
                &verified_logits,
                &[Some(constraint.speculative_masks(&draft_tokens)?)],
            )?
        } else {
            verified_logits
        };
        add_elapsed_us(&mut stats.projection_us, projection_start);
        let sampling_start = Instant::now();
        let resolution = if sampler.is_pipelinable() {
            let verified_tokens =
                sample_logits_positions(&verified_logits, sampler, &history, &mut compact_prng)?;
            resolve_speculative_tokens(&draft_tokens, &verified_tokens)?
        } else {
            resolve_exact_deterministic_target_logits(
                &draft_tokens,
                &verified_logits,
                sampler,
                &history,
                &mut compact_prng,
            )?
        };
        add_elapsed_us(&mut stats.sampling_us, sampling_start);
        let accepted_draft_len = resolution.accepted_draft_len;
        let rollback_count = usize::from(resolution.needs_rollback);
        stats.windows += 1;
        stats.drafted_tokens += draft_tokens.len();
        stats.accepted_draft_tokens += resolution.accepted_draft_len;
        stats.record_exact_sampling(resolution.exact_sampling);
        stats.record_window_acceptance(draft_tokens.len(), resolution.accepted_draft_len);
        if resolution.needs_rollback {
            stats.rollback_count += 1;
        }
        let accepted_len = resolution.accepted_verify_input_len;
        let accepted_last_hidden =
            slice_hidden_position(&verified.hidden, i32::try_from(accepted_len)? - 1)?;
        let accepted_shared_kv = if resolution.needs_rollback {
            let rollback_start = Instant::now();
            {
                let cache = self.cache.as_mut().ok_or_else(|| {
                    anyhow!("fill_gemma4_drafter_window_single: main cache absent")
                })?;
                trim_full_layer_cache_rows_to_accepted_prefix(
                    cache.as_mut_slice(),
                    &base_snapshot,
                    &[(0, accepted_len)],
                )?;
            }
            self.refresh_active_kv_residency_stats();
            add_elapsed_us(&mut stats.main_rollback_us, rollback_start);
            let rejected_len = verify_input.len().checked_sub(accepted_len).ok_or_else(|| {
                anyhow!(
                    "fill_gemma4_drafter_window_single: accepted length {accepted_len} exceeds verify length {}",
                    verify_input.len()
                )
            })?;
            crate::models::gemma4::shared_kv_row_trim_suffix_on(
                &verified.shared_kv,
                0,
                rejected_len,
                mlx::StreamOrDevice::default(),
            )?
        } else {
            verified.shared_kv
        };
        row_state.last_hidden = accepted_last_hidden;
        row_state.shared_kv = accepted_shared_kv;

        let mut tokens_to_append = resolution.tokens_to_append;
        if let Some(stop_idx) = tokens_to_append
            .iter()
            .position(|token| stop_token_ids.contains(token))
        {
            tokens_to_append.truncate(stop_idx + 1);
        }
        tokens_to_append.truncate(remaining);
        if let Some(constraint) = constraint.as_ref() {
            constraint.truncate_invalid_speculative_bonus(&mut tokens_to_append)?;
        }
        let committed_tokens = tokens_to_append.len();
        row_state.pending_tokens.extend(tokens_to_append);
        self.refresh_active_kv_residency_stats();
        let total_us = elapsed_us_since(window_started);
        let stats_delta = stats.saturating_delta_since(&stats_before_window);
        let policy_window = MtpDraftPolicyWindow::from_stats_delta(
            draft_tokens.len(),
            accepted_draft_len,
            committed_tokens,
            total_us,
            context_tokens,
            1,
            kv_state,
            &stats_delta,
        );
        let change = row_state.draft_policy.observe_window(policy_window);
        if change.reduced {
            stats.draft_budget_reductions = stats.draft_budget_reductions.saturating_add(1);
        } else if change.increased {
            stats.draft_budget_increases = stats.draft_budget_increases.saturating_add(1);
        }
        row_state.adaptive_draft_tokens = row_state
            .draft_policy
            .current_budget()
            .min(effective_max_draft_tokens);
        let timing_delta = stats
            .draft_cap_timing()
            .saturating_delta_since(timing_before);
        stats.record_draft_cap_observation(
            cfg.max_draft_tokens,
            &[draft_tokens.len()],
            &[context_tokens],
            accepted_draft_len,
            committed_tokens,
            rollback_count,
            total_us,
            timing_delta,
        );
        self.scatter_prng_state_from_rows(&[row_idx], &compact_prng)?;
        Ok(())
    }

    #[allow(clippy::too_many_arguments)]
    fn draft_gemma4_drafter_tokens_single(
        &mut self,
        stats: &mut MtpSpeculativeStats,
        row_state: &mut SchedulerGemma4DrafterRowState,
        model: &crate::models::Gemma4Model,
        drafter: &crate::models::gemma4::Gemma4AssistantModel,
        current_token: u32,
        draft_budget: usize,
        history: &[u32],
        sampler: Sampler,
        draft_prng: Option<&mut Array>,
        mut constraint: Option<&mut crate::core::constrained::ConstraintSession>,
    ) -> Result<(Vec<u32>, Vec<DraftTokenDistribution>)> {
        let mut draft_tokens = Vec::with_capacity(draft_budget);
        let mut draft_distributions = Vec::with_capacity(draft_budget);
        let mut draft_history = history.to_vec();
        let mut input_hidden = row_state.last_hidden.clone();
        let mut input_token = current_token;
        let kv_valid_len = (history.len() - 1) as i32;
        let draft_position = crate::models::gemma4::draft_position_for_shared_kv(kv_valid_len);
        let draft_uniforms = match draft_prng {
            Some(prng) => draw_uniforms(prng, draft_budget)?,
            None => vec![0.0; draft_budget],
        };

        for &draft_uniform in draft_uniforms.iter().take(draft_budget) {
            let token_arr: Array = (&[input_token][..], &[1_i32, 1_i32][..]).try_into()?;
            let token_embed = model.embed_on(&token_arr, mlx::StreamOrDevice::default())?;
            let inputs_embeds = mlx::ops::shape::concatenate_on(
                &[&token_embed, &input_hidden],
                2,
                mlx::StreamOrDevice::default(),
            )?;
            let draft_forward_start = Instant::now();
            let output = drafter.forward_on(
                &inputs_embeds,
                &row_state.shared_kv,
                draft_position,
                kv_valid_len,
                mlx::StreamOrDevice::default(),
            )?;
            add_elapsed_us(&mut stats.draft_forward_us, draft_forward_start);
            let sampling_start = Instant::now();
            let logits = if let Some(constraint) = constraint.as_mut() {
                let vocab = output.logits.shape().as_slice()[2];
                let row = output.logits.reshape((vocab,))?;
                crate::core::constrained::apply_token_mask(&row, &constraint.compute_mask()?)?
                    .reshape(&[1_i32, 1_i32, vocab][..])?
            } else {
                output.logits.clone()
            };
            let (next_token, distribution) = if sampler.is_pipelinable() {
                sample_draft_logits_position(&logits, sampler, &draft_history, None)?
            } else {
                sample_draft_logits_position_with_uniform(
                    &logits,
                    sampler,
                    &draft_history,
                    draft_uniform,
                )?
            };
            add_elapsed_us(&mut stats.sampling_us, sampling_start);
            if let Some(constraint) = constraint.as_mut() {
                constraint.commit_token(next_token)?;
            }
            draft_tokens.push(next_token);
            draft_distributions.push(distribution);
            draft_history.push(next_token);
            input_hidden = output.hidden_states;
            input_token = next_token;
        }

        Ok((draft_tokens, draft_distributions))
    }

    fn gemma4_drafter_position_ids(
        &mut self,
        model: &crate::models::Gemma4Model,
        start_pos: i32,
        len: i32,
    ) -> Result<Array> {
        if model.requires_position_ids() {
            build_position_ids(start_pos, len)
        } else {
            self.reusable_dummy_position_ids()
        }
    }

    fn gemma4_drafter_prefix_cache(&self) -> crate::models::gemma4::Gemma4DrafterPrefixCache {
        crate::models::gemma4::Gemma4DrafterPrefixCache::new_with_shared_prefix_lru(
            self.paged_prefix_cache.clone(),
            self.prefix_lru_cache.clone(),
            None,
        )
    }

    fn temp_gemma4_drafter_scheduler_for_row(
        &self,
        row_idx: usize,
    ) -> Result<Scheduler<crate::models::Gemma4Model>> {
        let state = self.slots[row_idx]
            .as_ref()
            .ok_or_else(|| anyhow!("temp_gemma4_drafter_scheduler_for_row: row slot absent"))?;
        let mut temp = self.temp_scheduler_with_parent_budget::<crate::models::Gemma4Model>()?;
        if let Some(config) = self.paged_prefix_cache.as_ref() {
            temp.enable_paged_prefix_cache(config.clone())?;
        }
        if let Some(prefix_lru_cache) = self.prefix_lru_cache.as_ref() {
            temp.share_prefix_lru_cache(Arc::clone(prefix_lru_cache));
        }
        if let Some(stats) = self.active_kv_stats.as_ref() {
            temp.enable_active_kv_offload(self.active_kv_config.clone(), stats.clone())?;
        }
        let temp_id = temp.admit(generate_request_from_state(state)?)?;
        {
            let temp_state = temp.slots[0].as_mut().ok_or_else(|| {
                anyhow!("temp_gemma4_drafter_scheduler_for_row: temp slot absent")
            })?;
            temp_state.id = state.id;
            temp_state.generated_tokens = state.generated_tokens.clone();
            temp_state.real_len = state.real_len;
            temp_state.finished = state.finished;
            temp_state.finish_reason = state.finish_reason;
            temp_state.constraint = state.constraint.clone();
        }
        temp.request_block_tables.remove(&temp_id);
        temp.request_block_tables
            .insert(state.id, RequestBlockTable::new(state.id));
        anyhow::ensure!(
            temp_id == RequestId(0),
            "temp_gemma4_drafter_scheduler_for_row: unexpected temp id {}",
            temp_id.0
        );
        Ok(temp)
    }

    fn temp_gemma4_drafter_rebase_scheduler_for_row(
        &self,
        row_idx: usize,
    ) -> Result<Scheduler<crate::models::Gemma4Model>> {
        let state = self.slots[row_idx].as_ref().ok_or_else(|| {
            anyhow!("temp_gemma4_drafter_rebase_scheduler_for_row: row slot absent")
        })?;
        let expected_current = *state.generated_tokens.last().ok_or_else(|| {
            anyhow!("temp_gemma4_drafter_rebase_scheduler_for_row: current token absent")
        })?;
        anyhow::ensure!(
            !state.stop_token_ids.contains(&expected_current),
            "temp_gemma4_drafter_rebase_scheduler_for_row: unfinished request current token is a stop token"
        );
        let mut temp = self.temp_scheduler_with_parent_budget::<crate::models::Gemma4Model>()?;
        if let Some(config) = self.paged_prefix_cache.as_ref() {
            temp.enable_paged_prefix_cache(config.clone())?;
        }
        if let Some(prefix_lru_cache) = self.prefix_lru_cache.as_ref() {
            temp.share_prefix_lru_cache(Arc::clone(prefix_lru_cache));
        }
        if let Some(stats) = self.active_kv_stats.as_ref() {
            temp.enable_active_kv_offload(self.active_kv_config.clone(), stats.clone())?;
        }
        let temp_id = temp.admit(generate_neural_rebase_request_from_state(state)?)?;
        let temp_state = temp.slots[0].as_mut().ok_or_else(|| {
            anyhow!("temp_gemma4_drafter_rebase_scheduler_for_row: temp slot absent")
        })?;
        temp_state.id = state.id;
        temp_state.constraint = state
            .constraint
            .as_ref()
            .map(|constraint| {
                let mut constraint = constraint.fork();
                constraint.rollback(1)?;
                Ok::<_, anyhow::Error>(constraint)
            })
            .transpose()?;
        temp.request_block_tables.remove(&temp_id);
        temp.request_block_tables
            .insert(state.id, RequestBlockTable::new(state.id));
        anyhow::ensure!(
            temp_id == RequestId(0),
            "temp_gemma4_drafter_rebase_scheduler_for_row: unexpected temp id {}",
            temp_id.0
        );
        Ok(temp)
    }

    pub fn rebase_gemma4_drafter_from_committed_history(
        &mut self,
        model: &crate::models::Gemma4Model,
        drafter: &crate::models::gemma4::Gemma4AssistantModel,
    ) -> Result<()> {
        self.ensure_not_poisoned()?;
        anyhow::ensure!(
            self.phase == Phase::Decoding,
            "rebase_gemma4_drafter_from_committed_history illegal in {:?} phase",
            self.phase
        );
        let drafter_state = self.gemma4_drafter_state.as_ref().ok_or_else(|| {
            anyhow!("rebase_gemma4_drafter_from_committed_history: drafter state absent")
        })?;
        let cfg = drafter_state.cfg;
        let mut stats = drafter_state.stats.clone();
        let active_rows = self
            .slots
            .iter()
            .enumerate()
            .filter_map(|(row, slot)| matches!(slot, Some(state) if !state.finished).then_some(row))
            .collect::<Vec<_>>();
        anyhow::ensure!(
            !active_rows.is_empty(),
            "rebase_gemma4_drafter_from_committed_history requires active rows"
        );

        let mut row_states = HashMap::with_capacity(active_rows.len());
        anyhow::ensure!(
            self.cache.is_some(),
            "rebase_gemma4_drafter_from_committed_history: main cache absent"
        );
        anyhow::ensure!(
            self.cache_rows == active_rows,
            "rebase_gemma4_drafter_from_committed_history: live cache rows {:?} do not match active rows {:?}",
            self.cache_rows,
            active_rows
        );
        for &row_idx in &active_rows {
            let expected_current = *self.slots[row_idx]
                .as_ref()
                .and_then(|state| state.generated_tokens.last())
                .ok_or_else(|| {
                    anyhow!(
                        "rebase_gemma4_drafter_from_committed_history: row {row_idx} current token absent"
                    )
                })?;
            let mut temp = self.temp_gemma4_drafter_rebase_scheduler_for_row(row_idx)?;
            let events = temp
                .prefill_admitted_gemma4_drafter_single(model, drafter, cfg, false)
                .map_err(|error| {
                    anyhow!("rebase_gemma4_drafter_from_committed_history row {row_idx}: {error:#}")
                })?;
            anyhow::ensure!(
                events.len() == 1
                    && events[0].token == expected_current
                    && events[0].finish_reason.is_none(),
                "rebase_gemma4_drafter_from_committed_history row {row_idx}: regenerated boundary token does not match committed token"
            );
            let mut temp_state = temp.gemma4_drafter_state.take().ok_or_else(|| {
                anyhow!(
                    "rebase_gemma4_drafter_from_committed_history row {row_idx}: temp drafter state absent"
                )
            })?;
            add_mtp_stats(&mut stats, temp_state.stats);
            let row_state = temp_state.rows.remove(&0).ok_or_else(|| {
                anyhow!(
                    "rebase_gemma4_drafter_from_committed_history row {row_idx}: temp row state absent"
                )
            })?;
            anyhow::ensure!(
                row_state.pending_tokens.is_empty(),
                "rebase_gemma4_drafter_from_committed_history row {row_idx}: rebase installed speculative pending tokens"
            );
            row_states.insert(row_idx, row_state);
        }

        self.gemma4_drafter_state = Some(SchedulerGemma4DrafterState {
            cfg,
            rows: row_states,
            stats,
        });
        self.refresh_active_kv_residency_stats();
        Ok(())
    }
}

