    #[test]
    #[serial]
    fn device_greedy_acceptance_packs_mismatch_and_bonus_tokens() {
        let verify_input: Array = (&[9_u32, 10, 11, 12, 19, 20, 21, 0][..], &[2_i32, 4_i32][..])
            .try_into()
            .expect("verify input");
        let verified_ids: Array = (
            &[10_u32, 99, 12, 77, 20, 21, 22, 0][..],
            &[2_i32, 4_i32][..],
        )
            .try_into()
            .expect("verified ids");

        let packed = pack_greedy_acceptance_on(
            &verify_input,
            &[4, 3],
            &verified_ids,
            mlx::StreamOrDevice::default(),
        )
        .expect("pack acceptance")
        .to_vec::<u32>()
        .expect("sync packed acceptance");
        assert_eq!(packed, vec![1, 10, 11, 12, 99, 2, 20, 21, 0, 22]);

        let (draft0, resolution0) =
            resolve_packed_greedy_acceptance(&packed, 5, 0, 3).expect("resolve row 0");
        assert_eq!(draft0, vec![10, 11, 12]);
        assert_eq!(resolution0.accepted_draft_len, 1);
        assert_eq!(resolution0.tokens_to_append, vec![10, 99]);
        assert!(resolution0.needs_rollback);

        let (draft1, resolution1) =
            resolve_packed_greedy_acceptance(&packed, 5, 1, 2).expect("resolve row 1");
        assert_eq!(draft1, vec![20, 21]);
        assert_eq!(resolution1.accepted_draft_len, 2);
        assert_eq!(resolution1.tokens_to_append, vec![20, 21, 22]);
        assert!(!resolution1.needs_rollback);
    }

    #[test]
    fn accepted_prefix_trim_updates_only_selected_cache_rows() {
        let mut cache = vec![LayerCache::Full(
            KVCache::new(2, 1, 1, 1, Dtype::Float32, 8).with_step(4),
        )];
        let k1: Array = (&[1.0_f32, 2.0, 3.0, 4.0][..], &[2_i32, 1, 2, 1][..])
            .try_into()
            .expect("k1");
        let v1: Array = (&[10.0_f32, 20.0, 30.0, 40.0][..], &[2_i32, 1, 2, 1][..])
            .try_into()
            .expect("v1");
        let k2: Array = (&[5.0_f32, 6.0, 7.0, 8.0][..], &[2_i32, 1, 2, 1][..])
            .try_into()
            .expect("k2");
        let v2: Array = (&[50.0_f32, 60.0, 70.0, 80.0][..], &[2_i32, 1, 2, 1][..])
            .try_into()
            .expect("v2");

        let LayerCache::Full(kv) = &mut cache[0] else {
            panic!("full cache");
        };
        kv.update_and_fetch(&k1, &v1, &[2, 2])
            .expect("first update");
        let snapshot = cache.iter().map(LayerCache::snapshot).collect::<Vec<_>>();
        let LayerCache::Full(kv) = &mut cache[0] else {
            panic!("full cache");
        };
        kv.update_and_fetch(&k2, &v2, &[2, 2])
            .expect("second update");

        trim_full_layer_cache_rows_to_accepted_prefix(&mut cache, &snapshot, &[(1, 1)])
            .expect("accepted-prefix trim");
        let LayerCache::Full(kv) = &cache[0] else {
            panic!("full cache");
        };
        assert_eq!(kv.offsets(), &[4, 3]);
        assert_eq!(full_layer_cache_row_offset(&cache, 0).unwrap(), 4);
        assert_eq!(full_layer_cache_row_offset(&cache, 1).unwrap(), 3);
    }

    #[test]
    fn full_layer_cache_row_offset_rejects_layer_drift() {
        let mut first = KVCache::new(1, 1, 1, 1, Dtype::Float32, 8).with_step(4);
        let mut second = KVCache::new(1, 1, 1, 1, Dtype::Float32, 8).with_step(4);
        let k: Array = (&[1.0_f32, 2.0][..], &[1_i32, 1, 2, 1][..])
            .try_into()
            .unwrap();
        let v = &k + 10.0_f32;
        first.update_and_fetch(&k, &v, &[2]).unwrap();
        second.update_and_fetch(&k, &v, &[1]).unwrap();
        let cache = vec![LayerCache::Full(first), LayerCache::Full(second)];

        let err = full_layer_cache_row_offset(&cache, 0).unwrap_err();

        assert!(
            err.to_string().contains("offset 1 at layer 1 != 2"),
            "unexpected error: {err:#}"
        );
    }

