    #[test]
    #[serial(mlx_metal)]
    fn mtp_rebase_teacher_forces_committed_boundary_token() {
        let mut scheduler = Scheduler::<ScriptedMtpSchedulerModel>::new(
            1,
            32768,
            crate::core::memory_budget::test_meta_qwen35(),
        )
        .expect("scheduler startup");
        let id = scheduler
            .admit(mtp_req(vec![1, 2], 5))
            .expect("admit request");
        let model = ScriptedMtpSchedulerModel::new(3, vec![4, 8], vec![vec![4, 5], vec![8, 9]]);
        let cfg = MtpSpeculativeConfig::new(1, Sampler::greedy()).expect("mtp cfg");

        scheduler
            .prefill_admitted_mtp_single(&model, &FakeMtpHead, cfg)
            .expect("initial MTP prefill");
        {
            let state = scheduler.get_mut(id).expect("request state");
            state.generated_tokens.push(7);
            state.real_len += 1;
        }
        let main_cache_offset_before =
            match &scheduler.cache.as_ref().expect("main cache before rebase")[0] {
                LayerCache::Full(cache) => cache.offsets()[0],
                LayerCache::Linear(_) | LayerCache::Mla(_) => panic!("expected full cache"),
            };

        scheduler
            .rebase_mtp_from_committed_history(&model, &FakeMtpHead)
            .expect("teacher-forced MTP rebase");

        assert_eq!(
            scheduler.get(id).expect("request state").generated_tokens,
            vec![3, 7],
            "rebase must treat the committed boundary token as authoritative"
        );
        let row = scheduler
            .mtp_state
            .as_ref()
            .expect("MTP state")
            .rows
            .get(&0)
            .expect("row state");
        assert!(
            row.pending_tokens.is_empty() && row.deferred_tail_commit.is_none(),
            "rebase must rebuild only the neural boundary state"
        );
        assert!(
            scheduler.mtp_at_batch_window_boundary(),
            "rebase must not publish tokens whose target KV exists only in the temporary scheduler"
        );
        let main_cache_offset_after =
            match &scheduler.cache.as_ref().expect("main cache after rebase")[0] {
                LayerCache::Full(cache) => cache.offsets()[0],
                LayerCache::Linear(_) | LayerCache::Mla(_) => panic!("expected full cache"),
            };
        assert_eq!(
            main_cache_offset_after, main_cache_offset_before,
            "neural side-state rebase must not replace or advance the live main cache"
        );
    }

    #[test]
    #[serial(mlx_metal)]
    fn native_mtp_exact_qualification_fails_closed_by_context_and_batch_shape() {
        let cfg = MtpSpeculativeConfig::new(1, Sampler::greedy()).expect("mtp cfg");

        let mut long_context = Scheduler::<ScriptedMtpSchedulerModel>::new(
            2,
            32768,
            crate::core::memory_budget::test_meta_qwen35(),
        )
        .expect("scheduler startup");
        long_context
            .admit(mtp_req(vec![1, 2, 3], 5))
            .expect("admit long row");
        let context_limited = ScriptedMtpSchedulerModel::new(3, vec![4], vec![vec![4, 5]])
            .with_exact_verify_limits(2, 2, 2);
        assert!(
            !long_context
                .native_mtp_fresh_exact_verify_eligible(&context_limited, cfg)
                .expect("fresh exact qualification"),
            "native MTP must not start beyond the model's exact context qualification"
        );

        let mut rolling = Scheduler::<ScriptedMtpSchedulerModel>::new(
            2,
            32768,
            crate::core::memory_budget::test_meta_qwen35(),
        )
        .expect("scheduler startup");
        rolling
            .admit(mtp_req(vec![1, 2], 5))
            .expect("admit first row");
        let batch_limited = ScriptedMtpSchedulerModel::new(3, vec![4], vec![vec![4, 5]])
            .with_exact_verify_limits(1, 8, 2);
        rolling
            .prefill_admitted_mtp_batch(&batch_limited, &FakeMtpHead, cfg)
            .expect("MTP prefill");
        for row in rolling
            .mtp_state
            .as_mut()
            .expect("MTP state")
            .rows
            .values_mut()
        {
            row.pending_tokens.clear();
            row.deferred_tail_commit = None;
        }
        assert!(rolling.mtp_at_batch_window_boundary());
        assert!(
            !rolling
                .native_mtp_rolling_admit_exact_verify_eligible(
                    &batch_limited,
                    cfg,
                    &mtp_req(vec![10, 11], 5),
                )
                .expect("rolling exact qualification"),
            "rolling admission must fail closed when the next batch width is unqualified"
        );
        rolling
            .retire_mtp_at_batch_window_boundary()
            .expect("retire MTP");
        assert!(
            rolling.mtp_state.is_none(),
            "retirement must discard only the MTP side state"
        );
    }

    #[test]
    #[serial(mlx_metal)]
    fn mtp_batch_postfill_uses_one_batched_mtp_forward_for_active_rows() {
        let mut s = Scheduler::<ScriptedMtpSchedulerModel>::new(
            2,
            32768,
            crate::core::memory_budget::test_meta_qwen35(),
        )
        .expect("scheduler startup");
        let id0 = s.admit(mtp_req(vec![1, 2], 5)).expect("admit row 0");
        let id1 = s.admit(mtp_req(vec![10, 11], 5)).expect("admit row 1");
        let model = ScriptedMtpSchedulerModel::new_with_first_token_calls(
            3,
            2,
            vec![4, 6, 8, 9],
            vec![vec![4, 5], vec![6, 7], vec![8, 10], vec![9, 11]],
        );
        let cfg = MtpSpeculativeConfig::new(1, Sampler::greedy()).expect("mtp cfg");

        let first = s
            .prefill_admitted_mtp_batch(&model, &FakeMtpHead, cfg)
            .expect("mtp batch prefill");
        assert_eq!(
            first,
            vec![
                StepEvent {
                    id: id0,
                    token: 3,
                    finish_reason: None
                },
                StepEvent {
                    id: id1,
                    token: 3,
                    finish_reason: None
                }
            ]
        );
        let prefill_stats = s.mtp_stats().expect("MTP stats");
        assert_eq!(prefill_stats.windows, 0);
        assert!(prefill_stats.draft_cap_observations.is_empty());

        s.step_mtp_batch(&model, &FakeMtpHead)
            .expect("first pending batch step");
        model.clear_mtp_hidden_trace();
        *model.project_calls.lock().unwrap() = 0;

        let step_2 = s
            .step_mtp_batch(&model, &FakeMtpHead)
            .expect("second pending batch step triggers postfill");
        assert_eq!(
            step_2,
            vec![
                StepEvent {
                    id: id0,
                    token: 5,
                    finish_reason: None
                },
                StepEvent {
                    id: id1,
                    token: 7,
                    finish_reason: None
                }
            ]
        );
        assert_eq!(
            model.mtp_hidden_batch_sizes(),
            vec![2, 2],
            "postfill should draft both rows in one MTP batch, then commit accepted tails in one MTP batch"
        );
        assert_eq!(
            model.mtp_hidden_seq_lens(),
            vec![1, 1],
            "batched postfill should need one draft step and one accepted-tail commit"
        );
        assert_eq!(
            *model.project_calls.lock().unwrap(),
            1,
            "batched verify should project the whole [B,S,H] hidden tensor once"
        );
        let stats = s.mtp_stats().expect("MTP stats");
        assert_eq!(stats.draft_host_sync_count, 0);
        assert_eq!(stats.windows, 4);
        assert_eq!(
            stats.verify_accept_host_sync_count, 2,
            "two batched fills should synchronize acceptance once per active row group"
        );
    }

    #[test]
    #[serial(mlx_metal)]
    fn mtp_long_context_postfill_uses_row_cache_draft_and_batched_verify() {
        let mut s = Scheduler::<ScriptedMtpSchedulerModel>::new(
            2,
            32768,
            crate::core::memory_budget::test_meta_qwen35(),
        )
        .expect("scheduler startup");
        let long_prompt_a = (0..(MTP_BATCH_DRAFT_ROW_CACHE_MIN_OFFSET as u32 + 1))
            .map(|idx| 1 + idx % 20)
            .collect::<Vec<_>>();
        let long_prompt_b = (0..(MTP_BATCH_DRAFT_ROW_CACHE_MIN_OFFSET as u32 + 1))
            .map(|idx| 10 + idx % 20)
            .collect::<Vec<_>>();
        let id0 = s.admit(mtp_req(long_prompt_a, 7)).expect("admit row 0");
        let id1 = s.admit(mtp_req(long_prompt_b, 7)).expect("admit row 1");
        let model = ScriptedMtpSchedulerModel::new_with_first_token_calls(
            3,
            2,
            vec![4, 6, 20, 8, 21, 9, 22, 12, 23, 13],
            vec![
                vec![4, 5],
                vec![6, 7],
                vec![8, 10],
                vec![9, 11],
                vec![12, 14],
                vec![13, 15],
            ],
        );
        let cfg = MtpSpeculativeConfig::new(1, Sampler::greedy()).expect("mtp cfg");

        s.prefill_admitted_mtp_batch(&model, &FakeMtpHead, cfg)
            .expect("mtp batch prefill");
        s.step_mtp_batch(&model, &FakeMtpHead)
            .expect("first pending batch step");
        model.clear_mtp_hidden_trace();
        model.clear_text_hidden_trace();

        let step_2 = s
            .step_mtp_batch(&model, &FakeMtpHead)
            .expect("second pending batch step triggers long-context postfill");
        assert_eq!(
            step_2,
            vec![
                StepEvent {
                    id: id0,
                    token: 5,
                    finish_reason: None
                },
                StepEvent {
                    id: id1,
                    token: 7,
                    finish_reason: None
                }
            ]
        );
        assert_eq!(
            model.mtp_hidden_batch_sizes(),
            vec![1, 1],
            "first long-context postfill should draft per row and defer accepted-tail commits"
        );
        assert_eq!(
            model.mtp_hidden_seq_lens(),
            vec![2, 2],
            "the first batched long-context postfill should fuse the deferred tail produced by the initial batched window"
        );
        assert_eq!(
            model.text_hidden_batch_sizes(),
            vec![2],
            "long-context postfill should still verify accepted windows in one main-model batch"
        );

        s.step_mtp_batch(&model, &FakeMtpHead)
            .expect("third pending batch step");
        model.clear_mtp_hidden_trace();
        model.clear_text_hidden_trace();

        let step_4 = s
            .step_mtp_batch(&model, &FakeMtpHead)
            .expect("fourth pending batch step triggers deferred-tail fused postfill");
        assert_eq!(
            step_4,
            vec![
                StepEvent {
                    id: id0,
                    token: 10,
                    finish_reason: None
                },
                StepEvent {
                    id: id1,
                    token: 11,
                    finish_reason: None
                }
            ]
        );
        assert_eq!(
            model.mtp_hidden_batch_sizes(),
            vec![1, 1],
            "next long-context postfill should still execute per row"
        );
        assert_eq!(
            model.mtp_hidden_seq_lens(),
            vec![2, 2],
            "next long-context postfill should fuse deferred tail commit with first draft"
        );
        assert_eq!(
            model.text_hidden_batch_sizes(),
            vec![2],
            "fused deferred-tail path should still verify accepted windows in one main-model batch"
        );
        let stats = s.mtp_stats().expect("MTP stats");
        assert_eq!(stats.draft_host_sync_count, 0);
        assert!(stats.verify_accept_host_sync_count > 0);
    }

    #[test]
